def baixar_logo_agora(nome_clube):
    _off = _ps_logo_offline(nome_clube)          # 1º: banco offline de escudos (pasta Dados)
    if _off: return _off
    # ======================================================================
    # 🔴 COLE SUA CHAVE DO API-FOOTBALL AQUI DENTRO DAS ASPAS:
    API_KEY = "856dcd7e7e1d429d978692f45368dd81" 
    # ======================================================================

    print(f"🔎 Procurando logo para: {nome_clube}...")
    nome_limpo = nome_clube.strip()
    caminho_final = f"Logos/{nome_limpo}.png"
    
    if os.path.exists(caminho_final):
        return caminho_final

    headers_browser = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
    }

    url_imagem = None

    # --- 1. TENTATIVA PREMIUM: API-FOOTBALL ---
    if API_KEY != "SUA_API_KEY_AQUI" and len(API_KEY) > 10:
        try:
            url_api = "https://v3.football.api-sports.io/teams"
            querystring = {"search": nome_limpo}
            headers_api = {
                'x-rapidapi-key': API_KEY,
                'x-rapidapi-host': 'v3.football.api-sports.io'
            }
            
            response = requests.get(url_api, headers=headers_api, params=querystring, timeout=3)
            
            if response.status_code == 200:
                data = response.json()
                if data["results"] > 0:
                    url_imagem = data["response"][0]["team"]["logo"]
                    print(f"   ✨ Achei no API-Football!")
        except Exception as e:
            print(f"   Erro API-Football: {e}")

    # --- 2. TENTATIVA WIKIPEDIA ---
    if not url_imagem:
        try:
            search_term = f"{nome_clube} football club"
            url_wiki = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={quote_plus(search_term)}&format=json"
            res = requests.get(url_wiki, headers=headers_browser, timeout=2)
            if res.status_code == 200:
                data = res.json()
                if data.get("query", {}).get("search"):
                    title = data["query"]["search"][0]["title"]
                    url_img = f"https://en.wikipedia.org/w/api.php?action=query&titles={quote_plus(title)}&prop=pageimages&format=json&pithumbsize=500"
                    res_img = requests.get(url_img, headers=headers_browser, timeout=2)
                    pages = res_img.json().get("query", {}).get("pages", {})
                    for pid in pages:
                        if "thumbnail" in pages[pid]:
                            url_imagem = pages[pid]["thumbnail"]["source"]
                            print(f"   Achei na Wikipedia: {title}")
                            break
        except: pass

    # --- 3. TENTATIVA THESPORTSDB ---
    if not url_imagem:
        try:
            url_api = f"https://www.thesportsdb.com/api/v1/json/3/searchteams.php?t={quote_plus(nome_clube)}"
            r = requests.get(url_api, headers=headers_browser, timeout=2)
            if r.status_code == 200:
                data = r.json()
                if data and data.get("teams"):
                    url_imagem = data["teams"][0]["strTeamBadge"]
                    print("   Achei no TheSportsDB")
        except: pass

    # --- DOWNLOAD E SALVAMENTO ---
    sucesso = False
    if url_imagem:
        try:
            print(f"   Baixando...")
            img_data = requests.get(url_imagem, headers=headers_browser, timeout=5).content
            
            with Image.open(io.BytesIO(img_data)) as img:
                img = img.convert("RGBA")
                img = img.resize((150, 150), Image.Resampling.LANCZOS)
                img.save(caminho_final, "PNG")
                
            print(f"✅ SUCESSO: Logo salva em {caminho_final}")
            sucesso = True
            return caminho_final
        except Exception as e:
            print(f"❌ Erro ao salvar imagem: {e}")

    # ====================================================================
    # PLANO Z: SELEÇÃO MANUAL (CORRIGIDO)
    # ====================================================================
    if not sucesso:
        resposta = messagebox.askyesno(
            "Logo não encontrada", 
            f"Não achei a logo do '{nome_clube}' na internet.\n\nDeseja selecionar uma imagem do seu computador?"
        )
        
        if resposta:
            arquivo_selecionado = filedialog.askopenfilename(
                title=f"Selecione a logo para {nome_clube}",
                filetypes=[("Imagens", "*.png *.jpg *.jpeg *.webp *.bmp")]
            )
            
            if arquivo_selecionado:
                try:
                    # CORREÇÃO AQUI: Removi o resource_path! 
                    # O arquivo_selecionado já vem com o caminho completo do Windows.
                    with Image.open(arquivo_selecionado) as img:
                        img = img.convert("RGBA")
                        img = img.resize((150, 150), Image.Resampling.LANCZOS)
                        img.save(caminho_final, "PNG")
                    print(f"✅ Logo selecionada manualmente: {caminho_final}")
                    return caminho_final
                except Exception as e:
                    messagebox.showerror("Erro", f"Erro ao processar imagem: {e}")
        
    return None

def baixar_logo_competicao(nome_comp):
    _off = _ps_logo_offline(nome_comp)           # 1º: banco offline de escudos (pasta Dados)
    if _off: return _off
    # ======================================================================
    # USE A MESMA CHAVE QUE VOCÊ USOU PARA OS CLUBES
    API_KEY = "856dcd7e7e1d429d978692f45368dd81" 
    # ======================================================================

    # Limpeza básica do nome para facilitar a busca
    # Remove acentos ou caracteres que a API pode não gostar se necessário
    nome_limpo = nome_comp.strip()
    caminho_final = f"Logos/{nome_limpo}.png"
    
    if os.path.exists(caminho_final):
        return caminho_final

    print(f"🏆 Buscando logo para competição: {nome_limpo}...")

    headers_browser = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
    }

    url_imagem = None

    # --- 1. TENTATIVA API-FOOTBALL (/leagues) ---
    if API_KEY != "SUA_API_KEY_AQUI" and len(API_KEY) > 10:
        try:
            # Endpoint muda de 'teams' para 'leagues'
            url_api = "https://v3.football.api-sports.io/leagues"
            
            # Ajustes finos para nomes comuns
            search_name = nome_limpo
            if "Brasileirão" in nome_limpo: search_name = "Serie A" # A API chama de Serie A (Brazil)
            if "Copa do Brasil" in nome_limpo: search_name = "Copa do Brasil"
            if "Libertadores" in nome_limpo: search_name = "Libertadores"
            
            querystring = {"search": search_name}
            
            headers_api = {
                'x-rapidapi-key': API_KEY,
                'x-rapidapi-host': 'v3.football.api-sports.io'
            }
            
            response = requests.get(url_api, headers=headers_api, params=querystring, timeout=3)
            
            if response.status_code == 200:
                data = response.json()
                if data["results"] > 0:
                    # Tenta filtrar pelo país se possível, ou pega o primeiro
                    # A API retorna uma lista. O logo está em response[0]['league']['logo']
                    url_imagem = data["response"][0]["league"]["logo"]
                    
                    # Se for Brasileirão, tenta garantir que é o do Brasil
                    for item in data["response"]:
                        country = item["country"]["name"]
                        if "Brasileirão" in nome_limpo and country == "Brazil":
                            url_imagem = item["league"]["logo"]
                            break
                            
                    print(f"   ✨ Achei competição na API-Football!")
        except Exception as e:
            print(f"   Erro API Competição: {e}")

    # --- 2. TENTATIVA WIKIPEDIA (Fallback muito bom para torneios) ---
    if not url_imagem:
        try:
            # Tenta buscar "Nome + logo" ou "Nome + tournament"
            search_term = f"{nome_limpo} football logo"
            url_wiki = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={quote_plus(search_term)}&format=json"
            res = requests.get(url_wiki, headers=headers_browser, timeout=2)
            if res.status_code == 200:
                data = res.json()
                if data.get("query", {}).get("search"):
                    title = data["query"]["search"][0]["title"]
                    url_img = f"https://en.wikipedia.org/w/api.php?action=query&titles={quote_plus(title)}&prop=pageimages&format=json&pithumbsize=500"
                    res_img = requests.get(url_img, headers=headers_browser, timeout=2)
                    pages = res_img.json().get("query", {}).get("pages", {})
                    for pid in pages:
                        if "thumbnail" in pages[pid]:
                            url_imagem = pages[pid]["thumbnail"]["source"]
                            break
        except: pass

    # --- DOWNLOAD ---
    if url_imagem:
        try:
            img_data = requests.get(url_imagem, headers=headers_browser, timeout=5).content
            with Image.open(io.BytesIO(img_data)) as img:
                img = img.convert("RGBA")
                img = img.resize((100, 100), Image.Resampling.LANCZOS) # Tamanho bom para o card
                img.save(caminho_final, "PNG")
            print(f"✅ Logo salva: {caminho_final}")
            return caminho_final
        except Exception as e:
            print(f"❌ Erro ao salvar: {e}")
            
    return None

def resource_path(relative_path):
    """ Retorna o caminho absoluto da pasta onde o .exe está rodando """
    import sys
    import os
    if getattr(sys, 'frozen', False):
        base_path = os.path.dirname(sys.executable)
    else:
        base_path = os.path.abspath(".")

    return os.path.join(base_path, relative_path)


