    @staticmethod
    def hex_to_rgb(hex_color):
        hex_color = hex_color.lstrip("#")
        return tuple(int(hex_color[i:i + 2], 16) for i in (0, 2, 4))

    def mostrar_tela_inicial(self):
        """Cria uma tela de menu inicial estilizada com o design do programa."""
        self.tela_inicial = tk.Frame(self, bg="#0F172A")
        self.tela_inicial.pack(fill="both", expand=True)

        # Container centralizado
        centro_frame = tk.Frame(self.tela_inicial, bg="#0F172A")
        centro_frame.place(relx=0.5, rely=0.5, anchor="center")

        # Título PRO STATS
        titulo_frame = tk.Frame(centro_frame, bg="#0F172A")
        titulo_frame.pack(pady=(0, 5))
        tk.Label(titulo_frame, text="PRO", font=("Impact", 65), fg="#38BDF8", bg="#0F172A").pack(side="left")
        tk.Label(titulo_frame, text="STATS", font=("Impact", 65), fg="white", bg="#0F172A").pack(side="left", padx=(10, 0))

        tk.Label(centro_frame, text="M A N A G E R", font=("Segoe UI", 16, "bold"), fg="#94A3B8", bg="#0F172A").pack(pady=(0, 60))

        # Função interna para padronizar efeito Hover nos botões
        def criar_btn(parent, texto, cor_bg, cor_fg, comando, hover_bg, hover_fg):
            btn = tk.Button(parent, text=texto, font=("Segoe UI", 12, "bold"), bg=cor_bg, fg=cor_fg, 
                            activebackground=hover_bg, activeforeground=hover_fg,
                            relief="flat", cursor="hand2", width=30, pady=12, command=comando)
            btn.bind("<Enter>", lambda e: btn.config(bg=hover_bg, fg=hover_fg))
            btn.bind("<Leave>", lambda e: btn.config(bg=cor_bg, fg=cor_fg))
            return btn

        # Botões Principais
        btn_continuar = criar_btn(centro_frame, "▶ CONTINUAR CARREIRA", "#00E676", "#064E3B", self.acao_continuar_carreira, "#34D399", "#064E3B")
        btn_continuar.pack(pady=10)

        btn_nova = criar_btn(centro_frame, "➕ NOVA CARREIRA", "#38BDF8", "#0F172A", self.acao_nova_carreira, "#7DD3FC", "#0F172A")
        btn_nova.pack(pady=10)

        btn_carregar = criar_btn(centro_frame, "📂 CARREGAR SAVE ANTIGO", "#1E293B", "#F8FAFC", self.acao_carregar_carreira, "#334155", "white")
        btn_carregar.pack(pady=10)

    def acao_continuar_carreira(self):
        """Continua do último save aberto ou salvo."""
        import os
        from tkinter import messagebox
        
        ultimo_save = self.obter_ultimo_save()
        
        if ultimo_save and os.path.exists(ultimo_save):
            self.arquivo_carreira_atual = ultimo_save
            self.carregar_dados()
            self.iniciar_interface_principal()
        else:
            # Se não encontrar o registro, tenta abrir o padrão. Se não existir, avisa.
            caminho_padrao = self.get_arquivo_json()
            if os.path.exists(caminho_padrao):
                self.arquivo_carreira_atual = caminho_padrao
                self.carregar_dados()
                self.iniciar_interface_principal()
            else:
                messagebox.showinfo("Aviso", "Nenhum save anterior encontrado. Iniciando uma nova carreira.")
                self.acao_nova_carreira()

    def acao_carregar_carreira(self):
        """Abre janela para escolher um save e o define como o último jogado."""
        from tkinter import filedialog
        import os
        
        pasta_inicial = os.path.join(os.path.abspath("."), "backups")
        if not os.path.exists(pasta_inicial):
            pasta_inicial = os.path.abspath(".")

        caminho = filedialog.askopenfilename(
            initialdir=pasta_inicial,
            title="Selecione o arquivo da sua carreira",
            filetypes=[("Arquivos JSON de Save", "*.json")]
        )
        
        if caminho:
            self.arquivo_carreira_atual = caminho
            self.salvar_ultimo_save(caminho) # <--- REGISTRA QUE ESTE FOI O ÚLTIMO ABERTO
            self.carregar_dados()
            self.iniciar_interface_principal()

    def acao_nova_carreira(self):
        """Inicia uma carreira do zero abrindo o criador de jogador."""
        self.resetar_dados_memoria()
        
        from tkinter import Toplevel, messagebox
        import datetime
        import os
        import sys
        
        BG_MODAL = "#0F172A"; BG_CARD = "#1E293B"; BG_INPUT = "#111827"
        ACCENT = "#00E676"; BORDER = "#334155"
        TEXT_MAIN = "#F8FAFC"; TEXT_SUB = "#94A3B8"
        
        md = Toplevel(self)
        md.title("Criar Lenda")
        md.geometry("550x750")
        md.configure(bg=BG_MODAL)
        
        x = (md.winfo_screenwidth() // 2) - 275; y = (md.winfo_screenheight() // 2) - 375
        md.geometry(f"+{x}+{y}"); md.grab_set()

        canvas = tk.Canvas(md, bg=BG_MODAL, highlightthickness=0)
        scrollbar = ttk.Scrollbar(md, orient="vertical", command=canvas.yview)
        scrollable_frame = tk.Frame(canvas, bg=BG_MODAL)

        scrollable_frame.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw", width=530)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        tk.Label(scrollable_frame, text="⭐", font=("Segoe UI Emoji", 40), bg=BG_MODAL).pack(pady=(20, 0))
        tk.Label(scrollable_frame, text="CRIAR NOVA CARREIRA", font=("Impact", 24), fg="white", bg=BG_MODAL).pack()
        tk.Label(scrollable_frame, text="Preencha os dados iniciais do seu jogador", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_MODAL).pack(pady=(0, 20))

        vars_form = {
            "Nome": tk.StringVar(), "Nascimento": tk.StringVar(value="01/01/2004"),
            "Nacionalidade": tk.StringVar(value="Brasil"), "Altura": tk.StringVar(value="180cm"),
            "Peso": tk.StringVar(value="75kg"), "Pé": tk.StringVar(value="Direito"),
            "Posição": tk.StringVar(value="ATA"), "Clube": tk.StringVar(),
            "InicioContrato": tk.StringVar(value=datetime.datetime.now().strftime("%d/%m/%Y")),
            "FimContrato": tk.StringVar(value=str(datetime.datetime.now().year + 3)),
            "Patrocinador": tk.StringVar(value="Nike"),
            "Salario": tk.StringVar(value="1500") # NOVO: Salário Semanal Base (Jovem promessa)
        }

        def criar_secao(titulo):
            tk.Label(scrollable_frame, text=titulo, font=("Segoe UI", 12, "bold"), fg="#38BDF8", bg=BG_MODAL).pack(anchor="w", padx=30, pady=(20, 5))
            tk.Frame(scrollable_frame, bg=BORDER, height=1).pack(fill="x", padx=30, pady=(0, 10))

        def criar_campo(label, var_key, combo_values=None):
            f = tk.Frame(scrollable_frame, bg=BG_MODAL); f.pack(fill="x", padx=30, pady=5)
            tk.Label(f, text=label.upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_MODAL).pack(anchor="w")
            if combo_values: ttk.Combobox(f, textvariable=vars_form[var_key], values=combo_values, font=("Segoe UI", 11)).pack(fill="x")
            else: tk.Entry(f, textvariable=vars_form[var_key], font=("Segoe UI", 11), bg=BG_INPUT, fg="white", relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

        def criar_meio_campo(parent, row, col, label, var_key):
            f = tk.Frame(parent, bg=BG_MODAL); f.grid(row=row, column=col, sticky="ew", padx=(0 if col==0 else 5, 5 if col==0 else 0))
            tk.Label(f, text=label.upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_MODAL).pack(anchor="w")
            tk.Entry(f, textvariable=vars_form[var_key], font=("Segoe UI", 11), bg=BG_INPUT, fg="white", relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

        criar_secao("DADOS PESSOAIS")
        criar_campo("Nome Completo", "Nome")
        f_r1 = tk.Frame(scrollable_frame, bg=BG_MODAL); f_r1.pack(fill="x", padx=30, pady=5)
        f_r1.columnconfigure(0, weight=1); f_r1.columnconfigure(1, weight=1)
        criar_meio_campo(f_r1, 0, 0, "Data Nasc. (dd/mm/aaaa)", "Nascimento")
        criar_meio_campo(f_r1, 0, 1, "Nacionalidade", "Nacionalidade")
        
        criar_secao("FÍSICO & TÁTICO")
        f_r2 = tk.Frame(scrollable_frame, bg=BG_MODAL); f_r2.pack(fill="x", padx=30, pady=5)
        f_r2.columnconfigure(0, weight=1); f_r2.columnconfigure(1, weight=1)
        criar_meio_campo(f_r2, 0, 0, "Altura", "Altura"); criar_meio_campo(f_r2, 0, 1, "Peso", "Peso")
        criar_campo("Pé Preferido", "Pé", ["Direito", "Esquerdo", "Ambidestro"])
        criar_campo("Posição", "Posição", ["ATA", "SA", "PE", "PD", "MEI", "MC", "VOL", "LE", "LD", "ZAG", "GOL"])

        criar_secao("CARREIRA & CONTRATO")
        criar_campo("Clube Inicial", "Clube")
        f_r3 = tk.Frame(scrollable_frame, bg=BG_MODAL); f_r3.pack(fill="x", padx=30, pady=5)
        f_r3.columnconfigure(0, weight=1); f_r3.columnconfigure(1, weight=1)
        criar_meio_campo(f_r3, 0, 0, "Início do Contrato", "InicioContrato")
        criar_meio_campo(f_r3, 0, 1, "Salário Semanal (€)", "Salario") # NOVO CAMPO DE SALÁRIO
        criar_campo("Patrocinador (Chuteira)", "Patrocinador", ["Nike", "Adidas", "Puma", "New Balance", "Under Armour", "Mizuno", "Umbro", "Sem Patrocínio"])

        def iniciar_jornada():
            if not vars_form["Nome"].get().strip() or not vars_form["Clube"].get().strip():
                messagebox.showwarning("Atenção", "Preencha Nome e Clube Inicial!", parent=md)
                return
            
            self.informacoes["Nome Completo"] = vars_form["Nome"].get().strip()
            self.informacoes["Data de Nascimento"] = vars_form["Nascimento"].get()
            self.informacoes["Nacionalidade"] = vars_form["Nacionalidade"].get()
            self.informacoes["Altura"] = vars_form["Altura"].get()
            self.informacoes["Peso"] = vars_form["Peso"].get()
            self.informacoes["Pé"] = vars_form["Pé"].get()
            self.informacoes["Posição"] = vars_form["Posição"].get()
            self.informacoes["Clube Atual"] = vars_form["Clube"].get().strip()
            self.informacoes["No Time Desde"] = vars_form["InicioContrato"].get()
            self.informacoes["Contrato Até"] = vars_form["FimContrato"].get()
            self.informacoes["Salario Semanal"] = vars_form["Salario"].get() 
            
            # --- NOVO: SISTEMA DE PATROCÍNIO INICIAL ---
            patrocinador = vars_form["Patrocinador"].get()
            self.informacoes["Fornecedor"] = patrocinador
            
            data_ini_str = vars_form["InicioContrato"].get()
            try:
                dt_ini = datetime.datetime.strptime(data_ini_str, "%d/%m/%Y")
                if patrocinador != "Sem Patrocínio":
                    # Contrato base de 2 anos
                    self.informacoes["Fim_Patrocinio"] = dt_ini.replace(year=dt_ini.year + 2).strftime("%d/%m/%Y")
                    # Valores base iniciais (Baixos, pois é promessa)
                    if patrocinador in ["Nike", "Adidas"]: self.informacoes["Valor_Patrocinio"] = 15000
                    elif patrocinador == "Puma": self.informacoes["Valor_Patrocinio"] = 10000
                    else: self.informacoes["Valor_Patrocinio"] = 5000
                else:
                    # Se começou sem patrocínio, recebe ofertas no fim do 1º ano
                    self.informacoes["Fim_Patrocinio"] = dt_ini.replace(year=dt_ini.year + 1).strftime("%d/%m/%Y")
                    self.informacoes["Valor_Patrocinio"] = 0
            except:
                self.informacoes["Fim_Patrocinio"] = "01/01/2030"
                self.informacoes["Valor_Patrocinio"] = 0

            # Histórico Inicial
            self.historico_transferencias = [{
                "Data": vars_form["InicioContrato"].get(), "De": "Base / Free Agent", "Para": vars_form["Clube"].get().strip(),
                "Tipo": "Contrato Inicial", "Valor": "-", "Salario": vars_form["Salario"].get()
            }]
            
            clube_inic = vars_form["Clube"].get().strip()
            if clube_inic and clube_inic not in self.club_logo_paths:
                path = baixar_logo_agora(clube_inic)
                if path: self.club_logo_paths[clube_inic] = path
            
            if getattr(sys, 'frozen', False): base_dir = os.path.dirname(sys.executable)
            else: base_dir = os.path.dirname(os.path.abspath(__file__))
                
            nome_seguro = self.informacoes["Nome Completo"].replace(" ", "_").replace("/", "").lower()
            pasta_saves = os.path.join(base_dir, "saves")
            if not os.path.exists(pasta_saves): os.makedirs(pasta_saves)
                
            self.arquivo_carreira_atual = os.path.join(pasta_saves, f"save_{nome_seguro}.json")
            
            self.salvar_dados()
            md.destroy()
            self.iniciar_interface_principal()
            
        tk.Button(scrollable_frame, text="▶ INICIAR JORNADA", font=("Segoe UI", 12, "bold"), bg=ACCENT, fg="#064E3B", cursor="hand2", relief="flat", pady=12, command=iniciar_jornada).pack(fill="x", padx=30, pady=40)

    def salvar_ultimo_save(self, caminho):
        """Grava o caminho do último save acessado em um arquivo de texto."""
        import os
        import sys
        if getattr(sys, 'frozen', False):
            base_dir = os.path.dirname(sys.executable)
        else:
            base_dir = os.path.dirname(os.path.abspath(__file__))
            
        config_path = os.path.join(base_dir, "ultimo_save.txt")
        try:
            with open(config_path, "w", encoding="utf-8") as f:
                f.write(caminho)
        except Exception as e:
            print(f"Erro ao registrar último save: {e}")

    def obter_ultimo_save(self):
        """Lê qual foi o último save acessado."""
        import os
        import sys
        if getattr(sys, 'frozen', False):
            base_dir = os.path.dirname(sys.executable)
        else:
            base_dir = os.path.dirname(os.path.abspath(__file__))
            
        config_path = os.path.join(base_dir, "ultimo_save.txt")
        if os.path.exists(config_path):
            try:
                with open(config_path, "r", encoding="utf-8") as f:
                    caminho = f.read().strip()
                    if os.path.exists(caminho):
                        return caminho
            except: pass
        return None

    def iniciar_interface_principal(self):
        """Constrói a interface do dashboard após sair do menu inicial."""
        # 1. Esconde a tela inicial
        if hasattr(self, 'tela_inicial'):
            self.tela_inicial.destroy()

        # 2. Chama as funções essenciais
        try: self._ps_preparar_logos()
        except Exception as _e: print("Logos offline:", _e)
        self.verificar_e_gerar_noticias_retroativas()
        self.iniciar_ciclo_vida_real()
        self.inicializar_banco_de_textos()

        # 3. Monta o Layout Principal (Conteúdo e Sidebar)
        self.main_container = tk.Frame(self, bg=self.colors["bg_sidebar"])
        self.main_container.pack(fill="both", expand=True)

        # --- MENU LATERAL ---
        self.sidebar_frame = tk.Frame(self.main_container, bg=self.colors["bg_sidebar"], width=260)
        self.sidebar_frame.pack(side="left", fill="y")
        self.sidebar_frame.pack_propagate(False)

        # Divisor sutil entre menu e conteúdo
        tk.Frame(self.main_container, bg="#1E293B", width=2).pack(side="left", fill="y")

        # --- ÁREA DIREITA (HUD + CONTEÚDO) ---
        self.right_area = tk.Frame(self.main_container, bg=self.colors["bg_content"])
        self.right_area.pack(side="left", fill="both", expand=True)

        # O NOVO HUD SUPERIOR FIXO
        self.topbar_frame = tk.Frame(self.right_area, bg="#0F172A", height=70)
        self.topbar_frame.pack(side="top", fill="x")
        self.topbar_frame.pack_propagate(False)
        
        # Sombra/Borda inferior do HUD
        tk.Frame(self.right_area, bg="#020617", height=3).pack(side="top", fill="x")

        # ÁREA DE CONTEÚDO DINÂMICO DAS ABAS
        self.content_area = tk.Frame(self.right_area, bg=self.colors["bg_content"])
        self.content_area.pack(side="top", fill="both", expand=True)

        # 4. Inicia os componentes
        self.construir_hud_superior()
        self.setup_sidebar()
        
        self.current_btn = None
        self.open_tab("Perfil do Jogador", "VISÃO GERAL", 0)

    def construir_hud_superior(self, tab_name="Perfil do Jogador", category_name="VISÃO GERAL"):
        """Cria uma barra de status estilizada no topo da tela (HUD Global)."""
        for widget in self.topbar_frame.winfo_children():
            widget.destroy()

        hud_bg = "#0F172A"

        # Esquerda: Caminho da Aba (Substitui o Breadcrumb antigo)
        tk.Label(self.topbar_frame, text=f"{category_name}  /  ", font=("Segoe UI", 10, "bold"), fg="#64748B", bg=hud_bg).pack(side="left", padx=(40, 0))
        tk.Label(self.topbar_frame, text=tab_name, font=("Segoe UI", 11, "bold"), fg="#38BDF8", bg=hud_bg).pack(side="left")

        # Direita: Container de Status do Jogador
        status_container = tk.Frame(self.topbar_frame, bg=hud_bg)
        status_container.pack(side="right", padx=40)

        # 1. Saldo Bancário (Se o sistema financeiro estiver ativo)
        saldo = 0
        if hasattr(self, 'informacoes') and "Patrimonio" in self.informacoes:
            t_jogos = sum(row[1] for row in self.dados_desempenho)
            t_gols = sum(row[2] for row in self.dados_desempenho)
            t_assis = sum(row[3] for row in self.dados_desempenho)
            t_titulos = sum(int(item[4]) for item in self.conquistas) if hasattr(self, 'conquistas') else 0
            
            ganhos = (t_jogos * 20000) + ((t_gols + t_assis) * 10000) + (t_titulos * 500000)
            gastos = sum(item['valor'] for item in self.informacoes.get("Patrimonio", []))
            saldo = ganhos - gastos

        if saldo > 0:
            saldo_str = f"€ {saldo/1000000:.1f}M" if saldo >= 1000000 else f"€ {saldo/1000:.0f}K"
            f_money = tk.Frame(status_container, bg="#1E293B", highlightthickness=1, highlightbackground="#334155", padx=10, pady=4)
            f_money.pack(side="left", padx=20)
            tk.Label(f_money, text="💳", font=("Segoe UI Emoji", 10), bg="#1E293B").pack(side="left")
            tk.Label(f_money, text=saldo_str, font=("Segoe UI", 10, "bold"), fg="#10B981", bg="#1E293B").pack(side="left", padx=(5, 0))

        # 2. Clube Atual
        clube = self.informacoes.get("Clube Atual", "Clube")
        tk.Label(status_container, text=clube.upper(), font=("Segoe UI", 10, "bold"), fg="white", bg=hud_bg).pack(side="left", padx=10)
        
        logo_path = self.club_logo_paths.get(clube)
        if logo_path and os.path.exists(resource_path(logo_path)):
            try:
                pil_l = Image.open(resource_path(logo_path)).resize((32, 32), Image.Resampling.LANCZOS)
                tk_l = ImageTk.PhotoImage(pil_l)
                self.club_logo_images.append(tk_l) # Usa o cache para não sumir
                tk.Label(status_container, image=tk_l, bg=hud_bg).pack(side="left")
            except: pass

        # 3. Avatar / Nome do Jogador
        tk.Frame(status_container, bg="#334155", width=1, height=30).pack(side="left", padx=20) # Separador
        
        nome_curto = self.informacoes.get("Nome Completo", "Jogador").split()[-1].upper()
        tk.Label(status_container, text=nome_curto, font=("Segoe UI", 11, "bold"), fg="#F8FAFC", bg=hud_bg).pack(side="left", padx=(0, 10))
        
        path_face = f"Faces/{self.informacoes.get('Nome Completo', '').replace(' ', '_')}.png"
        if os.path.exists(resource_path(path_face)):
            try:
                # Máscara circular para o avatar ficar redondo (mais elegante)
                pil_f = Image.open(resource_path(path_face)).convert("RGBA").resize((40, 40), Image.Resampling.LANCZOS)
                mask = Image.new("L", (40, 40), 0)
                draw = ImageDraw.Draw(mask)
                draw.ellipse((0, 0, 40, 40), fill=255)
                pil_f.putalpha(mask)
                
                # Borda circular dourada/ciano
                f_bg = Image.new("RGBA", (44, 44), (0,0,0,0))
                draw_bg = ImageDraw.Draw(f_bg)
                draw_bg.ellipse((0, 0, 44, 44), fill="#38BDF8") # Fundo da borda
                f_bg.paste(pil_f, (2, 2), pil_f)
                
                tk_f = ImageTk.PhotoImage(f_bg)
                self.club_logo_images.append(tk_f) 
                tk.Label(status_container, image=tk_f, bg=hud_bg).pack(side="left")
            except: 
                tk.Label(status_container, text="👤", font=("Segoe UI Emoji", 24), bg=hud_bg, fg="white").pack(side="left")
        else:
            tk.Label(status_container, text="👤", font=("Segoe UI Emoji", 24), bg=hud_bg, fg="white").pack(side="left")

