    def voltar_ao_menu_inicial(self):
        """Salva o progresso, limpa a interface atual e volta para a tela inicial."""
        from tkinter import messagebox
        import matplotlib.pyplot as plt
        
        # 1. Pergunta se deseja salvar antes de sair
        if messagebox.askyesno("Trocar Carreira", "Deseja SALVAR o progresso atual antes de voltar ao menu inicial?"):
            self.salvar_dados()

        # 2. Destrói a interface atual (Sidebar e Conteúdo)
        if hasattr(self, 'main_container') and self.main_container:
            self.main_container.destroy()

        # 3. Limpa os gráficos para não pesar a memória do PC
        for canvas_item in self.matplotlib_canvases:
            try:
                if hasattr(canvas_item, 'figure') and canvas_item.figure:
                    plt.close(canvas_item.figure)
                elif hasattr(canvas_item, 'get_tk_widget'):
                    plt.close(canvas_item.get_tk_widget().figure)
            except: pass
        self.matplotlib_canvases.clear()

        # 4. Zera as informações para carregar as do próximo save limpas
        self.resetar_dados_memoria()

        # 5. Mostra a tela de menu novamente
        self.mostrar_tela_inicial()

    @staticmethod
    def rgb_to_hex(rgb_color):
        return f"#{''.join(f'{c:02x}' for c in rgb_color)}"

    def setup_sidebar(self):
        """Constrói o menu lateral com rolagem isolada (não afeta o conteúdo)."""
        
        # 1. Configuração do Canvas
        self.sidebar_frame.pack_propagate(False)
        
        canvas_menu = tk.Canvas(self.sidebar_frame, bg=self.colors["bg_sidebar"], highlightthickness=0)
        scrollbar_menu = ttk.Scrollbar(self.sidebar_frame, orient="vertical", command=canvas_menu.yview)
        
        self.menu_inner = tk.Frame(canvas_menu, bg=self.colors["bg_sidebar"])
        
        canvas_window = canvas_menu.create_window((0, 0), window=self.menu_inner, anchor="nw")
        canvas_menu.configure(yscrollcommand=scrollbar_menu.set)
        
        scrollbar_menu.pack(side="right", fill="y")
        canvas_menu.pack(side="left", fill="both", expand=True)
        
        # --- FUNÇÃO DE SCROLL ISOLADA ---
        def _on_mousewheel_sidebar(event):
            """Rola apenas a sidebar e BLOQUEIA que o evento suba para o resto da janela."""
            canvas_menu.yview_scroll(int(-1*(event.delta/120)), "units")
            return "break"

        # Funções de redimensionamento
        def _on_frame_configure(event):
            canvas_menu.configure(scrollregion=canvas_menu.bbox("all"))

        def _on_canvas_configure(event):
            canvas_width = event.width
            canvas_menu.itemconfig(canvas_window, width=canvas_width)

        # Binds de configuração
        self.menu_inner.bind("<Configure>", _on_frame_configure)
        canvas_menu.bind("<Configure>", _on_canvas_configure)

        # Bind no fundo
        self.sidebar_frame.bind("<MouseWheel>", _on_mousewheel_sidebar)
        canvas_menu.bind("<MouseWheel>", _on_mousewheel_sidebar)
        self.menu_inner.bind("<MouseWheel>", _on_mousewheel_sidebar)

        # Header PRO STATS no menu lateral
        header = tk.Frame(self.menu_inner, bg=self.colors["bg_sidebar"], height=80)
        header.pack(fill="x", pady=(20, 10))
        
        l1 = tk.Label(header, text="PRO", font=("Impact", 28), fg=self.colors["accent"], bg=self.colors["bg_sidebar"])
        l1.pack(side="left", padx=(25, 0))
        l2 = tk.Label(header, text="STATS", font=("Impact", 28), fg="white", bg=self.colors["bg_sidebar"])
        l2.pack(side="left")
        
        header.bind("<MouseWheel>", _on_mousewheel_sidebar)
        l1.bind("<MouseWheel>", _on_mousewheel_sidebar)
        l2.bind("<MouseWheel>", _on_mousewheel_sidebar)

        # Botões do Menu
        self.menu_buttons = {} 

        for categoria, itens in self.menu_structure.items():
            # Título da Categoria
            lbl_cat = tk.Label(self.menu_inner, text=categoria, font=("Segoe UI", 9, "bold"), 
                               fg="#64748B", bg=self.colors["bg_sidebar"], anchor="w")
            lbl_cat.pack(fill="x", padx=25, pady=(20, 5))
            lbl_cat.bind("<MouseWheel>", _on_mousewheel_sidebar)
            
            # Botões das abas
            for nome_aba, icone, index in itens:
                btn = tk.Button(self.menu_inner, 
                                text=f"  {icone}   {nome_aba}", 
                                font=("Segoe UI", 10),
                                anchor="w",
                                bg=self.colors["bg_sidebar"],
                                fg=self.colors["text_muted"],
                                activebackground=self.colors["hover"],
                                activeforeground="white",
                                bd=0, cursor="hand2", padx=20, pady=8,
                                command=lambda n=nome_aba, c=categoria, i=index: self.open_tab(n, c, i))
                
                btn.pack(fill="x", padx=10, pady=1)
                btn.bind("<MouseWheel>", _on_mousewheel_sidebar)
                self.menu_buttons[index] = btn

        # ========================================================
        # NOVO BOTÃO: TROCAR CARREIRA / VOLTAR AO MENU INICIAL
        # ========================================================
        tk.Frame(self.menu_inner, bg=self.colors["bg_sidebar"], height=40).pack(fill="x") # Espaçador

        btn_voltar_menu = tk.Button(self.menu_inner, 
                                    text="🚪 TROCAR CARREIRA", 
                                    font=("Segoe UI", 10, "bold"),
                                    anchor="w",
                                    bg="#7F1D1D", # Fundo vermelho escuro
                                    fg="white",
                                    activebackground="#EF4444", # Vermelho vivo no hover
                                    activeforeground="white",
                                    bd=0, cursor="hand2", padx=20, pady=12,
                                    command=self.voltar_ao_menu_inicial)
        
        btn_voltar_menu.pack(fill="x", padx=10, pady=(0, 30))
        btn_voltar_menu.bind("<MouseWheel>", _on_mousewheel_sidebar)

    def open_tab(self, tab_name, category_name, tab_index):
        """Gerencia a troca de conteúdo."""
        
        # 1. Limpeza de Eventos de Scroll
        self.unbind_all("<MouseWheel>")
        self.unbind_all("<Shift-MouseWheel>")

        # 2. Limpeza de Memória e UI
        for widget in self.content_area.winfo_children():
            widget.destroy()
            
        for canvas_item in self.matplotlib_canvases:
            try:
                if hasattr(canvas_item, 'figure') and canvas_item.figure:
                    plt.close(canvas_item.figure)
                elif hasattr(canvas_item, 'get_tk_widget'):
                    plt.close(canvas_item.get_tk_widget().figure)
            except: pass
        self.matplotlib_canvases.clear()

        # 3. Atualização Visual do Menu Lateral
        if self.current_btn:
            self.current_btn.config(bg=self.colors["bg_sidebar"], fg=self.colors["text_muted"], font=("Segoe UI", 10))
        
        if tab_index in self.menu_buttons:
            new_btn = self.menu_buttons[tab_index]
            new_btn.config(bg=self.colors["bg_active"], fg="white", font=("Segoe UI", 10, "bold"))
            self.current_btn = new_btn

        # 4. Atualiza o HUD Superior (Substitui os Breadcrumbs velhos)
        self.construir_hud_superior(tab_name, category_name)

        # 5. Renderização do Conteúdo
        content_frame = ttk.Frame(self.content_area, style="Content.TFrame")
        content_frame.pack(fill="both", expand=True)

        if tab_name == "Perfil do Jogador": self.perfil_do_jogador(content_frame)
        elif tab_name == "Geral Carreira": self.desempenho_geral(content_frame)
        elif tab_name == "Por Temporada": self.dados_por_temporadas(content_frame)
