    def show_toast(self, message, tipo="sucesso"):
        """
        Exibe uma notificação flutuante (Toast) que some sozinha.
        Tipos: 'sucesso' (Verde), 'erro' (Vermelho), 'info' (Azul)
        """
        import tkinter as tk # Garante importação se necessário

        # Cores baseadas no seu tema dark
        colors = {
            "sucesso": {"bg": "#064E3B", "fg": "#34D399", "icon": "✓"}, # Fundo Esmeralda Escuro
            "erro":    {"bg": "#7F1D1D", "fg": "#F87171", "icon": "✕"}, # Fundo Vermelho Escuro
            "info":    {"bg": "#1E3A8A", "fg": "#60A5FA", "icon": "ℹ"}  # Fundo Azul Escuro
        }
        style = colors.get(tipo, colors["info"])

        # Cria a janela do toast (Toplevel sem bordas)
        toast = tk.Toplevel(self)
        toast.wm_overrideredirect(True) # Remove barra de título/botões
        toast.configure(bg=style["bg"])
        toast.attributes("-topmost", True) # Garante que fique acima de tudo
        
        # Frame interno para borda colorida
        frame = tk.Frame(toast, bg=style["bg"], highlightbackground=style["fg"], highlightthickness=1)
        frame.pack(fill="both", expand=True)

        # Ícone e Texto
        tk.Label(frame, text=style["icon"], font=("Segoe UI", 14, "bold"), fg=style["fg"], bg=style["bg"]).pack(side="left", padx=(15, 10), pady=10)
        tk.Label(frame, text=message, font=("Segoe UI", 10, "bold"), fg="white", bg=style["bg"]).pack(side="left", padx=(0, 20), pady=10)

        # --- POSICIONAMENTO INTELIGENTE ---
        toast.update_idletasks() # Calcula tamanho real
        
        # Pega coordenadas da janela principal do APP (não da tela inteira)
        main_x = self.winfo_rootx()
        main_y = self.winfo_rooty()
        main_w = self.winfo_width()
        main_h = self.winfo_height()
        
        t_w = toast.winfo_width()
        t_h = toast.winfo_height()
        
        # Posiciona no canto inferior direito do APP (com margem de 20px)
        pos_x = main_x + main_w - t_w - 25
        pos_y = main_y + main_h - t_h - 25
        
        toast.geometry(f"+{pos_x}+{pos_y}")
        
        # --- EFEITO DE FADE OUT E DESTRUIÇÃO ---
        def fade_out():
            try:
                alpha = float(toast.attributes("-alpha"))
                if alpha > 0.1:
                    alpha -= 0.1
                    toast.attributes("-alpha", alpha)
                    toast.after(50, fade_out)
                else:
                    toast.destroy()
            except: pass # Evita erro se a janela já foi fechada

        # Espera 3 segundos (3000ms) e começa a sumir
        toast.after(3000, fade_out)
        
        # Efeito de clique para fechar imediatamente (opcional)
        frame.bind("<Button-1>", lambda e: toast.destroy())

    def perfil_do_jogador(self, parent_frame):
        import tkinter as tk
        from tkinter import ttk, filedialog, Toplevel
        from PIL import Image, ImageTk, ImageDraw
        import os
        import datetime

        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"

        self.style.configure("PerfilMain.TFrame", background=BG_BASE)
        
        # --- ESTRUTURA COM SCROLL ---
        canvas_perfil = tk.Canvas(parent_frame, bg=BG_BASE, highlightthickness=0)
        scrollbar_perfil = ttk.Scrollbar(parent_frame, orient="vertical", command=canvas_perfil.yview)
        
        content_inner = ttk.Frame(canvas_perfil, style="PerfilMain.TFrame")
        window_id = canvas_perfil.create_window((0, 0), window=content_inner, anchor="nw")
        
        canvas_perfil.configure(yscrollcommand=scrollbar_perfil.set)
        canvas_perfil.pack(side="left", fill="both", expand=True)
        scrollbar_perfil.pack(side="right", fill="y")
        
        def _on_resize(event): canvas_perfil.itemconfig(window_id, width=event.width)
        canvas_perfil.bind("<Configure>", _on_resize)
        def _wheel(e): 
            try: canvas_perfil.yview_scroll(int(-1*(e.delta/120)), "units")
            except: pass
        canvas_perfil.bind_all("<MouseWheel>", _wheel)
        content_inner.bind("<Configure>", lambda e: canvas_perfil.configure(scrollregion=canvas_perfil.bbox("all")))

        # --- PROCESSAMENTO DE DADOS (PERFORMANCE) ---
        t_jogos = sum(row[1] for row in getattr(self, 'dados_desempenho', []))
        t_gols = sum(row[2] for row in getattr(self, 'dados_desempenho', []))
        t_assis = sum(row[3] for row in getattr(self, 'dados_desempenho', []))
        t_ama = sum(row[4] for row in getattr(self, 'dados_desempenho', []))
        t_ver = sum(row[6] for row in getattr(self, 'dados_desempenho', []))
        t_titulos = sum(int(t[4]) for t in getattr(self, 'conquistas', []) if len(t) > 4)

        media_gols = t_gols / t_jogos if t_jogos > 0 else 0
        media_assis = t_assis / t_jogos if t_jogos > 0 else 0
        media_contri = (t_gols + t_assis) / t_jogos if t_jogos > 0 else 0

        # --- CÁLCULO DE OVERALL ---
        overall_base = 65 
        if t_jogos == 0:
            overall = 0
        else:
            bonus_jogos = min(12, t_jogos * 0.04)
            bonus_gols = min(12, t_gols * 0.05)   
            bonus_media = min(10, media_contri * 8) 
            overall = int(overall_base + bonus_jogos + bonus_gols + bonus_media)
            if t_jogos < 15: overall = min(75, overall)
            elif t_jogos < 50: overall = min(85, overall)
            if overall > 99: overall = 99

        # --- INTEGRAÇÃO SALÁRIO E MERCADO ---
        moeda = self.informacoes.get("Moeda", "€")
        
        salario_val = "A Definir"
        if hasattr(self, 'historico_transferencias') and self.historico_transferencias:
            try: salario_val = str(self.historico_transferencias[0].get("Salario", "A Definir"))
            except: pass
        if salario_val == "A Definir" or not salario_val:
            salario_val = self.informacoes.get("Salario Semanal", self.informacoes.get("Salário", "A Definir"))

        mercado_val = "A Definir"
        if hasattr(self, 'dados_valor_mercado') and self.dados_valor_mercado:
            try:
                def sort_data_key(k):
                    if isinstance(k, (datetime.date, datetime.datetime)): return k
                    try: return datetime.datetime.strptime(str(k), "%Y-%m-%d").date()
                    except: 
                        try: return datetime.datetime.strptime(str(k), "%d/%m/%Y").date()
                        except: return datetime.date.min
                datas_ordenadas = sorted(list(self.dados_valor_mercado.keys()), key=sort_data_key)
                mercado_val = str(self.dados_valor_mercado[datas_ordenadas[-1]])
            except: pass
        if mercado_val == "A Definir" or not mercado_val:
            mercado_val = self.informacoes.get("Valor de Mercado", "A Definir")

        mercado_str = f"{moeda} {mercado_val}" if (mercado_val != "A Definir" and moeda not in mercado_val) else mercado_val
        salario_str = f"{moeda} {salario_val}" if (salario_val != "A Definir" and moeda not in salario_val) else salario_val

        # Outras Infos
        nome = self.informacoes.get("Nome Completo", "Jogador")
        posicao = self.informacoes.get("Posição", "Atacante")
        clube = self.informacoes.get("Clube Atual", "Clube Atual")
        nacionalidade = self.informacoes.get("Nacionalidade", "Brasileira")
        nasc = self.informacoes.get("Data de Nascimento", "01/01/2000")
        pe = self.informacoes.get("Pé Preferido", "Direito")
        altura = self.informacoes.get("Altura", "1.78")
        peso = self.informacoes.get("Peso", "75")
        path_foto = self.informacoes.get("Caminho da Foto", "Fotos/default.png")

        # ======================================================================
        # CÁLCULO DE IDADE DINÂMICO (Baseado na última partida jogada)
        # ======================================================================
        idade = "?"
        data_referencia = datetime.date.today()
        
        if hasattr(self, 'ultimas_performances') and self.ultimas_performances:
            try:
                # Busca a data do jogo mais recente registrado no seu save
                datas_validas = []
                for j in self.ultimas_performances:
                    dt_str = j.get("Data", "")
                    if dt_str:
                        try: datas_validas.append(datetime.datetime.strptime(dt_str, "%d/%m/%Y").date())
                        except: pass
                if datas_validas:
                    data_referencia = max(datas_validas)
            except: pass

        try:
            dia, mes, ano = map(int, nasc.split('/'))
            # Calcula a idade comparando a data de nascimento com a data do último jogo
            idade = data_referencia.year - ano - ((data_referencia.month, data_referencia.day) < (mes, dia))
        except: pass

        if not hasattr(self, 'cache_imgs_perfil'): self.cache_imgs_perfil = []
        self.cache_imgs_perfil.clear()

        # ======================================================================
        # 1. HEADER HERO (BANNER COM FOTO E OVERALL)
        # ======================================================================
        hero_frame = tk.Frame(content_inner, bg="#060B14", highlightthickness=1, highlightbackground="#334155")
        hero_frame.pack(fill="x", padx=40, pady=(30, 20))
        
        tk.Frame(hero_frame, bg=ACCENT, height=5).pack(side="top", fill="x")

        hero_inner = tk.Frame(hero_frame, bg="#060B14")
        hero_inner.pack(fill="both", expand=True, padx=40, pady=30)

        f_foto = tk.Frame(hero_inner, bg="#060B14")
        f_foto.pack(side="left", padx=(0, 30))

        def create_circle_image(path, size):
            try:
                img = Image.open(path).convert("RGBA")
                img = img.resize((size, size), Image.Resampling.LANCZOS)
                mask = Image.new("L", (size, size), 0)
                draw = ImageDraw.Draw(mask)
                draw.ellipse((0, 0, size, size), fill=255)
                result = Image.new("RGBA", (size, size), (0,0,0,0))
                result.paste(img, (0, 0), mask=mask)
                draw_res = ImageDraw.Draw(result)
                draw_res.ellipse((1, 1, size-1, size-1), outline=hex_to_rgb(ACCENT), width=3)
                return ImageTk.PhotoImage(result)
            except: return None

        def hex_to_rgb(h): return tuple(int(h.lstrip('#')[i:i+2], 16) for i in (0, 2, 4))

        path_final_foto = path_foto if os.path.exists(path_foto) else (resource_path(path_foto) if os.path.exists(resource_path(path_foto)) else None)

        tk_foto = create_circle_image(path_final_foto, 160) if path_final_foto else None
        if tk_foto:
            self.cache_imgs_perfil.append(tk_foto)
            lbl_foto = tk.Label(f_foto, image=tk_foto, bg="#060B14", cursor="hand2")
            lbl_foto.pack()
        else:
            lbl_foto = tk.Label(f_foto, text="👤", font=("Segoe UI Emoji", 80), bg="#1E293B", fg=ACCENT, width=2, height=1, cursor="hand2")
            lbl_foto.pack()

        def trocar_foto(e):
            p = filedialog.askopenfilename(title="Escolher Foto de Perfil", filetypes=[("Imagens", "*.png *.jpg *.jpeg *.webp")])
            if p:
                if not os.path.exists("Fotos"): os.makedirs("Fotos")
                dest = f"Fotos/perfil_{datetime.datetime.now().strftime('%Y%m%d%H%M%S')}.png"
                import shutil
                shutil.copy(p, dest)
                self.informacoes["Caminho da Foto"] = dest
                self.salvar_dados()
                for widget in parent_frame.winfo_children(): widget.destroy()
                self.perfil_do_jogador(parent_frame)
                
        lbl_foto.bind("<Button-1>", trocar_foto)
        tk.Label(f_foto, text="Clique para trocar", font=("Segoe UI", 8), fg=TEXT_SUB, bg="#060B14").pack(pady=(5,0))

        f_info = tk.Frame(hero_inner, bg="#060B14")
        f_info.pack(side="left", expand=True, fill="both")

        tk.Label(f_info, text=nome.upper(), font=("Impact", 40), fg="white", bg="#060B14").pack(anchor="w", pady=(10, 0))
        
        f_club = tk.Frame(f_info, bg="#060B14")
        f_club.pack(anchor="w", pady=(0, 10))

        path_logo = self.club_logo_paths.get(clube, f"Logos/{clube.strip()}.png")
        if os.path.exists(resource_path(path_logo)):
            try:
                pil_l = Image.open(resource_path(path_logo)).resize((25, 25), Image.Resampling.LANCZOS)
                tk_l = ImageTk.PhotoImage(pil_l)
                self.cache_imgs_perfil.append(tk_l)
                tk.Label(f_club, image=tk_l, bg="#060B14").pack(side="left", padx=(0, 10))
            except: pass
            
        tk.Label(f_club, text=f"{clube.upper()}  •  {posicao.upper()}", font=("Segoe UI", 12, "bold"), fg=TEXT_SUB, bg="#060B14").pack(side="left")

        f_ovr = tk.Frame(hero_inner, bg="#060B14")
        f_ovr.pack(side="right", padx=(20, 0))

        cor_ovr = "#4ADE80" if overall >= 85 else ("#FACC15" if overall >= 75 else "#94A3B8")
        if overall == 0: cor_ovr = "#334155"

        bg_hexa = tk.Frame(f_ovr, bg=cor_ovr, highlightthickness=1, highlightbackground=cor_ovr, padx=3, pady=3)
        bg_hexa.pack()
        in_hexa = tk.Frame(bg_hexa, bg="#060B14", padx=20, pady=10)
        in_hexa.pack()
        
        tk.Label(in_hexa, text="OVR", font=("Segoe UI", 10, "bold"), fg=cor_ovr, bg="#060B14").pack()
        tk.Label(in_hexa, text=str(overall) if overall > 0 else "--", font=("Impact", 45), fg="white", bg="#060B14").pack(pady=(0, 5))

        # ======================================================================
        # 2. CARDS BÁSICOS E MODAL DE EDIÇÃO
        # ======================================================================
        f_cards = tk.Frame(content_inner, bg=BG_BASE)
        f_cards.pack(fill="x", padx=40, pady=(0, 10))
        f_cards.columnconfigure(0, weight=1); f_cards.columnconfigure(1, weight=1); f_cards.columnconfigure(2, weight=1)

        def criar_info_row(parent, lbl, val):
            row = tk.Frame(parent, bg=BG_CARD)
            row.pack(fill="x", pady=4)
            tk.Label(row, text=lbl, font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
            tk.Label(row, text=val, font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(side="right")
            tk.Frame(parent, bg="#334155", height=1).pack(fill="x")

        # CARD 1: BIOGRAFIA
        card_bio = tk.Frame(f_cards, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
        card_bio.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        tk.Label(card_bio, text="📝 BIOGRAFIA", font=("Segoe UI", 10, "bold"), fg=ACCENT, bg=BG_CARD).pack(anchor="w", pady=(0, 10))
        criar_info_row(card_bio, "Nacionalidade", nacionalidade)
        criar_info_row(card_bio, "Nascimento", nasc)
        criar_info_row(card_bio, "Idade", f"{idade} Anos")

        # CARD 2: PERFIL FÍSICO
        card_fis = tk.Frame(f_cards, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
        card_fis.grid(row=0, column=1, sticky="nsew", padx=10)
        tk.Label(card_fis, text="⚡ PERFIL FÍSICO", font=("Segoe UI", 10, "bold"), fg="#4ADE80", bg=BG_CARD).pack(anchor="w", pady=(0, 10))
        criar_info_row(card_fis, "Altura", f"{altura} cm")
        criar_info_row(card_fis, "Peso", f"{peso} kg")
        criar_info_row(card_fis, "Pé Bom", pe)

        # CARD 3: MERCADO E CONTRATO
        card_mer = tk.Frame(f_cards, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
        card_mer.grid(row=0, column=2, sticky="nsew", padx=(10, 0))
        tk.Label(card_mer, text="💼 MERCADO & CONTRATO", font=("Segoe UI", 10, "bold"), fg="#F59E0B", bg=BG_CARD).pack(anchor="w", pady=(0, 10))
        criar_info_row(card_mer, "Clube", clube[:12])
        criar_info_row(card_mer, "Salário (Semanal)", salario_str)
        criar_info_row(card_mer, "Valor Estimado", mercado_str)

        # ======================================================================
        # MODAL LOCAL DE EDIÇÃO CORRIGIDO (BOTÃO SALVAR APARECENDO)
        # ======================================================================
        def abrir_modal_editar_info():
            md = Toplevel(self)
            md.title("Editar Informações Básicas")
            
            # Aumentado a altura do modal para 550 para o botão caber perfeitamente
            md.geometry("550x550") 
            md.configure(bg="#1F2937")
            md.resizable(False, False)
            md.grab_set()

            # Centralizar na tela
            x = (self.winfo_screenwidth() // 2) - 275
            y = (self.winfo_screenheight() // 2) - 275
            md.geometry(f"+{x}+{y}")

            mf = tk.Frame(md, bg="#1F2937")
            mf.pack(fill="both", expand=True, padx=30, pady=(20, 20))

            tk.Label(mf, text="✏️", font=("Segoe UI Emoji", 26), bg="#1F2937").pack(pady=(0, 5))
            tk.Label(mf, text="EDITAR PERFIL BÁSICO", font=("Impact", 22), bg="#1F2937", fg="white").pack()
            tk.Label(mf, text="Nota: Salário e Mercado são atualizados nas abas Financeiras.", font=("Segoe UI", 8, "italic"), bg="#1F2937", fg="#F59E0B").pack(pady=(0, 15))

            f_form = tk.Frame(mf, bg="#1F2937")
            f_form.pack(fill="x", expand=False)

            vars_dict = {
                "Nome Completo": tk.StringVar(value=self.informacoes.get("Nome Completo", "")),
                "Posição": tk.StringVar(value=self.informacoes.get("Posição", "")),
                "Nacionalidade": tk.StringVar(value=self.informacoes.get("Nacionalidade", "")),
                "Data de Nascimento": tk.StringVar(value=self.informacoes.get("Data de Nascimento", "")),
                "Pé Preferido": tk.StringVar(value=self.informacoes.get("Pé Preferido", "")),
                "Altura": tk.StringVar(value=self.informacoes.get("Altura", "")),
                "Peso": tk.StringVar(value=self.informacoes.get("Peso", ""))
            }

            labels = list(vars_dict.keys())
            for i, key in enumerate(labels):
                r = i // 2; c = i % 2
                f_campo = tk.Frame(f_form, bg="#1F2937")
                f_campo.grid(row=r, column=c, padx=10, pady=8, sticky="ew")
                f_form.columnconfigure(c, weight=1)

                tk.Label(f_campo, text=key.upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#1F2937").pack(anchor="w")
                tk.Entry(f_campo, textvariable=vars_dict[key], bg="#111827", fg="white", font=("Segoe UI", 10), relief="flat", highlightthickness=1, highlightbackground="#374151").pack(fill="x", ipady=4)

            def salvar_info():
                for k, v in vars_dict.items(): self.informacoes[k] = v.get()
                self.salvar_dados()
                md.destroy()
                for widget in parent_frame.winfo_children(): widget.destroy()
                self.perfil_do_jogador(parent_frame)

            # Botão agora fica dentro do mf, ancorado embaixo, com garantia de espaço
            tk.Button(mf, text="SALVAR DADOS", bg=ACCENT, fg="#0F172A", font=("Segoe UI", 11, "bold"), relief="flat", cursor="hand2", command=salvar_info, pady=10).pack(fill="x", side="bottom")

        f_btn_edit = tk.Frame(content_inner, bg=BG_BASE)
        f_btn_edit.pack(fill="x", padx=40, pady=(0, 10))
        btn_editar = tk.Button(f_btn_edit, text="✏️ EDITAR INFORMAÇÕES BÁSICAS", bg="#1E293B", fg="white", font=("Segoe UI", 8, "bold"), relief="flat", cursor="hand2", command=abrir_modal_editar_info)
        btn_editar.pack(side="right")

        # ======================================================================
        # 3. PAINEL DIVIDIDO (DNA ESQUERDA | ÚLTIMOS JOGOS DIREITA)
        # ======================================================================
        dashboard_split = tk.Frame(content_inner, bg=BG_BASE)
        dashboard_split.pack(fill="both", expand=True, padx=40, pady=(10, 40))
        dashboard_split.columnconfigure(0, weight=5) # 50% Esquerda
        dashboard_split.columnconfigure(1, weight=5) # 50% Direita

        # ----------------------------------------------------------------------
        # LADO ESQUERDO: DNA DO JOGADOR
        # ----------------------------------------------------------------------
        panel_dna = tk.Frame(dashboard_split, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
        panel_dna.grid(row=0, column=0, sticky="nsew", padx=(0, 10))

        head_dna = tk.Frame(panel_dna, bg="#252F3D")
        head_dna.pack(fill="x")
        tk.Frame(head_dna, bg="#A855F7", height=3).pack(fill="x", side="top")
        tk.Label(head_dna, text="🔥 DNA DO JOGADOR", font=("Segoe UI", 12, "bold"), fg="white", bg="#252F3D").pack(anchor="w", padx=20, pady=(10, 2))
        tk.Label(head_dna, text="Características táticas ativas no seu jogo.", font=("Segoe UI", 9), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w", padx=20, pady=(0, 10))

        grid_dna = tk.Frame(panel_dna, bg=BG_CARD)
        grid_dna.pack(fill="both", expand=True, padx=15, pady=15)
        grid_dna.columnconfigure(0, weight=1); grid_dna.columnconfigure(1, weight=1)

        playstyles_ativos = []
        if media_gols > 0.5: playstyles_ativos.append(("MATADOR", "Alta conversão de chances.", "#EF4444", "🎯"))
        if media_assis > 0.3: playstyles_ativos.append(("MAESTRO", "Visão de elite e passes.", "#38BDF8", "👁️"))
        if t_jogos >= 50 and (t_gols + t_assis) > t_jogos: playstyles_ativos.append(("GÊNIO", "+ de 1 gol/partida.", "#F59E0B", "👑"))
        if t_titulos >= 5: playstyles_ativos.append(("VENCEDOR", "Acostumado a taças.", "#FACC15", "🏆"))
        if t_ama > t_jogos * 0.25 or t_ver > 2: playstyles_ativos.append(("XERIFE", "Impõe respeito.", "#94A3B8", "🛑"))
        if t_jogos > 150: playstyles_ativos.append(("INCANSÁVEL", "Alta resistência.", "#4ADE80", "🔋"))
        if not playstyles_ativos: playstyles_ativos.append(("PROMISSOR", "Em fase de evolução.", "#A855F7", "🌱"))

        for i, (titulo, desc, cor, icon) in enumerate(playstyles_ativos):
            c = i % 2; r = i // 2 
            
            box = tk.Frame(grid_dna, bg="#060B14", highlightthickness=1, highlightbackground="#334155")
            box.grid(row=r, column=c, sticky="nsew", padx=8, pady=8)
            tk.Frame(box, bg=cor, height=2).pack(fill="x", side="top")
            
            inner = tk.Frame(box, bg="#060B14", padx=10, pady=10)
            inner.pack(fill="both", expand=True)
            
            f_top = tk.Frame(inner, bg="#060B14")
            f_top.pack(fill="x")
            tk.Label(f_top, text=icon, font=("Segoe UI Emoji", 16), bg="#060B14").pack(side="left", padx=(0, 5))
            tk.Label(f_top, text=titulo, font=("Impact", 13), fg=cor, bg="#060B14").pack(side="left")
            tk.Label(inner, text=desc, font=("Segoe UI", 8), fg=TEXT_SUB, bg="#060B14", wraplength=180, justify="left").pack(anchor="w", pady=(5,0))

        # ----------------------------------------------------------------------
        # LADO DIREITO: ÚLTIMAS ATUAÇÕES 
        # ----------------------------------------------------------------------
        panel_matches = tk.Frame(dashboard_split, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
        panel_matches.grid(row=0, column=1, sticky="nsew", padx=(10, 0))

        head_matches = tk.Frame(panel_matches, bg="#252F3D")
        head_matches.pack(fill="x")
        tk.Frame(head_matches, bg="#4ADE80", height=3).pack(fill="x", side="top")
        tk.Label(head_matches, text="⏱️ ÚLTIMAS ATUAÇÕES", font=("Segoe UI", 12, "bold"), fg="white", bg="#252F3D").pack(anchor="w", padx=20, pady=(10, 2))
        tk.Label(head_matches, text="Clique no card para abrir o relatório de Scout.", font=("Segoe UI", 9), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w", padx=20, pady=(0, 10))

        list_matches = tk.Frame(panel_matches, bg=BG_CARD)
        list_matches.pack(fill="both", expand=True, padx=15, pady=10)

        ultimos_jogos = self.ultimas_performances[:5] if hasattr(self, 'ultimas_performances') else []

        if not ultimos_jogos:
            tk.Label(list_matches, text="Nenhuma partida registrada no histórico.", font=("Segoe UI", 10, "italic"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="center", pady=40)
        else:
            for jogo in ultimos_jogos:
                j_data = jogo.get("Data", "")
                j_adv = jogo.get("Adversário", "Adversário")
                j_res = jogo.get("Resultado", "0-0")
                j_comp = jogo.get("Competição", "")
                j_gols = int(jogo.get("Gols", 0))
                j_assists = int(jogo.get("Assistências", 0))
                j_nota = float(jogo.get("Nota", 6.0))
                j_local = jogo.get("Local", "C")
                j_time = jogo.get("Time", clube)

                cor_res = "#94A3B8"
                try:
                    p_limpo = j_res.split(" ")[0]
                    g1, g2 = map(int, p_limpo.split("-"))
                    m_gols = g1 if j_local == "C" else g2
                    a_gols = g2 if j_local == "C" else g1
                    if m_gols > a_gols: cor_res = "#4ADE80"
                    elif m_gols < a_gols: cor_res = "#EF4444"
                except: pass

                card_m = tk.Frame(list_matches, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", cursor="hand2")
                card_m.pack(fill="x", pady=4, ipady=6)
                
                tk.Frame(card_m, bg=cor_res, width=4).pack(side="left", fill="y")
                
                f_inf = tk.Frame(card_m, bg="#252F3D", width=95)
                f_inf.pack(side="left", fill="y", padx=10)
                f_inf.pack_propagate(False)
                
                f_inf_txt = tk.Frame(f_inf, bg="#252F3D")
                f_inf_txt.place(relx=0, rely=0.5, anchor="w")
                tk.Label(f_inf_txt, text=j_data, font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(anchor="w")
                tk.Label(f_inf_txt, text=j_comp[:14], font=("Segoe UI", 7), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")

                f_score = tk.Frame(card_m, bg="#252F3D")
                f_score.pack(side="left", expand=True)

                t_casa = j_time if j_local == "C" else j_adv
                t_fora = j_adv if j_local == "C" else j_time

                def render_mini_logo(parent, name):
                    path = self.club_logo_paths.get(name, f"Logos/{name.strip()}.png")
                    if os.path.exists(resource_path(path)):
                        try:
                            img = ImageTk.PhotoImage(Image.open(resource_path(path)).resize((22, 22), Image.Resampling.LANCZOS))
                            self.cache_imgs_perfil.append(img)
                            tk.Label(parent, image=img, bg="#252F3D").pack(side="left", padx=5)
                            return
                        except: pass
                    tk.Label(parent, text=name[:3].upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(side="left", padx=5)

                f_c = tk.Frame(f_score, bg="#252F3D"); f_c.pack(side="left")
                tk.Label(f_c, text=t_casa[:3].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")
                render_mini_logo(f_c, t_casa)

                tk.Label(f_score, text=j_res, font=("Impact", 16), fg=cor_res, bg="#252F3D").pack(side="left", padx=10)

                f_f = tk.Frame(f_score, bg="#252F3D"); f_f.pack(side="left")
                render_mini_logo(f_f, t_fora)
                tk.Label(f_f, text=t_fora[:3].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")

                f_st = tk.Frame(card_m, bg="#252F3D")
                f_st.pack(side="right", padx=10)

                cor_nota = "#4ADE80" if j_nota >= 7.5 else ("#FACC15" if j_nota >= 6.5 else "#EF4444")
                tk.Label(f_st, text=f"{j_nota:.1f}", font=("Impact", 16), fg=cor_nota, bg="#252F3D").pack(side="right", padx=(10, 0))

                if j_gols > 0: tk.Label(f_st, text=f"⚽ {j_gols}", font=("Segoe UI", 9, "bold"), fg="#4ADE80", bg="#252F3D").pack(side="right", padx=3)
                if j_assists > 0: tk.Label(f_st, text=f"🤝 {j_assists}", font=("Segoe UI", 9, "bold"), fg="#38BDF8", bg="#252F3D").pack(side="right", padx=3)

                def on_ent(e, c=card_m, fi=f_inf, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fs=f_st):
                    for w in [c, fi, fit, fp, fc, ff, fs]: w.configure(bg="#334155") 
                    for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fs.winfo_children():
                        if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#334155")

                def on_lea(e, c=card_m, fi=f_inf, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fs=f_st):
                    for w in [c, fi, fit, fp, fc, ff, fs]: w.configure(bg="#252F3D")
                    for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fs.winfo_children():
                        if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#252F3D")
                
                card_m.bind("<Enter>", on_ent)
                card_m.bind("<Leave>", on_lea)

                jogo_dict = {
                    "data": j_data, "adv": j_adv, "comp": j_comp, "local": j_local,
                    "clube": j_time, "res": j_res, "status": jogo.get("Posição", ""),
                    "minutos": jogo.get("Minutos", 0), "gols": j_gols, "assists": j_assists,
                    "amarelos": jogo.get("Amarelos", 0), "vermelhos": jogo.get("Vermelhos", 0)
                }

                def ao_clicar(e, j=jogo_dict): self.abrir_popup_partida(j)
                
                card_m.bind("<Button-1>", ao_clicar)
                for w in [f_inf, f_inf_txt, f_score, f_c, f_f, f_st]:
                    w.bind("<Button-1>", ao_clicar)
                    for sub_w in w.winfo_children():
                        sub_w.bind("<Button-1>", ao_clicar)

        tk.Frame(content_inner, bg=BG_BASE, height=50).pack()

