    def criar_grafico_radar_atributos(self, parent_frame, atributos, bg_color="#1E293B", line_color="#38BDF8"):
        labels = list(atributos.keys())
        stats = list(atributos.values())
        num_vars = len(labels)

        # Fechar o ciclo
        angles = np.linspace(0, 2 * np.pi, num_vars, endpoint=False).tolist()
        stats += stats[:1]
        angles += angles[:1]

        # Configurações de Tamanho
        fig, ax = plt.subplots(figsize=(3, 3), subplot_kw=dict(polar=True))
        
        # COR DE FUNDO TOTAL (Transparente ou igual ao card)
        fig.patch.set_facecolor(bg_color)
        ax.set_facecolor(bg_color)

        # Plotagem
        # Linha sólida neon
        ax.plot(angles, stats, color=line_color, linewidth=2, linestyle='solid', zorder=10)
        # Preenchimento com transparência
        ax.fill(angles, stats, color=line_color, alpha=0.25, zorder=9)

        # Customização dos Eixos (Grid)
        ax.set_yticklabels([]) # Sem números radiais
        
        # Labels externos (Skill, Attack...)
        ax.set_xticks(angles[:-1])
        ax.set_xticklabels(labels, color="#94A3B8", size=9, fontweight="bold")

        # Escala
        ax.set_ylim(0, 100)
        
        # Estilo do Grid (Teia de Aranha)
        # Remove o círculo externo padrão
        ax.spines['polar'].set_visible(False)
        
        # Grid customizado
        ax.grid(color="#334155", linestyle='-', linewidth=0.8, alpha=0.5) # Grid cinza escuro
        
        # Adiciona círculos de referência manuais para ficar mais bonito
        ticks = [20, 40, 60, 80, 100]
        for t in ticks:
            # Desenha círculo tracejado
            grid_circle = plt.Circle((0, 0), t, transform=ax.transData._b, fill=False, edgecolor="#334155", linestyle='--', alpha=0.3)
            ax.add_artist(grid_circle)

        plt.tight_layout()

        # Renderizar
        canvas = FigureCanvasTkAgg(fig, master=parent_frame)
        canvas_widget = canvas.get_tk_widget()
        canvas_widget.pack(fill="both", expand=True)
        self.matplotlib_canvases.append(canvas)
        canvas.draw()

    def _normalizar_dados_para_timeline(self, dados_raw, tipo_estrutura):
        """Padroniza dados e ordena do MAIS RECENTE para o MAIS ANTIGO."""
        timeline_data = [] 
        
        # TIPO 1: Ligas e Copas (Listas)
        if tipo_estrutura == "dict_lista":
            for ano, lista_jogos in dados_raw.items():
                jogos_proc = []
                for jogo in lista_jogos:
                    try:
                        if isinstance(jogo, list) and len(jogo) > 10:
                            pos_motivo = str(jogo[7]) if len(jogo) > 7 else "Não Relacionado"
                            ca = int(jogo[10])
                            e2 = int(jogo[11])
                            ed = int(jogo[12])
                            mins = int(jogo[13]) if len(jogo) > 13 else 0
                            
                            j = {
                                "data": jogo[2], "local": jogo[3], "clube": jogo[4], "adv": jogo[5],
                                "res": jogo[6], "gols": int(jogo[8]), "assists": int(jogo[9]),
                                "comp": jogo[0], "rodada": str(jogo[1]),
                                "amarelos": ca,
                                "vermelhos": e2 + ed,
                                "minutos": mins,
                                "status": pos_motivo
                            }
                            jogos_proc.append(j)
                    except: pass
                
                if jogos_proc:
                    try: 
                        # CORREÇÃO AQUI: reverse=True para ficar do mais recente (Dez) para o antigo (Jan)
                        jogos_proc.sort(key=lambda x: datetime.datetime.strptime(x["data"], "%d/%m/%Y"), reverse=True)
                    except: pass
                    timeline_data.append({"ano": ano, "jogos": jogos_proc})

        # TIPO 2: Supercopas (Dicionários Nomeados)
        elif tipo_estrutura == "dict_nested":
            for ano, dict_comps in dados_raw.items():
                jogos_proc = []
                for nome_comp, lista_objs in dict_comps.items():
                    for jogo in lista_objs:
                        v_total = int(jogo.get("Expulsões (Dois Amarelos)", 0)) + int(jogo.get("Expulsões (Vermelho Direto)", 0))
                        mins = int(jogo.get("Minutos Jogados", 0))
                        pos_motivo = jogo.get("Posição", "Não Relacionado")
                        
                        j = {
                            "data": jogo.get("Data"), "local": jogo.get("Cidade"), 
                            "clube": jogo.get("Clube"), "adv": jogo.get("Adversário"),
                            "res": jogo.get("Resultado"), "gols": int(jogo.get("Gols", 0)), 
                            "assists": int(jogo.get("Assistências", 0)),
                            "comp": nome_comp, "rodada": jogo.get("Rodada"),
                            "amarelos": int(jogo.get("Cartões Amarelos", 0)),
                            "vermelhos": v_total,
                            "minutos": mins,
                            "status": pos_motivo
                        }
                        jogos_proc.append(j)
                if jogos_proc:
                    try: 
                        # CORREÇÃO AQUI TAMBÉM: reverse=True
                        jogos_proc.sort(key=lambda x: datetime.datetime.strptime(x["data"], "%d/%m/%Y"), reverse=True)
                    except: pass
                    timeline_data.append({"ano": ano, "jogos": jogos_proc})

        # Ordena os anos do maior para o menor (já estava correto, mas mantemos)
        timeline_data.sort(key=lambda x: x['ano'], reverse=True)
        return timeline_data

    def _render_logo_mini(self, parent, nome_clube):
        """Renderiza a logo pequena no card. SE NÃO TIVER, BAIXA AUTOMATICAMENTE."""
        
        # 1. Verifica se já temos o caminho no cache
        path = self.club_logo_paths.get(nome_clube)
        
        # 2. Se não, tenta adivinhar o caminho padrão
        if not path:
            safe_name = nome_clube.strip()
            path = f"Logos/{safe_name}.png"
        
        # 3. AUTO-DOWNLOAD: Se o arquivo não existir, chama a API
        if not os.path.exists(path):
            # Chama a função global de download que você já tem
            # Nota: Pode dar uma leve travadinha na 1ª vez que baixar
            novo_caminho = baixar_logo_agora(nome_clube)
            if novo_caminho:
                path = novo_caminho
                self.club_logo_paths[nome_clube] = path # Salva no cache da sessão
        
        # 4. Renderiza a imagem (se existir agora)
        if path and os.path.exists(path):
            try:
                pil = Image.open(resource_path(path)).resize((32, 32), Image.Resampling.LANCZOS)
                tk_icon = ImageTk.PhotoImage(pil)
                self.club_logo_images.append(tk_icon) 
                tk.Label(parent, image=tk_icon, bg="#1E293B").pack(side="left", padx=5)
                return
            except Exception as e:
                print(f"Erro render logo {nome_clube}: {e}")
        
        # 5. Fallback (Texto com as 3 primeiras letras) se falhar tudo
        tk.Label(parent, text=nome_clube[:3].upper(), font=("Segoe UI", 9, "bold"), fg="#94A3B8", bg="#1E293B").pack(side="left", padx=5)

    def criar_layout_timeline(self, parent_frame, titulo_aba, dados_raw, tipo_estrutura, subtitulo_opcional=None):
        """
        Timeline Premium: Motor unificado para Ligas, Copas e Campeonatos Continentais.
        Apresenta Dashboard de KPIs, Gráfico de Aproveitamento e Cards de Jogos Compactos.
        """
        import tkinter as tk
        from tkinter import ttk
        import datetime
        from PIL import Image, ImageTk
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        from collections import Counter
        import os

        # --- ESTILOS & CORES ---
        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"
        
        C_GOLS = "#4ADE80"
        C_ASSIS = "#60A5FA"
        C_JOGOS = "#F8FAFC"

        self.style.configure("TimeMain.TFrame", background=BG_BASE)
        
        # --- DADOS ---
        timeline = self._normalizar_dados_para_timeline(dados_raw, tipo_estrutura)
        anos_disponiveis = [s['ano'] for s in timeline]
        opcoes_combo = ["Todas as Temporadas"] + anos_disponiveis

        # --- ESTRUTURA ---
        frame_main = ttk.Frame(parent_frame, style="TimeMain.TFrame")
        frame_main.pack(fill="both", expand=True)

        canvas = tk.Canvas(frame_main, bg=BG_BASE, highlightthickness=0)
        scrollbar = ttk.Scrollbar(frame_main, orient="vertical", command=canvas.yview)
        
        inner = ttk.Frame(canvas, style="TimeMain.TFrame")
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e):
            if e.width > 1 and canvas.winfo_exists(): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        
        def _on_mousewheel(event):
            if canvas.winfo_exists(): 
                canvas.yview_scroll(int(-1*(event.delta/120)), "units")

        frame_main.bind('<Enter>', lambda e: canvas.bind_all("<MouseWheel>", _on_mousewheel))
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # --- HEADER DA PÁGINA ---
        pad_top = 30 if not subtitulo_opcional else 15
        header = tk.Frame(inner, bg=BG_BASE)
        header.pack(fill="x", padx=40, pady=(pad_top, 10))
        tk.Label(header, text=titulo_aba.upper(), font=("Impact", 32), fg="white", bg=BG_BASE).pack(anchor="w")
        sub = subtitulo_opcional if subtitulo_opcional else "Dossiê estatístico e histórico de partidas da competição."
        tk.Label(header, text=sub, font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_BASE).pack(anchor="w")

        # --- CONTROLES (FILTRO) ---
        ctrl_frame = tk.Frame(inner, bg=BG_BASE)
        ctrl_frame.pack(fill="x", padx=40, pady=(0, 20))
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=ACCENT, bg=BG_BASE).pack(anchor="w")
        
        valor_padrao = anos_disponiveis[0] if anos_disponiveis else opcoes_combo[0]
        selected_season = tk.StringVar(value=valor_padrao)
        
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_combo, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        content_container = tk.Frame(inner, bg=BG_BASE)
        content_container.pack(fill="both", expand=True)

        if not timeline:
            tk.Label(content_container, text="Nenhum registro encontrado para esta competição.", fg=TEXT_SUB, bg=BG_BASE, font=("Segoe UI", 12)).pack(pady=50)
            return

        if not hasattr(self, 'fig_timeline'): self.fig_timeline = []
        self.render_queue = [] 
        self.after_id = None   

        # ======================================================================
        # DASHBOARD HERO (Com a NOVA GRADE DE KPIs)
        # ======================================================================
        def desenhar_card_resumo(filtro_ano, lista_jogos):
            jogos_validos = [j for j in lista_jogos if j.get('minutos', 0) > 0 and j.get('status') not in ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]]
            
            t_jogos = len(jogos_validos)
            t_gols = sum(j['gols'] for j in jogos_validos)
            t_assis = sum(j['assists'] for j in jogos_validos)
            t_mins = sum(j.get('minutos', 0) for j in jogos_validos)

            # CÁLCULO DE MOTM (Puxando do histórico completo)
            t_motm = 0
            for j in jogos_validos:
                for up in getattr(self, 'ultimas_performances', []):
                    if up.get("Data") == j.get("data") and up.get("Adversário") == j.get("adv"):
                        if up.get("Detalhes", {}).get("MOTM"):
                            t_motm += 1
                        break
            
            v, e, d = 0, 0, 0
            comps = []
            for j in jogos_validos:
                comps.append(j['comp'])
                try:
                    p_limpo = j['res'].split(" ")[0]
                    g1, g2 = map(int, p_limpo.split("-"))
                    if j['local'] == 'F': g1, g2 = g2, g1
                    if g1 > g2: v += 1
                    elif g1 < g2: d += 1
                    else: e += 1
                except: pass

            comp_principal = Counter(comps).most_common(1)[0][0] if comps else titulo_aba

            dash_frame = tk.Frame(content_container, bg=BG_BASE)
            dash_frame.pack(fill="x", padx=40, pady=(10, 20))
            dash_frame.columnconfigure(0, weight=7)
            dash_frame.columnconfigure(1, weight=3)

            # --- LADO ESQUERDO: HERO BANNER (LOGO + KPIs) ---
            kpi_card = tk.Frame(dash_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            kpi_card.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
            tk.Frame(kpi_card, bg=ACCENT, height=4).pack(fill="x", side="top")
            
            f_top_kpi = tk.Frame(kpi_card, bg=BG_CARD)
            f_top_kpi.pack(fill="x", padx=20, pady=(15, 10))
            
            f_logo = tk.Frame(f_top_kpi, bg=BG_CARD)
            f_logo.pack(side="left", padx=(0, 20))
            
            safe_name = comp_principal.strip()
            path_logo = f"Logos/{safe_name}.png"
            if not os.path.exists(resource_path(path_logo)):
                novo = baixar_logo_competicao(safe_name) 
                if novo: path_logo = novo
                
            if os.path.exists(resource_path(path_logo)):
                try:
                    pil_img = Image.open(resource_path(path_logo)).resize((60, 60), Image.Resampling.LANCZOS)
                    tk_img = ImageTk.PhotoImage(pil_img)
                    if not hasattr(self, 'comp_logo_cache'): self.comp_logo_cache = []
                    self.comp_logo_cache.append(tk_img)
                    tk.Label(f_logo, image=tk_img, bg=BG_CARD).pack()
                except: tk.Label(f_logo, text="🏆", font=("Segoe UI Emoji", 35), bg=BG_CARD).pack()
            else:
                tk.Label(f_logo, text="🏆", font=("Segoe UI Emoji", 35), bg=BG_CARD).pack()

            f_tit = tk.Frame(f_top_kpi, bg=BG_CARD)
            f_tit.pack(side="left")
            
            nome_limpo_comp = comp_principal.upper()
            if len(nome_limpo_comp) > 25: nome_limpo_comp = nome_limpo_comp[:22] + "..."
            
            tk.Label(f_tit, text=nome_limpo_comp, font=("Impact", 28), fg="white", bg=BG_CARD).pack(anchor="w")
            lbl_sub = "Visão Geral da Carreira" if filtro_ano == "Todas as Temporadas" else f"Estatísticas da Temporada {filtro_ano}"
            tk.Label(f_tit, text=lbl_sub, font=("Segoe UI", 11, "bold"), fg=ACCENT, bg=BG_CARD).pack(anchor="w")

            # --- A NOVA GRADE DE ESTATÍSTICAS (3 Colunas x 2 Linhas) ---
            f_kpis_grid = tk.Frame(kpi_card, bg=BG_CARD)
            f_kpis_grid.pack(fill="x", padx=15, pady=(0, 15))
            
            for i in range(3): f_kpis_grid.columnconfigure(i, weight=1)

            def add_kpi(parent, title, val, color, icon, row_idx, col_idx):
                f = tk.Frame(parent, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", padx=15, pady=8)
                f.grid(row=row_idx, column=col_idx, sticky="nsew", padx=5, pady=5)
                f_t = tk.Frame(f, bg="#252F3D")
                f_t.pack(anchor="w")
                tk.Label(f_t, text=icon, font=("Segoe UI Emoji", 10), bg="#252F3D", fg="white").pack(side="left", padx=(0,5))
                tk.Label(f_t, text=title, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(side="left")
                tk.Label(f, text=str(val), font=("Segoe UI", 20, "bold"), fg=color, bg="#252F3D").pack(anchor="w", pady=(2,0))

            lista_kpis = [
                ("JOGOS", t_jogos, "white", "👕"),
                ("GOLS", t_gols, C_GOLS, "⚽"),
                ("ASSISTS", t_assis, C_ASSIS, "🤝"),
                ("MÉDIA G/J", f"{t_gols/t_jogos if t_jogos>0 else 0:.2f}", "#F59E0B", "🔥"),
                ("MOTM", t_motm, "#A855F7", "🏅"),
                ("MINUTOS", f"{t_mins:,}".replace(",", "."), "#94A3B8", "⏱️")
            ]

            for idx, (title, val, color, icon) in enumerate(lista_kpis):
                r = idx // 3
                c = idx % 3
                add_kpi(f_kpis_grid, title, val, color, icon, r, c)

            # --- LADO DIREITO: Gráfico Donut de Aproveitamento ---
            chart_card = tk.Frame(dash_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=15, pady=15)
            chart_card.grid(row=0, column=1, sticky="nsew", padx=(10, 0))
            tk.Label(chart_card, text="RETROSPECTO DA EQUIPE", font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(anchor="center", pady=(0, 5))
            
            if t_jogos > 0:
                fig, ax = plt.subplots(figsize=(2.5, 2.5), facecolor=BG_CARD)
                sizes = [v, e, d]
                colors = ["#10B981", "#94A3B8", "#EF4444"]
                labels_p = ["V", "E", "D"]
                
                fsizes = [s for s in sizes if s > 0]
                fcolors = [c for s, c in zip(sizes, colors) if s > 0]
                flabels = [l for s, l in zip(sizes, labels_p) if s > 0]
                
                if fsizes:
                    wedges, texts, autotexts = ax.pie(fsizes, colors=fcolors, autopct='%1.0f%%', startangle=90, 
                           textprops=dict(color="#0F172A", fontsize=9, fontweight="bold"),
                           wedgeprops=dict(width=0.4, edgecolor=BG_CARD, linewidth=2))
                    ax.text(0, 0, f"{t_jogos}\nJOGOS", ha='center', va='center', fontsize=11, fontweight='bold', color="white")
                    ax.legend(wedges, flabels, loc="lower center", bbox_to_anchor=(0.5, -0.15), frameon=False, labelcolor=TEXT_SUB, ncol=3, fontsize=9)
                    
                plt.tight_layout()
                canvas_pie = FigureCanvasTkAgg(fig, master=chart_card)
                canvas_pie.draw()
                canvas_pie.get_tk_widget().pack(fill="both", expand=True)
                
                self.fig_timeline.append(fig)
                self.matplotlib_canvases.append(canvas_pie)
            else:
                tk.Label(chart_card, text="Sem dados de resultado", fg=TEXT_SUB, bg=BG_CARD).pack(expand=True)

        # --- RENDERIZAÇÃO EM LOTE DOS JOGOS ---
        def desenhar_lote():
            if not content_container.winfo_exists(): return
            itens_por_vez = 6
            count = 0
            while self.render_queue and count < itens_por_vez:
                try:
                    tipo, dados = self.render_queue.pop(0)
                    if tipo == "season_header":
                        f_sep = tk.Frame(content_container, bg=BG_BASE)
                        f_sep.pack(fill="x", padx=40, pady=(20, 10))
                        tk.Label(f_sep, text=f"TEMPORADA {dados}", font=("Segoe UI", 12, "bold"), fg="#38BDF8", bg=BG_BASE).pack(side="left")
                        tk.Frame(f_sep, bg="#334155", height=1).pack(side="left", fill="x", expand=True, padx=(15, 0))
                    elif tipo == "match_card":
                        _criar_card_jogo(dados)
                    count += 1
                except: break

            if self.render_queue:
                if hasattr(self, 'loading_label') and self.loading_label.winfo_exists(): self.loading_label.pack_forget()
                self.after_id = self.after(10, desenhar_lote)
            else:
                if hasattr(self, 'loading_label') and self.loading_label.winfo_exists(): self.loading_label.destroy()
                tk.Frame(content_container, bg=BG_BASE, height=50).pack()

        # --- CARD DE JOGO COMPACTO (Estilo Premium) ---
        def _criar_card_jogo(jogo):
            wrapper = tk.Frame(content_container, bg=BG_BASE)
            wrapper.pack(fill="x", padx=40, pady=4)
            
            cor_res = "#94A3B8"
            try:
                placar_limpo = jogo['res'].split(" ")[0]
                g_fav, g_con = map(int, placar_limpo.split("-"))
                if jogo['local'] == 'F': g_fav, g_con = g_con, g_fav
                if g_fav > g_con: cor_res = "#4ADE80"
                elif g_fav < g_con: cor_res = "#EF4444"
            except: pass

            card = tk.Frame(wrapper, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", cursor="hand2")
            card.pack(fill="x", ipady=6)
            tk.Frame(card, bg=cor_res, width=4).pack(side="left", fill="y")

            # Bloco Esquerdo (Data e Info)
            f_info = tk.Frame(card, bg="#252F3D", width=120)
            f_info.pack(side="left", fill="y", padx=10)
            f_info.pack_propagate(False)
            
            f_inf_txt = tk.Frame(f_info, bg="#252F3D")
            f_inf_txt.place(relx=0, rely=0.5, anchor="w")
            tk.Label(f_inf_txt, text=jogo['data'], font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(anchor="w")
            tk.Label(f_inf_txt, text=f"{jogo['comp'][:15]}", font=("Segoe UI", 7), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")

            # Bloco Central (Placar)
            f_score = tk.Frame(card, bg="#252F3D")
            f_score.pack(side="left", expand=True)

            nome_casa = jogo['clube'] if jogo['local'] == 'C' else jogo['adv']
            nome_fora = jogo['adv'] if jogo['local'] == 'C' else jogo['clube']

            def render_mini_logo(parent, name, bg_c):
                path = self.club_logo_paths.get(name, f"Logos/{name.strip()}.png")
                try:
                    if os.path.exists(resource_path(path)):
                        img = ImageTk.PhotoImage(Image.open(resource_path(path)).resize((25, 25), Image.Resampling.LANCZOS))
                        if not hasattr(self, 'club_logo_images'): self.club_logo_images = []
                        self.club_logo_images.append(img)
                        tk.Label(parent, image=img, bg=bg_c).pack(side="left", padx=5)
                        return
                except: pass
                tk.Label(parent, text=name[:3].upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=bg_c).pack(side="left", padx=5)

            f_c = tk.Frame(f_score, bg="#252F3D"); f_c.pack(side="left")
            tk.Label(f_c, text=nome_casa[:15].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")
            render_mini_logo(f_c, nome_casa, "#252F3D")

            tk.Label(f_score, text=jogo['res'], font=("Impact", 16), fg=cor_res, bg="#252F3D").pack(side="left", padx=15)

            f_f = tk.Frame(f_score, bg="#252F3D"); f_f.pack(side="left")
            render_mini_logo(f_f, nome_fora, "#252F3D")
            tk.Label(f_f, text=nome_fora[:15].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")

            # Bloco Direito (Stats)
            f_perf = tk.Frame(card, bg="#252F3D")
            f_perf.pack(side="right", padx=15)
            
            if jogo['gols'] > 0: tk.Label(f_perf, text=f"⚽ {jogo['gols']}", font=("Segoe UI", 9, "bold"), fg="#4ADE80", bg="#252F3D").pack(side="right", padx=3)
            if jogo['assists'] > 0: tk.Label(f_perf, text=f"🤝 {jogo['assists']}", font=("Segoe UI", 9, "bold"), fg="#38BDF8", bg="#252F3D").pack(side="right", padx=3)
            
            if jogo.get('vermelhos', 0) > 0: tk.Label(f_perf, text="🟥 Expulso", font=("Segoe UI", 9, "bold"), fg="#EF4444", bg="#252F3D").pack(side="right", padx=3)
            elif jogo.get('amarelos', 0) > 0: tk.Label(f_perf, text="🟨 Amarelo", font=("Segoe UI", 9, "bold"), fg="#FACC15", bg="#252F3D").pack(side="right", padx=3)

            mins = jogo.get('minutos', 0)
            if mins == 0 and jogo['gols'] == 0 and jogo['assists'] == 0:
                tk.Label(f_perf, text=jogo.get('status', 'Não Jogou'), font=("Segoe UI", 8, "italic"), fg="#64748B", bg="#252F3D").pack(side="right")

            # Eventos Interativos
            def on_ent(e, c=card, fi=f_info, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fper=f_perf):
                for w in [c, fi, fit, fp, fc, ff, fper]: w.configure(bg="#334155")
                for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fper.winfo_children():
                    if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#334155")

            def on_lea(e, c=card, fi=f_info, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fper=f_perf):
                for w in [c, fi, fit, fp, fc, ff, fper]: w.configure(bg="#252F3D")
                for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fper.winfo_children():
                    if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#252F3D")
            
            card.bind("<Enter>", on_ent)
            card.bind("<Leave>", on_lea)

            def ao_clicar(e, j=jogo): 
                j_pop = {
                    "data": j['data'], "adv": j['adv'], "comp": j['comp'], "rodada": j['rodada'], "local": j['local'],
                    "clube": j['clube'], "res": j['res'], "status": j['status'], "minutos": j['minutos'],
                    "gols": j['gols'], "assists": j['assists'], "amarelos": j['amarelos'], "vermelhos": j['vermelhos']
                }
                self.abrir_popup_partida(j_pop)
            
            for w in [card, f_info, f_inf_txt, f_score, f_c, f_f, f_perf]:
                w.bind("<Button-1>", ao_clicar)
                for sub_w in w.winfo_children(): sub_w.bind("<Button-1>", ao_clicar)

        def iniciar_renderizacao(event=None):
            if self.after_id:
                try: self.after_cancel(self.after_id)
                except: pass
                self.after_id = None

            for f in self.fig_timeline: plt.close(f)
            self.fig_timeline.clear()

            for widget in content_container.winfo_children(): widget.destroy()
            
            self.loading_label = tk.Label(content_container, text="⟳ CARREGANDO DADOS...", font=("Segoe UI", 12, "bold"), fg=ACCENT, bg=BG_BASE)
            self.loading_label.pack(pady=20)
            self.update_idletasks() 

            filtro = selected_season.get()
            self.render_queue = []
            
            jogos_para_resumo = []
            
            for season in timeline:
                if filtro == "Todas as Temporadas" or season['ano'] == filtro:
                    jogos_para_resumo.extend(season['jogos'])
                    if filtro == "Todas as Temporadas":
                        self.render_queue.append(("season_header", season['ano']))
                    for jogo in season['jogos']:
                        self.render_queue.append(("match_card", jogo))
            
            if jogos_para_resumo:
                desenhar_card_resumo(filtro, jogos_para_resumo)
            else:
                tk.Label(content_container, text="Sem dados para este filtro.", fg=TEXT_SUB, bg=BG_BASE).pack(pady=20)
            
            desenhar_lote()

        combo.bind("<<ComboboxSelected>>", iniciar_renderizacao)
        self.after(100, iniciar_renderizacao)

    def criar_tabela_ultimas_performances(self, parent_frame, performances):
        # Define table columns
        cols = ("Data", "Comp.", "Local", "Adv.", "Res.", "G", "A", "Nota")

        # Frame for the treeview table
        tree_frame = ttk.Frame(parent_frame, style="Custom.TFrame")
        tree_frame.pack(fill="x", expand=True, padx=5, pady=(5,0))

        # Create Treeview widget
        tree = ttk.Treeview(tree_frame, columns=cols, show="headings", style="Treeview", height=3)

        # Define column widths and text alignment
        col_widths = {"Data": 65, "Comp.": 80, "Local": 30, "Adv.": 80, "Res.": 40, "G": 25, "A": 25, "Nota": 35}
        col_anchors = {"Data": "center", "Comp.": "w", "Local": "center", "Adv.": "w", "Res.": "center", "G": "center", "A": "center", "Nota": "center"}

        # Configure column headings and properties
        for col in cols:
            tree.heading(col, text=col, anchor="center")
            tree.column(col, anchor=col_anchors.get(col, "center"), width=col_widths.get(col, 80), minwidth=col_widths.get(col, 20))

        # Insert data into the table with alternating row colors
        for i, perf in enumerate(performances):
            nota_formatada = f"{perf['Nota']:.1f}" if isinstance(perf['Nota'], float) else perf['Nota']
            # Garante que "Gols", "Assistências" e "Nota" sejam strings para evitar erros com '-'
            valores = (perf["Data"], perf["Competição"], perf["Local"], perf["Adversário"], perf["Resultado"],
                       str(perf["Gols"]), str(perf["Assistências"]), str(nota_formatada))
            tag = "evenrow" if i % 2 == 0 else "oddrow"
            tree.insert("", "end", values=valores, tags=(tag,))

        # Configure alternating row colors for the Treeview
        tree.tag_configure("oddrow", background="#44546A", foreground="white") # Darker shade of gray
        tree.tag_configure("evenrow", background="#3A4A5E", foreground="white") # Same as Treeview background

        tree.pack(fill="x", expand=True) # Pack the treeview
        self.auto_adjust_treeview_columns(tree)
        return tree # Return the Treeview instance

    def toggle_performances_view(self, event=None):
        """
        Alterna entre a exibição de 'Últimas 3 Partidas' e 'Próximas 3 Partidas'.
        Atualiza o título da tabela e o conteúdo, além do ícone da seta.
        """
        # Determina o novo estado, título e dados
        if self.current_performance_view == "ultimas":
            self.current_performance_view = "proximas"
            new_title = "Próximas Partidas"
            new_data = self.proximas_performances
            new_arrow_text = "◀"  # Seta para a esquerda quando mostra "Próximas"
        else:
            self.current_performance_view = "ultimas"
            new_title = "Últimas Partidas"
            new_data = self.ultimas_performances
            new_arrow_text = "▶"  # Seta para a direita quando mostra "Últimas"

        # Atualiza o título do Label
        self.performances_title_label.config(text=new_title)

        # Atualiza o texto/direção do botão de seta
        self.arrow_button.config(text=new_arrow_text)

        # Limpa o conteúdo existente da tabela (Treeview)
        for item in self.performances_tree.get_children():
            self.performances_tree.delete(item)

        # Preenche a tabela com os novos dados
        for i, perf in enumerate(new_data):
            # Garante que "Gols", "Assistências", "Nota" e "Resultado" sejam strings para evitar erros com '-'
            valores = (perf["Data"], perf["Competição"], perf["Local"], perf["Adversário"], str(perf["Resultado"]),
                       str(perf["Gols"]), str(perf["Assistências"]), str(perf["Nota"]))
            
            tag = "evenrow" if i % 2 == 0 else "oddrow"
            self.performances_tree.insert("", "end", values=valores, tags=(tag,))

        # Efeito visual de "flash" no botão da seta para indicar a transição
        self.auto_adjust_treeview_columns(self.performances_tree)
        original_bg = self.arrow_button.cget("bg")
        self.arrow_button.config(bg="#FFD700")  # Cor dourada para o flash
        self.after(150, lambda: self.arrow_button.config(bg=original_bg)) # Volta à cor original após 150ms

    def dados_por_temporadas(self, parent_frame):
        # --- IMPORTAÇÕES E ESTILOS ---
        import tkinter as tk
        from tkinter import ttk
        from PIL import Image, ImageTk
        import os
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np

        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"
        
        C_GOLS = "#4ADE80"
        C_ASSIS = "#38BDF8"
        C_JOGOS = "#F8FAFC"
        C_AMARELO = "#FACC15"
        C_VERMELHO = "#EF4444"
        C_TITS = "#F59E0B"

        self.style.configure("SeasonMain.TFrame", background=BG_BASE)
        
        # --- ESTRUTURA COM SCROLL ---
        aba_temp = ttk.Frame(parent_frame, style="SeasonMain.TFrame")
        aba_temp.pack(fill="both", expand=True)

        canvas_season = tk.Canvas(aba_temp, bg=BG_BASE, highlightthickness=0)
        scrollbar_season = ttk.Scrollbar(aba_temp, orient="vertical", command=canvas_season.yview)
        
        content_inner = ttk.Frame(canvas_season, style="SeasonMain.TFrame")
        window_id = canvas_season.create_window((0, 0), window=content_inner, anchor="nw")
        
        canvas_season.configure(yscrollcommand=scrollbar_season.set)
        canvas_season.pack(side="left", fill="both", expand=True)
        scrollbar_season.pack(side="right", fill="y")
        
        def _resize(e): canvas_season.itemconfig(window_id, width=e.width)
        canvas_season.bind("<Configure>", _resize)
        
        def _wheel(e): 
            try: canvas_season.yview_scroll(int(-1*(e.delta/120)), "units")
            except: pass
            
        canvas_season.bind_all("<MouseWheel>", _wheel)
        
        # CORREÇÃO: Garante que a aba principal recupere o scroll se o mouse passar nela
        canvas_season.bind("<Enter>", lambda e: canvas_season.bind_all("<MouseWheel>", _wheel))
        
        content_inner.bind("<Configure>", lambda e: canvas_season.configure(scrollregion=canvas_season.bbox("all")))

        # --- HEADER E CONTROLES ---
        header = tk.Frame(content_inner, bg=BG_BASE, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="RESUMO POR TEMPORADA", font=("Impact", 32), fg="white", bg=BG_BASE).pack(anchor="w")
        tk.Label(header, text="Análise de desempenho, impacto e títulos isolados por ano.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_BASE).pack(anchor="w")

        ctrl_frame = tk.Frame(content_inner, bg=BG_BASE)
        ctrl_frame.pack(fill="x", padx=40, pady=(10, 10))
        tk.Label(ctrl_frame, text="SELECIONE A TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=ACCENT, bg=BG_BASE).pack(anchor="w")
        
        opcoes = ["Selecione uma Temporada"] + list(sorted(self.dados_temporada_Geral.keys(), reverse=True))
        selected_season = tk.StringVar(value=opcoes[1] if len(opcoes) > 1 else opcoes[0])
        
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes, state="readonly", width=30, font=("Segoe UI", 11))
        combo.pack(anchor="w", pady=5)

        dynamic_container = tk.Frame(content_inner, bg=BG_BASE)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_season'): self.fig_season = []
        if not hasattr(self, 'cache_tacas_temporada'): self.cache_tacas_temporada = []

        def atualizar_view(event=None):
            for f in self.fig_season: plt.close(f)
            self.fig_season.clear()
            self.cache_tacas_temporada.clear()
            
            for widget in dynamic_container.winfo_children(): widget.destroy()
            
            ano = selected_season.get()
            if ano == "Selecione uma Temporada": return

            dados = self.dados_temporada_Geral.get(ano, [])
            if not dados:
                tk.Label(dynamic_container, text="Sem registros para esta temporada.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_BASE).pack(pady=40)
                return

            # --- CÁLCULOS ---
            t_jogos = sum(d[1] for d in dados)
            t_gols = sum(d[2] for d in dados)
            t_assis = sum(d[3] for d in dados)
            media_contri = (t_gols + t_assis) / t_jogos if t_jogos > 0 else 0

            t_titulos = 0
            imagens_titulos = []
            for t in getattr(self, 'conquistas', []):
                try:
                    temp_str = str(t[2]) 
                    lista_ganhos = [x.strip() for x in temp_str.split(",")]
                    
                    qtd_neste_ano = 0
                    for ganho in lista_ganhos:
                        if ano in ganho:
                            qtd_neste_ano += 1
                            
                    if qtd_neste_ano > 0:
                        t_titulos += qtd_neste_ano
                        img_path = t[0]
                        for _ in range(qtd_neste_ano): 
                            imagens_titulos.append(img_path)
                except: pass

            soma_notas = 0.0
            jogos_com_nota = 0
            for j in getattr(self, 'ultimas_performances', []):
                if self._inferir_temporada(j.get("Data", "")) == ano:
                    try:
                        soma_notas += float(j.get("Nota", 6.0))
                        jogos_com_nota += 1
                    except: pass
            
            media_nota = soma_notas / jogos_com_nota if jogos_com_nota > 0 else 0.0
            cor_nota = "#4ADE80" if media_nota >= 7.5 else ("#FACC15" if media_nota >= 6.5 else "#EF4444")

            # ======================================================================
            # 1. HERO BANNER
            # ======================================================================
            top_ribbon = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            top_ribbon.pack(fill="x", padx=40, pady=(10, 20))
            
            tk.Frame(top_ribbon, bg=ACCENT, height=4).pack(fill="x", side="top")

            hero_inner = tk.Frame(top_ribbon, bg=BG_CARD)
            hero_inner.pack(fill="both", expand=True, padx=30, pady=20)

            f_title = tk.Frame(hero_inner, bg=BG_CARD)
            f_title.pack(side="left", padx=(0, 40))
            tk.Label(f_title, text=f"TEMPORADA {ano}", font=("Impact", 36), fg="white", bg=BG_CARD).pack(anchor="w")
            tk.Label(f_title, text="Resumo de Produtividade Direta", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")

            f_kpis = tk.Frame(hero_inner, bg=BG_CARD)
            f_kpis.pack(side="right", expand=True, fill="x")
            for i in range(4): f_kpis.columnconfigure(i, weight=1)

            top_kpis = [
                ("JOGOS", t_jogos, C_JOGOS, "👕"),
                ("GOLS", t_gols, C_GOLS, "⚽"),
                ("ASSIST.", t_assis, C_ASSIS, "🤝"),
                ("PARTICIPAÇÃO", f"{media_contri:.2f}", "#A855F7", "🔥")
            ]

            for i, (titulo, val, cor, icone) in enumerate(top_kpis):
                box = tk.Frame(f_kpis, bg=BG_CARD)
                box.grid(row=0, column=i, sticky="nsew", padx=10)
                tk.Label(box, text=f"{icone} {titulo}", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="center")
                tk.Label(box, text=val, font=("Segoe UI", 26, "bold"), fg=cor, bg=BG_CARD).pack(anchor="center", pady=(5,0))

            # ======================================================================
            # 2. O PALCO CENTRAL (Donuts + Vitrine)
            # ======================================================================
            mid_grid = tk.Frame(dynamic_container, bg=BG_BASE)
            mid_grid.pack(fill="x", padx=40, pady=(0, 20))
            mid_grid.columnconfigure(0, weight=1) 
            mid_grid.columnconfigure(1, weight=1) 
            mid_grid.columnconfigure(2, weight=1) 

            def criar_grafico_donut(parent, col_idx, titulo_graf, indice_dado, cor_tema):
                f_card = tk.Frame(parent, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=15, pady=15)
                f_card.grid(row=0, column=col_idx, sticky="nsew", padx=(0, 10) if col_idx == 0 else ((0, 10) if col_idx == 1 else 0))
                
                tk.Label(f_card, text=titulo_graf, font=("Segoe UI", 11, "bold"), fg="white", bg=BG_CARD).pack(anchor="center", pady=(0, 10))

                dados_graf = [(d[0], d[indice_dado]) for d in dados if d[indice_dado] > 0]
                dados_graf.sort(key=lambda x: x[1], reverse=True)
                
                if not dados_graf:
                    tk.Label(f_card, text="Nenhum registro.", font=("Segoe UI", 10, "italic"), fg=TEXT_SUB, bg=BG_CARD).pack(expand=True)
                    return

                labels = [d[0][:15] + ".." if len(d[0]) > 15 else d[0] for d in dados_graf]
                sizes = [d[1] for d in dados_graf]
                
                if cor_tema == C_GOLS: colors = ['#4ADE80', '#22C55E', '#16A34A', '#15803D', '#14532D', '#052E16']
                else: colors = ['#38BDF8', '#0EA5E9', '#0284C7', '#0369A1', '#075985', '#0C4A6E']
                colors = (colors * ((len(sizes) // len(colors)) + 1))[:len(sizes)]

                fig_pie, ax_pie = plt.subplots(figsize=(3, 2.5), facecolor=BG_CARD)
                wedges, texts, autotexts = ax_pie.pie(
                    sizes, labels=None, autopct='%1.0f%%', startangle=90, colors=colors, 
                    pctdistance=0.75, textprops=dict(color="#0F172A", fontsize=8, fontweight="bold"), 
                    wedgeprops=dict(width=0.4, edgecolor=BG_CARD, linewidth=2)
                )
                
                total = sum(sizes)
                ax_pie.text(0, 0, f"{total}\nTOTAL", ha='center', va='center', fontsize=10, fontweight='bold', color="white")
                ax_pie.legend(wedges, labels, loc="center left", bbox_to_anchor=(1, 0, 0.5, 1), frameon=False, labelcolor=TEXT_SUB, fontsize=8)
                plt.tight_layout()
                
                canvas_pie = FigureCanvasTkAgg(fig_pie, master=f_card)
                canvas_pie.draw()
                canvas_pie.get_tk_widget().pack(fill="both", expand=True)
                self.fig_season.append(fig_pie)
                self.matplotlib_canvases.append(canvas_pie)

            criar_grafico_donut(mid_grid, 0, "🎯 DISTRIBUIÇÃO DE GOLS", 2, C_GOLS)
            criar_grafico_donut(mid_grid, 1, "🎁 DISTRIBUIÇÃO DE ASSISTÊNCIAS", 3, C_ASSIS)

            # Coluna 3: Vitrine da Temporada e Nota
            f_vitrine = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
            f_vitrine.grid(row=0, column=2, sticky="nsew", padx=(0, 0))

            f_nota = tk.Frame(f_vitrine, bg="#252F3D", highlightthickness=1, highlightbackground=cor_nota, padx=10, pady=10)
            f_nota.pack(fill="x", pady=(0, 15))
            tk.Label(f_nota, text="NOTA MÉDIA (ANO)", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(side="left", padx=5)
            tk.Label(f_nota, text=f"{media_nota:.2f}", font=("Segoe UI", 16, "bold"), fg=cor_nota, bg="#252F3D").pack(side="right", padx=5)

            tk.Label(f_vitrine, text="🏆 GALERIA DE HONRA", font=("Segoe UI", 11, "bold"), fg=C_TITS, bg=BG_CARD).pack(anchor="center", pady=(5, 10))

            if t_titulos == 0:
                tk.Label(f_vitrine, text="Nenhuma taça erguida\nnesta temporada.", font=("Segoe UI", 10, "italic"), fg="#64748B", bg=BG_CARD, pady=30).pack()
            else:
                f_shelf_container = tk.Frame(f_vitrine, bg="#060B14", highlightthickness=1, highlightbackground="#38BDF8", bd=0)
                f_shelf_container.pack(fill="both", expand=True, pady=5, padx=5)

                cv_vitrine = tk.Canvas(f_shelf_container, bg="#060B14", highlightthickness=0)
                cv_vitrine.pack(fill="both", expand=True)

                limite_exibicao = 8 
                tamanho_taca = 150
                tacas_pre_carregadas = []
                
                for img_p in imagens_titulos[:limite_exibicao]:
                    path_final = None
                    if os.path.exists(img_p): path_final = img_p
                    elif os.path.exists(os.path.abspath(img_p)): path_final = os.path.abspath(img_p)
                    elif os.path.exists(resource_path(img_p)): path_final = resource_path(img_p) 

                    if path_final:
                        try:
                            pil_img = Image.open(path_final).resize((tamanho_taca, tamanho_taca), Image.Resampling.LANCZOS)
                            tk_img = ImageTk.PhotoImage(pil_img)
                            self.cache_tacas_temporada.append(tk_img)
                            tacas_pre_carregadas.append(tk_img)
                        except:
                            tacas_pre_carregadas.append(None)
                    else:
                        tacas_pre_carregadas.append(None)

                def desenhar_vitrine(event):
                    cv_vitrine.delete("all")
                    w = event.width
                    h = event.height
                    if w < 10 or h < 10: return

                    cv_vitrine.create_polygon(w*0.1, 0, w*0.4, 0, w*0.3, h, w*0.0, h, fill="#0F172A", outline="")
                    cv_vitrine.create_polygon(w*0.6, 0, w*0.7, 0, w*0.5, h, w*0.4, h, fill="#0F172A", outline="")
                    cv_vitrine.create_line(0, 0, w, h*0.5, fill="#1E293B", width=1, dash=(4, 4)) 

                    chao_y = h - 20
                    cv_vitrine.create_rectangle(0, chao_y, w, h, fill="#1E293B", outline="")
                    cv_vitrine.create_line(0, chao_y, w, chao_y, fill="#38BDF8", width=2) 

                    qtd_tacas = len(tacas_pre_carregadas)
                    gap_ideal = 10
                    largura_disponivel = w - 30 
                    
                    espaco_necessario = (qtd_tacas * tamanho_taca) + ((qtd_tacas - 1) * gap_ideal)

                    if espaco_necessario <= largura_disponivel or qtd_tacas <= 1:
                        gap_real = gap_ideal
                        largura_total_usada = espaco_necessario
                    else:
                        gap_real = (largura_disponivel - (qtd_tacas * tamanho_taca)) / (qtd_tacas - 1)
                        largura_total_usada = largura_disponivel

                    start_x = (w - largura_total_usada) / 2 + (tamanho_taca / 2)

                    for i, tk_img in enumerate(tacas_pre_carregadas):
                        cv_vitrine.create_oval(start_x - 45, chao_y - 8, start_x + 45, chao_y + 8, fill="#020617", outline="")
                        
                        if tk_img:
                            cv_vitrine.create_image(start_x, chao_y + 2, image=tk_img, anchor="s")
                        else:
                            cv_vitrine.create_text(start_x, chao_y, text="🏆", font=("Segoe UI Emoji", 70), fill=C_TITS, anchor="s")
                        
                        start_x += tamanho_taca + gap_real

                    if t_titulos > limite_exibicao:
                        cv_vitrine.create_text(w - 25, 25, text=f"+{t_titulos - limite_exibicao}", font=("Impact", 18), fill=C_TITS)

                cv_vitrine.bind("<Configure>", desenhar_vitrine)

            # ======================================================================
            # 3. LISTA DE COMPETIÇÕES (TABELA ALINHADA E INTERATIVA)
            # ======================================================================
            list_container = tk.Frame(dynamic_container, bg=BG_BASE)
            list_container.pack(fill="both", expand=True, padx=40, pady=(10, 40))

            tk.Label(list_container, text="DESEMPENHO POR COMPETIÇÃO (Clique para Detalhes)", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_BASE).pack(anchor="w", pady=(0, 10))

            dados_ordenados = sorted(dados, key=lambda x: x[1], reverse=True) 

            header_t = tk.Frame(list_container, bg="#252F3D", height=35)
            header_t.pack(fill="x", pady=(0, 5))
            
            cols_def = [
                ("COMPETIÇÃO", 0.02, "w"),
                ("JOGOS", 0.45, "c"),
                ("GOLS", 0.55, "c"),
                ("ASSIST.", 0.65, "c"),
                ("MÉDIA G/J", 0.75, "c"),
                ("CARTÕES", 0.85, "c"),
                ("MINUTOS", 0.95, "c")
            ]
            
            for txt, rx, anc in cols_def:
                tk.Label(header_t, text=txt, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").place(relx=rx, rely=0.5, anchor=anc if anc != "c" else "center")

            for i, row in enumerate(dados_ordenados):
                comp_nome, jogos, gols, ass, ama, ver2, verd, mins = row
                cartoes_totais = ama + ver2 + verd
                media_gols = gols / jogos if jogos > 0 else 0

                row_f = tk.Frame(list_container, bg=BG_CARD, height=60, highlightthickness=1, highlightbackground="#334155", cursor="hand2")
                row_f.pack(fill="x", pady=3)
                row_f.pack_propagate(False)

                bar_color = "#38BDF8"
                n_up = comp_nome.upper()
                if "LIBERTADORES" in n_up or "CHAMPIONS" in n_up: bar_color = "#F59E0B"
                elif "BRASILEIRÃO" in n_up or "SERIE A" in n_up or "SÉRIE A" in n_up: bar_color = "#4ADE80"
                elif "COPA" in n_up or "CUP" in n_up or "POKAL" in n_up: bar_color = "#EF4444"
                elif "MUNDIAL" in n_up: bar_color = "#A855F7"
                
                tk.Frame(row_f, bg=bar_color, width=4).place(relx=0, rely=0, relheight=1)

                f_nome = tk.Frame(row_f, bg=BG_CARD)
                f_nome.place(relx=0.02, rely=0.5, anchor="w")
                
                try:
                    safe_name = comp_nome.strip()
                    path_logo = f"Logos/{safe_name}.png"
                    if not os.path.exists(resource_path(path_logo)):
                        novo = baixar_logo_competicao(safe_name)
                        if novo: path_logo = novo
                    
                    if os.path.exists(resource_path(path_logo)):
                        pil = Image.open(resource_path(path_logo)).resize((35, 35), Image.Resampling.LANCZOS)
                        tk_ico = ImageTk.PhotoImage(pil)
                        if not hasattr(self, 'club_logo_images'): self.club_logo_images = []
                        self.club_logo_images.append(tk_ico)
                        tk.Label(f_nome, image=tk_ico, bg=BG_CARD).pack(side="left", padx=(0, 10))
                    else:
                        tk.Label(f_nome, text="🏆", font=("Segoe UI Emoji", 16), bg=BG_CARD, fg=TEXT_SUB).pack(side="left", padx=(0, 10))
                except: 
                    tk.Label(f_nome, text="🏆", font=("Segoe UI Emoji", 16), bg=BG_CARD, fg=TEXT_SUB).pack(side="left", padx=(0, 10))

                nome_cut = comp_nome.upper()
                if len(nome_cut) > 25: nome_cut = nome_cut[:22] + "..."
                tk.Label(f_nome, text=nome_cut, font=("Segoe UI", 11, "bold"), fg="white", bg=BG_CARD).pack(side="left")

                tk.Label(row_f, text=str(jogos), font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).place(relx=0.45, rely=0.5, anchor="center")
                tk.Label(row_f, text=str(gols), font=("Segoe UI", 12, "bold"), fg=C_GOLS, bg=BG_CARD).place(relx=0.55, rely=0.5, anchor="center")
                tk.Label(row_f, text=str(ass), font=("Segoe UI", 12, "bold"), fg=C_ASSIS, bg=BG_CARD).place(relx=0.65, rely=0.5, anchor="center")
                tk.Label(row_f, text=f"{media_gols:.2f}", font=("Segoe UI", 11, "bold"), fg=TEXT_SUB, bg=BG_CARD).place(relx=0.75, rely=0.5, anchor="center")
                
                cor_cartao = C_AMARELO if cartoes_totais > 0 else TEXT_SUB
                tk.Label(row_f, text=str(cartoes_totais), font=("Segoe UI", 12, "bold"), fg=cor_cartao, bg=BG_CARD).place(relx=0.85, rely=0.5, anchor="center")
                
                tk.Label(row_f, text=f"{mins:,}".replace(",", "."), font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_CARD).place(relx=0.95, rely=0.5, anchor="center")

                def on_ent(e, r=row_f, fn=f_nome, c=bar_color): 
                    r.configure(bg="#252F3D", highlightbackground=c)
                    fn.configure(bg="#252F3D")
                    for child in fn.winfo_children(): child.configure(bg="#252F3D")
                    for child in r.winfo_children(): 
                        if isinstance(child, tk.Label): child.configure(bg="#252F3D")
                    
                def on_lea(e, r=row_f, fn=f_nome): 
                    r.configure(bg=BG_CARD, highlightbackground="#334155")
                    fn.configure(bg=BG_CARD)
                    for child in fn.winfo_children(): child.configure(bg=BG_CARD)
                    for child in r.winfo_children(): 
                        if isinstance(child, tk.Label): child.configure(bg=BG_CARD)
                
                row_f.bind("<Enter>", on_ent); row_f.bind("<Leave>", on_lea)

                def ao_clicar_linha(event, a=ano, c=comp_nome):
                    self.abrir_popup_resumo_competicao(a, c)

                row_f.bind("<Button-1>", ao_clicar_linha)
                for widget_interno in row_f.winfo_children() + f_nome.winfo_children():
                    widget_interno.bind("<Button-1>", ao_clicar_linha)

            tk.Frame(dynamic_container, bg=BG_BASE, height=50).pack()

        combo.bind("<<ComboboxSelected>>", atualizar_view)
        if len(opcoes) > 1: atualizar_view()

    def abrir_popup_resumo_competicao(self, ano, comp_nome):
        from tkinter import Toplevel
        import tkinter as tk
        
        tot_jogos = 0; tot_gols = 0; tot_assists = 0
        soma_notas = 0.0; jogos_com_nota = 0
        tot_motm = 0
        
        tot_xg = 0.0; tot_chutes_gol = 0; tot_chutes_trave = 0; tot_chutes_fora = 0
        tot_chutes_bloq = 0; tot_gc_perdidas = 0
        tot_xa = 0.0; tot_pre_assists = 0; tot_posses_ganhas = 0; tot_posses_perdidas = 0; tot_distancia = 0.0
        
        tot_passes_dec = 0; tot_chances_criadas = 0; tot_dribles = 0
        tot_passes_c = 0; tot_passes_e = 0; tot_cruz_c = 0; tot_cruz_t = 0
        
        tot_desarmes = 0; tot_faltas_s = 0; tot_faltas_c = 0
        tot_clean = 0; tot_amarelos = 0; tot_vermelhos = 0
        
        tot_dir = 0; tot_esq = 0; tot_cab = 0
        tot_falta = 0; tot_pen = 0
        mapa_gols_acumulado = []

        for jogo in self.ultimas_performances:
            if self._inferir_temporada(jogo.get("Data", "")) == ano and jogo.get("Competição") == comp_nome:
                pos = jogo.get("Posição", "MEI")
                status_ausente = ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]
                if int(jogo.get("Minutos", 90)) == 0 or pos in status_ausente:
                    continue
                
                tot_jogos += 1
                tot_gols += int(jogo.get("Gols", 0))
                tot_assists += int(jogo.get("Assistências", 0))
                
                try:
                    soma_notas += float(jogo.get("Nota", 6.0))
                    jogos_com_nota += 1
                except: pass

                det = jogo.get("Detalhes", {})
                
                if det.get("MOTM"): tot_motm += 1
                if det.get("CleanSheet"): tot_clean += 1
                
                tot_xg += float(det.get("xG", 0.0))
                tot_xa += float(det.get("xA", 0.0)) 
                tot_pre_assists += int(det.get("PreAssistencias", 0)) 
                tot_posses_ganhas += int(det.get("PossesGanhas", 0)) 
                tot_posses_perdidas += int(det.get("PossesPerdidas", 0)) 
                tot_distancia += float(det.get("DistanciaPercorrida", 0.0)) 
                tot_chutes_gol += int(det.get("ChutesNoGol", 0))
                tot_chutes_trave += int(det.get("ChutesNaTrave", 0))
                tot_chutes_fora += int(det.get("ChutesPraFora", 0))
                tot_chutes_bloq += int(det.get("ChutesBloqueados", 0))
                tot_gc_perdidas += int(det.get("GrandesChancesPerdidas", 0))
                
                tot_passes_dec += int(det.get("PassesDecisivos", 0))
                tot_chances_criadas += int(det.get("ChancesCriadas", 0))
                tot_dribles += int(det.get("DriblesCertos", 0))
                tot_passes_c += int(det.get("PassesCertos", 0))
                tot_passes_e += int(det.get("PassesErrados", 0))
                tot_cruz_c += int(det.get("CruzamentosCertos", 0))
                tot_cruz_t += int(det.get("CruzamentosTentados", 0))
                
                tot_desarmes += int(det.get("Desarmes", 0))
                tot_faltas_s += int(det.get("FaltasSofridas", 0))
                tot_faltas_c += int(det.get("FaltasCometidas", 0))
                
                tot_dir += int(det.get("PeDireito", 0))
                tot_esq += int(det.get("PeEsquerdo", 0))
                tot_cab += int(det.get("Cabeca", 0))
                tot_falta += int(det.get("FaltasGol", 0))
                tot_pen += int(det.get("PenalGol", 0))
                
                mapa_gols_acumulado.extend(det.get("MapaGols", []))

        for d in self.dados_temporada_Geral.get(ano, []):
            if d[0] == comp_nome:
                tot_amarelos = d[4]
                tot_vermelhos = d[5] + d[6]
                break

        media_nota = soma_notas / jogos_com_nota if jogos_com_nota > 0 else 0.0

        BG_MODAL = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"

        pop = Toplevel(self)
        pop.title(f"Relatório de Scout - {comp_nome} ({ano})")
        pop.geometry("750x850")
        pop.configure(bg=BG_MODAL)
        pop.resizable(False, False)
        
        pop.update_idletasks()
        x = (pop.winfo_screenwidth() // 2) - (750 // 2)
        y = (pop.winfo_screenheight() // 2) - (850 // 2)
        pop.geometry(f"+{x}+{y}")
        pop.grab_set()

        header = tk.Frame(pop, bg=BG_MODAL)
        header.pack(fill="x", pady=(20, 10), padx=30)
        
        f_logo = tk.Frame(header, bg=BG_MODAL)
        f_logo.pack(side="left")
        
        try:
            safe_name = comp_nome.strip()
            path_logo = f"Logos/{safe_name}.png"
            if os.path.exists(resource_path(path_logo)):
                from PIL import Image, ImageTk
                pil = Image.open(resource_path(path_logo)).resize((60, 60), Image.Resampling.LANCZOS)
                tk_ico = ImageTk.PhotoImage(pil)
                self.club_logo_images.append(tk_ico) 
                tk.Label(f_logo, image=tk_ico, bg=BG_MODAL).pack()
            else:
                tk.Label(f_logo, text="🏆", font=("Segoe UI Emoji", 35), bg=BG_MODAL, fg=TEXT_SUB).pack()
        except: pass

        f_txt = tk.Frame(header, bg=BG_MODAL)
        f_txt.pack(side="left", padx=15)
        tk.Label(f_txt, text=comp_nome.upper(), font=("Impact", 28), fg="white", bg=BG_MODAL).pack(anchor="w")
        tk.Label(f_txt, text=f"Dossiê Estatístico da Temporada {ano}", font=("Segoe UI", 11), fg=ACCENT, bg=BG_MODAL).pack(anchor="w")

        # =======================================================
        # ÁREA DE SCROLL ESTÁVEL (À PROVA DE BUGS)
        # =======================================================
        body_container = tk.Frame(pop, bg=BG_MODAL)
        body_container.pack(fill="both", expand=True, padx=10, pady=(0, 10))

        canvas = tk.Canvas(body_container, bg=BG_MODAL, highlightthickness=0)
        scrollbar = ttk.Scrollbar(body_container, orient="vertical", command=canvas.yview)
        scroll_frame = tk.Frame(canvas, bg=BG_MODAL)

        # Fixamos a largura do frame interno para evitar o loop de redimensionamento
        canvas.create_window((0, 0), window=scroll_frame, anchor="nw", width=740)
        canvas.configure(yscrollcommand=scrollbar.set)

        # Deixamos a scrollbar sempre na tela
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        # Atualiza a área de scroll sempre que o conteúdo interno mudar
        scroll_frame.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        def _on_mousewheel(event):
            try: canvas.yview_scroll(int(-1*(event.delta/120)), "units")
            except: pass
            
        # O pop-up só rouba o scroll quando o mouse entra nele
        pop.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", _on_mousewheel))
        
        # Quando fechar, limpamos o bind para a tela de trás voltar a funcionar
        def fechar_popup_seguro():
            canvas.unbind_all("<MouseWheel>") 
            pop.destroy() 
            
            if hasattr(self, 'scroll_ativo'):
                self.bind_all("<MouseWheel>", self.scroll_ativo)
            
        pop.protocol("WM_DELETE_WINDOW", fechar_popup_seguro)
        
        scroll_frame.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # =======================================================
        # 1. BLOCO DE RESUMO RÁPIDO
        # =======================================================
        f_resumo = tk.Frame(scroll_frame, bg=BG_MODAL)
        f_resumo.pack(fill="x", pady=10, padx=15)
        for i in range(5): f_resumo.columnconfigure(i, weight=1)

        cor_nota = "#4ADE80" if media_nota >= 7.5 else ("#FACC15" if media_nota >= 6.5 else "#EF4444")
        
        kpis_base = [
            ("JOGOS", tot_jogos, "white"), ("GOLS", tot_gols, "#4ADE80"), 
            ("ASSIST.", tot_assists, "#38BDF8"), ("NOTA MÉDIA", f"{media_nota:.2f}", cor_nota),
            ("MOTM", tot_motm, "#F59E0B")
        ]
        
        for i, (lbl, val, cor) in enumerate(kpis_base):
            box = tk.Frame(f_resumo, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=10, pady=10)
            box.grid(row=0, column=i, sticky="nsew", padx=5)
            tk.Label(box, text=str(val), font=("Impact", 24), fg=cor, bg=BG_CARD).pack()
            tk.Label(box, text=lbl, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack()

        # =======================================================
        # FUNÇÃO HELPER PARA BLOCOS DE ESTATÍSTICAS
        # =======================================================
        def criar_bloco_stats(titulo, cor_titulo, lista_stats):
            f_bloco = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            f_bloco.pack(fill="x", pady=8, padx=20)
            
            tk.Label(f_bloco, text=titulo, font=("Segoe UI", 10, "bold"), fg=cor_titulo, bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 5))
            
            grid_s = tk.Frame(f_bloco, bg=BG_CARD)
            grid_s.pack(fill="x", padx=15, pady=(0, 10))
            
            for idx, (icone, label, valor) in enumerate(lista_stats):
                r = idx // 2; c = idx % 2
                item_f = tk.Frame(grid_s, bg=BG_CARD)
                item_f.grid(row=r, column=c, sticky="ew", padx=10, pady=2)
                grid_s.columnconfigure(c, weight=1)
                
                tk.Label(item_f, text=f"{icone} {label}", font=("Segoe UI", 9), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
                try: cv = "white" if float(valor) > 0 else "#64748B"
                except: cv = "white" if str(valor) not in ["0", "0.0", "0 / 0", "Não", ""] else "#64748B"
                
                tk.Label(item_f, text=str(valor), font=("Segoe UI", 10, "bold"), fg=cv, bg=BG_CARD).pack(side="right")

        # BLOCO 1: OFENSIVA
        ataque_stats = [
            ("📊", "Expected Goals (xG)", f"{tot_xg:.2f}"),
            ("🎯", "Chutes no Gol", tot_chutes_gol),
            ("🥅", "Chutes na Trave", tot_chutes_trave),
            ("❌", "Chutes para Fora", tot_chutes_fora),
            ("🛡️", "Chutes Bloqueados", tot_chutes_bloq),
            ("🤦", "Grandes Chances Perdidas", tot_gc_perdidas),
            ("🏃", "Distância Percorrida", f"{tot_distancia:.1f} km"),
        ]
        criar_bloco_stats("⚔️ OFENSIVA & FINALIZAÇÃO", "#4ADE80", ataque_stats)

        # BLOCO 2: PASSES
        criacao_stats = [
            ("📊", "Expected Assists (xA)", f"{tot_xa:.2f}"),
            ("🔑", "Passes Decisivos", tot_passes_dec),
            ("✨", "Chances Claras Criadas", tot_chances_criadas),
            ("🎁", "Pré-Assistências", tot_pre_assists),
            ("⚡", "Dribles Certos", tot_dribles),
            ("✅", "Passes Certos", tot_passes_c),
            ("❌", "Passes Errados", tot_passes_e),
            ("↪️", "Cruzamentos (C/T)", f"{tot_cruz_c} / {tot_cruz_t}"),
            ("♻️", "Posses Ganhas", tot_posses_ganhas),
            ("🗑️", "Posses Perdidas", tot_posses_perdidas),
        ]
        criar_bloco_stats("🧠 CRIAÇÃO E PASSES", "#38BDF8", criacao_stats)

        # BLOCO 3: DEFESA
        defesa_stats = [
            ("🥾", "Desarmes", tot_desarmes),
            ("🧤", "Jogos sem Sofrer Gols", tot_clean),
            ("🤕", "Faltas Sofridas", tot_faltas_s),
            ("🛑", "Faltas Cometidas", tot_faltas_c),
            ("🟨", "Cartões Amarelos", tot_amarelos),
            ("🟥", "Cartões Vermelhos", tot_vermelhos),
        ]
        criar_bloco_stats("🛡️ DEFESA E DISCIPLINA", "#EF4444", defesa_stats)

        # BLOCO 4: RAIO-X DOS GOLS E MAPA (Só se fez gol)
        if int(tot_gols) > 0:
            raiox_stats = [
                ("🦶", "Pé Direito", tot_dir),
                ("🦶", "Pé Esquerdo", tot_esq),
                ("🗣️", "Cabeça", tot_cab),
                ("🎯", "Falta Direta", tot_falta),
                ("🥅", "Pênalti", tot_pen)
            ]
            criar_bloco_stats("🎯 ANATOMIA DOS GOLS", "#F59E0B", raiox_stats)

            if mapa_gols_acumulado:
                f_mapa_popup = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#F59E0B")
                f_mapa_popup.pack(fill="x", pady=8, padx=20)
                
                tk.Label(f_mapa_popup, text="🗺️ ONDE SEUS GOLS ENTRARAM NO TORNEIO", font=("Segoe UI", 10, "bold"), fg="#F59E0B", bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 0))
                
                cv_pop = tk.Canvas(f_mapa_popup, bg="#2A3645", height=180, highlightthickness=0)
                cv_pop.pack(fill="x", padx=15, pady=(10, 5))
                
                f_leg_pop = tk.Frame(f_mapa_popup, bg=BG_CARD)
                f_leg_pop.pack(fill="x", pady=(0, 10), padx=15)
                tk.Label(f_leg_pop, text="🟣 Ângulo/Alto", font=("Segoe UI", 8, "bold"), fg="#8B5CF6", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟠 Meia Altura", font=("Segoe UI", 8, "bold"), fg="#F59E0B", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟢 Rasteiro", font=("Segoe UI", 8, "bold"), fg="#10B981", bg=BG_CARD).pack(side="left", expand=True)
                
                def desenhar_mapa_popup(event):
                    cv_pop.delete("all")
                    w = event.width
                    h = event.height
                    if w < 50 or h < 50: return
                    
                    goal_h = 130  
                    goal_w = 340  
                    
                    t_x1 = (w - goal_w) / 2
                    t_x2 = t_x1 + goal_w
                    t_y1 = (h - goal_h) / 2 + 5
                    t_y2 = t_y1 + goal_h
                    
                    post_width = 6
                    
                    espaco_rede = 25
                    for i in range(int(t_x1) + espaco_rede, int(t_x2), espaco_rede):
                        cv_pop.create_line(i, t_y1, i, t_y2, fill="#3A4A5E", dash=(2, 2))
                    for i in range(int(t_y1) + espaco_rede, int(t_y2), espaco_rede):
                        cv_pop.create_line(t_x1, i, t_x2, i, fill="#3A4A5E", dash=(2, 2))

                    cv_pop.create_line(t_x1, t_y2, t_x1, t_y1, t_x2, t_y1, t_x2, t_y2, fill="white", width=post_width, joinstyle=tk.ROUND, capstyle=tk.ROUND)

                    for (px, py) in mapa_gols_acumulado:
                        real_x = t_x1 + (px * (t_x2 - t_x1))
                        real_y = t_y1 + (py * (t_y2 - t_y1))
                        raio = 8
                        cor_bola = "#10B981" if py > 0.65 else ("#8B5CF6" if py < 0.35 else "#F59E0B")
                        
                        cv_pop.create_oval(real_x-raio-3, real_y-raio-3, real_x+raio+3, real_y+raio+3, outline=cor_bola, width=2)
                        cv_pop.create_oval(real_x-raio, real_y-raio, real_x+raio, real_y+raio, fill=cor_bola, outline="white", width=2)

                cv_pop.bind("<Configure>", desenhar_mapa_popup)

        tk.Frame(scroll_frame, bg=BG_MODAL, height=20).pack()

        tk.Button(pop, text="FECHAR DOSSIÊ", bg="#334155", fg="white", font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", command=fechar_popup_seguro, pady=10).pack(fill="x", padx=20, side="bottom", pady=15)

    def desempenho_geral(self, parent_frame):
        # --- IMPORTAÇÕES E ESTILOS ---
        import tkinter as tk
        from tkinter import ttk
        from PIL import Image, ImageTk
        import os

        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"
        
        C_GOLS = "#4ADE80"   
        C_ASSIS = "#38BDF8"  
        C_JOGOS = "#F8FAFC"  
        C_AMARELO = "#FACC15" 
        C_VERMELHO = "#EF4444" 
        C_TITS = "#F59E0B"

        self.style.configure("GeralMain.TFrame", background=BG_BASE)
        
        # --- ESTRUTURA COM SCROLL GLOBAL (VERTICAL) ---
        canvas_geral = tk.Canvas(parent_frame, bg=BG_BASE, highlightthickness=0)
        scrollbar_geral = ttk.Scrollbar(parent_frame, orient="vertical", command=canvas_geral.yview)
        
        content_inner = ttk.Frame(canvas_geral, style="GeralMain.TFrame")
        window_id = canvas_geral.create_window((0, 0), window=content_inner, anchor="nw")
        
        canvas_geral.configure(yscrollcommand=scrollbar_geral.set)
        canvas_geral.pack(side="left", fill="both", expand=True)
        scrollbar_geral.pack(side="right", fill="y")
        
        def _on_resize(event): canvas_geral.itemconfig(window_id, width=event.width)
        canvas_geral.bind("<Configure>", _on_resize)
        
        def _wheel(e): 
            try: canvas_geral.yview_scroll(int(-1*(e.delta/120)), "units")
            except: pass
            
        canvas_geral.bind_all("<MouseWheel>", _wheel)
        canvas_geral.bind("<Enter>", lambda e: canvas_geral.bind_all("<MouseWheel>", _wheel))
        content_inner.bind("<Configure>", lambda e: canvas_geral.configure(scrollregion=canvas_geral.bbox("all")))

        # --- CÁLCULO DOS TOTAIS DA CARREIRA ---
        t_jogos = sum(row[1] for row in getattr(self, 'dados_desempenho', []))
        t_gols = sum(row[2] for row in getattr(self, 'dados_desempenho', []))
        t_assis = sum(row[3] for row in getattr(self, 'dados_desempenho', []))
        t_mins = sum(row[7] for row in getattr(self, 'dados_desempenho', []))
        
        media_contri = (t_gols + t_assis) / t_jogos if t_jogos > 0 else 0

        t_titulos = 0
        tacas_agrupadas = [] 
        for t in getattr(self, 'conquistas', []):
            try:
                qtd = int(t[4])
                t_titulos += qtd
                if qtd > 0:
                    tacas_agrupadas.append({
                        'path': t[0], 
                        'qtd': qtd,
                        'nome': t[1]
                    })
            except: pass
            
        tacas_agrupadas.sort(key=lambda x: x['qtd'], reverse=True)

        if not hasattr(self, 'cache_tacas_geral'): self.cache_tacas_geral = []
        self.cache_tacas_geral.clear()

        # ======================================================================
        # 1. HERO BANNER (RESUMO GLOBAL)
        # ======================================================================
        hero_frame = tk.Frame(content_inner, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
        hero_frame.pack(fill="x", padx=40, pady=(30, 20))
        
        tk.Frame(hero_frame, bg="#FFD700", height=4).pack(side="top", fill="x")

        hero_inner = tk.Frame(hero_frame, bg=BG_CARD)
        hero_inner.pack(fill="both", expand=True, padx=30, pady=20)

        f_title = tk.Frame(hero_inner, bg=BG_CARD)
        f_title.pack(side="left", padx=(0, 40))
        tk.Label(f_title, text="RESUMO GERAL", font=("Impact", 36), fg="white", bg=BG_CARD).pack(anchor="w")
        tk.Label(f_title, text="Soma absoluta de toda a sua trajetória", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")

        f_kpis = tk.Frame(hero_inner, bg=BG_CARD)
        f_kpis.pack(side="right", expand=True, fill="x")
        for i in range(5): f_kpis.columnconfigure(i, weight=1)

        stats_hero = [
            ("JOGOS", t_jogos, C_JOGOS, "👕"),
            ("GOLS", t_gols, C_GOLS, "⚽"),
            ("ASSIST.", t_assis, C_ASSIS, "🤝"),
            ("PARTICIPAÇÃO", f"{media_contri:.2f}", "#A855F7", "🔥"),
            ("TÍTULOS", t_titulos, C_TITS, "🏆")
        ]

        for i, (lbl, val, color, icone) in enumerate(stats_hero):
            box = tk.Frame(f_kpis, bg=BG_CARD)
            box.grid(row=0, column=i, sticky="nsew", padx=10)
            tk.Label(box, text=f"{icone} {lbl}", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="center")
            tk.Label(box, text=str(val), font=("Segoe UI", 26, "bold"), fg=color, bg=BG_CARD).pack(anchor="center", pady=(5,0))

        # ======================================================================
        # 2. O PALCO CENTRAL
        # ======================================================================
        mid_grid = tk.Frame(content_inner, bg=BG_BASE)
        mid_grid.pack(fill="x", padx=40, pady=(0, 20))
        mid_grid.columnconfigure(0, weight=2)
        mid_grid.columnconfigure(1, weight=3)

        # --- ESQUERDA: CAMISAS VESTIDAS ---
        f_clubes = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
        f_clubes.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        
        tk.Label(f_clubes, text="🛡️ CAMISAS VESTIDAS", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 15))

        clubes_jogados = sorted(getattr(self, 'dados_desempenho_por_clubes', {}).items(), key=lambda x: x[1].get('jogos', 0), reverse=True)[:5] 
        
        if not clubes_jogados:
            tk.Label(f_clubes, text="Nenhum clube registrado.", font=("Segoe UI", 10, "italic"), fg=TEXT_SUB, bg=BG_CARD).pack(pady=20)
        else:
            grid_c = tk.Frame(f_clubes, bg=BG_CARD)
            grid_c.pack(fill="both", expand=True)
            
            for i, (nome_c, stats_c) in enumerate(clubes_jogados):
                row_c = tk.Frame(grid_c, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", padx=10, pady=8)
                row_c.pack(fill="x", pady=4)
                
                try:
                    safe_name = nome_c.strip()
                    path_logo = f"Logos/{safe_name}.png"
                    if os.path.exists(resource_path(path_logo)):
                        pil = Image.open(resource_path(path_logo)).resize((30, 30), Image.Resampling.LANCZOS)
                        tk_ico = ImageTk.PhotoImage(pil)
                        self.cache_tacas_geral.append(tk_ico)
                        tk.Label(row_c, image=tk_ico, bg="#252F3D").pack(side="left", padx=(5, 10))
                    else:
                        tk.Label(row_c, text="🛡️", font=("Segoe UI Emoji", 14), bg="#252F3D", fg=TEXT_SUB).pack(side="left", padx=(5, 10))
                except:
                    tk.Label(row_c, text="🛡️", font=("Segoe UI Emoji", 14), bg="#252F3D", fg=TEXT_SUB).pack(side="left", padx=(5, 10))

                nome_cut = nome_c[:18] + ".." if len(nome_c) > 18 else nome_c
                tk.Label(row_c, text=nome_cut.upper(), font=("Segoe UI", 10, "bold"), fg="white", bg="#252F3D").pack(side="left")
                
                f_st = tk.Frame(row_c, bg="#252F3D")
                f_st.pack(side="right", padx=5)
                tk.Label(f_st, text=str(stats_c.get('jogos', 0)), font=("Segoe UI", 12, "bold"), fg="white", bg="#252F3D").pack(side="left")
                tk.Label(f_st, text="Jogos", font=("Segoe UI", 8), fg=TEXT_SUB, bg="#252F3D").pack(side="left", padx=(4, 0))

        # --- DIREITA: VITRINE GLOBAL C/ SCROLL CUSTOMIZADO ---
        f_vitrine = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
        f_vitrine.grid(row=0, column=1, sticky="nsew", padx=(10, 0))

        tk.Label(f_vitrine, text="🏆 GALERIA DE HONRA GLOBAL", font=("Segoe UI", 12, "bold"), fg=C_TITS, bg=BG_CARD).pack(anchor="w", pady=(0, 10))

        if t_titulos == 0:
            tk.Label(f_vitrine, text="Nenhuma taça erguida na carreira ainda.", font=("Segoe UI", 10, "italic"), fg="#64748B", bg=BG_CARD, pady=30).pack()
        else:
            f_shelf_container = tk.Frame(f_vitrine, bg="#060B14", highlightthickness=1, highlightbackground="#38BDF8", bd=0)
            f_shelf_container.pack(fill="both", expand=True, pady=5, padx=5)

            cv_vitrine = tk.Canvas(f_shelf_container, bg="#060B14", highlightthickness=0)
            cv_vitrine.pack(side="top", fill="both", expand=True)

            # ======================================================================
            # O NOVO SISTEMA DE SCROLLBAR INVISÍVEL / MODERNA
            # ======================================================================
            f_scroll = tk.Frame(f_shelf_container, bg="#060B14", height=14)
            f_scroll.pack(side="bottom", fill="x", pady=(0, 5))

            cv_scroll = tk.Canvas(f_scroll, bg="#060B14", highlightthickness=0, height=14)
            cv_scroll.pack(fill="both", expand=True, padx=20)
            
            # Cria a "cápsula" da barra de rolagem (Discreta inicialmente)
            thumb = cv_scroll.create_rectangle(0, 3, 100, 11, fill="#334155", outline="", tags="thumb")

            def _update_scroll(first, last):
                w = cv_scroll.winfo_width()
                if w > 10:
                    cv_scroll.coords(thumb, float(first)*w, 3, float(last)*w, 11)

            cv_vitrine.configure(xscrollcommand=_update_scroll)

            # Funções de interação com a nova barra
            def _on_drag_scroll(e):
                w = cv_scroll.winfo_width()
                if w > 10:
                    thumb_w = cv_scroll.coords(thumb)[2] - cv_scroll.coords(thumb)[0]
                    frac = (e.x - (thumb_w/2)) / w
                    cv_vitrine.xview_moveto(frac)

            # Efeito Hover (Acende Azul Neon)
            cv_scroll.tag_bind("thumb", "<Enter>", lambda e: [cv_scroll.itemconfig(thumb, fill="#38BDF8"), cv_scroll.config(cursor="hand2")])
            cv_scroll.tag_bind("thumb", "<Leave>", lambda e: [cv_scroll.itemconfig(thumb, fill="#334155"), cv_scroll.config(cursor="")])
            cv_scroll.tag_bind("thumb", "<B1-Motion>", _on_drag_scroll)
            cv_scroll.bind("<Button-1>", _on_drag_scroll)
            cv_scroll.bind("<B1-Motion>", _on_drag_scroll)

            def _on_shift_mousewheel(event):
                try: cv_vitrine.xview_scroll(int(-1*(event.delta/120)), "units")
                except: pass
            cv_vitrine.bind("<Shift-MouseWheel>", _on_shift_mousewheel)

            # ======================================================================
            
            tamanho_taca = 120 
            for taca in tacas_agrupadas:
                img_p = taca['path']
                path_final = None
                if os.path.exists(img_p): path_final = img_p
                elif os.path.exists(os.path.abspath(img_p)): path_final = os.path.abspath(img_p)
                elif os.path.exists(resource_path(img_p)): path_final = resource_path(img_p) 

                if path_final:
                    try:
                        pil_img = Image.open(path_final).resize((tamanho_taca, tamanho_taca), Image.Resampling.LANCZOS)
                        tk_img = ImageTk.PhotoImage(pil_img)
                        self.cache_tacas_geral.append(tk_img)
                        taca['tk_img'] = tk_img
                    except: taca['tk_img'] = None
                else: taca['tk_img'] = None

            def obter_coords_3d_v2(qtd_visual):
                formacoes = {
                    1: [(0, 0, 1.0)], 
                    2: [(-15, -10, 0.9), (15, 0, 1.0)],
                    3: [(-20, -15, 0.85), (20, -15, 0.85), (0, 0, 1.0)],
                    4: [(-25, -20, 0.8), (15, -20, 0.8), (-15, 0, 1.0), (25, 0, 1.0)],
                    5: [(-30, -25, 0.75), (0, -25, 0.75), (30, -25, 0.75), (-15, 0, 1.0), (15, 0, 1.0)]
                }
                if qtd_visual in formacoes: return formacoes[qtd_visual]

                coords = []
                if qtd_visual <= 9:
                    n_fundo = (qtd_visual // 2) + (qtd_visual % 2)
                    n_frente = qtd_visual - n_fundo
                    esp_x = 25; x_ini = - ((n_fundo - 1) * esp_x) / 2 
                    for i in range(n_fundo): coords.append((x_ini + i * esp_x, -25, 0.8))
                    esp_x = 30; x_ini = - ((n_frente - 1) * esp_x) / 2 
                    for i in range(n_frente): coords.append((x_ini + i * esp_x, 5, 1.0))
                else:
                    n_fila = qtd_visual // 3
                    esp_x = 20; x_ini = - ((n_fila - 1) * esp_x) / 2 
                    for i in range(n_fila): coords.append((x_ini + i * esp_x, -40, 0.7))
                    n_f2 = n_fila + (1 if qtd_visual % 3 >= 1 else 0)
                    esp_x = 25; x_ini = - ((n_f2 - 1) * esp_x) / 2 
                    for i in range(n_f2): coords.append((x_ini + i * esp_x, -15, 0.85))
                    n_f1 = qtd_visual - n_fila - n_f2
                    esp_x = 30; x_ini = - ((n_f1 - 1) * esp_x) / 2 
                    for i in range(n_f1): coords.append((x_ini + i * esp_x, 10, 1.0))
                return coords

            def desenhar_vitrine(event):
                cv_vitrine.delete("all")
                w_vis = event.width
                h = event.height
                if w_vis < 10 or h < 10: return

                qtd_slots = len(tacas_agrupadas)
                if qtd_slots == 0: return

                largura_slot = 180 
                gap_ideal = 20
                
                # CÁLCULO DA PRATELEIRA INFINITA
                largura_total_necessaria = (qtd_slots * largura_slot) + ((qtd_slots - 1) * gap_ideal) + 60
                w_canvas = max(w_vis, largura_total_necessaria)
                
                cv_vitrine.configure(scrollregion=(0, 0, w_canvas, h))

                # Fundo esticado infinitamente
                cv_vitrine.create_polygon(w_canvas*0.1, 0, w_canvas*0.4, 0, w_canvas*0.3, h, w_canvas*0.0, h, fill="#0F172A", outline="")
                cv_vitrine.create_polygon(w_canvas*0.6, 0, w_canvas*0.7, 0, w_canvas*0.5, h, w_canvas*0.4, h, fill="#0F172A", outline="")

                chao_y = h - 25
                cv_vitrine.create_rectangle(0, chao_y, w_canvas, h, fill="#1E293B", outline="")
                cv_vitrine.create_line(0, chao_y, w_canvas, chao_y, fill="#38BDF8", width=2) 

                if largura_total_necessaria <= w_vis:
                    start_x = (w_vis - ((qtd_slots * largura_slot) + ((qtd_slots - 1) * gap_ideal))) / 2 + (largura_slot / 2)
                else:
                    start_x = 30 + (largura_slot / 2)

                for taca in tacas_agrupadas:
                    qtd = taca['qtd']
                    nome = taca['nome'].upper()

                    if any(x in nome for x in ["MUNDIAL", "CHAMPIONS", "COPA DO MUNDO"]): peso = 6
                    elif any(x in nome for x in ["LIBERTADORES", "SUL-AMERICANA", "EUROPA"]): peso = 5
                    elif any(x in nome for x in ["BRASILEIRÃO", "SERIE A", "PREMIER", "LIGA", "BUNDESLIGA"]): peso = 4
                    elif any(x in nome for x in ["COPA", "CUP", "POKAL"]): peso = 3
                    elif any(x in nome for x in ["SUPERCOPA", "RECOPA"]): peso = 2
                    else: peso = 1
                    
                    n_trophies = min(qtd, 15) 
                    coords_formacao = obter_coords_3d_v2(n_trophies)
                    coords_formacao.sort(key=lambda x: x[1]) 
                    
                    largura_sombra = 35 + (n_trophies * 4)
                    cv_vitrine.create_oval(start_x - largura_sombra, chao_y - 8, start_x + largura_sombra, chao_y + 8, fill="#020617", outline="")
                    
                    tk_img = taca.get('tk_img')

                    for dx, dy, scale in coords_formacao:
                        if tk_img:
                            if scale < 1.0:
                                try:
                                    original_size = 140 if peso >= 5 else 125
                                    new_size = int(original_size * scale)
                                    path_final = taca['path']
                                    if not os.path.exists(path_final): path_final = resource_path(path_final)
                                    pil_img = Image.open(path_final).resize((new_size, new_size), Image.Resampling.LANCZOS)
                                    tk_mini = ImageTk.PhotoImage(pil_img)
                                    self.cache_tacas_geral.append(tk_mini)
                                    cv_vitrine.create_image(start_x + dx, chao_y + 2 + dy, image=tk_mini, anchor="s")
                                except: cv_vitrine.create_text(start_x + dx, chao_y + dy, text="🏆", font=("Segoe UI Emoji", int(60*scale)), fill="#F59E0B", anchor="s")
                            else:
                                cv_vitrine.create_image(start_x + dx, chao_y + 2 + dy, image=tk_img, anchor="s")
                        else:
                            cv_vitrine.create_text(start_x + dx, chao_y + dy, text="🏆", font=("Segoe UI Emoji", int(60*scale)), fill="#F59E0B", anchor="s")
                    
                    if qtd > 1:
                        cv_vitrine.create_rectangle(start_x - 18, chao_y + 4, start_x + 18, chao_y + 22, fill="#0F172A", outline="#38BDF8", width=1)
                        cv_vitrine.create_text(start_x, chao_y + 13, text=f"{qtd}x", font=("Impact", 11), fill="#F8FAFC")
                    
                    start_x += largura_slot + gap_ideal

            cv_vitrine.bind("<Configure>", desenhar_vitrine)

        # --- TABELA DE COMPETIÇÕES ABAIXO ---
        list_container = tk.Frame(content_inner, bg=BG_BASE)
        list_container.pack(fill="both", expand=True, padx=40, pady=(10, 40))
        tk.Label(list_container, text="HISTÓRICO POR COMPETIÇÃO (Clique para Relatório Geral)", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_BASE).pack(anchor="w", pady=(0, 10))

        dados_agrupados = {}
        for row in getattr(self, 'dados_desempenho', []):
            if len(row) < 8: continue
            comp_nome, jogos, gols, ass, ama, ver2, verd, mins = row[:8]
            nome_upper = comp_nome.upper()
            nome_final = comp_nome
            if "COPA DO MUNDO" in nome_upper and "ELIMIN" not in nome_upper: nome_final = "Copa Do Mundo"
            elif "ELIMIN" in nome_upper: nome_final = "Elimin. Copa Do Mundo"
            elif "COPA AMÉRICA" in nome_upper or "COPA AMERICA" in nome_upper: nome_final = "Copa América"

            if nome_final not in dados_agrupados: dados_agrupados[nome_final] = [nome_final, 0, 0, 0, 0, 0, 0, 0]
            dados_agrupados[nome_final][1] += jogos; dados_agrupados[nome_final][2] += gols; dados_agrupados[nome_final][3] += ass
            dados_agrupados[nome_final][4] += ama; dados_agrupados[nome_final][5] += ver2; dados_agrupados[nome_final][6] += verd; dados_agrupados[nome_final][7] += mins

        dados_ordenados = sorted(list(dados_agrupados.values()), key=lambda x: x[1], reverse=True)
        if not dados_ordenados:
            tk.Label(list_container, text="Você ainda não disputou nenhuma partida oficial.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_BASE).pack(pady=40)
            return

        header_t = tk.Frame(list_container, bg="#252F3D", height=35)
        header_t.pack(fill="x", pady=(0, 5))
        cols_def = [("COMPETIÇÃO", 0.02, "w"), ("JOGOS", 0.45, "c"), ("GOLS", 0.55, "c"), ("ASSIST.", 0.65, "c"), ("MÉDIA G/J", 0.75, "c"), ("CARTÕES", 0.85, "c"), ("MINUTOS", 0.95, "c")]
        for txt, rx, anc in cols_def: tk.Label(header_t, text=txt, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").place(relx=rx, rely=0.5, anchor=anc if anc != "c" else "center")

        for i, row in enumerate(dados_ordenados):
            comp_nome, jogos, gols, ass, ama, ver2, verd, mins = row
            cartoes_totais = ama + ver2 + verd
            media_gols = gols / jogos if jogos > 0 else 0

            row_f = tk.Frame(list_container, bg=BG_CARD, height=60, highlightthickness=1, highlightbackground="#334155", cursor="hand2")
            row_f.pack(fill="x", pady=3); row_f.pack_propagate(False)

            bar_color = "#38BDF8"
            n_up = comp_nome.upper()
            if "LIBERTADORES" in n_up or "CHAMPIONS" in n_up: bar_color = "#F59E0B"
            elif "BRASILEIRÃO" in n_up or "SERIE A" in n_up or "SÉRIE A" in n_up: bar_color = "#4ADE80"
            elif "COPA" in n_up or "CUP" in n_up or "POKAL" in n_up: bar_color = "#EF4444"
            elif "MUNDIAL" in n_up: bar_color = "#A855F7"
            
            tk.Frame(row_f, bg=bar_color, width=4).place(relx=0, rely=0, relheight=1)
            f_nome = tk.Frame(row_f, bg=BG_CARD); f_nome.place(relx=0.02, rely=0.5, anchor="w")
            
            try:
                safe_name = comp_nome.strip()
                path_logo = f"Logos/{safe_name}.png"
                if not os.path.exists(resource_path(path_logo)):
                    novo = baixar_logo_competicao(safe_name)
                    if novo: path_logo = novo
                if os.path.exists(resource_path(path_logo)):
                    pil = Image.open(resource_path(path_logo)).resize((35, 35), Image.Resampling.LANCZOS)
                    tk_ico = ImageTk.PhotoImage(pil); self.cache_tacas_geral.append(tk_ico)
                    tk.Label(f_nome, image=tk_ico, bg=BG_CARD).pack(side="left", padx=(0, 10))
                else: tk.Label(f_nome, text="🏆", font=("Segoe UI Emoji", 16), bg=BG_CARD, fg=TEXT_SUB).pack(side="left", padx=(0, 10))
            except: tk.Label(f_nome, text="🏆", font=("Segoe UI Emoji", 16), bg=BG_CARD, fg=TEXT_SUB).pack(side="left", padx=(0, 10))

            tk.Label(f_nome, text=comp_nome.upper()[:22] + "..." if len(comp_nome) > 25 else comp_nome.upper(), font=("Segoe UI", 11, "bold"), fg="white", bg=BG_CARD).pack(side="left")
            tk.Label(row_f, text=str(jogos), font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).place(relx=0.45, rely=0.5, anchor="center")
            tk.Label(row_f, text=str(gols), font=("Segoe UI", 12, "bold"), fg=C_GOLS, bg=BG_CARD).place(relx=0.55, rely=0.5, anchor="center")
            tk.Label(row_f, text=str(ass), font=("Segoe UI", 12, "bold"), fg=C_ASSIS, bg=BG_CARD).place(relx=0.65, rely=0.5, anchor="center")
            tk.Label(row_f, text=f"{media_gols:.2f}", font=("Segoe UI", 11, "bold"), fg=TEXT_SUB, bg=BG_CARD).place(relx=0.75, rely=0.5, anchor="center")
            tk.Label(row_f, text=str(cartoes_totais), font=("Segoe UI", 12, "bold"), fg=C_AMARELO if cartoes_totais > 0 else TEXT_SUB, bg=BG_CARD).place(relx=0.85, rely=0.5, anchor="center")
            tk.Label(row_f, text=f"{mins:,}".replace(",", "."), font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_CARD).place(relx=0.95, rely=0.5, anchor="center")

            def on_ent(e, r=row_f, fn=f_nome, c=bar_color): 
                r.configure(bg="#252F3D", highlightbackground=c)
                fn.configure(bg="#252F3D")
                for child in fn.winfo_children(): child.configure(bg="#252F3D")
                for child in r.winfo_children(): 
                    if isinstance(child, tk.Label): child.configure(bg="#252F3D")
                
            def on_lea(e, r=row_f, fn=f_nome): 
                r.configure(bg=BG_CARD, highlightbackground="#334155")
                fn.configure(bg=BG_CARD)
                for child in fn.winfo_children(): child.configure(bg=BG_CARD)
                for child in r.winfo_children(): 
                    if isinstance(child, tk.Label): child.configure(bg=BG_CARD)
            
            row_f.bind("<Enter>", on_ent); row_f.bind("<Leave>", on_lea)

            def ao_clicar_linha(event, c=comp_nome): self.abrir_popup_resumo_competicao_geral(c)
            row_f.bind("<Button-1>", ao_clicar_linha)
            for widget_interno in row_f.winfo_children() + f_nome.winfo_children(): widget_interno.bind("<Button-1>", ao_clicar_linha)

        tk.Frame(content_inner, bg=BG_BASE, height=50).pack()
    
    def abrir_popup_resumo_competicao_geral(self, comp_nome_alvo):
        from tkinter import Toplevel
        import tkinter as tk
        import os
        
        tot_jogos = 0; tot_gols = 0; tot_assists = 0
        soma_notas = 0.0; jogos_com_nota = 0
        tot_motm = 0
        
        tot_xg = 0.0; tot_chutes_gol = 0; tot_chutes_trave = 0; tot_chutes_fora = 0
        tot_chutes_bloq = 0; tot_gc_perdidas = 0
        tot_xa = 0.0; tot_pre_assists = 0; tot_posses_ganhas = 0; tot_posses_perdidas = 0; tot_distancia = 0.0
        
        tot_passes_dec = 0; tot_chances_criadas = 0; tot_dribles = 0
        tot_passes_c = 0; tot_passes_e = 0; tot_cruz_c = 0; tot_cruz_t = 0
        
        tot_desarmes = 0; tot_faltas_s = 0; tot_faltas_c = 0
        tot_clean = 0; tot_amarelos = 0; tot_vermelhos = 0
        
        tot_dir = 0; tot_esq = 0; tot_cab = 0
        tot_falta = 0; tot_pen = 0
        mapa_gols_acumulado = []

        # --- FILTRAGEM EM TODA A CARREIRA ---
        for jogo in self.ultimas_performances:
            jogo_comp = jogo.get("Competição", "")
            
            # Aplica a mesma normalização de nome usada na tabela principal
            nome_upper = jogo_comp.upper()
            nome_final = jogo_comp
            if "COPA DO MUNDO" in nome_upper and "ELIMIN" not in nome_upper: nome_final = "Copa Do Mundo"
            elif "ELIMIN" in nome_upper: nome_final = "Elimin. Copa Do Mundo"
            elif "COPA AMÉRICA" in nome_upper or "COPA AMERICA" in nome_upper: nome_final = "Copa América"

            if nome_final == comp_nome_alvo:
                pos = jogo.get("Posição", "MEI")
                status_ausente = ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]
                if int(jogo.get("Minutos", 90)) == 0 or pos in status_ausente:
                    continue
                
                tot_jogos += 1
                tot_gols += int(jogo.get("Gols", 0))
                tot_assists += int(jogo.get("Assistências", 0))
                
                try:
                    soma_notas += float(jogo.get("Nota", 6.0))
                    jogos_com_nota += 1
                except: pass

                det = jogo.get("Detalhes", {})
                if det.get("MOTM"): tot_motm += 1
                if det.get("CleanSheet"): tot_clean += 1
                
                tot_xg += float(det.get("xG", 0.0))
                tot_xa += float(det.get("xA", 0.0))
                tot_pre_assists += int(det.get("PreAssistencias", 0))
                tot_posses_ganhas += int(det.get("PossesGanhas", 0))
                tot_posses_perdidas += int(det.get("PossesPerdidas", 0))
                tot_distancia += float(det.get("DistanciaPercorrida", 0.0))

                tot_chutes_gol += int(det.get("ChutesNoGol", 0))
                tot_chutes_trave += int(det.get("ChutesNaTrave", 0))
                tot_chutes_fora += int(det.get("ChutesPraFora", 0))
                tot_chutes_bloq += int(det.get("ChutesBloqueados", 0))
                tot_gc_perdidas += int(det.get("GrandesChancesPerdidas", 0))
                
                tot_passes_dec += int(det.get("PassesDecisivos", 0))
                tot_chances_criadas += int(det.get("ChancesCriadas", 0))
                tot_dribles += int(det.get("DriblesCertos", 0))
                tot_passes_c += int(det.get("PassesCertos", 0))
                tot_passes_e += int(det.get("PassesErrados", 0))
                tot_cruz_c += int(det.get("CruzamentosCertos", 0))
                tot_cruz_t += int(det.get("CruzamentosTentados", 0))
                
                tot_desarmes += int(det.get("Desarmes", 0))
                tot_faltas_s += int(det.get("FaltasSofridas", 0))
                tot_faltas_c += int(det.get("FaltasCometidas", 0))
                
                tot_dir += int(det.get("PeDireito", 0))
                tot_esq += int(det.get("PeEsquerdo", 0))
                tot_cab += int(det.get("Cabeca", 0))
                tot_falta += int(det.get("FaltasGol", 0))
                tot_pen += int(det.get("PenalGol", 0))
                
                mapa_gols_acumulado.extend(det.get("MapaGols", []))

        # Puxar cartões diretamente do dados_desempenho
        for row in getattr(self, 'dados_desempenho', []):
            if len(row) < 8: continue
            jogo_comp = row[0]
            nome_upper = jogo_comp.upper()
            nome_final = jogo_comp
            if "COPA DO MUNDO" in nome_upper and "ELIMIN" not in nome_upper: nome_final = "Copa Do Mundo"
            elif "ELIMIN" in nome_upper: nome_final = "Elimin. Copa Do Mundo"
            elif "COPA AMÉRICA" in nome_upper or "COPA AMERICA" in nome_upper: nome_final = "Copa América"

            if nome_final == comp_nome_alvo:
                tot_amarelos += row[4]
                tot_vermelhos += row[5] + row[6]

        media_nota = soma_notas / jogos_com_nota if jogos_com_nota > 0 else 0.0

        BG_MODAL = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#38BDF8"

        pop = Toplevel(self)
        pop.title(f"Relatório de Scout Histórico - {comp_nome_alvo}")
        pop.geometry("750x850")
        pop.configure(bg=BG_MODAL)
        pop.resizable(False, False)
        
        pop.update_idletasks()
        x = (pop.winfo_screenwidth() // 2) - (750 // 2)
        y = (pop.winfo_screenheight() // 2) - (850 // 2)
        pop.geometry(f"+{x}+{y}")
        pop.grab_set()

        header = tk.Frame(pop, bg=BG_MODAL)
        header.pack(fill="x", pady=(20, 10), padx=30)
        
        f_logo = tk.Frame(header, bg=BG_MODAL)
        f_logo.pack(side="left")
        
        try:
            safe_name = comp_nome_alvo.strip()
            path_logo = f"Logos/{safe_name}.png"
            if os.path.exists(resource_path(path_logo)):
                from PIL import Image, ImageTk
                pil = Image.open(resource_path(path_logo)).resize((60, 60), Image.Resampling.LANCZOS)
                tk_ico = ImageTk.PhotoImage(pil)
                if not hasattr(self, 'club_logo_images'): self.club_logo_images = []
                self.club_logo_images.append(tk_ico) 
                tk.Label(f_logo, image=tk_ico, bg=BG_MODAL).pack()
            else:
                tk.Label(f_logo, text="🏆", font=("Segoe UI Emoji", 35), bg=BG_MODAL, fg=TEXT_SUB).pack()
        except: pass

        f_txt = tk.Frame(header, bg=BG_MODAL)
        f_txt.pack(side="left", padx=15)
        tk.Label(f_txt, text=comp_nome_alvo.upper(), font=("Impact", 28), fg="white", bg=BG_MODAL).pack(anchor="w")
        tk.Label(f_txt, text="Dossiê Estatístico Histórico (Todas as Temporadas)", font=("Segoe UI", 11), fg="#F59E0B", bg=BG_MODAL).pack(anchor="w")

        body_container = tk.Frame(pop, bg=BG_MODAL)
        body_container.pack(fill="both", expand=True, padx=10, pady=(0, 10))

        canvas = tk.Canvas(body_container, bg=BG_MODAL, highlightthickness=0)
        scrollbar = ttk.Scrollbar(body_container, orient="vertical", command=canvas.yview)
        scroll_frame = tk.Frame(canvas, bg=BG_MODAL)

        canvas.create_window((0, 0), window=scroll_frame, anchor="nw", width=700)
        canvas.configure(yscrollcommand=scrollbar.set)

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        def _on_mousewheel(event):
            try: canvas.yview_scroll(int(-1*(event.delta/120)), "units")
            except: pass
            
        pop.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", _on_mousewheel))
        
        def fechar_popup():
            canvas.unbind_all("<MouseWheel>")
            pop.destroy()
            
        pop.protocol("WM_DELETE_WINDOW", fechar_popup)
        scroll_frame.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # =======================================================
        # 1. BLOCO DE RESUMO RÁPIDO
        # =======================================================
        f_resumo = tk.Frame(scroll_frame, bg=BG_MODAL)
        f_resumo.pack(fill="x", pady=10, padx=15)
        for i in range(5): f_resumo.columnconfigure(i, weight=1)

        cor_nota = "#4ADE80" if media_nota >= 7.5 else ("#FACC15" if media_nota >= 6.5 else "#EF4444")
        
        kpis_base = [
            ("JOGOS", tot_jogos, "white"), ("GOLS", tot_gols, "#4ADE80"), 
            ("ASSIST.", tot_assists, "#38BDF8"), ("NOTA MÉDIA", f"{media_nota:.2f}", cor_nota),
            ("MOTM", tot_motm, "#F59E0B")
        ]
        
        for i, (lbl, val, cor) in enumerate(kpis_base):
            box = tk.Frame(f_resumo, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=10, pady=10)
            box.grid(row=0, column=i, sticky="nsew", padx=5)
            tk.Label(box, text=str(val), font=("Impact", 24), fg=cor, bg=BG_CARD).pack()
            tk.Label(box, text=lbl, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack()

        # =======================================================
        # FUNÇÃO HELPER PARA BLOCOS DE ESTATÍSTICAS
        # =======================================================
        def criar_bloco_stats(titulo, cor_titulo, lista_stats):
            f_bloco = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            f_bloco.pack(fill="x", pady=8, padx=20)
            
            tk.Label(f_bloco, text=titulo, font=("Segoe UI", 10, "bold"), fg=cor_titulo, bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 5))
            
            grid_s = tk.Frame(f_bloco, bg=BG_CARD)
            grid_s.pack(fill="x", padx=15, pady=(0, 10))
            
            for idx, (icone, label, valor) in enumerate(lista_stats):
                r = idx // 2; c = idx % 2
                item_f = tk.Frame(grid_s, bg=BG_CARD)
                item_f.grid(row=r, column=c, sticky="ew", padx=10, pady=2)
                grid_s.columnconfigure(c, weight=1)
                
                tk.Label(item_f, text=f"{icone} {label}", font=("Segoe UI", 9), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
                try: cv = "white" if float(valor) > 0 else "#64748B"
                except: cv = "white" if str(valor) not in ["0", "0.0", "0 / 0", "Não", ""] else "#64748B"
                
                tk.Label(item_f, text=str(valor), font=("Segoe UI", 10, "bold"), fg=cv, bg=BG_CARD).pack(side="right")

        # BLOCO 1: OFENSIVA
        ataque_stats = [
            ("📊", "Expected Goals (xG)", f"{tot_xg:.2f}"),
            ("🎯", "Chutes no Gol", tot_chutes_gol),
            ("🥅", "Chutes na Trave", tot_chutes_trave),
            ("❌", "Chutes para Fora", tot_chutes_fora),
            ("🛡️", "Chutes Bloqueados", tot_chutes_bloq),
            ("🤦", "Grandes Chances Perdidas", tot_gc_perdidas),
            ("🏃", "Distância Percorrida", f"{tot_distancia:.1f} km"),
        ]
        criar_bloco_stats("⚔️ OFENSIVA & FINALIZAÇÃO", "#4ADE80", ataque_stats)

        # BLOCO 2: PASSES
        criacao_stats = [
            ("📊", "Expected Assists (xA)", f"{tot_xa:.2f}"),
            ("🔑", "Passes Decisivos", tot_passes_dec),
            ("✨", "Chances Claras Criadas", tot_chances_criadas),
            ("🎁", "Pré-Assistências", tot_pre_assists),
            ("⚡", "Dribles Certos", tot_dribles),
            ("✅", "Passes Certos", tot_passes_c),
            ("❌", "Passes Errados", tot_passes_e),
            ("↪️", "Cruzamentos (C/T)", f"{tot_cruz_c} / {tot_cruz_t}"),
            ("♻️", "Posses Ganhas", tot_posses_ganhas),
            ("🗑️", "Posses Perdidas", tot_posses_perdidas),
        ]
        criar_bloco_stats("🧠 CRIAÇÃO E PASSES", "#38BDF8", criacao_stats)

        # BLOCO 3: DEFESA
        defesa_stats = [
            ("🥾", "Desarmes", tot_desarmes),
            ("🧤", "Jogos sem Sofrer Gols", tot_clean),
            ("🤕", "Faltas Sofridas", tot_faltas_s),
            ("🛑", "Faltas Cometidas", tot_faltas_c),
            ("🟨", "Cartões Amarelos", tot_amarelos),
            ("🟥", "Cartões Vermelhos", tot_vermelhos),
        ]
        criar_bloco_stats("🛡️ DEFESA E DISCIPLINA", "#EF4444", defesa_stats)

        # BLOCO 4: RAIO-X DOS GOLS E MAPA
        if int(tot_gols) > 0:
            raiox_stats = [
                ("🦶", "Pé Direito", tot_dir),
                ("🦶", "Pé Esquerdo", tot_esq),
                ("🗣️", "Cabeça", tot_cab),
                ("🎯", "Falta Direta", tot_falta),
                ("🥅", "Pênalti", tot_pen)
            ]
            criar_bloco_stats("🎯 ANATOMIA DOS GOLS", "#F59E0B", raiox_stats)

            if mapa_gols_acumulado:
                f_mapa_popup = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#F59E0B")
                f_mapa_popup.pack(fill="x", pady=8, padx=20)
                
                tk.Label(f_mapa_popup, text="🗺️ ONDE SEUS GOLS ENTRARAM NA HISTÓRIA DO TORNEIO", font=("Segoe UI", 10, "bold"), fg="#F59E0B", bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 0))
                
                cv_pop = tk.Canvas(f_mapa_popup, bg="#2A3645", height=180, highlightthickness=0)
                cv_pop.pack(fill="x", padx=15, pady=(10, 5))
                
                f_leg_pop = tk.Frame(f_mapa_popup, bg=BG_CARD)
                f_leg_pop.pack(fill="x", pady=(0, 10), padx=15)
                tk.Label(f_leg_pop, text="🟣 Ângulo/Alto", font=("Segoe UI", 8, "bold"), fg="#8B5CF6", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟠 Meia Altura", font=("Segoe UI", 8, "bold"), fg="#F59E0B", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟢 Rasteiro", font=("Segoe UI", 8, "bold"), fg="#10B981", bg=BG_CARD).pack(side="left", expand=True)
                
                def desenhar_mapa_popup(event):
                    cv_pop.delete("all")
                    w = event.width
                    h = event.height
                    if w < 50 or h < 50: return
                    
                    goal_h = 130  
                    goal_w = 340  
                    
                    t_x1 = (w - goal_w) / 2
                    t_x2 = t_x1 + goal_w
                    t_y1 = (h - goal_h) / 2 + 5
                    t_y2 = t_y1 + goal_h
                    
                    post_width = 6
                    
                    espaco_rede = 25
                    for i in range(int(t_x1) + espaco_rede, int(t_x2), espaco_rede):
                        cv_pop.create_line(i, t_y1, i, t_y2, fill="#3A4A5E", dash=(2, 2))
                    for i in range(int(t_y1) + espaco_rede, int(t_y2), espaco_rede):
                        cv_pop.create_line(t_x1, i, t_x2, i, fill="#3A4A5E", dash=(2, 2))

                    cv_pop.create_line(t_x1, t_y2, t_x1, t_y1, t_x2, t_y1, t_x2, t_y2, fill="white", width=post_width, joinstyle=tk.ROUND, capstyle=tk.ROUND)

                    for (px, py) in mapa_gols_acumulado:
                        real_x = t_x1 + (px * (t_x2 - t_x1))
                        real_y = t_y1 + (py * (t_y2 - t_y1))
                        raio = 8
                        cor_bola = "#10B981" if py > 0.65 else ("#8B5CF6" if py < 0.35 else "#F59E0B")
                        
                        cv_pop.create_oval(real_x-raio-3, real_y-raio-3, real_x+raio+3, real_y+raio+3, outline=cor_bola, width=2)
                        cv_pop.create_oval(real_x-raio, real_y-raio, real_x+raio, real_y+raio, fill=cor_bola, outline="white", width=2)

                cv_pop.bind("<Configure>", desenhar_mapa_popup)

        tk.Frame(scroll_frame, bg=BG_MODAL, height=20).pack()

        tk.Button(pop, text="FECHAR RELATÓRIO", bg="#334155", fg="white", font=("Segoe UI", 11, "bold"), relief="flat", command=fechar_popup, cursor="hand2", pady=10).pack(fill="x", padx=20, side="bottom", pady=15)

    def aba_detalhes_gols_faltas(self, parent_frame):
        # --- CORES E ESTILOS ---
        import tkinter as tk
        from tkinter import ttk
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np
        
        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        COLOR_RIGHT = "#0EA5E9" 
        COLOR_LEFT = "#F59E0B"  
        COLOR_HEAD = "#EF4444"  
        
        self.style.configure("DetMain.TFrame", background=BG_BASE)
        self.style.configure("DetCard.TFrame", background=BG_CARD, relief="solid", borderwidth=1, bordercolor="#334155")
        self.style.configure("DetTitle.TLabel", background=BG_CARD, foreground=TEXT_MAIN, font=("Segoe UI", 12, "bold"))
        self.style.configure("XRayCard.TFrame", background="#252F3D", relief="flat") 
        self.style.configure("XRayVal.TLabel", background="#252F3D", foreground="#38BDF8", font=("Segoe UI", 16, "bold"))
        self.style.configure("XRayLbl.TLabel", background="#252F3D", foreground="#CBD5E1", font=("Segoe UI", 8))

        aba_detalhes = ttk.Frame(parent_frame, style="DetMain.TFrame")
        aba_detalhes.pack(fill="both", expand=True)

        canvas_perf = tk.Canvas(aba_detalhes, bg=BG_BASE, highlightthickness=0)
        scrollbar_perf = ttk.Scrollbar(aba_detalhes, orient="vertical", command=canvas_perf.yview)
        
        perf_inner = ttk.Frame(canvas_perf, style="DetMain.TFrame")
        perf_window_id = canvas_perf.create_window((0, 0), window=perf_inner, anchor="nw")
        
        canvas_perf.configure(yscrollcommand=scrollbar_perf.set)
        canvas_perf.pack(side="left", fill="both", expand=True)
        scrollbar_perf.pack(side="right", fill="y")
        
        def _on_resize(event): canvas_perf.itemconfig(perf_window_id, width=event.width)
        canvas_perf.bind("<Configure>", _on_resize)
        def _on_mousewheel(event): 
            try:
                if canvas_perf.winfo_exists() and perf_inner.winfo_reqheight() > canvas_perf.winfo_height():
                    canvas_perf.yview_scroll(int(-1*(event.delta/120)), "units")
            except: pass
        canvas_perf.bind_all("<MouseWheel>", _on_mousewheel)
        perf_inner.bind("<Configure>", lambda e: canvas_perf.configure(scrollregion=canvas_perf.bbox("all")))

        # --- HEADER E FILTRO ---
        ctrl_frame = tk.Frame(perf_inner, bg=BG_BASE)
        ctrl_frame.pack(fill="x", padx=40, pady=(30, 0))
        
        tk.Label(ctrl_frame, text="MÉTRICAS DE FINALIZAÇÃO", font=("Impact", 32), fg="white", bg=BG_BASE).pack(anchor="w")
        tk.Label(ctrl_frame, text="Detalhes técnicos, zonas de gol e funil de letalidade organizados por eficiência.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_BASE).pack(anchor="w", pady=(0, 15))
        
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=COLOR_RIGHT, bg=BG_BASE).pack(anchor="w")
        
        opcoes_ano = ["Todas as Temporadas"] + sorted(list(getattr(self, 'dados_jogador', {}).keys()), reverse=True)
        selected_season = tk.StringVar(value=opcoes_ano[0])
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_ano, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        # --- CONTAINER DINÂMICO ---
        dynamic_container = tk.Frame(perf_inner, bg=BG_BASE)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_detalhes'): self.fig_detalhes = []

        def atualizar_view(event=None):
            for f in self.fig_detalhes: plt.close(f)
            self.fig_detalhes.clear()
            for widget in dynamic_container.winfo_children(): widget.destroy()

            filtro = selected_season.get()

            # Variáveis de cálculo
            pe_dir, pe_esq, cabeca = 0, 0, 0
            cantos_sup, cantos_inf, centro = 0, 0, 0
            faltas_tot, faltas_gol, penal_tot, penal_gol = 0, 0, 0, 0
            chutes_alvo, chutes_trave, chutes_fora, chutes_bloqueados = 0, 0, 0, 0
            total_gols_filtrado = 0
            xg_total = 0.0
            gols_empate, gols_virada = 0, 0
            gc_perdidas = 0
            gols_mapeados_trave = []

            # Retrocompatibilidade
            if filtro == "Todas as Temporadas":
                pe_dir = self.tipo_de_Gols.get("Perna Direita", 0)
                pe_esq = self.tipo_de_Gols.get("Perna Esquerda", 0)
                cabeca = self.tipo_de_Gols.get("Cabeça", 0)
                cantos_sup = self.tipo_de_Gols.get("Canto Superior Esquerdo", 0) + self.tipo_de_Gols.get("Canto Superior Direito", 0) + self.tipo_de_Gols.get("Meio Superior", 0)
                cantos_inf = self.tipo_de_Gols.get("Canto Inferior Direito", 0) + self.tipo_de_Gols.get("Canto Inferior Esquerdo", 0) + self.tipo_de_Gols.get("Meio Inferior", 0)
                centro = self.tipo_de_Gols.get("Meio", 0) + self.tipo_de_Gols.get("Canto Centro Direito", 0) + self.tipo_de_Gols.get("Canto Centro Esquerdo", 0)
                faltas_tot = self.Bolas_paradas.get("Faltas batidas", 0)
                faltas_gol = self.Bolas_paradas.get("Faltas Convertidas", 0)
                penal_tot = self.Bolas_paradas.get("Penaltis batidas", 0)
                penal_gol = self.Bolas_paradas.get("Penaltis Convertidas", 0)

            for jogo in self.ultimas_performances:
                if filtro != "Todas as Temporadas" and self._inferir_temporada(jogo.get("Data", "")) != filtro:
                    continue

                det = jogo.get("Detalhes", {})
                g = int(jogo.get("Gols", 0))
                total_gols_filtrado += g
                
                if filtro != "Todas as Temporadas":
                    pe_dir += int(det.get("PeDireito", 0))
                    pe_esq += int(det.get("PeEsquerdo", 0))
                    cabeca += int(det.get("Cabeca", 0))
                    cantos_sup += int(det.get("CantoSup", 0))
                    cantos_inf += int(det.get("CantoInf", 0))
                    centro += int(det.get("Centro", 0))
                    faltas_tot += int(det.get("FaltasBat", 0))
                    faltas_gol += int(det.get("FaltasGol", 0))
                    penal_tot += int(det.get("PenalBat", 0))
                    penal_gol += int(det.get("PenalGol", 0))

                c_alvo = int(det.get("ChutesNoGol", 0))
                c_alvo = max(c_alvo, g)
                chutes_alvo += c_alvo
                chutes_trave += int(det.get("ChutesNaTrave", 0))
                chutes_fora += int(det.get("ChutesPraFora", 0))
                chutes_bloqueados += int(det.get("ChutesBloqueados", 0))
                
                xg_total += float(det.get("xG", 0.0))
                gols_empate += 1 if det.get("GolEmpate") else 0
                gols_virada += 1 if det.get("GolVirada") else 0
                gc_perdidas += int(det.get("GrandesChancesPerdidas", 0))

                # Extrair posições do mapa
                mapa = det.get("MapaGols", [])
                for coord in mapa: gols_mapeados_trave.append(coord)

            total_chutes = chutes_alvo + chutes_trave + chutes_fora + chutes_bloqueados
            tx_conversao = (total_gols_filtrado / total_chutes * 100) if total_chutes > 0 else 0
            tx_precisao = (chutes_alvo / total_chutes * 100) if total_chutes > 0 else 0

            total_gols_analisados = pe_dir + pe_esq + cabeca
            if pe_dir > pe_esq: pref_foot = "Direito"; pref_val = pe_dir
            else: pref_foot = "Esquerdo"; pref_val = pe_esq
            pct_pref = (pref_val / total_gols_analisados * 100) if total_gols_analisados > 0 else 0

            # ======================================================================
            # ANDAR 1: FAIXA EXECUTIVA (KPIs Principais)
            # ======================================================================
            top_ribbon = tk.Frame(dynamic_container, bg=BG_BASE)
            top_ribbon.pack(fill="x", padx=40, pady=(10, 20))
            for i in range(4): top_ribbon.columnconfigure(i, weight=1)

            top_kpis = [
                ("GOLS MAPEADOS", f"{total_gols_filtrado}", "Total na temporada", "#10B981", "🎯"),
                ("TAXA CONVERSÃO", f"{tx_conversao:.1f}%", "Gols / Total Chutes", "#38BDF8", "⚡"),
                ("EXPECTED GOALS", f"{xg_total:.2f}", "xG acumulado", "#F59E0B", "📊"),
                ("PRECISÃO ALVO", f"{tx_precisao:.1f}%", "Chutes no gol", "#A855F7", "🥅")
            ]

            for i, (titulo, val, sub, cor, icone) in enumerate(top_kpis):
                box = tk.Frame(top_ribbon, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
                box.grid(row=0, column=i, sticky="nsew", padx=(0, 15) if i < 3 else 0)
                tk.Frame(box, bg=cor, height=2).pack(fill="x", side="top")
                tk.Label(box, text=f"{icone} {titulo}", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w", pady=(10, 5))
                tk.Label(box, text=val, font=("Segoe UI", 26, "bold"), fg=cor, bg=BG_CARD).pack(anchor="w")
                tk.Label(box, text=sub, font=("Segoe UI", 8), fg="#64748B", bg=BG_CARD).pack(anchor="w")

            # ======================================================================
            # ANDAR 2: ANATOMIA DO GOL (Donut | Mapa Trave | Bolas Paradas)
            # ======================================================================
            mid_grid = tk.Frame(dynamic_container, bg=BG_BASE)
            mid_grid.pack(fill="x", padx=40, pady=10)
            mid_grid.columnconfigure(0, weight=1) # Donut Origem
            mid_grid.columnconfigure(1, weight=2) # Mapa da Trave
            mid_grid.columnconfigure(2, weight=1) # Bolas Paradas

            # 2.1 ORIGEM DO GOL (DONUT)
            card_origin = ttk.Frame(mid_grid, style="DetCard.TFrame", padding=15)
            card_origin.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
            ttk.Label(card_origin, text="ORIGEM DOS GOLS", style="DetTitle.TLabel").pack(anchor="center", pady=(0, 10))
            
            fig_body, ax_body = plt.subplots(figsize=(3.5, 3.5), facecolor=BG_CARD)
            sizes_b = [pe_dir, pe_esq, cabeca]
            colors_b = [COLOR_RIGHT, COLOR_LEFT, COLOR_HEAD]
            
            if sum(sizes_b) == 0: sizes_b = [1, 0, 0]; colors_b = ["#334155", "#334155", "#334155"]
            wedges, _, _ = ax_body.pie(sizes_b, labels=None, autopct='%1.1f%%', startangle=90, colors=colors_b, 
                                       pctdistance=0.80, textprops=dict(color="white", fontsize=9, fontweight="bold"), 
                                       wedgeprops=dict(width=0.35, edgecolor=BG_CARD, linewidth=2))
            
            ax_body.text(0, 0, f"{total_gols_analisados}\nGOLS", ha='center', va='center', fontsize=12, fontweight='bold', color=TEXT_MAIN)
            ax_body.legend(wedges, ['Direita', 'Esquerda', 'Cabeça'], loc="lower center", bbox_to_anchor=(0.5, -0.2), frameon=False, labelcolor=TEXT_SUB, fontsize=9, ncol=1)
            plt.tight_layout()
            
            cb = FigureCanvasTkAgg(fig_body, master=card_origin); cb.draw(); cb.get_tk_widget().pack(fill="both", expand=True)
            self.fig_detalhes.append(fig_body)

            # 2.2 MAPA DE CALOR DOS GOLS (TRAVE NEON CENTRAL)
            card_loc = ttk.Frame(mid_grid, style="DetCard.TFrame", padding=20)
            card_loc.grid(row=0, column=1, sticky="nsew", padx=10)
            ttk.Label(card_loc, text="MAPA DA TRAVE (ZONAS DE GOL)", style="DetTitle.TLabel").pack(anchor="center", pady=(0, 10))
            
            f_leg_loc = tk.Frame(card_loc, bg=BG_CARD)
            f_leg_loc.pack(fill="x", pady=(0, 10))
            tk.Label(f_leg_loc, text="🟣 Ângulo/Alto", font=("Segoe UI", 8, "bold"), fg="#8B5CF6", bg=BG_CARD).pack(side="left", expand=True)
            tk.Label(f_leg_loc, text="🟠 Meia Altura", font=("Segoe UI", 8, "bold"), fg="#F59E0B", bg=BG_CARD).pack(side="left", expand=True)
            tk.Label(f_leg_loc, text="🟢 Rasteiro", font=("Segoe UI", 8, "bold"), fg="#10B981", bg=BG_CARD).pack(side="left", expand=True)

            cv_calor = tk.Canvas(card_loc, bg="#0F172A", highlightthickness=0)
            cv_calor.pack(fill="both", expand=True, pady=5)

            qtd_alto = sum(1 for _, py in gols_mapeados_trave if py < 0.35)
            qtd_meio = sum(1 for _, py in gols_mapeados_trave if 0.35 <= py <= 0.65)
            qtd_rast = sum(1 for _, py in gols_mapeados_trave if py > 0.65)
            
            f_resumo_calor = tk.Frame(card_loc, bg=BG_CARD)
            f_resumo_calor.pack(anchor="center", pady=(10, 0))
            tk.Label(f_resumo_calor, text=f"Total Mapeado: {len(gols_mapeados_trave)}   |", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
            tk.Label(f_resumo_calor, text=f"🟣 Alto: {qtd_alto}", font=("Segoe UI", 9, "bold"), fg="#8B5CF6", bg=BG_CARD).pack(side="left", padx=5)
            tk.Label(f_resumo_calor, text=f"🟠 Meio: {qtd_meio}", font=("Segoe UI", 9, "bold"), fg="#F59E0B", bg=BG_CARD).pack(side="left", padx=5)
            tk.Label(f_resumo_calor, text=f"🟢 Rasteiro: {qtd_rast}", font=("Segoe UI", 9, "bold"), fg="#10B981", bg=BG_CARD).pack(side="left", padx=5)

            def desenhar_mapa_dinamico(event):
                cv_calor.delete("all")
                w = event.width
                h = event.height
                if w < 50 or h < 50: return
                
                t_x1, t_y1 = 40, 40
                t_x2, t_y2 = w - 40, h - 20
                post_width = 8
                crossbar_y = t_y1 + post_width / 2

                # Rede mais elegante
                espaco_rede = 35
                net_y_start = int(crossbar_y + post_width / 2)
                for i in range(int(t_x1 + espaco_rede), int(t_x2), int(espaco_rede)): 
                    cv_calor.create_line(i, net_y_start, i, t_y2, fill="#1E293B", dash=(4, 2), width=1.5)
                for i in range(net_y_start + espaco_rede, int(t_y2), int(espaco_rede)): 
                    cv_calor.create_line(t_x1 + post_width/2, i, t_x2 - post_width/2, i, fill="#1E293B", dash=(4, 2), width=1.5)
                
                # Sombra Ciano
                cv_calor.create_line(t_x1-2, t_y2, t_x1-2, t_y1-2, t_x2+2, t_y1-2, t_x2+2, t_y2, fill="#38BDF8", width=4, joinstyle=tk.ROUND, capstyle=tk.ROUND)
                # Barra Branca
                cv_calor.create_line(t_x1, t_y2, t_x1, t_y1, t_x2, t_y1, t_x2, t_y2, fill="white", width=post_width, joinstyle=tk.ROUND, capstyle=tk.ROUND)

                goalmouth_x1 = t_x1 + post_width/2; goalmouth_x2 = t_x2 - post_width/2
                goalmouth_y1 = crossbar_y + post_width/2; goalmouth_y2 = t_y2

                for (px, py) in gols_mapeados_trave:
                    real_x = goalmouth_x1 + (px * (goalmouth_x2 - goalmouth_x1))
                    real_y = goalmouth_y1 + (py * (goalmouth_y2 - goalmouth_y1))
                    
                    raio = 9
                    cor_bola = "#10B981" if py > 0.65 else ("#8B5CF6" if py < 0.35 else "#F59E0B")
                    
                    cv_calor.create_oval(real_x-raio-4, real_y-raio-4, real_x+raio+4, real_y+raio+4, outline=cor_bola, width=2)
                    cv_calor.create_oval(real_x-raio, real_y-raio, real_x+raio, real_y+raio, fill=cor_bola, outline="white", width=2)

            cv_calor.bind("<Configure>", desenhar_mapa_dinamico)

            # 2.3 BOLAS PARADAS (BAR CHART)
            card_set = ttk.Frame(mid_grid, style="DetCard.TFrame", padding=15)
            card_set.grid(row=0, column=2, sticky="nsew", padx=(10, 0))
            ttk.Label(card_set, text="BOLAS PARADAS", style="DetTitle.TLabel").pack(anchor="center", pady=(0, 10))
            
            fig_set, ax_set = plt.subplots(figsize=(3.5, 3.5), facecolor=BG_CARD)
            self._aplicar_gradiente_fundo(ax_set, cor_topo="#1E3A8A", cor_fundo=BG_CARD)
            
            totals = [penal_tot, faltas_tot]
            goals = [penal_gol, faltas_gol]
            y_pos = np.arange(2)
            
            ax_set.barh(y_pos, totals, 0.4, color="#334155", edgecolor="#475569", label='Batidas', zorder=2)
            ax_set.barh(y_pos, goals, 0.4, color=["#38BDF8", "#A3E635"], edgecolor="white", linewidth=1, label='Gols', zorder=3)
            
            ax_set.set_yticks(y_pos); ax_set.set_yticklabels(['Pênaltis', 'Faltas'], color=TEXT_MAIN, fontsize=10, fontweight="bold")
            ax_set.spines['top'].set_visible(False); ax_set.spines['right'].set_visible(False)
            ax_set.spines['bottom'].set_visible(False); ax_set.spines['left'].set_visible(False)
            ax_set.tick_params(axis='x', bottom=False, labelbottom=False)
            
            for i, (t, g) in enumerate(zip(totals, goals)):
                offset = 0.2 if g > 0 else 0
                ax_set.text(g + offset, i, f"{g}", va='center', ha='left', color="white", fontweight='bold', fontsize=11, zorder=4)
                ax_set.text(t + 0.5, i, f"({g}/{t})", va='center', ha='left', color=TEXT_SUB, fontsize=9, zorder=4)

            plt.tight_layout()
            cs = FigureCanvasTkAgg(fig_set, master=card_set); cs.draw(); cs.get_tk_widget().pack(fill="both", expand=True)
            self.fig_detalhes.append(fig_set)

            # ======================================================================
            # ANDAR 3: LABORATÓRIO (Funil | Grid de KPIs)
            # ======================================================================
            bot_grid = tk.Frame(dynamic_container, bg=BG_BASE)
            bot_grid.pack(fill="x", padx=40, pady=10)
            bot_grid.columnconfigure(0, weight=1) # Funil
            bot_grid.columnconfigure(1, weight=2) # Grid KPIs

            # 3.1 FUNIL DE CONVERSÃO
            card_funnel = ttk.Frame(bot_grid, style="DetCard.TFrame", padding=20)
            card_funnel.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
            ttk.Label(card_funnel, text="FUNIL DE LETALIDADE", style="DetTitle.TLabel").pack(anchor="w", pady=(0, 5))
            
            fig_funnel, ax_funnel = plt.subplots(figsize=(4, 3.5), facecolor=BG_CARD)
            self._aplicar_gradiente_fundo(ax_funnel, cor_topo="#1E3A8A", cor_fundo=BG_CARD)
            
            f_labels = ["Total de Chutes", "Chutes no Alvo", "Gols Marcados"]
            f_values = [total_chutes, chutes_alvo, total_gols_filtrado]
            plot_values = [v if v > 0 else 0.1 for v in f_values] 
            y_pos_f = [2, 1, 0]
            
            for y, val, p_val, col, lbl in zip(y_pos_f, f_values, plot_values, ["#475569", "#38BDF8", "#10B981"], f_labels):
                ax_funnel.barh(y, p_val, left=-p_val/2, height=0.6, color=col, align='center', zorder=3, edgecolor="white", linewidth=1)
                ax_funnel.text(0, y, "0" if val == 0 else str(val), ha='center', va='center', color='white', fontweight='bold', fontsize=12, zorder=4)
                ax_funnel.text(- (max(plot_values)/2) - (max(plot_values)*0.1), y, lbl, ha='right', va='center', color=TEXT_SUB, fontsize=9, fontweight="bold", zorder=4)

            ax_funnel.spines['top'].set_visible(False); ax_funnel.spines['right'].set_visible(False)
            ax_funnel.spines['left'].set_visible(False); ax_funnel.spines['bottom'].set_visible(False)
            ax_funnel.tick_params(axis='both', bottom=False, left=False, labelbottom=False, labelleft=False)
            
            plt.tight_layout()
            cf = FigureCanvasTkAgg(fig_funnel, master=card_funnel); cf.draw(); cf.get_tk_widget().pack(fill="both", expand=True)
            self.fig_detalhes.append(fig_funnel)

            # 3.2 DETALHES AVANÇADOS (GRID 4x2)
            card_eff = ttk.Frame(bot_grid, style="DetCard.TFrame", padding=20)
            card_eff.grid(row=0, column=1, sticky="nsew", padx=10)
            ttk.Label(card_eff, text="PERFIL E EFICIÊNCIA TÉCNICA", style="DetTitle.TLabel").pack(anchor="w", pady=(0, 15))
            
            eff_grid = ttk.Frame(card_eff, style="DetCard.TFrame")
            eff_grid.pack(fill="both", expand=True)
            
            kpis_eff = [
                ("PÉ PREFERIDO", f"{pref_foot}", f"{pct_pref:.0f}% de uso", COLOR_RIGHT),
                ("GOLS DECISIVOS", f"{gols_empate + gols_virada}", f"{gols_virada} Vir. | {gols_empate} Emp.", "#0EA5E9"),
                ("CABECEIO", f"{cabeca}", "Gols Aéreos", COLOR_HEAD), 
                ("GRANDES CHANCES", f"{gc_perdidas}", "Perdidas (Oport. Claras)", "#EF4444"),
                ("VERSATILIDADE", f"{pe_esq if pref_foot == 'Direito' else pe_dir}", "Gols (Pé Ruim)", "#8B5CF6"),
                ("AZARÃO (TRAVE)", f"{chutes_trave}", "Bolas na trave", "#F59E0B"), 
                ("CHUTES BLOQ.", f"{chutes_bloqueados}", "Travados pela zaga", "#94A3B8"),
                ("CHUTES P/ FORA", f"{chutes_fora}", "Errou o alvo", "#64748B") 
            ]
            
            for i, (title, val, sub, cor_borda) in enumerate(kpis_eff):
                mc = tk.Frame(eff_grid, bg="#252F3D", highlightthickness=1, highlightbackground="#334155")
                mc.grid(row=i//4, column=i%4, sticky="nsew", padx=4, pady=4)
                tk.Frame(mc, bg=cor_borda, width=3).pack(side="left", fill="y")
                
                inner_mc = ttk.Frame(mc, style="XRayCard.TFrame", padding=8)
                inner_mc.pack(side="left", fill="both", expand=True)
                ttk.Label(inner_mc, text=title, style="XRayLbl.TLabel", font=("Segoe UI", 7, "bold")).pack(anchor="w")
                ttk.Label(inner_mc, text=val, style="XRayVal.TLabel", font=("Segoe UI", 13, "bold"), foreground=cor_borda).pack(anchor="w", pady=(1, 0))
                ttk.Label(inner_mc, text=sub, style="XRayLbl.TLabel", font=("Segoe UI", 7)).pack(anchor="w")
                
                mc.bind("<Enter>", lambda e, w=mc, iw=inner_mc: [w.config(bg="#334155"), iw.configure(style="XRayCardHover.TFrame")])
                mc.bind("<Leave>", lambda e, w=mc, iw=inner_mc: [w.config(bg="#252F3D"), iw.configure(style="XRayCard.TFrame")])
                self.style.configure("XRayCardHover.TFrame", background="#334155")

            eff_grid.columnconfigure(0, weight=1); eff_grid.columnconfigure(1, weight=1)
            eff_grid.columnconfigure(2, weight=1); eff_grid.columnconfigure(3, weight=1)
            
            tk.Frame(dynamic_container, bg=BG_BASE, height=50).pack()

        combo.bind("<<ComboboxSelected>>", atualizar_view)
        atualizar_view()

