    def desempenho_por_clubes(self, parent_frame):
        # --- CONFIGURAÇÃO DE ESTILOS "NEXT-GEN" ---
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np
        import os
        from PIL import Image, ImageTk

        BG_DARK = "#0F172A"       
        BG_CARD = "#1E293B"       
        ACCENT_CYAN = "#38BDF8"   
        ACCENT_GOLD = "#F59E0B"   
        TEXT_MAIN = "#F8FAFC"     
        TEXT_SUB = "#94A3B8"      
        
        self.style.configure("ClubMain.TFrame", background=BG_DARK)

        # --- ESTRUTURA PRINCIPAL (Scrollável) ---
        aba_clubes = ttk.Frame(parent_frame, style="ClubMain.TFrame")
        aba_clubes.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_clubes, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_clubes, orient="vertical", command=canvas.yview)
        
        inner = ttk.Frame(canvas, style="ClubMain.TFrame")
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        def _scroll(e): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # ======================================================================
        # MOTOR DE DADOS ENRIQUECIDOS (Com as imagens dos Troféus e Minutos Reais)
        # ======================================================================
        dados_ricos = {}
        for c, d in getattr(self, 'dados_desempenho_por_clubes', {}).items():
            dados_ricos[c] = {
                'jogos': d.get('jogos', 0),
                'gols': d.get('gols', 0),
                'assists': d.get('assistencias', 0),
                'titulos': d.get('titulos', 0),
                'mins': 0, 
                'motm': 0,
                'imagens_titulos': [] 
            }
            
        # Puxar imagens dos títulos
        for item in getattr(self, 'conquistas', []):
            try:
                img_path = item[0]
                clube_titulo = item[3]
                if clube_titulo in dados_ricos:
                    if img_path and img_path not in dados_ricos[clube_titulo]['imagens_titulos']:
                        dados_ricos[clube_titulo]['imagens_titulos'].append(img_path)
            except: pass
        
        # Puxar Melhor em Campo (MOTM)
        for j in getattr(self, 'ultimas_performances', []):
            clube_jogo = j.get("Time", self.informacoes.get("Clube Atual"))
            if clube_jogo in dados_ricos:
                det = j.get("Detalhes", {})
                if det.get("MOTM"): dados_ricos[clube_jogo]['motm'] += 1

        # VARREDURA PROFUNDA DE MINUTOS 
        fontes_padrao = [
            getattr(self, 'dados_temporadas_Liga', {}),
            getattr(self, 'dados_temporadas_Copas_Nacional', {}),
            getattr(self, 'dados_temporadas_Copas_Regional', {}),
            getattr(self, 'dados_temporadas_Copas_Continental', {}),
            getattr(self, 'desmepenho_mundila_de_clubes', {})
        ]
        
        for fonte in fontes_padrao:
            for ano, lista in fonte.items():
                for jogo in lista:
                    try:
                        c = jogo[4] # Clube Representado
                        m = int(jogo[13]) # Minutos
                        if c in dados_ricos: dados_ricos[c]['mins'] += m
                    except: pass
                    
        # Varredura Supercopa
        if hasattr(self, 'dados_temporadas_SuperCopa'):
            for ano, comps in self.dados_temporadas_SuperCopa.items():
                if isinstance(comps, dict):
                    for nc, lj in comps.items():
                        for jogo in lj:
                            try:
                                c = jogo.get("Clube")
                                m = int(jogo.get("Minutos Jogados", 0))
                                if c in dados_ricos: dados_ricos[c]['mins'] += m
                            except: pass
                elif isinstance(comps, list):
                    for jogo in comps:
                        try:
                            c = jogo[4]
                            m = int(jogo[13])
                            if c in dados_ricos: dados_ricos[c]['mins'] += m
                        except: pass
                        
        # Varredura Seleção
        if hasattr(self, 'dados_competicoes_por_seleção'):
            for nc, lj in self.dados_competicoes_por_seleção.items():
                for jogo in lj:
                    try:
                        c = jogo[3] # Seleção
                        m = int(jogo[12]) # Índice de minutos pra seleção
                        if c in dados_ricos: dados_ricos[c]['mins'] += m
                    except: pass

        total_clubes = len(dados_ricos)
        total_j = sum(d['jogos'] for d in dados_ricos.values())
        total_g = sum(d['gols'] for d in dados_ricos.values())
        total_a = sum(d['assists'] for d in dados_ricos.values())
        total_t = sum(d['titulos'] for d in dados_ricos.values())

        # ======================================================================
        # 1. HEADER (Visão Geral)
        # ======================================================================
        f_header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        f_header.pack(fill="x")
        
        tk.Label(f_header, text="HISTÓRICO POR CLUBES", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(f_header, text="Dossiê de desempenho e impacto em cada camisa que você vestiu.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # KPIs do Header
        f_kpis = tk.Frame(inner, bg=BG_DARK)
        f_kpis.pack(fill="x", padx=40, pady=(0, 20))
        
        kpis_gerais = [
            ("CLUBES", total_clubes, "#A855F7"),
            ("JOGOS", total_j, "white"),
            ("GOLS", total_g, "#4ADE80"),
            ("ASSISTS", total_a, "#38BDF8"),
            ("TÍTULOS", total_t, "#F59E0B")
        ]
        
        for lbl, val, cor in kpis_gerais:
            box = tk.Frame(f_kpis, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=10)
            box.pack(side="left", padx=(0, 15))
            tk.Frame(box, bg=cor, height=3).pack(fill="x", side="top", pady=(0, 5))
            tk.Label(box, text=str(val), font=("Segoe UI", 20, "bold"), fg=cor, bg=BG_CARD).pack(anchor="w")
            tk.Label(box, text=lbl, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")

        # ======================================================================
        # 2. LISTA EXPANDIDA DOS CLUBES (DOSSIÊ)
        # ======================================================================
        f_lista = tk.Frame(inner, bg=BG_DARK)
        f_lista.pack(fill="x", padx=40, pady=10)
        
        clubes_ordenados = sorted(dados_ricos.items(), key=lambda x: x[1]['jogos'], reverse=True)
        
        if not clubes_ordenados:
            tk.Label(f_lista, text="Nenhum dado de clube registrado ainda.", fg=TEXT_SUB, bg=BG_DARK, font=("Segoe UI", 12)).pack(pady=40)

        for nome_clube, stats in clubes_ordenados:
            # Container da linha AGORA USANDO TK.FRAME PARA A BORDA FUNCIONAR!
            row = tk.Frame(f_lista, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            row.pack(fill="x", pady=8)
            
            # Layout Grid interno para alinhamento perfeito
            inner_row = tk.Frame(row, bg=BG_CARD, padx=15, pady=15)
            inner_row.pack(fill="both", expand=True)
            
            inner_row.columnconfigure(0, weight=2) # Logo + Nome
            inner_row.columnconfigure(1, weight=2) # Jogos / Gols / Assists
            inner_row.columnconfigure(2, weight=2) # Minutos / Média / MOTM
            inner_row.columnconfigure(3, weight=1) # Títulos
            
            # --- COLUNA 0: CLUBE ---
            f_clube = tk.Frame(inner_row, bg=BG_CARD)
            f_clube.grid(row=0, column=0, sticky="w")
            
            cor_destaque = ACCENT_GOLD if nome_clube.upper() == "BRASIL" else ACCENT_CYAN
            tk.Frame(f_clube, bg=cor_destaque, width=4).pack(side="left", fill="y", padx=(0, 15))
            
            self._render_logo_mini(f_clube, nome_clube)
            nome_cut = nome_clube.upper()
            if len(nome_cut) > 16: nome_cut = nome_cut[:14] + "..."
            tk.Label(f_clube, text=nome_cut, font=("Segoe UI", 14, "bold"), fg="white", bg=BG_CARD).pack(side="left", padx=(10, 0))

            # --- COLUNA 1: PRODUTIVIDADE ---
            f_prod = tk.Frame(inner_row, bg=BG_CARD)
            f_prod.grid(row=0, column=1, sticky="w", padx=20)
            
            def add_stat(parent, icone, lbl, val, cor_val):
                f = tk.Frame(parent, bg=BG_CARD)
                f.pack(side="left", padx=10)
                tk.Label(f, text=f"{icone} {lbl}", font=("Segoe UI", 8), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")
                tk.Label(f, text=str(val), font=("Segoe UI", 14, "bold"), fg=cor_val, bg=BG_CARD).pack(anchor="w")

            add_stat(f_prod, "👕", "JOGOS", stats['jogos'], "white")
            add_stat(f_prod, "⚽", "GOLS", stats['gols'], "#4ADE80")
            add_stat(f_prod, "🤝", "ASSISTS", stats['assists'], "#38BDF8")

            # --- COLUNA 2: EFICIÊNCIA ---
            f_efi = tk.Frame(inner_row, bg=BG_CARD)
            f_efi.grid(row=0, column=2, sticky="w", padx=20)
            
            media_g = (stats['gols'] / stats['jogos']) if stats['jogos'] > 0 else 0
            
            add_stat(f_efi, "⏱️", "MINUTOS", f"{stats['mins']:,}".replace(",", "."), "#94A3B8")
            add_stat(f_efi, "📊", "MÉDIA G/J", f"{media_g:.2f}", "#FACC15" if media_g >= 0.5 else "white")
            add_stat(f_efi, "🏅", "MOTM", stats['motm'], "#A855F7")

            # --- COLUNA 3: TÍTULOS ---
            f_titulos = tk.Frame(inner_row, bg=BG_CARD)
            f_titulos.grid(row=0, column=3, sticky="e", padx=10)
            
            if stats['titulos'] > 0:
                f_miniaturas = tk.Frame(f_titulos, bg=BG_CARD)
                f_miniaturas.pack(side="left", padx=(0, 10))
                
                imagens_para_mostrar = stats['imagens_titulos'][:3] 
                
                if not imagens_para_mostrar:
                    tk.Label(f_miniaturas, text="🏆", font=("Segoe UI Emoji", 24), bg=BG_CARD, fg=ACCENT_GOLD).pack(side="left")
                else:
                    for img_path in imagens_para_mostrar:
                        path_final = None
                        if os.path.exists(img_path): path_final = img_path
                        elif os.path.exists(os.path.abspath(img_path)): path_final = os.path.abspath(img_path)
                        elif os.path.exists(self.resource_path(img_path)): path_final = self.resource_path(img_path)
                        
                        mostrou = False
                        if path_final:
                            try:
                                pil_img = Image.open(path_final).resize((35, 35), Image.Resampling.LANCZOS)
                                tk_img = ImageTk.PhotoImage(pil_img)
                                self.club_logo_images.append(tk_img) 
                                tk.Label(f_miniaturas, image=tk_img, bg=BG_CARD).pack(side="left", padx=2)
                                mostrou = True
                            except: pass
                            
                        if not mostrou:
                            tk.Label(f_miniaturas, text="🏆", font=("Segoe UI Emoji", 18), bg=BG_CARD, fg=ACCENT_GOLD).pack(side="left", padx=2)
                
                if len(stats['imagens_titulos']) > 3:
                    tk.Label(f_miniaturas, text="+", font=("Segoe UI", 12, "bold"), fg=ACCENT_GOLD, bg=BG_CARD).pack(side="left", padx=2)

                f_t_txt = tk.Frame(f_titulos, bg=BG_CARD)
                f_t_txt.pack(side="left", padx=5)
                tk.Label(f_t_txt, text=str(stats['titulos']), font=("Segoe UI", 16, "bold"), fg=ACCENT_GOLD, bg=BG_CARD).pack(anchor="w")
                tk.Label(f_t_txt, text="TÍTULOS", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")
            else:
                tk.Label(f_titulos, text="Nenhum título", font=("Segoe UI", 9, "italic"), fg="#475569", bg=BG_CARD).pack()

            # Efeitos de Hover
            def on_ent(e, r=row, ir=inner_row): 
                r.configure(bg="#252F3D", highlightbackground="#475569")
                ir.configure(bg="#252F3D")
                for child in ir.winfo_children(): 
                    try: child.configure(bg="#252F3D")
                    except: pass
                    for sub in child.winfo_children():
                        try: sub.configure(bg="#252F3D")
                        except: pass

            def on_lea(e, r=row, ir=inner_row): 
                r.configure(bg=BG_CARD, highlightbackground="#334155")
                ir.configure(bg=BG_CARD)
                for child in ir.winfo_children(): 
                    try: child.configure(bg=BG_CARD)
                    except: pass
                    for sub in child.winfo_children():
                        try: sub.configure(bg=BG_CARD)
                        except: pass

            row.bind("<Enter>", on_ent); row.bind("<Leave>", on_lea)

        # ======================================================================
        # 3. GRÁFICO COMPARATIVO DE ARTILHARIA
        # ======================================================================
        if total_g > 0:
            f_chart = tk.Frame(inner, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_chart.pack(fill="x", padx=40, pady=(20, 40))
            
            tk.Label(f_chart, text="ARTILHARIA POR CLUBE", font=("Segoe UI", 14, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 5))
            tk.Label(f_chart, text="Comparativo de onde você foi mais letal.", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w", pady=(0, 20))

            fig, ax = plt.subplots(figsize=(10, max(3, len(clubes_ordenados)*0.6)), facecolor=BG_CARD)
            self._aplicar_gradiente_fundo(ax, cor_topo="#1E3A8A", cor_fundo=BG_CARD)

            nomes_plot = []
            gols_plot = []
            
            for c, s in reversed(clubes_ordenados):
                if s['gols'] > 0:
                    nomes_plot.append(c[:15].upper())
                    gols_plot.append(s['gols'])

            if gols_plot:
                y_pos = np.arange(len(nomes_plot))
                bars = ax.barh(y_pos, gols_plot, height=0.5, color="#4ADE80", edgecolor="white", linewidth=1, zorder=3)
                
                for i, v in enumerate(gols_plot):
                    ax.text(v + (max(gols_plot)*0.02), i, str(v), color="white", fontweight="bold", va="center", zorder=4)

                ax.set_yticks(y_pos)
                ax.set_yticklabels(nomes_plot, color="white", fontweight="bold", fontsize=10)
                
                ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
                ax.spines['left'].set_visible(False); ax.spines['bottom'].set_visible(False)
                ax.tick_params(axis='x', bottom=False, labelbottom=False) 
                ax.tick_params(axis='y', colors=TEXT_SUB, labelsize=9)
                
                plt.tight_layout()
                canvas_chart = FigureCanvasTkAgg(fig, master=f_chart)
                canvas_chart.draw()
                canvas_chart.get_tk_widget().pack(fill="both", expand=True)
                self.matplotlib_canvases.append(canvas_chart)

        tk.Frame(inner, bg=BG_DARK, height=50).pack()

    def aba_gols_por_minutos(self, parent_frame):
        # --- IMPORTAÇÕES E ESTILOS ---
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np

        BG_DARK = "#0F172A"       
        BG_CARD = "#1E293B"       
        TEXT_MAIN = "#F8FAFC"     
        TEXT_SUB = "#94A3B8"      
        
        COLOR_1T = "#38BDF8"  # Ciano
        COLOR_2T = "#EF4444"  # Vermelho
        COLOR_PR = "#F59E0B"  # Dourado

        self.style.configure("MinMain.TFrame", background=BG_DARK)

        # --- ESTRUTURA (Scrollável) ---
        aba_minutos = ttk.Frame(parent_frame, style="MinMain.TFrame")
        aba_minutos.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_minutos, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_minutos, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="MinMain.TFrame")
        
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        def _scroll(e): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # ======================================================================
        # 1. HEADER E FILTRO
        # ======================================================================
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="CRONOMETRIA DOS GOLS", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="Análise de letalidade: em qual momento do jogo você é mais perigoso?", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # Filtro de Temporada
        ctrl_frame = tk.Frame(inner, bg=BG_DARK)
        ctrl_frame.pack(fill="x", padx=40, pady=(10, 10))
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=COLOR_1T, bg=BG_DARK).pack(anchor="w")
        
        # Puxar anos disponíveis dos dados
        anos_disp = set()
        for d in self.dados_gols_por_minutos:
            if d[6] > 0: anos_disp.add(str(d[0]))
        
        opcoes_ano = ["Todas as Temporadas"] + sorted(list(anos_disp), reverse=True)
        selected_season = tk.StringVar(value=opcoes_ano[0])
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_ano, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        # Container Dinâmico
        dynamic_container = tk.Frame(inner, bg=BG_DARK)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_minutos'): self.fig_minutos = []

        def atualizar_view(event=None):
            # Limpeza
            for f in self.fig_minutos: plt.close(f)
            self.fig_minutos.clear()
            for widget in dynamic_container.winfo_children(): widget.destroy()

            filtro = selected_season.get()

            # --- PROCESSAMENTO DE DADOS ---
            dados_filtrados = []
            for d in self.dados_gols_por_minutos:
                if d[6] > 0: # Tem gols
                    if filtro == "Todas as Temporadas" or str(d[0]) == filtro:
                        dados_filtrados.append(d)
            
            # Ordenar por ano (decrescente) e total de gols
            dados_filtrados.sort(key=lambda x: (str(x[0]), x[6]), reverse=True)

            if not dados_filtrados:
                tk.Label(dynamic_container, text="Nenhum gol registrado para este filtro.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_DARK).pack(pady=50)
                return

            # Agregação Global
            sum_1t = sum(d[3] for d in dados_filtrados)
            sum_2t = sum(d[4] for d in dados_filtrados)
            sum_pr = sum(d[5] for d in dados_filtrados)
            total_gols = sum_1t + sum_2t + sum_pr

            pct_1t = (sum_1t / total_gols * 100) if total_gols > 0 else 0
            pct_2t = (sum_2t / total_gols * 100) if total_gols > 0 else 0
            pct_pr = (sum_pr / total_gols * 100) if total_gols > 0 else 0
            
            poder_decisao = pct_2t + pct_pr

            # Lógica do Scout
            if sum_2t + sum_pr > sum_1t:
                perfil_tempo = "Decisivo no 2º Tempo"
                desc_tempo = "Você costuma crescer de produção na etapa final, aproveitando o cansaço do adversário para matar o jogo."
                cor_perfil = COLOR_2T
            elif sum_1t > sum_2t + sum_pr:
                perfil_tempo = "Agressivo no Início"
                desc_tempo = "Sua marca é resolver o jogo logo cedo. Você impõe um ritmo forte no 1º tempo e surpreende as defesas."
                cor_perfil = COLOR_1T
            else:
                perfil_tempo = "Ameaça Constante"
                desc_tempo = "Seus gols são perfeitamente distribuídos. Você é perigoso em qualquer momento da partida."
                cor_perfil = "#10B981" # Verde

            # ======================================================================
            # 2. HEADER KPIS
            # ======================================================================
            kpi_frame = tk.Frame(dynamic_container, bg=BG_DARK)
            kpi_frame.pack(fill="x", padx=40, pady=(0, 20))
            kpi_frame.columnconfigure(0, weight=1); kpi_frame.columnconfigure(1, weight=1); kpi_frame.columnconfigure(2, weight=1); kpi_frame.columnconfigure(3, weight=1)

            kpis = [
                ("TOTAL DE GOLS", total_gols, "white"),
                ("GOLS 1º TEMPO", f"{sum_1t} ({pct_1t:.1f}%)", COLOR_1T),
                ("GOLS 2º TEMPO", f"{sum_2t} ({pct_2t:.1f}%)", COLOR_2T),
                ("PODER DE DECISÃO", f"{poder_decisao:.1f}%", COLOR_PR) # 2T + PR
            ]

            for i, (lbl, val, cor) in enumerate(kpis):
                box = tk.Frame(kpi_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
                box.grid(row=0, column=i, sticky="nsew", padx=(0, 15) if i < 3 else 0)
                tk.Frame(box, bg=cor, height=3).pack(fill="x", side="top", pady=(0, 10))
                tk.Label(box, text=str(val), font=("Segoe UI", 22, "bold"), fg=cor, bg=BG_CARD).pack(anchor="w")
                tk.Label(box, text=lbl, font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")

            # ======================================================================
            # 3. ÁREA DE GRÁFICOS (DIVIDIDA)
            # ======================================================================
            charts_grid = tk.Frame(dynamic_container, bg=BG_DARK)
            charts_grid.pack(fill="both", expand=True, padx=40, pady=10)
            charts_grid.columnconfigure(0, weight=7) # 70% Barra
            charts_grid.columnconfigure(1, weight=3) # 30% Donut

            # --- LADO ESQUERDO: GRÁFICO DE BARRAS EMPILHADAS ---
            f_barras = tk.Frame(charts_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_barras.grid(row=0, column=0, sticky="nsew", padx=(0, 20))
            
            tk.Label(f_barras, text="📊 DISTRIBUIÇÃO POR COMPETIÇÃO", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 15))

            # Preparar dados para o plot
            labels_bar = []
            gols_1 = []
            gols_2 = []
            gols_p = []
            
            for d in dados_filtrados:
                comp = d[1][:15] + ".." if len(d[1]) > 15 else d[1]
                if filtro == "Todas as Temporadas":
                    lbl = f"{comp}\n({d[0]})"
                else:
                    lbl = f"{comp}"
                labels_bar.append(lbl)
                gols_1.append(d[3])
                gols_2.append(d[4])
                gols_p.append(d[5])

            fig_bar, ax_bar = plt.subplots(figsize=(8, 4), facecolor=BG_CARD)
            self._aplicar_gradiente_fundo(ax_bar, cor_topo="#1E3A8A", cor_fundo=BG_CARD)

            x_pos = np.arange(len(labels_bar))
            width = 0.5
            
            # Barras Empilhadas
            b1 = ax_bar.bar(x_pos, gols_1, width, label='1º Tempo', color=COLOR_1T, edgecolor="white", linewidth=0.5, zorder=3)
            b2 = ax_bar.bar(x_pos, gols_2, width, bottom=gols_1, label='2º Tempo', color=COLOR_2T, edgecolor="white", linewidth=0.5, zorder=3)
            
            bottom_p = np.array(gols_1) + np.array(gols_2)
            b3 = ax_bar.bar(x_pos, gols_p, width, bottom=bottom_p, label='Prorrogação', color=COLOR_PR, edgecolor="white", linewidth=0.5, zorder=3)

            ax_bar.set_xticks(x_pos)
            ax_bar.set_xticklabels(labels_bar, color=TEXT_SUB, fontsize=9, fontweight="bold")
            
            ax_bar.spines['top'].set_visible(False); ax_bar.spines['right'].set_visible(False)
            ax_bar.spines['left'].set_visible(False); ax_bar.spines['bottom'].set_color("#475569")
            ax_bar.tick_params(axis='y', colors=TEXT_SUB, labelsize=9)
            ax_bar.grid(axis='y', linestyle=':', alpha=0.3, color="white", zorder=0)

            legend = ax_bar.legend(loc='upper right', frameon=False, ncol=3)
            for text in legend.get_texts(): text.set_color("white")

            # Tooltip interativo
            annot = ax_bar.annotate("", xy=(0,0), xytext=(0, 10), textcoords="offset points",
                                bbox=dict(boxstyle="round", fc="#0F172A", ec="white", lw=1, alpha=0.95),
                                arrowprops=dict(arrowstyle="->", color="white"), fontsize=9, color="white", zorder=10, ha='center')
            annot.set_visible(False)

            def hover(event):
                vis = annot.get_visible()
                if event.inaxes == ax_bar:
                    found = False
                    for bars, label_text in [(b1, "1º Tempo"), (b2, "2º Tempo"), (b3, "Prorrogação")]:
                        for bar in bars:
                            if bar.contains(event)[0] and bar.get_height() > 0:
                                x = bar.get_x() + bar.get_width() / 2
                                y = bar.get_y() + bar.get_height()
                                annot.xy = (x, y)
                                annot.set_text(f"{label_text}\n{int(bar.get_height())} Gols")
                                annot.get_bbox_patch().set_edgecolor(bar.get_facecolor())
                                annot.set_visible(True)
                                fig_bar.canvas.draw_idle()
                                found = True; break
                        if found: break
                    if not found and vis: annot.set_visible(False); fig_bar.canvas.draw_idle()

            fig_bar.canvas.mpl_connect("motion_notify_event", hover)

            plt.tight_layout()
            canvas_bar = FigureCanvasTkAgg(fig_bar, master=f_barras)
            canvas_bar.draw()
            canvas_bar.get_tk_widget().pack(fill="both", expand=True)
            self.fig_minutos.append(fig_bar)
            self.matplotlib_canvases.append(canvas_bar)

            # --- LADO DIREITO: DONUT E SCOUT ---
            f_right = tk.Frame(charts_grid, bg=BG_DARK)
            f_right.grid(row=0, column=1, sticky="nsew")

            # Donut Chart
            f_donut = tk.Frame(f_right, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_donut.pack(fill="x", pady=(0, 20))
            
            tk.Label(f_donut, text="MOMENTO DOS GOLS", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 10))

            fig_pie, ax_pie = plt.subplots(figsize=(3, 3), facecolor=BG_CARD)
            sizes = [sum_1t, sum_2t, sum_pr]
            labels_pie = ['1º Tempo', '2º Tempo', 'Prorrogação']
            colors_pie = [COLOR_1T, COLOR_2T, COLOR_PR]
            
            # Limpa zeros para não bugar o gráfico
            filt_sizes = [s for s in sizes if s > 0]
            filt_colors = [c for s, c in zip(sizes, colors_pie) if s > 0]
            filt_labels = [l for s, l in zip(sizes, labels_pie) if s > 0]

            if filt_sizes:
                wedges, texts, autotexts = ax_pie.pie(
                    filt_sizes, labels=None, autopct='%1.0f%%',
                    startangle=90, colors=filt_colors, pctdistance=0.75,
                    textprops=dict(color="white", fontsize=10, fontweight="bold"),
                    wedgeprops=dict(width=0.4, edgecolor=BG_CARD, linewidth=3)
                )
                ax_pie.legend(wedges, filt_labels, loc="center", bbox_to_anchor=(0.5, -0.1), frameon=False, labelcolor=TEXT_SUB, ncol=2, fontsize=9)
            
            plt.tight_layout()
            canvas_pie = FigureCanvasTkAgg(fig_pie, master=f_donut)
            canvas_pie.draw()
            canvas_pie.get_tk_widget().pack(fill="both", expand=True)
            self.fig_minutos.append(fig_pie)
            self.matplotlib_canvases.append(canvas_pie)

            # Scout Report (Insight)
            f_scout = tk.Frame(f_right, bg="#252F3D", highlightthickness=1, highlightbackground=cor_perfil, padx=20, pady=20)
            f_scout.pack(fill="both", expand=True)

            tk.Label(f_scout, text="📋 RELATÓRIO DO OLHEIRO", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")
            tk.Label(f_scout, text=perfil_tempo.upper(), font=("Impact", 20), fg=cor_perfil, bg="#252F3D").pack(anchor="w", pady=(5, 5))
            tk.Label(f_scout, text=desc_tempo, font=("Segoe UI", 10, "italic"), fg="white", bg="#252F3D", wraplength=250, justify="left").pack(anchor="w")

            tk.Frame(dynamic_container, bg=BG_DARK, height=50).pack()

        # Gatilho inicial
        combo.bind("<<ComboboxSelected>>", atualizar_view)
        atualizar_view()

    def aba_valor_mercado(self, parent_frame):
        # --- IMPORTAÇÕES ---
        import matplotlib.ticker as ticker
        import matplotlib.dates as mdates
        from dateutil.relativedelta import relativedelta
        import numpy as np
        import datetime
        from tkinter import Toplevel, messagebox
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import matplotlib.pyplot as plt

        # --- ESTILOS PREMIUM ---
        COLOR_UP = "#10B981"    # Verde
        COLOR_DOWN = "#EF4444"  # Vermelho
        COLOR_CHART_LINE = "#38BDF8" # Azul Sky
        BG_CHART = "#1E293B"    # Slate 800
        BG_DARK = "#0F172A"
        TEXT_SUB = "#94A3B8"    # <--- ADICIONE ESTA LINHA
        TEXT_MAIN = "#F8FAFC"   # <--- E ESTA LINHA TAMBÉM

        self.style.configure("FinMain.TFrame", background=BG_DARK)
        self.style.configure("FinCard.TFrame", background=BG_CHART, relief="flat", borderwidth=0)
        self.style.configure("FinHead.TLabel", background=BG_DARK, foreground="white", font=("Segoe UI", 24, "bold"))
        self.style.configure("KpiCard.TFrame", background=BG_CHART, relief="flat")

        # --- PREPARAÇÃO DOS DADOS ---
        # Garante que o dicionário exista
        if not hasattr(self, 'dados_valor_mercado') or not isinstance(self.dados_valor_mercado, dict):
            self.dados_valor_mercado = {}

        parsed_data = []
        nasc_obj = None
        if self.informacoes.get("Data de Nascimento"):
            try: nasc_obj = datetime.datetime.strptime(self.informacoes["Data de Nascimento"], "%d/%m/%Y")
            except: pass

        for k, v in self.dados_valor_mercado.items():
            # Tratamento de valor
            val_num = 0.0
            if isinstance(v, (int, float)): val_num = float(v)
            else:
                s = str(v).replace("€", "").replace(" ", "").upper()
                try:
                    if "M" in s: val_num = float(s.replace("M", "").replace(",", ".")) * 1_000_000
                    elif "K" in s: val_num = float(s.replace("K", "").replace(",", ".")) * 1_000
                    else: val_num = float(s.replace(",", "."))
                except: pass
            
            # Tratamento de Data
            dt_obj = datetime.date.today()
            if isinstance(k, (datetime.date, datetime.datetime)): 
                dt_obj = k if isinstance(k, datetime.date) else k.date()
            else:
                try: dt_obj = datetime.datetime.strptime(str(k), "%d/%m/%Y").date()
                except:
                    try: dt_obj = datetime.datetime.strptime(str(k), "%Y-%m-%d").date()
                    except: pass 

            # Calcula Idade
            idade_txt = "-"
            age = 25 # Default
            if nasc_obj:
                try:
                    dt_comp = datetime.datetime(dt_obj.year, dt_obj.month, dt_obj.day)
                    age = relativedelta(dt_comp, nasc_obj).years
                    idade_txt = f"{age} anos"
                except: pass

            parsed_data.append({"date": dt_obj, "value": val_num, "age": idade_txt, "age_num": age, "original_key": k})

        parsed_data.sort(key=lambda x: x["date"])
        
        # Se não houver dados, cria um marco zero
        if not parsed_data:
            dt_hoje = datetime.date.today()
            parsed_data.append({"date": dt_hoje, "value": 0, "age": "-", "age_num": 20, "original_key": dt_hoje})

        def fmt_eur(v):
            if v >= 1e6: return f"€ {v/1e6:.1f}M".replace(".", ",")
            if v >= 1e3: return f"€ {v/1e3:.0f}K"
            return f"€ {v:.0f}"

        # --- AÇÕES DE CRUD (MODAL E EXCLUSÃO) ---
        def excluir_valor(chave_original):
            if messagebox.askyesno("Excluir", "Tem certeza que deseja excluir este registro de valor de mercado?"):
                if chave_original in self.dados_valor_mercado:
                    del self.dados_valor_mercado[chave_original]
                    self.salvar_dados()
                    self.show_toast("Registro excluído!", "info")
                    self.open_tab("Valor de Mercado", "MERCADO & MÉDICO", 10)

        def abrir_modal_valor(is_edit=False, item_edit=None):
            BG_MODAL = "#1F2937"; BG_INPUT = "#111827"; ACCENT = "#10B981"; BORDER = "#374151"; TEXT_SUB = "#9CA3AF"
            
            md = Toplevel(self); md.title("Editar Valor" if is_edit else "Atualizar Valor")
            md.geometry("400x450"); md.configure(bg=BG_MODAL); md.resizable(False, False)
            
            x = (md.winfo_screenwidth() // 2) - 200
            y = (md.winfo_screenheight() // 2) - 225
            md.geometry(f"+{x}+{y}"); md.grab_set()

            mf = tk.Frame(md, bg=BG_MODAL); mf.pack(fill="both", expand=True, padx=30, pady=30)

            tk.Label(mf, text="💰" if not is_edit else "✏️", font=("Segoe UI Emoji", 40), bg=BG_MODAL).pack(pady=(0, 5))
            tk.Label(mf, text="NOVO VALOR" if not is_edit else "EDITAR VALOR", font=("Segoe UI", 16, "bold"), bg=BG_MODAL, fg="white").pack()
            tk.Label(mf, text="Avaliação de mercado no Transfermarkt", font=("Segoe UI", 10), bg=BG_MODAL, fg=TEXT_SUB).pack(pady=(5, 20))

            # Carrega valores se for edição, senão usa defaults
            if is_edit and item_edit:
                dt_str = item_edit["date"].strftime("%d/%m/%Y")
                val_str = fmt_eur(item_edit["value"]).replace(" ", "")
                chave_antiga = item_edit["original_key"]
            else:
                dt_str = datetime.datetime.now().strftime("%d/%m/%Y")
                val_atual = parsed_data[-1]['value'] if parsed_data else 0
                val_str = fmt_eur(val_atual).replace(" ", "") if val_atual > 0 else "€1M"
                chave_antiga = None

            v_data = tk.StringVar(value=dt_str)
            v_valor = tk.StringVar(value=val_str)

            tk.Label(mf, text="DATA (DD/MM/AAAA)", bg=BG_MODAL, fg=TEXT_SUB, font=("Segoe UI", 8, "bold")).pack(anchor="w", pady=(10, 2))
            tk.Entry(mf, textvariable=v_data, bg=BG_INPUT, fg="white", font=("Segoe UI", 11), relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

            tk.Label(mf, text="VALOR (Ex: 10.5M ou 500K)", bg=BG_MODAL, fg=TEXT_SUB, font=("Segoe UI", 8, "bold")).pack(anchor="w", pady=(15, 2))
            tk.Entry(mf, textvariable=v_valor, bg=BG_INPUT, fg="white", font=("Segoe UI", 11), relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

            def salvar_valor():
                d_str = v_data.get().strip()
                v_str = v_valor.get().strip().upper().replace("€", "")

                if not d_str or not v_str:
                    messagebox.showwarning("Aviso", "Preencha todos os campos!", parent=md)
                    return

                try:
                    dt_valida = datetime.datetime.strptime(d_str, "%d/%m/%Y").date()
                    
                    # Se for edição e a data mudou, remove a chave antiga
                    if is_edit and chave_antiga and chave_antiga != dt_valida:
                        if chave_antiga in self.dados_valor_mercado:
                            del self.dados_valor_mercado[chave_antiga]
                    
                    # Salva no dicionário
                    self.dados_valor_mercado[dt_valida] = f"€ {v_str}"
                    self.salvar_dados()
                    
                    md.destroy()
                    self.show_toast("Valor de mercado atualizado!", "sucesso")
                    self.open_tab("Valor de Mercado", "MERCADO & MÉDICO", 10)
                    
                except ValueError:
                    messagebox.showerror("Erro", "Formato de data inválido! Use DD/MM/AAAA.", parent=md)

            btn_txt = "SALVAR ALTERAÇÕES" if is_edit else "SALVAR ATUALIZAÇÃO"
            tk.Button(mf, text=btn_txt, command=salvar_valor, bg=ACCENT, fg="#0F172A", font=("Segoe UI", 10, "bold"), relief="flat", pady=8, cursor="hand2").pack(fill="x", side="bottom", pady=20)


        # --- ESTRUTURA VISUAL DA ABA ---
        main_container = ttk.Frame(parent_frame, style="FinMain.TFrame")
        main_container.pack(fill="both", expand=True)

        # Header
        header = tk.Frame(main_container, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        
        titles = tk.Frame(header, bg=BG_DARK)
        titles.pack(side="left")
        tk.Label(titles, text="VALOR DE MERCADO", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(titles, text="Histórico de valorização e curva de evolução da carreira", font=("Segoe UI", 11), fg="#94A3B8", bg=BG_DARK).pack(anchor="w")

        btn_add = tk.Button(header, text="📈 ATUALIZAR VALOR", bg="#10B981", fg="#0F172A", 
                            font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", 
                            padx=20, pady=10, command=abrir_modal_valor)
        btn_add.pack(side="right", anchor="center")

        # Layout Dividido (Gráfico Esquerda | Lista Direita)
        split_frame = tk.Frame(main_container, bg=BG_DARK)
        split_frame.pack(fill="both", expand=True, padx=40, pady=(10, 20))
        split_frame.columnconfigure(0, weight=7) # 70% Gráfico
        split_frame.columnconfigure(1, weight=3) # 30% Histórico

        # ======================================================================
        # COLUNA ESQUERDA: GRÁFICO E KPIs
        # ======================================================================
        left_col = tk.Frame(split_frame, bg=BG_DARK)
        left_col.grid(row=0, column=0, sticky="nsew", padx=(0, 20))

        # KPIs
        kpi_row = tk.Frame(left_col, bg=BG_DARK)
        kpi_row.pack(fill="x", pady=(0, 20))
        kpi_row.columnconfigure(0, weight=1); kpi_row.columnconfigure(1, weight=1); kpi_row.columnconfigure(2, weight=1)

        curr_val = parsed_data[-1]["value"]
        max_val = max(d["value"] for d in parsed_data)
        
        # Lógica da Fase de Carreira
        idade_atual = parsed_data[-1]["age_num"]
        fase_carreira = "Jovem Promessa"
        cor_fase = "#38BDF8"
        if idade_atual >= 30:
            fase_carreira = "Lenda Veterana"
            cor_fase = "#94A3B8"
        elif idade_atual >= 24:
            fase_carreira = "Auge Técnico"
            cor_fase = "#F59E0B"

        # Maior Salto de Valor
        maior_salto = 0
        for i in range(1, len(parsed_data)):
            salto = parsed_data[i]["value"] - parsed_data[i-1]["value"]
            if salto > maior_salto: maior_salto = salto

        if len(parsed_data) > 1:
            prev_val = parsed_data[-2]["value"]
            diff = curr_val - prev_val
            pct = (diff / prev_val * 100) if prev_val > 0 else 0
        else: diff = 0; pct = 0
            
        trend_col = COLOR_UP if diff >= 0 else COLOR_DOWN
        trend_txt = f"{'▲' if diff >= 0 else '▼'} {abs(pct):.1f}% (vs anterior)"

        kpis = [
            ("VALOR ATUAL", fmt_eur(curr_val), trend_txt, trend_col),
            ("PICO DE CARREIRA", fmt_eur(max_val), f"Fase: {fase_carreira}", cor_fase),
            ("MAIOR VALORIZAÇÃO", f"+ {fmt_eur(maior_salto)}", "Maior salto em uma atualização", COLOR_CHART_LINE)
        ]

        for i, (title, val, badge_txt, color) in enumerate(kpis):
            card = ttk.Frame(kpi_row, style="KpiCard.TFrame", padding=15)
            card.grid(row=0, column=i, sticky="ew", padx=(0, 15) if i < 2 else 0)
            tk.Frame(card, bg=color, width=4).pack(side="left", fill="y", padx=(0, 15))
            content = tk.Frame(card, bg=BG_CHART)
            content.pack(side="left", fill="both", expand=True)
            tk.Label(content, text=title, font=("Segoe UI", 9, "bold"), fg="#94A3B8", bg=BG_CHART).pack(anchor="w")
            tk.Label(content, text=val, font=("Segoe UI", 18, "bold"), fg=color, bg=BG_CHART).pack(anchor="w", pady=2)
            tk.Label(content, text=badge_txt, font=("Segoe UI", 8, "bold"), fg=color, bg="#0F172A", padx=8, pady=2).pack(anchor="w", pady=(5, 0))

        # Container do Gráfico
        chart_wrap = tk.Frame(left_col, bg=BG_CHART, highlightthickness=1, highlightbackground="#334155")
        chart_wrap.pack(fill="both", expand=True)
        
        # ======================================================================
        # NOVO: RODAPÉ DE INSIGHTS (STATUS GLOBAL E ROI)
        # ======================================================================
