        box_status.grid(row=0, column=0, sticky="nsew", padx=(0, 10))

        tk.Label(box_status, text="🌍 STATUS GLOBAL", font=("Segoe UI", 10, "bold"), fg="#38BDF8", bg=BG_CHART).pack(anchor="w", pady=(0, 5))

