    def gerar_artigo_detalhado(self, noticia):
        import random
        
        dados = noticia.get("stats", {})
        tipo = noticia.get("tipo", "match")
        
        nome = dados.get("nome", "Jogador").split()[0].title()
        clube = dados.get("clube", "Time").title()
        adv = dados.get("adv", "Adversário").title()
        placar = dados.get("placar", "0-0")
        
        # --- DADOS DETALHADOS ---
        gols = int(dados.get("gols", 0))
        assists = int(dados.get("assists", 0))
        nota = float(dados.get("nota", 6.0))
        
        # Tenta pegar os detalhes (Falta, Pênalti)
        detalhes = dados.get("detalhes", {})
        gols_falta = int(detalhes.get("FaltasGol", 0))
        gols_penalti = int(detalhes.get("PenalGol", 0))
        
        # Análise do Placar e Local
        try:
            p_limpo = placar.split(" ")[0] 
            g_casa, g_fora = map(int, p_limpo.split("-"))
            local_jogo = dados.get("local", "C").upper()
            
            if local_jogo == "F": 
                meus_gols_time = g_fora; gols_adv_time = g_casa
            else: 
                meus_gols_time = g_casa; gols_adv_time = g_fora
                
            saldo = meus_gols_time - gols_adv_time
        except: 
            saldo = 0; meus_gols_time = 0; gols_adv_time = 0

        # --- ÁRVORE DE DECISÃO DE TEXTO ---
        chave_db = "vitoria_coletiva" # Padrão
        
        if tipo == "match":
            
            # 1. DERROTA (Prioridade máxima se perdeu, a não ser que tenha brilhado muito individualmente)
            if saldo < 0 and nota < 8.0:
                chave_db = "derrota"
                
            # 2. EMPATE SEM GOLS
            elif saldo == 0 and meus_gols_time == 0:
                chave_db = "empate_zero"
                
            # 3. EMPATE COM GOLS
            elif saldo == 0:
                chave_db = "empate"
                
            # --- CENÁRIOS DE DESTAQUE INDIVIDUAL (VITÓRIA OU EMPATE) ---
            else:
                participacao_total = gols + assists
                
                # A. ONE MAN ARMY: Participou de TODOS os gols do time (e o time fez pelo menos 2)
                if participacao_total == meus_gols_time and meus_gols_time >= 2:
                    chave_db = "atuacao_one_man_army"
                
                # B. HAT-TRICK (3 ou mais gols)
                elif gols >= 3:
                    chave_db = "atuacao_hattrick"
                
                # C. GARÇOM (2 ou mais assistências e 0 gols)
                elif assists >= 2 and gols == 0:
                    chave_db = "atuacao_garcom"
                
                # D. BOLA PARADA (Fez gol de falta ou pênalti e foi decisivo/poucos gols)
                elif (gols_falta > 0 or gols_penalti > 0) and gols <= 2:
                    chave_db = "atuacao_bola_parada"
                
                # E. VITÓRIA PADRÃO (Nenhuma das acima)
                else:
                    chave_db = "vitoria_coletiva"

        # --- GERAÇÃO DO TEXTO ---
        autores = ["André Rizek", "PVC", "Mauro Cezar", "Redação GE", "Fabrizio Romano", "TNT Sports", "ESPN", "Caio Ribeiro"]
        cidades = ["São Paulo", "Rio de Janeiro", "Belo Horizonte", "Porto Alegre", "Londres", "Madrid", "Turim", "Salvador"]
        
        titulo_final = noticia["titulo"]
        autor = random.choice(autores)
        local_data = f"{random.choice(cidades)}, {noticia['data']}"
        
        # Tenta criar uma chave específica, ex: "vitoria_coletiva_champions_league"
        chave_torneio = f"{chave_db}_{comp.lower().replace(' ', '_')}"

        # Verifica se existe um texto exclusivo para esse torneio e cenário
        if chave_torneio in self.db_match_textos:
            textos = self.db_match_textos[chave_torneio]
        else:
            # Se não tiver, usa o genérico (o que já existe hoje)
            textos = self.db_match_textos.get(chave_db, self.db_match_textos["vitoria_coletiva"])
        comp = dados.get("comp", "Torneio") # Pega o nome do campeonato
        format_dict = {"nome": nome, "clube": clube, "adv": adv, "placar": placar, "comp": comp}
        
        # Se for um cenário específico, sobrescreve o título genérico que veio do 'salvar_jogo'
        if chave_db not in ["vitoria_coletiva", "derrota", "empate", "empate_zero"]:
            titulo_final = random.choice(textos["titulos"]).format(**format_dict)
            
        intro = random.choice(textos["intro"]).format(**format_dict)
        meio = random.choice(textos["meio"]).format(**format_dict)
        aspas = random.choice(textos.get("aspas", ["'Seguimos trabalhando', disse o jogador."])).format(**format_dict)
        fim = random.choice(textos["fim"]).format(**format_dict)
        
        texto_final = f"{intro}\n\n{meio}\n\n{aspas}\n\n{fim}"

        return titulo_final, texto_final, autor, local_data
    
    @staticmethod
    def _tarefa_download_isolada(nome_limpo, caminho_final):
        """
        Método estático e isolado.
        Retorna: (Sucesso: bool, Mensagem: str)
        """
        import requests
        from bs4 import BeautifulSoup
        from urllib.parse import quote_plus
        from PIL import Image
        
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
            'Accept': 'text/html,image/webp,*/*;q=0.8'
        }
        
        url_encontrada = None

        try:
            # 1. Busca DuckDuckGo
            q = quote_plus(f"{nome_limpo} football logo png transparent")
            r = requests.get(f"https://duckduckgo.com/i.js?q={q}&o=json", headers=headers, timeout=3)
            if r.status_code == 200:
                data = r.json()
                if "results" in data and len(data["results"]) > 0:
                    url_encontrada = data["results"][0]["image"]
        except: pass

        if not url_encontrada:
            try:
                # 2. Busca Football-Logos
                q = quote_plus(nome_limpo)
                r = requests.get(f"https://football-logos.cc/?s={q}", headers=headers, timeout=4)
                if r.status_code == 200:
                    soup = BeautifulSoup(r.text, 'html.parser')
                    imgs = soup.select('div.post-content img') or soup.select('div.entry-content img')
                    if imgs: url_encontrada = imgs[0]['src']
            except: pass

        if url_encontrada:
            try:
                img_data = requests.get(url_encontrada, headers=headers, timeout=5).content
                with open(caminho_final, 'wb') as f:
                    f.write(img_data)
                
                # Resize seguro (sem Tkinter, apenas PIL puro)
                with Image.open(resource_path(caminho_final)) as img:
                    img = img.resize((150, 150), Image.Resampling.LANCZOS)
                    img.save(caminho_final)
                
                return True
            except: return False
            
        return False

    def baixar_logo_automaticamente(self, nome_clube):
        """Dispara o worker em thread isolada para não travar a tela."""
        import threading
        import queue
        
        if not nome_clube: return

        nome_limpo = nome_clube.strip()
        caminho_final = f"Logos/{nome_limpo}.png"
        
        # Se já existe, não faz nada
        if os.path.exists(caminho_final):
            self.club_logo_paths[nome_limpo] = caminho_final
            return

        print(f"Iniciando download em segundo plano para: {nome_clube}...")

        # Garante que a fila de downloads existe no sistema
        if not hasattr(self, 'fila_downloads'):
            self.fila_downloads = queue.Queue()

        # Define a função trabalhadora internamente
        def worker():
            sucesso = self._tarefa_download_isolada(nome_limpo, caminho_final)
            self.fila_downloads.put((sucesso, nome_limpo, caminho_final))

        # Inicia a thread (daemon=True garante que morre se o app fechar)
        t = threading.Thread(target=worker, daemon=True)
        t.start()
        
        # Garante que o verificador da fila está rodando
        if not hasattr(self, '_loop_fila_ativo'):
            self._loop_fila_ativo = True
            self.verificar_fila_downloads()

    def verificar_fila_downloads(self):
        """
        Verifica a fila na Thread Principal e atualiza o App.
        """
        # 1. Proteção: Se a janela foi fechada, pare tudo imediatamente.
        try:
            if not self.winfo_exists():
                return 
        except:
            return

        # 2. Processa a fila
        try:
            while True:
                # Pega o resultado sem bloquear a interface
                sucesso, nome, caminho = self.fila_downloads.get_nowait()
                
                if sucesso:
                    # Atualiza o dicionário de caminhos do App
                    self.club_logo_paths[nome] = caminho
                    print(f"✅ Logo salva: {nome}")
                    
                    # Opcional: Se quiser recarregar a tela atual para mostrar a logo
                    # if self.tab_frame: 
                    #     self.update_idletasks()
                else:
                    print(f"❌ Falha ao baixar: {nome}")
                    
        except queue.Empty:
            pass # Fila vazia, tudo normal
            
        # 3. Reagendar (Loop Infinito Seguro)
        # Só reagenda se a janela ainda existir
        try:
            self.after(1000, self.verificar_fila_downloads)
        except:
            pass

    def _finalizar_download_seguro(self, sucesso, nome, caminho):
        """Atualiza a UI na thread principal"""
        if sucesso:
            self.club_logo_paths[nome] = caminho
            print(f"Logo salva: {caminho}")
        else:
            print(f"Não foi possível baixar a logo de {nome}")

