        def add_marca_gol(event):
            try: total_gols = int(self.vars_add_match["Gols"].get())
            except: total_gols = 0
            if len(self.coordenadas_gols_temp) >= total_gols and total_gols > 0:
                self.show_toast(f"Você já marcou a posição dos seus {total_gols} gols!", "info"); return
            x, y = event.x, event.y
            if (trave_x1 - 10) <= x <= (trave_x2 + 10) and (trave_y1 - 10) <= y <= trave_y2:
                raio = 6; perc_x = round((x - trave_x1) / (trave_x2 - trave_x1), 3); perc_y = round((y - trave_y1) / (trave_y2 - trave_y1), 3)
                cor_bola = "#10B981" if perc_y > 0.65 else ("#8B5CF6" if perc_y < 0.35 else "#F59E0B")
                canvas_gol.create_oval(x-raio-2, y-raio-2, x+raio+2, y+raio+2, outline=cor_bola, width=2, tags="gol_marca")
                canvas_gol.create_oval(x-raio, y-raio, x+raio, y+raio, fill=cor_bola, outline="white", width=2, tags="gol_marca")
                self.coordenadas_gols_temp.append((perc_x, perc_y))
