    def _aplicar_gradiente_fundo(self, ax, cor_topo="#2A3645", cor_fundo="#121820"):
        """
        Aplica um gradiente vertical sutil ao fundo de um eixo Matplotlib.
        Cria uma sensação de profundidade e 'Glow'.
        """
        import matplotlib.colors as mcolors
        import numpy as np

        # 1. Deixa o fundo do eixo transparente para o gradiente aparecer
        ax.set_facecolor("none") 
        
        # 2. Cria o gradiente matemático (de Topo para Fundo)
        c1 = mcolors.to_rgba(cor_topo)
        c2 = mcolors.to_rgba(cor_fundo)
        # Cria 256 faixas de cor misturando c1 e c2
        gradient = np.linspace(c1, c2, 256).reshape((256, 1, 4))
        
        # 3. Pega os limites atuais do gráfico para preencher a área exata
        # Precisamos garantir que os limites existam (auto-scale)
        xlim = ax.get_xlim()
        ylim = ax.get_ylim()
        
        # 4. Desenha a imagem do gradiente ATRÁS dos dados (zorder=-10)
        ax.imshow(gradient, aspect='auto', extent=[xlim[0], xlim[1], ylim[0], ylim[1]], zorder=-10)

    def aba_analise_adversarios(self, parent_frame):
        # --- IMPORTAÇÕES E ESTILOS ---
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np
        import os

        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        COLOR_WIN = "#10B981"  # Verde
        COLOR_LOSE = "#EF4444" # Vermelho
        COLOR_DRAW = "#94A3B8" # Cinza
        COLOR_GOAL = "#F59E0B" # Dourado

        self.style.configure("AdvMain.TFrame", background=BG_DARK)

        # --- ESTRUTURA (Scrollável) ---
        aba_adv = ttk.Frame(parent_frame, style="AdvMain.TFrame")
        aba_adv.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_adv, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_adv, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="AdvMain.TFrame")
        
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        
        def _scroll(e): 
            try:
                # 1. Se o mouse estiver EXATAMENTE sobre a lista suspensa, 
                # deixa a listinha rolar normalmente e para por aqui.
                classe_widget = e.widget.winfo_class()
                if classe_widget == 'Listbox' or 'popdown' in str(e.widget).lower():
                    return
            except: pass
            
            # === ROLAGEM DA TELA PRINCIPAL ===
            try:
                # 2. A MÁGICA: Tira o foco do Combobox ao rolar a tela.
                # Isso força a lista suspensa a FECHAR instantaneamente, 
                # impedindo que ela fique "desprendida" flutuando na tela.
                parent_frame.focus_set()
                
                # 3. Faz a rolagem do fundo (Canvas)
                if inner.winfo_reqheight() > canvas.winfo_height():
                    yv = canvas.yview()
                    
                    # Travas de limite (evita bugar o scroll no topo/fundo)
                    if e.delta < 0 and yv[1] >= 0.999: return 
                    if e.delta > 0 and yv[0] <= 0.001: return 
                        
                    canvas.yview_scroll(int(-1*(e.delta/120)), "units")
            except: pass
            
        # === A MÁGICA AQUI: Salva a função do scroll na memória do sistema ===
        self.scroll_ativo = _scroll 
        
        canvas.bind_all("<MouseWheel>", self.scroll_ativo)
        canvas.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", self.scroll_ativo))

        # ======================================================================
        # 1. HEADER E FILTRO
        # ======================================================================
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="RAIO-X DOS ADVERSÁRIOS", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="Mapeamento de rivalidades: descubra suas vítimas favoritas e seus maiores algozes.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        ctrl_frame = tk.Frame(inner, bg=BG_DARK)
        ctrl_frame.pack(fill="x", padx=40, pady=(10, 10))
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=COLOR_GOAL, bg=BG_DARK).pack(anchor="w")
        
        opcoes_ano = ["Todas as Temporadas"] + sorted(list(getattr(self, 'dados_jogador', {}).keys()), reverse=True)
        selected_season = tk.StringVar(value=opcoes_ano[0])
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_ano, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        dynamic_container = tk.Frame(inner, bg=BG_DARK)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_adv'): self.fig_adv = []

        def atualizar_view(event=None):
            # Limpeza de Gráficos e Widgets
            for f in self.fig_adv: plt.close(f)
            self.fig_adv.clear()
            for widget in dynamic_container.winfo_children(): widget.destroy()

            filtro = selected_season.get()
            stats_adv = {} 
            
            # --- MOTOR DE DADOS (Lê direto das atuações reais) ---
            for jogo in getattr(self, 'ultimas_performances', []):
                # Filtro de Temporada
                if filtro != "Todas as Temporadas" and self._inferir_temporada(jogo.get("Data", "")) != filtro:
                    continue

                # Valida se realmente jogou a partida
                mins = int(jogo.get("Minutos", 90))
                pos = jogo.get("Posição", "MEI")
                status_ausente = ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]
                
                if mins <= 0 or pos in status_ausente:
                    continue

                adv = str(jogo.get("Adversário", "Desconhecido")).strip()
                gols = int(jogo.get("Gols", 0))
                assists = int(jogo.get("Assistências", 0))
                res = jogo.get("Resultado", "0-0")
                loc = jogo.get("Local", "C").upper()

                # Processar Placar (Vitória, Empate, Derrota e Gols Sofridos)
                try:
                    placar_limpo = res.split(" ")[0]
                    gc_placar, gf_placar = map(int, placar_limpo.split("-"))
                    
                    if loc == "C":
                        gols_pro_time = gc_placar
                        gols_contra_time = gf_placar
                    else:
                        gols_pro_time = gf_placar
                        gols_contra_time = gc_placar

                    if gols_pro_time > gols_contra_time: vit, emp, der = 1, 0, 0
                    elif gols_pro_time < gols_contra_time: vit, emp, der = 0, 0, 1
                    else: vit, emp, der = 0, 1, 0
                except:
                    vit, emp, der, gols_contra_time = 0, 0, 0, 0

                # Registrar no Dicionário
                if adv not in stats_adv:
                    stats_adv[adv] = {'j': 0, 'v': 0, 'e': 0, 'd': 0, 'gols_marcados': 0, 'assists': 0, 'gols_sofridos': 0}

                s = stats_adv[adv]
                s['j'] += 1
                s['v'] += vit
                s['e'] += emp
                s['d'] += der
                s['gols_marcados'] += gols
                s['assists'] += assists
                s['gols_sofridos'] += gols_contra_time

            if not stats_adv:
                tk.Label(dynamic_container, text="Nenhum dado de adversário encontrado para este filtro.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_DARK).pack(pady=50)
                return

            # Ordenações
            top_vitimas = sorted(stats_adv.items(), key=lambda x: (x[1]['gols_marcados'], x[1]['assists'], x[1]['v']), reverse=True)
            top_fregueses = sorted(stats_adv.items(), key=lambda x: (x[1]['v'], x[1]['gols_marcados']), reverse=True)
            top_carrascos = sorted(stats_adv.items(), key=lambda x: (x[1]['d'], x[1]['gols_sofridos']), reverse=True)

            maior_vitima = top_vitimas[0] if top_vitimas and top_vitimas[0][1]['gols_marcados'] > 0 else None
            maior_carrasco = top_carrascos[0] if top_carrascos and top_carrascos[0][1]['d'] > 0 else None

            total_v = sum(d['v'] for d in stats_adv.values())
            total_e = sum(d['e'] for d in stats_adv.values())
            total_d = sum(d['d'] for d in stats_adv.values())
            total_j = total_v + total_e + total_d

            # ======================================================================
            # NOVO: BARRA DE BUSCA ESPECÍFICA DE ADVERSÁRIOS (AUTOCOMPLETE + DARK MODE)
            # ======================================================================
            f_busca_wrapper = tk.Frame(dynamic_container, bg=BG_DARK)
            f_busca_wrapper.pack(fill="x", padx=40, pady=(0, 15))

            # Colocando a busca dentro de um Card estiloso
            f_busca = tk.Frame(f_busca_wrapper, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
            f_busca.pack(fill="x")
            
            tk.Label(f_busca, text="🔎 PESQUISAR DOSSIÊ DO RIVAL:", font=("Segoe UI", 10, "bold"), fg="#38BDF8", bg=BG_CARD).pack(side="left", padx=(0, 15))
            
            lista_todos_adv = sorted(list(stats_adv.keys()))
            adv_selecionado = tk.StringVar()
            
            # --- ESTILIZANDO O CAMPO DO COMBOBOX (MODO ESCURO PREMIUM) ---
            self.style.configure("Dark.TCombobox",
                                 fieldbackground="#111827", # Fundo escuro onde digita
                                 background="#1E293B",      # Fundo do botão da setinha
                                 foreground="white",        # Cor do texto digitado
                                 arrowcolor="#38BDF8",      # Cor da setinha (Ciano)
                                 bordercolor="#334155",     # Borda padrão
                                 lightcolor="#334155",
                                 darkcolor="#334155")
            
            self.style.map("Dark.TCombobox",
                           fieldbackground=[("active", "#1F2937"), ("focus", "#111827")],
                           bordercolor=[("focus", "#38BDF8")], # Borda acende quando clica
                           selectbackground=[("focus", "#38BDF8")],
                           selectforeground=[("focus", "#0F172A")])

            # --- HACK PARA FORÇAR A LISTA SUSPENSA A FICAR NO MODO ESCURO ---
            self.option_add('*TCombobox*Listbox.background', '#111827')
            self.option_add('*TCombobox*Listbox.foreground', 'white')
            self.option_add('*TCombobox*Listbox.selectBackground', '#38BDF8')
            self.option_add('*TCombobox*Listbox.selectForeground', '#0F172A')
            self.option_add('*TCombobox*Listbox.font', ('Segoe UI', 10))
            
            # Adicionamos o style="Dark.TCombobox" no componente
            combo_advs = ttk.Combobox(f_busca, textvariable=adv_selecionado, values=lista_todos_adv, width=35, font=("Segoe UI", 11), style="Dark.TCombobox")
            combo_advs.pack(side="left", padx=10, ipady=3)
            
            if lista_todos_adv:
                combo_advs.current(0)
                
            # --- FUNÇÃO DE AUTOCOMPLETE (Pesquisa Inteligente) ---
            def on_key_release(event):
                # Ignora teclas de controle para não bugar a navegação
                if event.keysym in ('Up', 'Down', 'Left', 'Right', 'Return', 'Escape', 'Tab', 'Shift_L', 'Shift_R'):
                    return
                
                # 1. Guarda o texto atual e a posição exata do cursor
                texto_digitado = adv_selecionado.get()
                pos_cursor = combo_advs.index(tk.INSERT)
                
                if texto_digitado == '':
                    combo_advs['values'] = lista_todos_adv
                else:
                    # Filtra a lista com base no que você digitou
                    filtrados = [adv for adv in lista_todos_adv if texto_digitado.lower() in adv.lower()]
                    combo_advs['values'] = filtrados
                
                # 2. Abre a lista suspensa para mostrar os resultados
                combo_advs.event_generate('<Down>')
                
                # 3. MÁGICA: Devolve o foco para o campo de texto e bota o cursor no lugar certo!
                combo_advs.focus_set()
                combo_advs.icursor(pos_cursor)

            combo_advs.bind('<KeyRelease>', on_key_release)
            
            def btn_abrir_dossie():
                adv = adv_selecionado.get().strip()
                # Verifica ignorando maiúsculas/minúsculas se o time existe no histórico
                adv_real = next((a for a in stats_adv.keys() if a.lower() == adv.lower()), None)
                
                if adv_real:
                    self.abrir_popup_historico_adversario(adv_real)
                else:
                    self.show_toast(f"Adversário '{adv}' não encontrado no seu histórico.", "erro")
                    
            btn_pesquisar = tk.Button(f_busca, text="ABRIR DOSSIÊ", bg="#38BDF8", fg="#0F172A", font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", command=btn_abrir_dossie, padx=20, pady=5)
            btn_pesquisar.pack(side="left", padx=15)
            
            # Efeito Hover no botão
            btn_pesquisar.bind("<Enter>", lambda e: btn_pesquisar.config(bg="#7DD3FC"))
            btn_pesquisar.bind("<Leave>", lambda e: btn_pesquisar.config(bg="#38BDF8"))
            # ======================================================================

            # ======================================================================
            # 2. HERO CARDS (DÉRBI) & DONUT CHART
            # ======================================================================
            hero_grid = tk.Frame(dynamic_container, bg=BG_DARK)
            hero_grid.pack(fill="x", padx=40, pady=(0, 20))
            hero_grid.columnconfigure(0, weight=1); hero_grid.columnconfigure(1, weight=1); hero_grid.columnconfigure(2, weight=1)

            def criar_card_hero(parent, row, col, titulo, icone, adv_data, cor_borda, texto_stat):
                f = tk.Frame(parent, bg=BG_CARD, highlightthickness=1, highlightbackground=cor_borda, padx=20, pady=20)
                f.grid(row=row, column=col, sticky="nsew", padx=10, pady=10)
                
                tk.Label(f, text=f"{icone} {titulo}", font=("Segoe UI", 10, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="center", pady=(0, 15))
                
                if not adv_data:
                    tk.Label(f, text="Nenhum registro.", font=("Segoe UI", 11, "italic"), fg="#64748B", bg=BG_CARD).pack(expand=True)
                    return
                
                nome_clube, stats = adv_data
                
                f_logo = tk.Frame(f, bg=BG_CARD, width=80, height=80)
                f_logo.pack(pady=5)
                f_logo.pack_propagate(False)
                
                logo_path = self.club_logo_paths.get(nome_clube)
                
                # CORREÇÃO AQUI: Removido o 'self.' do resource_path
                if not logo_path or not os.path.exists(resource_path(logo_path)):
                    novo = baixar_logo_agora(nome_clube)
                    if novo: logo_path = novo
                
                # CORREÇÃO AQUI: Removido o 'self.' do resource_path
                if logo_path and os.path.exists(resource_path(logo_path)):
                    try:
                        from PIL import Image, ImageTk
                        # CORREÇÃO AQUI: Removido o 'self.' do resource_path
                        pil_img = Image.open(resource_path(logo_path)).resize((70, 70), Image.Resampling.LANCZOS)
                        tk_img = ImageTk.PhotoImage(pil_img)
                        self.club_logo_images.append(tk_img) 
                        tk.Label(f_logo, image=tk_img, bg=BG_CARD).pack(expand=True)
                    except: 
                        tk.Label(f_logo, text=nome_clube[:3].upper(), font=("Impact", 24), fg=cor_borda, bg=BG_CARD).pack(expand=True)
                else:
                    tk.Label(f_logo, text=nome_clube[:3].upper(), font=("Impact", 24), fg=cor_borda, bg=BG_CARD).pack(expand=True)

                nome_limpo = nome_clube[:15] + ".." if len(nome_clube) > 15 else nome_clube
                tk.Label(f, text=nome_limpo.upper(), font=("Impact", 20), fg="white", bg=BG_CARD).pack(pady=(5, 0))
                tk.Label(f, text=texto_stat(stats), font=("Segoe UI", 11, "bold"), fg=cor_borda, bg=BG_CARD).pack()

            def txt_vitima(s): return f"{s['gols_marcados']} Gols Marcados"
            criar_card_hero(hero_grid, 0, 0, "A MAIOR VÍTIMA", "🎯", maior_vitima, COLOR_GOAL, txt_vitima)

            def txt_carrasco(s): return f"{s['d']} Derrotas Sofridas"
            criar_card_hero(hero_grid, 0, 1, "O GRANDE CARRASCO", "☠️", maior_carrasco, COLOR_LOSE, txt_carrasco)

            f_chart = tk.Frame(hero_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_chart.grid(row=0, column=2, sticky="nsew", padx=10, pady=10)
            tk.Label(f_chart, text="📊 APROVEITAMENTO GERAL", font=("Segoe UI", 10, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="center", pady=(0, 5))

            fig_pie, ax_pie = plt.subplots(figsize=(2.5, 2.5), facecolor=BG_CARD)
            sizes = [total_v, total_e, total_d]
            colors_pie = [COLOR_WIN, COLOR_DRAW, COLOR_LOSE]
            
            filt_sizes = [s for s in sizes if s > 0]
            filt_colors = [c for s, c in zip(sizes, colors_pie) if s > 0]

            if filt_sizes:
                wedges, texts, autotexts = ax_pie.pie(
                    filt_sizes, labels=None, autopct='%1.0f%%',
                    startangle=90, colors=filt_colors, pctdistance=0.75,
                    textprops=dict(color="#0F172A", fontsize=9, fontweight="bold"),
                    wedgeprops=dict(width=0.4, edgecolor=BG_CARD, linewidth=2)
                )
                aprov_pct = ((total_v * 3) + (total_e * 1)) / (total_j * 3) * 100 if total_j > 0 else 0
                ax_pie.text(0, 0, f"{aprov_pct:.1f}%\nAPROV.", ha='center', va='center', fontsize=11, fontweight='bold', color=TEXT_MAIN)
            
            plt.tight_layout()
            canvas_pie = FigureCanvasTkAgg(fig_pie, master=f_chart)
            canvas_pie.draw()
            canvas_pie.get_tk_widget().pack(fill="both", expand=True)
            self.fig_adv.append(fig_pie)
            self.matplotlib_canvases.append(canvas_pie)

            # ======================================================================
            # 3. LISTAS DETALHADAS (VÍTIMAS, FREGUESES E CARRASCOS) - ALINHAMENTO PERFEITO
            # ======================================================================
            def desenhar_tabela(titulo, icone, cor_borda, dados_lista):
                if not dados_lista: return
                
                f_tabela = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground=cor_borda)
                f_tabela.pack(fill="x", padx=40, pady=15)
                
                # Título da Tabela
                header_t = tk.Frame(f_tabela, bg="#252F3D", height=45)
                header_t.pack(fill="x")
                header_t.pack_propagate(False)
                tk.Frame(header_t, bg=cor_borda, width=4).pack(side="left", fill="y")
                tk.Label(header_t, text=f"{icone} {titulo}", font=("Segoe UI", 12, "bold"), fg="white", bg="#252F3D").pack(side="left", padx=15)

                # Cabeçalho com coordenadas exatas (relx)
                col_frame = tk.Frame(f_tabela, bg=BG_CARD, height=35)
                col_frame.pack(fill="x", padx=15, pady=(10, 0))
                
                cols_def = [
                    ("ADVERSÁRIO", 0.02, "w"),
                    ("JOGOS", 0.45, "c"),
                    ("GOLS ⚽", 0.55, "c"),
                    ("ASSISTS 🤝", 0.65, "c"),
                    ("RETROSPECTO", 0.80, "c"),
                    ("APROVEITAMENTO", 0.95, "c")
                ]
                
                for txt, rx, anc in cols_def:
                    tk.Label(col_frame, text=txt, font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).place(relx=rx, rely=0.5, anchor=anc if anc != "c" else "center")

                # Linhas de Dados com as mesmas coordenadas
                for index, (nome_clube, st) in enumerate(dados_lista[:5]):
                    row_f = tk.Frame(f_tabela, bg=BG_CARD, height=55, cursor="hand2")
                    row_f.pack(fill="x", padx=15, pady=2)
                    row_f.pack_propagate(False)

                    # Coluna Adversário (relx = 0.02)
                    f_nome = tk.Frame(row_f, bg=BG_CARD)
                    f_nome.place(relx=0.02, rely=0.5, anchor="w")
                    tk.Label(f_nome, text=f"#{index+1}", font=("Segoe UI", 9, "bold"), fg=cor_borda, bg=BG_CARD, width=3).pack(side="left")
                    self._render_logo_mini(f_nome, nome_clube)
                    tk.Label(f_nome, text=nome_clube.upper(), font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(side="left", padx=5)

                    # Colunas de Números
                    tk.Label(row_f, text=str(st['j']), font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).place(relx=0.45, rely=0.5, anchor="center")
                    tk.Label(row_f, text=str(st['gols_marcados']), font=("Segoe UI", 11, "bold"), fg=COLOR_GOAL if st['gols_marcados'] > 0 else "white", bg=BG_CARD).place(relx=0.55, rely=0.5, anchor="center")
                    tk.Label(row_f, text=str(st['assists']), font=("Segoe UI", 11, "bold"), fg="#38BDF8" if st['assists'] > 0 else "white", bg=BG_CARD).place(relx=0.65, rely=0.5, anchor="center")

                    # Coluna Retrospecto (relx = 0.80)
                    f_ved = tk.Frame(row_f, bg=BG_CARD)
                    f_ved.place(relx=0.80, rely=0.5, anchor="center")
                    tk.Label(f_ved, text=f"{st['v']}", font=("Segoe UI", 10, "bold"), fg=COLOR_WIN, bg=BG_CARD).pack(side="left")
                    tk.Label(f_ved, text="-", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(side="left", padx=2)
                    tk.Label(f_ved, text=f"{st['e']}", font=("Segoe UI", 10, "bold"), fg=COLOR_DRAW, bg=BG_CARD).pack(side="left")
                    tk.Label(f_ved, text="-", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(side="left", padx=2)
                    tk.Label(f_ved, text=f"{st['d']}", font=("Segoe UI", 10, "bold"), fg=COLOR_LOSE, bg=BG_CARD).pack(side="left")

                    # Coluna Aproveitamento (relx = 0.95)
                    aprov = ((st['v'] * 3) + (st['e'] * 1)) / (st['j'] * 3) * 100 if st['j'] > 0 else 0
                    f_aprov = tk.Frame(row_f, bg=BG_CARD)
                    f_aprov.place(relx=0.95, rely=0.5, anchor="center")
                    
                    cor_aprov = COLOR_WIN if aprov >= 50 else (COLOR_DRAW if aprov >= 30 else COLOR_LOSE)
                    tk.Label(f_aprov, text=f"{aprov:.0f}%", font=("Segoe UI", 10, "bold"), fg=cor_aprov, bg=BG_CARD).pack(side="left", padx=(0, 8))
                    
                    bg_bar = tk.Frame(f_aprov, bg="#0F172A", width=60, height=6)
                    bg_bar.pack(side="left")
                    bg_bar.pack_propagate(False)
                    tk.Frame(bg_bar, bg=cor_aprov).place(relx=0, rely=0, relheight=1, relwidth=(aprov/100))

                    # Linha Separadora
                    if index < 4 and index < len(dados_lista) - 1:
                        tk.Frame(f_tabela, bg="#334155", height=1).pack(fill="x", padx=15)

                    # Hover Effect dinâmico
                    def on_ent(e, r=row_f, fn=f_nome, fv=f_ved, fa=f_aprov): 
                        r.configure(bg="#252F3D"); fn.configure(bg="#252F3D"); fv.configure(bg="#252F3D"); fa.configure(bg="#252F3D")
                        for child in fn.winfo_children(): child.configure(bg="#252F3D")
                        for child in fv.winfo_children(): child.configure(bg="#252F3D")
                        for child in fa.winfo_children(): 
                            if isinstance(child, tk.Label): child.configure(bg="#252F3D")
                    
                    def on_lea(e, r=row_f, fn=f_nome, fv=f_ved, fa=f_aprov): 
                        r.configure(bg=BG_CARD); fn.configure(bg=BG_CARD); fv.configure(bg=BG_CARD); fa.configure(bg=BG_CARD)
                        for child in fn.winfo_children(): child.configure(bg=BG_CARD)
                        for child in fv.winfo_children(): child.configure(bg=BG_CARD)
                        for child in fa.winfo_children():
                            if isinstance(child, tk.Label): child.configure(bg=BG_CARD)
                    
                    row_f.bind("<Enter>", on_ent); row_f.bind("<Leave>", on_lea)

                    def ao_clicar_adv(e, n_adv=nome_clube):
                        self.abrir_popup_historico_adversario(n_adv)

                    row_f.bind("<Button-1>", ao_clicar_adv)
                    for container_interno in [f_nome, f_ved, f_aprov]:
                        container_interno.bind("<Button-1>", ao_clicar_adv)
                        for sub_label in container_interno.winfo_children():
                            sub_label.bind("<Button-1>", ao_clicar_adv)
                    
                    for child in row_f.winfo_children():
                        if isinstance(child, tk.Label):
                            child.bind("<Button-1>", ao_clicar_adv)

            if top_vitimas and top_vitimas[0][1]['gols_marcados'] > 0:
                desenhar_tabela("VÍTIMAS FAVORITAS (Mais Gols)", "🎯", COLOR_GOAL, top_vitimas)
            if top_fregueses and top_fregueses[0][1]['v'] > 0:
                desenhar_tabela("MAIORES FREGUESES (Mais Vitórias)", "✅", COLOR_WIN, top_fregueses)
            if top_carrascos and top_carrascos[0][1]['d'] > 0:
                desenhar_tabela("MAIORES CARRASCOS (Mais Derrotas)", "☠️", COLOR_LOSE, top_carrascos)

            # Gráfico Geral
            total_v = sum(d['v'] for d in stats_adv.values())
            total_e = sum(d['e'] for d in stats_adv.values())
            total_d = sum(d['d'] for d in stats_adv.values())
            total_j = total_v + total_e + total_d

            if total_j > 0:
                frame_chart = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
                frame_chart.pack(fill="x", padx=40, pady=20)
                
                tk.Label(frame_chart, text="APROVEITAMENTO GERAL (JOGOS ATUADOS)", font=("Segoe UI", 14, "bold"), fg="white", bg=BG_CARD).pack(pady=(20, 10))
                
                f_bar = tk.Frame(frame_chart, bg=BG_CARD, height=30)
                f_bar.pack(fill="x", padx=40, pady=(0, 20))
                
                pct_v = (total_v / total_j)
                pct_e = (total_e / total_j)
                pct_d = (total_d / total_j)
                
                f_v = tk.Frame(f_bar, bg=COLOR_WIN); f_v.place(relx=0, rely=0, relheight=1, relwidth=pct_v)
                f_e = tk.Frame(f_bar, bg="#94A3B8"); f_e.place(relx=pct_v, rely=0, relheight=1, relwidth=pct_e)
                f_d = tk.Frame(f_bar, bg=COLOR_LOSE); f_d.place(relx=pct_v+pct_e, rely=0, relheight=1, relwidth=pct_d)
                
                f_leg = tk.Frame(frame_chart, bg=BG_CARD)
                f_leg.pack(pady=(0, 20))
                tk.Label(f_leg, text=f"{total_v} Vitórias ({pct_v*100:.1f}%)", fg=COLOR_WIN, bg=BG_CARD, font=("Segoe UI", 10, "bold")).pack(side="left", padx=10)
                tk.Label(f_leg, text=f"{total_e} Empates ({pct_e*100:.1f}%)", fg="#94A3B8", bg=BG_CARD, font=("Segoe UI", 10, "bold")).pack(side="left", padx=10)
                tk.Label(f_leg, text=f"{total_d} Derrotas ({pct_d*100:.1f}%)", fg=COLOR_LOSE, bg=BG_CARD, font=("Segoe UI", 10, "bold")).pack(side="left", padx=10)

            tk.Frame(dynamic_container, bg=BG_DARK, height=50).pack()

            # --- TRAVA O TAMANHO DA TELA ---
            parent_frame.update_idletasks()
            canvas.configure(scrollregion=canvas.bbox("all"))

            # --- CORREÇÃO DO SCROLL ---
            # 1. Tira o foco do Combobox para ele soltar o mouse
            parent_frame.focus_set()
            # 2. Força a tela a recalcular o tamanho e reativar o scroll
            canvas.update_idletasks()
            canvas.bind_all("<MouseWheel>", _scroll)

        combo.bind("<<ComboboxSelected>>", atualizar_view)
        atualizar_view()

    def abrir_popup_historico_adversario(self, adv_nome):
        from tkinter import Toplevel, ttk
        import tkinter as tk
        import os
        from PIL import Image, ImageTk
        import datetime

        # 1. Filtrar todos os jogos contra este adversário e somar TUDO
        jogos_contra = []
        tot_jogos = 0
        tot_gols = 0
        tot_assists = 0
        v, e, d = 0, 0, 0
        soma_notas = 0.0
        
        # Stats Avançadas
        # Stats Avançadas
        tot_xg = 0.0; tot_chutes_gol = 0; tot_chutes_trave = 0; tot_chutes_fora = 0
        tot_chutes_bloq = 0; tot_gc_perdidas = 0
        tot_xa = 0.0; tot_pre_assists = 0; tot_posses_ganhas = 0; tot_posses_perdidas = 0; tot_distancia = 0.0
        tot_passes_dec = 0; tot_chances_criadas = 0; tot_dribles = 0
        tot_passes_c = 0; tot_passes_e = 0; tot_cruz_c = 0; tot_cruz_t = 0
        tot_desarmes = 0; tot_faltas_s = 0; tot_faltas_c = 0; tot_clean = 0
        tot_amarelos = 0; tot_vermelhos = 0
        tot_dir = 0; tot_esq = 0; tot_cab = 0; tot_falta = 0; tot_pen = 0
        mapa_gols_acumulado = []

        for jogo in self.ultimas_performances:
            if jogo.get("Adversário", "").strip().upper() == adv_nome.upper():
                mins = int(jogo.get("Minutos", 90))
                pos = jogo.get("Posição", "MEI")
                if mins > 0 and pos not in ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]:
                    jogos_contra.append(jogo)
                    tot_jogos += 1
                    
                    # Estatísticas Individuais
                    tot_gols += int(jogo.get("Gols", 0))
                    tot_assists += int(jogo.get("Assistências", 0))
                    try: soma_notas += float(jogo.get("Nota", 6.0))
                    except: pass

                    # Resultados e Placar
                    try:
                        placar_limpo = jogo.get("Resultado", "0-0").split(" ")[0]
                        gc, gf = map(int, placar_limpo.split("-"))
                        loc = jogo.get("Local", "C").upper()
                        meus_g = gc if loc == "C" else gf
                        adv_g = gf if loc == "C" else gc
                        if meus_g > adv_g: v += 1
                        elif meus_g < adv_g: d += 1
                        else: e += 1
                    except: pass

                    # Extração de Detalhes
                    det = jogo.get("Detalhes", {})
                    if det.get("CleanSheet"): tot_clean += 1
                    
                    tot_xg += float(det.get("xG", 0.0))
                    tot_xa += float(det.get("xA", 0.0))
                    tot_pre_assists += int(det.get("PreAssistencias", 0))
                    tot_posses_ganhas += int(det.get("PossesGanhas", 0))
                    tot_posses_perdidas += int(det.get("PossesPerdidas", 0))
                    tot_distancia += float(det.get("DistanciaPercorrida", 0.0))
                    tot_chutes_gol += int(det.get("ChutesNoGol", 0))
                    tot_chutes_trave += int(det.get("ChutesNaTrave", 0))
                    tot_chutes_fora += int(det.get("ChutesPraFora", 0))
                    tot_chutes_bloq += int(det.get("ChutesBloqueados", 0))
                    tot_gc_perdidas += int(det.get("GrandesChancesPerdidas", 0))
                    
                    tot_passes_dec += int(det.get("PassesDecisivos", 0))
                    tot_chances_criadas += int(det.get("ChancesCriadas", 0))
                    tot_dribles += int(det.get("DriblesCertos", 0))
                    tot_passes_c += int(det.get("PassesCertos", 0))
                    tot_passes_e += int(det.get("PassesErrados", 0))
                    tot_cruz_c += int(det.get("CruzamentosCertos", 0))
                    tot_cruz_t += int(det.get("CruzamentosTentados", 0))
                    
                    tot_desarmes += int(det.get("Desarmes", 0))
                    tot_faltas_s += int(det.get("FaltasSofridas", 0))
                    tot_faltas_c += int(det.get("FaltasCometidas", 0))
                    
                    tot_amarelos += int(jogo.get("Amarelos", 0))
                    tot_vermelhos += int(jogo.get("Vermelhos", 0))
                    
                    tot_dir += int(det.get("PeDireito", 0))
                    tot_esq += int(det.get("PeEsquerdo", 0))
                    tot_cab += int(det.get("Cabeca", 0))
                    tot_falta += int(det.get("FaltasGol", 0))
                    tot_pen += int(det.get("PenalGol", 0))
                    
                    mapa_gols_acumulado.extend(det.get("MapaGols", []))

        if not jogos_contra:
            self.show_toast(f"Nenhum jogo válido encontrado contra {adv_nome}.", "erro")
            return

        # Ordenar cronologicamente (Mais recente primeiro)
        try: jogos_contra.sort(key=lambda x: datetime.datetime.strptime(x.get("Data", "01/01/2000"), "%d/%m/%Y"), reverse=True)
        except: pass

        media_nota = soma_notas / tot_jogos if tot_jogos > 0 else 0.0

        # --- ESTILOS DO POP-UP ---
        BG_MODAL = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"

        pop = Toplevel(self)
        pop.title(f"Dossiê Completo: vs {adv_nome.upper()}")
        pop.geometry("800x850")
        pop.configure(bg=BG_MODAL)
        pop.resizable(False, False)
        
        # Centralizar
        pop.update_idletasks()
        x = (pop.winfo_screenwidth() // 2) - 400
        y = (pop.winfo_screenheight() // 2) - 425
        pop.geometry(f"+{x}+{y}")
        pop.grab_set()

        # =======================================================
        # HEADER (Logo e Nome do Rival)
        # =======================================================
        header = tk.Frame(pop, bg=BG_MODAL)
        header.pack(fill="x", pady=(25, 10), padx=30)
        
        f_logo = tk.Frame(header, bg=BG_MODAL)
        f_logo.pack(side="left")
        
        path_logo = self.club_logo_paths.get(adv_nome, f"Logos/{adv_nome.strip()}.png")
        if os.path.exists(resource_path(path_logo)):
            try:
                pil = Image.open(resource_path(path_logo)).resize((70, 70), Image.Resampling.LANCZOS)
                tk_ico = ImageTk.PhotoImage(pil)
                if not hasattr(self, 'popup_adv_cache'): self.popup_adv_cache = []
                self.popup_adv_cache.append(tk_ico) 
                tk.Label(f_logo, image=tk_ico, bg=BG_MODAL).pack(padx=(0, 15))
            except: 
                tk.Label(f_logo, text=adv_nome[:3].upper(), font=("Impact", 40), fg="#EF4444", bg=BG_MODAL).pack(padx=(0, 15))
        else:
            tk.Label(f_logo, text=adv_nome[:3].upper(), font=("Impact", 40), fg="#EF4444", bg=BG_MODAL).pack(padx=(0, 15))

        f_txt = tk.Frame(header, bg=BG_MODAL)
        f_txt.pack(side="left")
        tk.Label(f_txt, text=adv_nome.upper(), font=("Impact", 32), fg="white", bg=BG_MODAL).pack(anchor="w")
        tk.Label(f_txt, text="Análise Profunda e Histórico de Confrontos", font=("Segoe UI", 11), fg="#F59E0B", bg=BG_MODAL).pack(anchor="w")

        # =======================================================
        # ÁREA DE SCROLL INTELIGENTE
        # =======================================================
        body_container = tk.Frame(pop, bg=BG_MODAL)
        body_container.pack(fill="both", expand=True, padx=10, pady=(0, 10))

        canvas = tk.Canvas(body_container, bg=BG_MODAL, highlightthickness=0)
        scrollbar = ttk.Scrollbar(body_container, orient="vertical", command=canvas.yview)
        scroll_frame = tk.Frame(canvas, bg=BG_MODAL)

        win_id = canvas.create_window((0, 0), window=scroll_frame, anchor="nw", width=750)
        canvas.configure(yscrollcommand=scrollbar.set)

        # Lógica para esconder a scrollbar se não precisar
        def check_scroll(event=None):
            canvas.configure(scrollregion=canvas.bbox("all"))
            if scroll_frame.winfo_reqheight() <= canvas.winfo_height():
                scrollbar.pack_forget()
            else:
                scrollbar.pack(side="right", fill="y")

        scroll_frame.bind("<Configure>", check_scroll)
        canvas.bind("<Configure>", lambda e: [canvas.itemconfig(win_id, width=e.width), check_scroll()])

        canvas.pack(side="left", fill="both", expand=True)

        def _on_mousewheel(event):
            try:
                if scroll_frame.winfo_reqheight() > canvas.winfo_height():
                    canvas.yview_scroll(int(-1*(event.delta/120)), "units")
            except: pass
            
        # O pop-up rouba o scroll pra ele apenas quando o mouse está dentro dele
        pop.bind("<Enter>", lambda e: canvas.bind_all("<MouseWheel>", _on_mousewheel))
        
        def fechar_popup_seguro():
            canvas.unbind_all("<MouseWheel>") # Solta o scroll do popup
            pop.destroy() # Destrói a janela do popup
            
            # === A MÁGICA AQUI: Devolve o controle do scroll para a aba de trás! ===
            if hasattr(self, 'scroll_ativo'):
                self.bind_all("<MouseWheel>", self.scroll_ativo)
            
        # Se o usuário fechar no "X" vermelho da janela do Windows
        pop.protocol("WM_DELETE_WINDOW", fechar_popup_seguro)

        # =======================================================
        # KPIs AGREGADOS BÁSICOS
        # =======================================================
        f_kpis = tk.Frame(scroll_frame, bg=BG_MODAL)
        f_kpis.pack(fill="x", padx=15, pady=10)
        for i in range(4): f_kpis.columnconfigure(i, weight=1)

        cor_nota = "#4ADE80" if media_nota >= 7.5 else ("#FACC15" if media_nota >= 6.5 else "#EF4444")
        
        kpis_lista = [
            ("CONFRONTOS", str(tot_jogos), "white", "⚔️"),
            ("RETROSPECTO", f"{v}V - {e}E - {d}D", "#10B981" if v > d else ("#EF4444" if d > v else "#94A3B8"), "⚖️"),
            ("GOLS & ASSISTS", f"{tot_gols}G | {tot_assists}A", "#38BDF8", "🔥"),
            ("NOTA MÉDIA", f"{media_nota:.2f}", cor_nota, "⭐")
        ]

        for i, (lbl, val, cor, icone) in enumerate(kpis_lista):
            box = tk.Frame(f_kpis, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=15, pady=10)
            box.grid(row=0, column=i, sticky="nsew", padx=5)
            tk.Label(box, text=f"{icone} {lbl}", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")
            tk.Label(box, text=val, font=("Impact", 20), fg=cor, bg=BG_CARD).pack(anchor="w", pady=(5,0))

        # =======================================================
        # BLOCOS DE ESTATÍSTICAS DETALHADAS (O SCOUT)
        # =======================================================
        def criar_bloco_stats(titulo, cor_titulo, lista_stats):
            f_bloco = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            f_bloco.pack(fill="x", pady=8, padx=20)
            
            tk.Label(f_bloco, text=titulo, font=("Segoe UI", 10, "bold"), fg=cor_titulo, bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 5))
            
            grid_s = tk.Frame(f_bloco, bg=BG_CARD)
            grid_s.pack(fill="x", padx=15, pady=(0, 10))
            
            for idx, (icone, label, valor) in enumerate(lista_stats):
                r = idx // 2; c = idx % 2
                item_f = tk.Frame(grid_s, bg=BG_CARD)
                item_f.grid(row=r, column=c, sticky="ew", padx=10, pady=2)
                grid_s.columnconfigure(c, weight=1)
                
                tk.Label(item_f, text=f"{icone} {label}", font=("Segoe UI", 9), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
                try: cv = "white" if float(valor) > 0 else "#64748B"
                except: cv = "white" if str(valor) not in ["0", "0.0", "0 / 0", "Não", ""] else "#64748B"
                
                tk.Label(item_f, text=str(valor), font=("Segoe UI", 10, "bold"), fg=cv, bg=BG_CARD).pack(side="right")

        # BLOCO 1: OFENSIVA
            # BLOCO 1: OFENSIVA
        ataque_stats = [
            ("📊", "Expected Goals (xG)", f"{tot_xg:.2f}"),
            ("🎯", "Chutes no Gol", tot_chutes_gol),
            ("🥅", "Chutes na Trave", tot_chutes_trave),
            ("❌", "Chutes para Fora", tot_chutes_fora),
            ("🛡️", "Chutes Bloqueados", tot_chutes_bloq),
            ("🤦", "Grandes Chances Perdidas", tot_gc_perdidas),
            ("🏃", "Distância Percorrida", f"{tot_distancia:.1f} km"),
        ]
        criar_bloco_stats("⚔️ OFENSIVA & FINALIZAÇÃO", "#4ADE80", ataque_stats)

        # BLOCO 2: PASSES
        criacao_stats = [
            ("📊", "Expected Assists (xA)", f"{tot_xa:.2f}"),
            ("🔑", "Passes Decisivos", tot_passes_dec),
            ("✨", "Chances Claras Criadas", tot_chances_criadas),
            ("🎁", "Pré-Assistências", tot_pre_assists),
            ("⚡", "Dribles Certos", tot_dribles),
            ("✅", "Passes Certos", tot_passes_c),
            ("❌", "Passes Errados", tot_passes_e),
            ("↪️", "Cruzamentos (C/T)", f"{tot_cruz_c} / {tot_cruz_t}"),
            ("♻️", "Posses Ganhas", tot_posses_ganhas),
            ("🗑️", "Posses Perdidas", tot_posses_perdidas),
        ]
        criar_bloco_stats("🧠 CRIAÇÃO E PASSES", "#38BDF8", criacao_stats)

        # BLOCO 3: DEFESA
        defesa_stats = [
            ("🥾", "Desarmes", tot_desarmes),
            ("🧤", "Jogos sem Sofrer Gols", tot_clean),
            ("🤕", "Faltas Sofridas", tot_faltas_s),
            ("🛑", "Faltas Cometidas", tot_faltas_c),
            ("🟨", "Cartões Amarelos", tot_amarelos),
            ("🟥", "Cartões Vermelhos", tot_vermelhos),
        ]
        criar_bloco_stats("🛡️ DEFESA E DISCIPLINA", "#EF4444", defesa_stats)

        # BLOCO 4: RAIO-X DOS GOLS E MAPA (Só se fez gol)
        if tot_gols > 0:
            raiox_stats = [
                ("🦶", "Pé Direito", tot_dir),
                ("🦶", "Pé Esquerdo", tot_esq),
                ("🗣️", "Cabeça", tot_cab),
                ("🎯", "Falta Direta", tot_falta),
                ("🥅", "Pênalti", tot_pen)
            ]
            criar_bloco_stats("🎯 ANATOMIA DOS GOLS", "#F59E0B", raiox_stats)

            if mapa_gols_acumulado:
                f_mapa_popup = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#F59E0B")
                f_mapa_popup.pack(fill="x", pady=8, padx=20)
                
                tk.Label(f_mapa_popup, text=f"🗺️ ONDE SEUS GOLS ENTRARAM CONTRA O {adv_nome.upper()}", font=("Segoe UI", 10, "bold"), fg="#F59E0B", bg=BG_CARD).pack(anchor="w", padx=15, pady=(10, 0))
                
                cv_pop = tk.Canvas(f_mapa_popup, bg="#2A3645", height=180, highlightthickness=0)
                cv_pop.pack(fill="x", padx=15, pady=(10, 5))
                
                f_leg_pop = tk.Frame(f_mapa_popup, bg=BG_CARD)
                f_leg_pop.pack(fill="x", pady=(0, 10), padx=15)
                tk.Label(f_leg_pop, text="🟣 Ângulo/Alto", font=("Segoe UI", 8, "bold"), fg="#8B5CF6", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟠 Meia Altura", font=("Segoe UI", 8, "bold"), fg="#F59E0B", bg=BG_CARD).pack(side="left", expand=True)
                tk.Label(f_leg_pop, text="🟢 Rasteiro", font=("Segoe UI", 8, "bold"), fg="#10B981", bg=BG_CARD).pack(side="left", expand=True)
                
                def desenhar_mapa_popup(event):
                    cv_pop.delete("all")
                    w = event.width
                    h = event.height
                    if w < 50 or h < 50: return
                    
                    goal_h = 130  
                    goal_w = 340  
                    
                    t_x1 = (w - goal_w) / 2
                    t_x2 = t_x1 + goal_w
                    t_y1 = (h - goal_h) / 2 + 5
                    t_y2 = t_y1 + goal_h
                    post_width = 6
                    espaco_rede = 25
                    
                    for i in range(int(t_x1) + espaco_rede, int(t_x2), espaco_rede):
                        cv_pop.create_line(i, t_y1, i, t_y2, fill="#3A4A5E", dash=(2, 2))
                    for i in range(int(t_y1) + espaco_rede, int(t_y2), espaco_rede):
                        cv_pop.create_line(t_x1, i, t_x2, i, fill="#3A4A5E", dash=(2, 2))

                    cv_pop.create_line(t_x1, t_y2, t_x1, t_y1, t_x2, t_y1, t_x2, t_y2, fill="white", width=post_width, joinstyle=tk.ROUND, capstyle=tk.ROUND)

                    for (px, py) in mapa_gols_acumulado:
                        real_x = t_x1 + (px * (t_x2 - t_x1))
                        real_y = t_y1 + (py * (t_y2 - t_y1))
                        raio = 8
                        cor_bola = "#10B981" if py > 0.65 else ("#8B5CF6" if py < 0.35 else "#F59E0B")
                        
                        cv_pop.create_oval(real_x-raio-3, real_y-raio-3, real_x+raio+3, real_y+raio+3, outline=cor_bola, width=2)
                        cv_pop.create_oval(real_x-raio, real_y-raio, real_x+raio, real_y+raio, fill=cor_bola, outline="white", width=2)

                cv_pop.bind("<Configure>", desenhar_mapa_popup)

        # =======================================================
        # CONTAINER DE CARDS (O DESIGN PREMIUM!)
        # =======================================================
        f_tabela = tk.Frame(scroll_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
        f_tabela.pack(fill="both", expand=True, padx=20, pady=(10, 20))
        
        tk.Label(f_tabela, text="TODAS AS PARTIDAS", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 10))

        # --- RENDERIZAÇÃO DOS CARDS ESTILO LIGA ---
        for jogo in jogos_contra:
            wrapper = tk.Frame(f_tabela, bg=BG_CARD)
            wrapper.pack(fill="x", pady=4)
            
            cor_res = "#94A3B8"
            try:
                placar_limpo = jogo.get("Resultado", "0-0").split(" ")[0]
                g_fav, g_con = map(int, placar_limpo.split("-"))
                loc = jogo.get("Local", "C")
                if loc == 'F': g_fav, g_con = g_con, g_fav
                if g_fav > g_con: cor_res = "#4ADE80"
                elif g_fav < g_con: cor_res = "#EF4444"
            except: pass

            card = tk.Frame(wrapper, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", cursor="hand2")
            card.pack(fill="x", ipady=6)
            tk.Frame(card, bg=cor_res, width=4).pack(side="left", fill="y")

            # Bloco Esquerdo (Data e Competição)
            f_info = tk.Frame(card, bg="#252F3D", width=120)
            f_info.pack(side="left", fill="y", padx=10)
            f_info.pack_propagate(False)
            
            f_inf_txt = tk.Frame(f_info, bg="#252F3D")
            f_inf_txt.place(relx=0, rely=0.5, anchor="w")
            tk.Label(f_inf_txt, text=jogo.get('Data'), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(anchor="w")
            comp_nome = jogo.get('Competição', '')
            tk.Label(f_inf_txt, text=f"{comp_nome[:15]}", font=("Segoe UI", 7), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")

            # Bloco Central (Placar com Escudos)
            f_score = tk.Frame(card, bg="#252F3D")
            f_score.pack(side="left", expand=True)

            is_casa = jogo.get("Local", "C") == "C"
            clube_jogo = jogo.get("Time", self.informacoes.get("Clube Atual"))
            adv_jogo = jogo.get("Adversário")

            nome_casa = clube_jogo if is_casa else adv_jogo
            nome_fora = adv_jogo if is_casa else clube_jogo

            def render_mini_logo(parent, name, bg_c):
                path = self.club_logo_paths.get(name, f"Logos/{name.strip()}.png")
                try:
                    if os.path.exists(resource_path(path)):
                        img = ImageTk.PhotoImage(Image.open(resource_path(path)).resize((25, 25), Image.Resampling.LANCZOS))
                        if not hasattr(self, 'popup_logos_cache'): self.popup_logos_cache = []
                        self.popup_logos_cache.append(img)
                        tk.Label(parent, image=img, bg=bg_c).pack(side="left", padx=5)
                        return
                except: pass
                tk.Label(parent, text=name[:3].upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=bg_c).pack(side="left", padx=5)

            f_c = tk.Frame(f_score, bg="#252F3D"); f_c.pack(side="left")
            tk.Label(f_c, text=nome_casa[:15].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")
            render_mini_logo(f_c, nome_casa, "#252F3D")

            tk.Label(f_score, text=jogo.get('Resultado', '0-0'), font=("Impact", 16), fg=cor_res, bg="#252F3D").pack(side="left", padx=15)

            f_f = tk.Frame(f_score, bg="#252F3D"); f_f.pack(side="left")
            render_mini_logo(f_f, nome_fora, "#252F3D")
            tk.Label(f_f, text=nome_fora[:15].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#252F3D").pack(side="left")

            # Bloco Direito (Stats do Jogador)
            f_perf = tk.Frame(card, bg="#252F3D")
            f_perf.pack(side="right", padx=15)
            
            g = int(jogo.get("Gols", 0))
            a = int(jogo.get("Assistências", 0))
            nota_jogo = float(jogo.get("Nota", 6.0))
            cor_nota_card = "#4ADE80" if nota_jogo >= 7.5 else ("#FACC15" if nota_jogo >= 6.5 else "#EF4444")

            tk.Label(f_perf, text=f"{nota_jogo:.1f}", font=("Impact", 16), fg=cor_nota_card, bg="#252F3D").pack(side="right", padx=(10,0))

            if g > 0: tk.Label(f_perf, text=f"⚽ {g}", font=("Segoe UI", 9, "bold"), fg="#4ADE80", bg="#252F3D").pack(side="right", padx=3)
            if a > 0: tk.Label(f_perf, text=f"🤝 {a}", font=("Segoe UI", 9, "bold"), fg="#38BDF8", bg="#252F3D").pack(side="right", padx=3)

            # Efeitos Interativos de Hover
            def on_ent(e, c=card, fi=f_info, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fper=f_perf):
                for w in [c, fi, fit, fp, fc, ff, fper]: w.configure(bg="#334155")
                for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fper.winfo_children():
                    if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#334155")

            def on_lea(e, c=card, fi=f_info, fit=f_inf_txt, fp=f_score, fc=f_c, ff=f_f, fper=f_perf):
                for w in [c, fi, fit, fp, fc, ff, fper]: w.configure(bg="#252F3D")
                for child in fit.winfo_children() + fp.winfo_children() + fc.winfo_children() + ff.winfo_children() + fper.winfo_children():
                    if isinstance(child, tk.Label) or isinstance(child, tk.Frame): child.configure(bg="#252F3D")
            
            card.bind("<Enter>", on_ent)
            card.bind("<Leave>", on_lea)

            # Clique para abrir o Dossiê da Partida!
            def ao_clicar(e, j_data=jogo): 
                j_pop = {
                    "data": j_data.get("Data"),
                    "adv": j_data.get("Adversário"),
                    "comp": j_data.get("Competição"),
                    "rodada": j_data.get("Rodada", ""),
                    "local": j_data.get("Local", "C"),
                    "clube": j_data.get("Time", self.informacoes.get("Clube Atual")),
                    "res": j_data.get("Resultado"),
                    "status": j_data.get("Posição"),
                    "minutos": j_data.get("Minutos", 90),
                    "gols": j_data.get("Gols", 0),
                    "assists": j_data.get("Assistências", 0),
                    "amarelos": j_data.get("Amarelos", 0),
                    "vermelhos": j_data.get("Vermelhos", 0)
                }
                self.abrir_popup_partida(j_pop)
            
            for w in [card, f_info, f_inf_txt, f_score, f_c, f_f, f_perf]:
                w.bind("<Button-1>", ao_clicar)
                for sub_w in w.winfo_children(): sub_w.bind("<Button-1>", ao_clicar)

        tk.Frame(scroll_frame, bg=BG_MODAL, height=10).pack()

        tk.Button(pop, text="FECHAR DOSSIÊ", bg="#334155", fg="white", font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", command=fechar_popup_seguro, pady=10).pack(fill="x", padx=20, side="bottom", pady=15)

    def get_arquivo_json(self):
        """Retorna o caminho do arquivo de save atual ou o padrão caso seja nova carreira."""
        import os
        import sys
        
        # 1. Se o usuário CARREGOU uma carreira, salva sempre no mesmo arquivo que ele abriu
        if hasattr(self, 'arquivo_carreira_atual') and self.arquivo_carreira_atual:
            return self.arquivo_carreira_atual
            
        # 2. Se é uma NOVA CARREIRA, cria/sobrescreve o arquivo padrão
        if getattr(sys, 'frozen', False):
            application_path = os.path.dirname(sys.executable)
        else:
            application_path = os.path.dirname(os.path.abspath(__file__))
            
        return os.path.join(application_path, "dados_save.json")

    def atualizar_badge_notificacao(self):
        # --- PROTEÇÃO CONTRA ERRO DE INICIALIZAÇÃO ---
        # Se a variável ainda não foi criada no __init__, a gente para por aqui.
        if not hasattr(self, 'badge_widget'):
            return

        # 1. Remove badge anterior se existir
        if self.badge_widget:
            self.badge_widget.destroy()
            self.badge_widget = None
            
        # Se não tem notícias novas ou o menu ainda não foi criado, não faz nada
        if getattr(self, 'noticias_nao_lidas', 0) <= 0:
            return
        
        if not hasattr(self, 'menu_buttons') or not self.menu_buttons:
            return

        # 2. Encontra o botão "Notícias & Feed" (Índice 17)
        btn_news = self.menu_buttons.get(17) 
        
        if btn_news:
            # Cria a bolinha (Label vermelha redonda simulada)
            self.badge_widget = tk.Label(
                btn_news, 
                text=str(self.noticias_nao_lidas),
                bg="#EF4444", # Vermelho
                fg="white",
                font=("Segoe UI", 8, "bold"),
                bd=0,
                padx=5,
                pady=0
            )
            self.badge_widget.place(relx=0.85, rely=0.5, anchor="center")

    def verificar_e_gerar_noticias_retroativas(self):
        """
        Gera notícias para jogos do histórico que ainda não estão no feed.
        Essencial para popular a aba Notícias com partidas antigas.
        """
        import random
        from datetime import datetime, timedelta

        # Se não tiver histórico, não faz nada
        if not hasattr(self, 'ultimas_performances') or not self.ultimas_performances:
            return

        # Garante que o feed existe
        if not hasattr(self, 'feed_noticias'):
            self.feed_noticias = []

        # Cria um conjunto de chaves únicas das notícias existentes para evitar duplicatas
        # Chave = Data + Adversário
        noticias_existentes = set()
        for n in self.feed_noticias:
            if n.get("tipo") == "match":
                stats = n.get("stats", {})
                chave = f"{n['data']}_{stats.get('adv', 'Rival')}"
                noticias_existentes.add(chave)

        novas_noticias = []
        
        # Pega dados básicos para o texto
        nome_jogador = self.informacoes.get("Nome Completo", "Jogador").split()[0].upper()
        clube_atual = self.informacoes.get("Clube Atual", "Clube").upper()

        # Itera sobre o histórico (do mais recente para o mais antigo)
        for jogo in self.ultimas_performances:
            data = jogo.get("Data")
            adv = jogo.get("Adversário")
            chave_jogo = f"{data}_{adv}"

            # Se esse jogo AINDA NÃO tem notícia, cria uma agora
            if chave_jogo not in noticias_existentes:
                try:
                    # Extrai dados
                    gols = int(jogo.get("Gols", 0))
                    assists = int(jogo.get("Assistências", 0))
                    nota = float(jogo.get("Nota", 6.0))
                    placar = jogo.get("Resultado", "0-0")
                    comp = jogo.get("Competição", "Campeonato")
                    time_atuacao = jogo.get("Time", clube_atual).upper()

                    # Lógica de Manchete (Simplificada para retroativos)
                    tag_news = "JOGO"
                    
                    # Análise rápida do placar
                    try:
                        p_limpo = placar.split(" ")[0]
                        pc, pf = map(int, p_limpo.split("-"))
                        loc = jogo.get("Local", "C")
                        g_pro = pc if loc == "C" else pf
                        g_contra = pf if loc == "C" else pc
                        saldo = g_pro - g_contra
                    except: saldo = 0

                    if nota >= 9.0: 
                        headline = f"ATUAÇÃO DE GALA: {nome_jogador} BRILHA CONTRA O {adv.upper()}"
                        tag_news = "DESTAQUE"
                    elif gols >= 2:
                        headline = f"{nome_jogador} DECIDE E {time_atuacao} VENCE O {adv.upper()}"
                        tag_news = "JOGO"
                    elif saldo >= 3:
                        headline = f"GOLEADA: {time_atuacao} ATROPELA O {adv.upper()} POR {placar}"
                        tag_news = "DESTAQUE"
                    elif saldo < 0:
                        headline = f"{time_atuacao} TROPEÇA DIANTE DO {adv.upper()}"
                        tag_news = "CRISE" if nota < 5 else "JOGO"
                    else:
                        headline = f"TUDO IGUAL: {time_atuacao} E {adv.upper()} EMPATAM"

                    # Cria o objeto da notícia
                    noticia = {
                        "tipo": "match",
                        "data": data,
                        "titulo": headline,
                        "texto_curto": f"Relembre os detalhes do confronto que terminou em {placar}.",
                        "tag": tag_news,
                        "lida": True, # Marcamos como lida para não inundar de notificações
                        "stats": {
                            "nome": nome_jogador,
                            "clube": time_atuacao,
                            "adv": adv,
                            "placar": placar,
                            "gols": gols,
                            "assists": assists,
                            "nota": nota,
                            "comp": comp,
                            "local": jogo.get("Local", "C"),
                            "saldo": saldo
                        }
                    }
                    novas_noticias.append(noticia)
                    
                    # Opcional: Gerar uma notícia aleatória (fake) antiga também?
                    # Vamos evitar para não poluir demais o histórico de uma vez.

                except Exception as e:
                    print(f"Erro ao gerar notícia retroativa para {data}: {e}")

        # Adiciona as novas notícias ao feed
        if novas_noticias:
            print(f"Gerando {len(novas_noticias)} notícias retroativas...")
            self.feed_noticias.extend(novas_noticias)
            
            # Reordena tudo por data (do mais novo para o mais antigo)
            try:
                self.feed_noticias.sort(key=lambda x: datetime.strptime(x['data'], "%d/%m/%Y"), reverse=True)
            except: pass
            
            if len(self.feed_noticias) > 10:
                self.feed_noticias = self.feed_noticias[:10]

            # Salva para garantir
            self.salvar_dados()

    def verificar_quebra_recorde(self, comp_atual, gols_na_partida):
        # Normaliza o nome da competição para bater com a chave do dicionário
        chave_db = None
        for k in self.recordes_reais.keys():
            if k in comp_atual: # Ex: "Premier League" in "Premier League 2028/29"
                chave_db = k
                break
        
        if not chave_db: return

        # 1. Calcular seus totais
        meus_gols_hist = 0
        meus_gols_season = 0
        
        # Pega o ano atual baseado na última performance salva
        ano_atual = list(self.dados_temporada_Geral.keys())[0] if self.dados_temporada_Geral else "2024"

        # Varre o histórico para somar
        # Nota: Você precisa adaptar isso se usar a estrutura de lista ou dicionário dependendo da competição
        # Vou fazer uma varredura genérica no 'dados_desempenho' que já soma tudo
        for row in self.dados_desempenho:
            if row[0] == comp_atual: # Verifica nome exato (com cuidado com ano)
                # Para simplificar, vamos somar da lista geral de performances
                pass

        # Soma precisa varrendo 'ultimas_performances'
        for jogo in self.ultimas_performances:
            if chave_db in jogo["Competição"]:
                g = int(jogo["Gols"])
                meus_gols_hist += g
                # Verifica se é da temporada atual (lógica simples de data ou ano)
                # Aqui simplificado:
                if jogo["Competição"] == comp_atual: # Nome exato com ano
                    meus_gols_season += g

        dados_rec = self.recordes_reais[chave_db]

        # 2. Verificar Recorde de Temporada
        rec_season_nome, rec_season_val = dados_rec.get("artilharia_season", ("-", 999))
        
        # Se você acabou de passar ou empatar
        if meus_gols_season == rec_season_val:
            self.show_toast(f"HISTÓRICO! Você igualou o recorde de {rec_season_nome} ({rec_season_val} gols)!", "sucesso")
        elif meus_gols_season == rec_season_val + 1 and gols_na_partida > 0:
             # Só avisa na hora que quebra
             import tkinter.messagebox
             tkinter.messagebox.showinfo("RECORDE QUEBRADO!", f"LENDÁRIO!\n\nVocê acabou de se tornar o maior artilheiro em uma única edição de {chave_db}!\n\nNovo Recorde: {meus_gols_season} Gols\nAnterior: {rec_season_nome} ({rec_season_val})")

        # 3. Verificar Ranking Histórico
        lista_lendas = dados_rec.get("artilharia_hist", [])
        # Ordena: Lendas + Você
        minha_entry = ("VOCÊ", meus_gols_hist)
        ranking_virtual = sorted(lista_lendas + [minha_entry], key=lambda x: x[1], reverse=True)
        
        # Acha sua posição
        minha_pos = -1
        for i, (nome, gols) in enumerate(ranking_virtual):
            if nome == "VOCÊ" and gols == meus_gols_hist:
                minha_pos = i + 1
                break
        
        # Se entrou no TOP 5 pela primeira vez (lógica simples: se está no top 5 agora)
        if minha_pos <= 5 and meus_gols_hist > 0:
            # Verifica quem você ultrapassou (quem está em pos+1 agora)
            if len(ranking_virtual) > minha_pos:
                ultrapassado = ranking_virtual[minha_pos][0] # O cara abaixo de você
                if ultrapassado != "VOCÊ":
                    self.show_toast(f"Subiu no Ranking! Passou {ultrapassado}.", "info")

    def aba_rankings(self, parent_frame):
        # --- ESTILOS & CORES ---
        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        ACCENT_GOLS = "#4ADE80"   # Verde
        ACCENT_ASSIST = "#60A5FA" # Azul
        ACCENT_JOGOS = "#F8FAFC"  # Branco
        TEXT_SUB = "#94A3B8"

        self.style.configure("RankMain.TFrame", background=BG_DARK)
        self.style.configure("RankBtn.TButton", font=("Segoe UI", 10, "bold"), padding=6)

        # --- ESTRUTURA ---
        aba_rank = ttk.Frame(parent_frame, style="RankMain.TFrame")
        aba_rank.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_rank, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_rank, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="RankMain.TFrame")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        canvas.create_window((0, 0), window=inner, anchor="nw")
        
        def _resize(e): canvas.itemconfig(canvas.find_all()[0], width=e.width)
        canvas.bind("<Configure>", _resize)
        def _scroll(e): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # --- HEADER ---
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="RANKINGS HISTÓRICOS", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="Sua posição entre as lendas (apenas competições disputadas)", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # --- BOTÕES DE CATEGORIA ---
        btn_frame = tk.Frame(inner, bg=BG_DARK)
        btn_frame.pack(fill="x", padx=40, pady=(10, 20))

        # Variável de controle (persistente enquanto a aba está aberta)
        if not hasattr(self, 'categoria_ranking_atual'):
            self.categoria_ranking_atual = "gols"

        def trocar_categoria(cat):
            self.categoria_ranking_atual = cat
            # Atualiza visual dos botões
            b_gol.config(bg=ACCENT_GOLS if cat=="gols" else BG_CARD, fg="#064E3B" if cat=="gols" else "white")
            b_ass.config(bg=ACCENT_ASSIST if cat=="assists" else BG_CARD, fg="#1e3a8a" if cat=="assists" else "white")
            b_jog.config(bg=ACCENT_JOGOS if cat=="jogos" else BG_CARD, fg="black" if cat=="jogos" else "white")
            renderizar_listas()

        b_gol = tk.Button(btn_frame, text="⚽ MAIORES ARTILHEIROS", font=("Segoe UI", 10, "bold"), relief="flat", padx=15, pady=8, command=lambda: trocar_categoria("gols"))
        b_gol.pack(side="left", padx=(0, 10))

        b_ass = tk.Button(btn_frame, text="👟 MAIORES GARÇONS", font=("Segoe UI", 10, "bold"), relief="flat", padx=15, pady=8, command=lambda: trocar_categoria("assists"))
        b_ass.pack(side="left", padx=(0, 10))

        b_jog = tk.Button(btn_frame, text="👕 MAIS JOGOS", font=("Segoe UI", 10, "bold"), relief="flat", padx=15, pady=8, command=lambda: trocar_categoria("jogos"))
        b_jog.pack(side="left")

        # Container onde as tabelas vão aparecer
        lists_container = tk.Frame(inner, bg=BG_DARK)
        lists_container.pack(fill="both", expand=True, padx=40)

        # --- FUNÇÃO DE RENDERIZAÇÃO ---
        def renderizar_listas():
            # Limpa container
            for w in lists_container.winfo_children(): w.destroy()
            
            tipo = self.categoria_ranking_atual
            encontrou_alguma_comp = False # Para mostrar aviso se estiver vazio
            
            # Define chaves e cores baseadas no tipo
            if tipo == "gols":
                key_db = "artilharia_hist"
                idx_dados = 2 # Índice de Gols em dados_desempenho
                cor_bar = ACCENT_GOLS
                titulo_sec = "GOLS MARCADOS"
            elif tipo == "assists":
                key_db = "assists_hist"
                idx_dados = 3 # Índice de Assists
                cor_bar = ACCENT_ASSIST
                titulo_sec = "ASSISTÊNCIAS"
            else:
                key_db = "jogos_hist"
                idx_dados = 1 # Índice de Jogos
                cor_bar = ACCENT_JOGOS
                titulo_sec = "PARTIDAS DISPUTADAS"

            # Itera sobre as competições configuradas em Recordes Reais
            for nome_comp, dados_rec in self.recordes_reais.items():
                
                # 1. BUSCAR MEUS DADOS NO "GERAL CARREIRA" (dados_desempenho)
                meu_valor_ranking = 0
                meus_jogos_total = 0 # <--- CRUCIAL: Conta jogos para saber se participou
                
                # Itera sobre dados_desempenho: [Nome, J, G, A, ...]
                for row in self.dados_desempenho:
                    nome_minha_comp = row[0].upper() # Nome nos seus stats (ex: Copa do Brasil)
                    nome_ranking = nome_comp.upper() # Nome no Ranking (ex: Supercopa do Brasil)
                    
                    eh_a_competicao = False

                    # Verificação 1: Match Exato (Ideal)
                    if nome_ranking == nome_minha_comp:
                        eh_a_competicao = True
                    
                    # Verificação 2: Aproximação (Ex: "Libertadores" em "Conmebol Libertadores")
                    elif nome_ranking in nome_minha_comp or nome_minha_comp in nome_ranking:
                        eh_a_competicao = True
                        
                        # --- [CORREÇÃO DO BUG] ---
                        # Se uma tem "SUPER" (Supercopa) e a outra não (Copa), NÃO é a mesma!
                        if "SUPER" in nome_ranking and "SUPER" not in nome_minha_comp: 
                            eh_a_competicao = False
                        elif "SUPER" in nome_minha_comp and "SUPER" not in nome_ranking: 
                            eh_a_competicao = False

                    if eh_a_competicao:
                        meus_jogos_total += int(row[1]) 
                        meu_valor_ranking += int(row[idx_dados])

                # --- FILTRO DE PARTICIPAÇÃO ---
                # Se nunca jogou (0 jogos), essa competição NÃO aparece na lista
                if meus_jogos_total == 0: 
                    continue
                
                encontrou_alguma_comp = True

                # 2. PREPARAR LISTA MISTA (LENDAS + VOCÊ)
                lista_lendas = dados_rec.get(key_db, [])
                
                # Adiciona o jogador
                ranking_completo = lista_lendas + [("VOCÊ (Atual)", meu_valor_ranking)]
                # Ordena do maior para o menor
                ranking_completo.sort(key=lambda x: x[1], reverse=True)

                # Descobre o índice do jogador na lista completa
                indice_usuario = -1
                for i, item in enumerate(ranking_completo):
                    if item[0] == "VOCÊ (Atual)":
                        indice_usuario = i
                        break

                # 3. RENDERIZAR CARD DA COMPETIÇÃO
                card = tk.Frame(lists_container, bg=BG_CARD)
                card.pack(fill="x", pady=10)
                
                # Topo do Card
                top = tk.Frame(card, bg="#233040", height=45)
                top.pack(fill="x")
                top.pack_propagate(False)
                
                self._render_logo_mini(top, nome_comp)
                tk.Label(top, text=f"{nome_comp.upper()} - {titulo_sec}", font=("Segoe UI", 11, "bold"), fg=TEXT_SUB, bg="#233040").pack(side="left", padx=10)

                # --- 4. RENDERIZAR LINHAS (LÓGICA TOP 10 + VOCÊ) ---
                max_val = ranking_completo[0][1] if ranking_completo else 1
                mostrou_separador = False

                for i, (nome_player, qtd) in enumerate(ranking_completo):
                    pos = i + 1
                    is_me = (i == indice_usuario)
                    
                    # === LÓGICA DE EXIBIÇÃO ===
                    # Mostra se for Top 10 OU se for o usuário
                    if pos > 10 and not is_me:
                        continue 
                    
                    # Se pulou gente (ex: rank 11 até 49) e agora vai mostrar o usuário (rank 50), põe "..."
                    if pos > 11 and is_me and not mostrou_separador:
                        sep_row = tk.Frame(card, bg=BG_CARD)
                        sep_row.pack(fill="x", pady=2)
                        tk.Label(sep_row, text="...", font=("Segoe UI", 12, "bold"), fg="#64748B", bg=BG_CARD).pack(anchor="center")
                        mostrou_separador = True

                    # Renderiza a Linha
                    bg_row = BG_CARD
                    fg_row = "white"
                    font_row = ("Segoe UI", 10)
                    
                    if is_me:
                        bg_row = "#374151" # Fundo destacado para mim
                        fg_row = cor_bar   # Texto colorido
                        font_row = ("Segoe UI", 10, "bold")

                    row_f = tk.Frame(card, bg=bg_row)
                    row_f.pack(fill="x", pady=1, padx=1)
                    
                    # Posição
                    cor_pos = "#64748B"
                    if pos == 1: cor_pos = "#FFD700"
                    elif pos == 2: cor_pos = "#C0C0C0"
                    elif pos == 3: cor_pos = "#CD7F32"
                    if is_me: cor_pos = cor_bar
                    
                    tk.Label(row_f, text=f"#{pos}", width=4, font=("Segoe UI", 10, "bold"), fg=cor_pos, bg=bg_row).pack(side="left")
                    tk.Label(row_f, text=nome_player, font=font_row, fg=fg_row, bg=bg_row).pack(side="left", padx=10)
                    
                    # Barra Visual
                    if max_val > 0:
                        pct = qtd / max_val
                        w_bar = int(pct * 200)
                    else: w_bar = 0
                    
                    f_right = tk.Frame(row_f, bg=bg_row)
                    f_right.pack(side="right", padx=20)
                    
                    tk.Frame(f_right, bg=cor_bar, width=w_bar, height=6).pack(side="left", padx=(0, 10))
                    tk.Label(f_right, text=str(qtd), font=("Segoe UI", 10, "bold"), fg="white", bg=bg_row, width=5).pack(side="left")

                # Rodapé "Faltam X" (Motivação)
                if meu_valor_ranking > 0 and indice_usuario > 0:
                    alvo = ranking_completo[indice_usuario-1]
                    diff = alvo[1] - meu_valor_ranking
                    msg = f"Faltam {diff} para ultrapassar {alvo[0]} (#{indice_usuario})"
                    tk.Label(card, text=msg, font=("Segoe UI", 9, "italic"), fg=cor_bar, bg=BG_CARD).pack(anchor="e", padx=15, pady=5)
                elif indice_usuario == 0 and meu_valor_ranking > 0:
                    tk.Label(card, text="👑 RECORDE ABSOLUTO!", font=("Segoe UI", 9, "bold"), fg="#FFD700", bg=BG_CARD).pack(anchor="e", padx=15, pady=5)

            # Se não encontrou nenhuma competição jogada
            if not encontrou_alguma_comp:
                tk.Label(lists_container, text="Você ainda não disputou partidas nas competições configuradas no Ranking.", 
                         fg=TEXT_SUB, bg=BG_DARK, font=("Segoe UI", 12)).pack(pady=40)
            else:
                tk.Label(lists_container, text="", bg=BG_DARK, height=2).pack()

        # Inicializa com a última categoria selecionada ou padrão
        trocar_categoria(self.categoria_ranking_atual)

    def iniciar_ciclo_vida_real(self):
        """
        Ciclo de vida (Modo Jogo Apenas):
        Não gera eventos aleatórios. Apenas mantém o loop ativo se necessário
        para futuras implementações ou timers de interface.
        """
        # Removemos a chamada de 'gerar_eventos_aleatorios'.
        # Mantemos apenas o loop para não quebrar a estrutura caso adicione algo depois.
        self.after(60000, self.iniciar_ciclo_vida_real)

    def _inferir_temporada(self, data_str):
        """Lê a data de um jogo e descobre a qual temporada ele pertence."""
        try:
            dia, mes, ano_num = map(int, data_str.split('/'))
            ano_euro = f"{ano_num}/{str(ano_num + 1)[-2:]}" if mes >= 7 else f"{ano_num - 1}/{str(ano_num)[-2:]}"
            ano_br = str(ano_num)
            
            # Prioriza a que existir no banco de dados do jogador
            if hasattr(self, 'dados_jogador'):
                if ano_euro in self.dados_jogador: return ano_euro
                if ano_br in self.dados_jogador: return ano_br
                tem_euro = any("/" in k for k in self.dados_jogador.keys())
                return ano_euro if tem_euro else ano_br
            return ano_br
        except:
            return "2025"

    def aba_analise_tatica(self, parent_frame):
        # --- CORES E ESTILOS MODERNOS ---
        import tkinter as tk
        from tkinter import ttk
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np

        BG_BASE = "#0F172A"       
        BG_CARD = "#1E293B"       
        ACCENT_TACTIC = "#8B5CF6" 
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"

        self.style.configure("TacMain.TFrame", background=BG_BASE)
        self.style.configure("TacCard.TFrame", background=BG_CARD, relief="solid", borderwidth=1, bordercolor="#334155")
        
        # --- SCROLL SETUP ---
        canvas = tk.Canvas(parent_frame, bg=BG_BASE, highlightthickness=0)
        scrollbar = ttk.Scrollbar(parent_frame, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="TacMain.TFrame")
        
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        def _scroll(e): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        # ======================================================================
        # 1. HEADER E FILTRO
        # ======================================================================
        header_bg = "#111827"
        f_header = tk.Frame(inner, bg=header_bg)
        f_header.pack(fill="x", pady=(0, 10))
        tk.Frame(f_header, bg=ACCENT_TACTIC, height=3).pack(fill="x")
        
        h_content = tk.Frame(f_header, bg=header_bg, padx=40, pady=20)
        h_content.pack(fill="x")
        
        tk.Label(h_content, text="ANÁLISE DE SCOUT", font=("Impact", 28), fg="white", bg=header_bg).pack(anchor="w")
        tk.Label(h_content, text="Mapeamento tático e evolução de forma baseado no rendimento", font=("Segoe UI", 11), fg=TEXT_SUB, bg=header_bg).pack(anchor="w")
        
        # Filtro
        ctrl_frame = tk.Frame(inner, bg=BG_BASE)
        ctrl_frame.pack(fill="x", padx=40, pady=(10, 10))
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=ACCENT_TACTIC, bg=BG_BASE).pack(anchor="w")
        
        opcoes_ano = ["Todas as Temporadas"] + sorted(list(getattr(self, 'dados_jogador', {}).keys()), reverse=True)
        selected_season = tk.StringVar(value=opcoes_ano[0])
        combo = ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_ano, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        # Container Dinâmico
        dynamic_container = tk.Frame(inner, bg=BG_BASE)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_tatica'): self.fig_tatica = []

        def atualizar_view(event=None):
            for f in self.fig_tatica: plt.close(f)
            self.fig_tatica.clear()
            for widget in dynamic_container.winfo_children(): widget.destroy()

            filtro = selected_season.get()

            # --- MOTOR DE DADOS ---
            total_jogos = 0
            soma_gols, soma_assists = 0, 0
            soma_chances, soma_dribles, soma_passes, soma_desarmes = 0, 0, 0, 0
            soma_xg = 0.0
            soma_xa = 0.0; soma_distancia = 0.0; soma_pos_ganhas = 0; soma_pos_perdidas = 0
            soma_p_certos, soma_p_errados = 0, 0
            soma_faltas_sof, soma_faltas_com = 0, 0
            soma_notas = 0.0
            soma_motm = 0
            jogos_grafico_linha = [] 
            
            for jogo in self.ultimas_performances:
                if filtro != "Todas as Temporadas" and self._inferir_temporada(jogo.get("Data", "")) != filtro:
                    continue

                pos = jogo.get("Posição", "MEI")
                status_ausente = ["Banco", "Suspenso", "Lesionado", "Convocado", "Não Relacionado"]
                
                if pos not in status_ausente and int(jogo.get("Minutos", 90)) > 0:
                    total_jogos += 1
                    soma_gols += int(jogo.get("Gols", 0))
                    soma_assists += int(jogo.get("Assistências", 0))
                    
                    jogos_grafico_linha.insert(0, jogo)
                    
                    try:
                        soma_notas += float(jogo.get("Nota", 6.0))
                    except: pass
                    
                    det = jogo.get("Detalhes", {})
                    soma_chances += int(det.get("ChancesCriadas", 0))
                    soma_dribles += int(det.get("DriblesCertos", 0))
                    soma_passes += int(det.get("PassesDecisivos", 0))
                    soma_desarmes += int(det.get("Desarmes", 0))
                    soma_xg += float(det.get("xG", 0.0))
                    soma_xa += float(det.get("xA", 0.0))
                    soma_distancia += float(det.get("DistanciaPercorrida", 0.0))
                    soma_pos_ganhas += int(det.get("PossesGanhas", 0))
                    soma_pos_perdidas += int(det.get("PossesPerdidas", 0))
                    soma_p_certos += int(det.get("PassesCertos", 0))
                    soma_p_errados += int(det.get("PassesErrados", 0))
                    soma_faltas_sof += int(det.get("FaltasSofridas", 0))
                    soma_faltas_com += int(det.get("FaltasCometidas", 0))
                    
                    if det.get("MOTM"): soma_motm += 1
                    
            if total_jogos > 0:
                m_gols = soma_gols / total_jogos
                m_assists = soma_assists / total_jogos
                m_chances = soma_chances / total_jogos
                m_dribles = soma_dribles / total_jogos
                m_passes = soma_passes / total_jogos
                m_desarmes = soma_desarmes / total_jogos
                m_xg = soma_xg / total_jogos
                m_xa = soma_xa / total_jogos
                m_distancia = soma_distancia / total_jogos
                m_pos_ganhas = soma_pos_ganhas / total_jogos
                m_pos_perdidas = soma_pos_perdidas / total_jogos
                m_faltas = soma_faltas_sof / total_jogos
                m_faltas_c = soma_faltas_com / total_jogos
                m_nota = soma_notas / total_jogos
            else:
                m_gols = m_assists = m_chances = m_dribles = m_passes = m_desarmes = m_xg = m_faltas = m_faltas_c = m_nota = 0
                m_xa = m_distancia = m_pos_ganhas = m_pos_perdidas = 0

            tot_passes = soma_p_certos + soma_p_errados
            pct_passes = (soma_p_certos / tot_passes * 100) if tot_passes > 0 else 0.0

            def escalar(valor, max_esperado):
                return min(100, max(0, int((valor / max_esperado) * 100)))

            radar_data = {
                "Ataque\n(Gols)": escalar(m_gols, 0.8),
                "Passe Final\n(Assist)": escalar(m_assists, 0.4),
                "Criação\n(Chances/Chave)": escalar(m_chances + m_passes, 3.5),
                "Habilidade\n(Dribles)": escalar(m_dribles, 4.0),
                "Defesa\n(Desarmes)": escalar(m_desarmes, 3.0),
            }

            estilo = "Indefinido"; desc_estilo = "Jogue mais partidas nesta temporada."; cor_estilo = TEXT_SUB
            if total_jogos > 0:
                maior_atributo = max(radar_data, key=radar_data.get)
                max_val = radar_data[maior_atributo]
                
                if max_val < 15:
                    estilo = "Coadjuvante em Evolução"; desc_estilo = "Discreto em campo. Precisa participar mais ativamente."; cor_estilo = "#94A3B8"
                elif "Ataque" in maior_atributo:
                    estilo = "Matador Implacável"; desc_estilo = "Foco total na área e em balançar as redes. Altamente letal."; cor_estilo = "#EF4444" 
                elif "Criação" in maior_atributo or "Passe" in maior_atributo:
                    estilo = "Maestro Criador"; desc_estilo = "O cérebro do time. Quebra defesas adversárias com passes."; cor_estilo = "#0EA5E9" 
                elif "Habilidade" in maior_atributo:
                    estilo = "Driblador Insinuante"; desc_estilo = "Destrói a marcação no um contra um. Muito liso e rápido."; cor_estilo = "#F59E0B" 
                elif "Defesa" in maior_atributo:
                    estilo = "Muralha Defensiva"; desc_estilo = "Especialista na contenção. Pesadelo para atacantes."; cor_estilo = "#10B981" 

            cor_nota = "#4ADE80" if m_nota >= 7.5 else ("#FACC15" if m_nota >= 6.5 else "#EF4444")

            # ======================================================================
            # ANDAR 1: FAIXA EXECUTIVA (KPIs Principais)
            # ======================================================================
            top_ribbon = tk.Frame(dynamic_container, bg=BG_BASE)
            top_ribbon.pack(fill="x", padx=40, pady=(10, 20))
            for i in range(4): top_ribbon.columnconfigure(i, weight=1)

            top_kpis = [
                ("NOTA MÉDIA", f"{m_nota:.2f}", "Avaliação Sofascore", cor_nota, "⭐"),
                ("MELHOR EM CAMPO", f"{soma_motm}", "Prêmios MOTM", "#FFD700", "🏅"),
                ("GOLS / JOGO", f"{m_gols:.2f}", "Eficiência matadora", "#EF4444", "⚽"),
                ("ASSIST. / JOGO", f"{m_assists:.2f}", "Serviços do garçom", "#A855F7", "🤝")
            ]

            for i, (titulo, val, sub, cor, icone) in enumerate(top_kpis):
                box = tk.Frame(top_ribbon, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
                box.grid(row=0, column=i, sticky="nsew", padx=(0, 15) if i < 3 else 0)
                tk.Frame(box, bg=cor, height=2).pack(fill="x", side="top")
                tk.Label(box, text=f"{icone} {titulo}", font=("Segoe UI", 9, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w", pady=(10, 5))
                tk.Label(box, text=val, font=("Segoe UI", 26, "bold"), fg=cor, bg=BG_CARD).pack(anchor="w")
                tk.Label(box, text=sub, font=("Segoe UI", 8), fg="#64748B", bg=BG_CARD).pack(anchor="w")

            # ======================================================================
            # ANDAR 2: NÚCLEO TÁTICO (Radar | Scout | Detalhes)
            # ======================================================================
            mid_grid = tk.Frame(dynamic_container, bg=BG_BASE)
            mid_grid.pack(fill="x", padx=40, pady=10)
            mid_grid.columnconfigure(0, weight=3) # Radar
            mid_grid.columnconfigure(1, weight=3) # Scout
            mid_grid.columnconfigure(2, weight=4) # Detalhes

            # COLUNA 1: RADAR
            f_radar = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_radar.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
            tk.Label(f_radar, text="ATRIBUTOS TÁTICOS", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="center", pady=(0, 10))

            if total_jogos == 0:
                tk.Label(f_radar, text="Sem dados.", fg=TEXT_SUB, bg=BG_CARD).pack(expand=True)
            else:
                radar_plot_frame = tk.Frame(f_radar, bg=BG_CARD)
                radar_plot_frame.pack(fill="both", expand=True)
                self.criar_grafico_radar_atributos(radar_plot_frame, radar_data, bg_color=BG_CARD, line_color=ACCENT_TACTIC)
                if self.matplotlib_canvases: self.fig_tatica.append(self.matplotlib_canvases[-1].figure)

            # COLUNA 2: RELATÓRIO SCOUT
            f_scout = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_scout.grid(row=0, column=1, sticky="nsew", padx=10)
            tk.Label(f_scout, text="📋 RELATÓRIO DO OLHEIRO", font=("Segoe UI", 12, "bold"), fg=ACCENT_TACTIC, bg=BG_CARD).pack(anchor="w", pady=(0, 15))

            box_perfil = tk.Frame(f_scout, bg="#252F3D", highlightthickness=1, highlightbackground=cor_estilo, padx=15, pady=15)
            box_perfil.pack(fill="x", pady=(0, 15))
            tk.Label(box_perfil, text="ESTILO DE JOGO", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")
            tk.Label(box_perfil, text=estilo.upper(), font=("Impact", 20), fg=cor_estilo, bg="#252F3D").pack(anchor="w", pady=(0, 2))
            tk.Label(box_perfil, text=desc_estilo, font=("Segoe UI", 9, "italic"), fg="white", bg="#252F3D", wraplength=220, justify="left").pack(anchor="w")

            f_pros = tk.Frame(f_scout, bg="#1B3B2F", highlightthickness=1, highlightbackground="#10B981", padx=10, pady=10)
            f_pros.pack(fill="x", pady=(0, 10))
            tk.Label(f_pros, text="🟢 PONTOS FORTES", font=("Segoe UI", 9, "bold"), fg="#10B981", bg="#1B3B2F").pack(anchor="w", pady=(0, 5))

            f_cons = tk.Frame(f_scout, bg="#3B1B1B", highlightthickness=1, highlightbackground="#EF4444", padx=10, pady=10)
            f_cons.pack(fill="x")
            tk.Label(f_cons, text="🔴 A MELHORAR", font=("Segoe UI", 9, "bold"), fg="#EF4444", bg="#3B1B1B").pack(anchor="w", pady=(0, 5))

            if total_jogos > 0:
                atributos_ordenados = sorted(radar_data.items(), key=lambda item: item[1], reverse=True)
                for attr, val in atributos_ordenados[:2]:
                    nome_limpo = attr.split("\n")[0].replace("(", "").replace(")", "")
                    tk.Label(f_pros, text=f"+ {nome_limpo}", font=("Segoe UI", 9, "bold"), fg="white", bg="#1B3B2F").pack(anchor="w")
                for attr, val in atributos_ordenados[-2:]:
                    nome_limpo = attr.split("\n")[0].replace("(", "").replace(")", "")
                    tk.Label(f_cons, text=f"- {nome_limpo}", font=("Segoe UI", 9, "bold"), fg="white", bg="#3B1B1B").pack(anchor="w")

            # COLUNA 3: MÉTRICAS DETALHADAS
            f_tech = tk.Frame(mid_grid, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_tech.grid(row=0, column=2, sticky="nsew", padx=(10, 0))
            tk.Label(f_tech, text="MÉTRICAS DETALHADAS", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 15))

            tech_inner = tk.Frame(f_tech, bg=BG_CARD)
            tech_inner.pack(fill="both", expand=True)
            tech_inner.columnconfigure(0, weight=1); tech_inner.columnconfigure(1, weight=1)

            detalhes_kpis = [
                ("xG / JOGO", f"{m_xg:.2f}", "Gols esperados", "#F59E0B"),
                ("xA / JOGO", f"{m_xa:.2f}", "Assists esperadas", "#38BDF8"),
                ("PASSES DECISIVOS", f"{m_passes:.1f}", "Passes p/ finalização", "#38BDF8"),
                ("CHANCES CRIADAS", f"{m_chances:.1f}", "Oportunidades", "#34D399"),
                ("DISTÂNCIA / JOGO", f"{m_distancia:.1f}km", "Média percorrida", "#4ADE80"),
                ("DRIBLES CERTOS", f"{m_dribles:.1f}", "Quebras de marcação", "#F59E0B"),
                ("DESARMES / JOGO", f"{m_desarmes:.1f}", "Bolas recuperadas", "#10B981"),
                ("POSSES GANHAS", f"{m_pos_ganhas:.1f}", "Recuperações p/ jogo", "#10B981"),
                ("POSSES PERDIDAS", f"{m_pos_perdidas:.1f}", "Perdas p/ jogo", "#EF4444"),
                ("FALTAS SOFRIDAS", f"{m_faltas:.1f}", "Faltas no jogador", "#FACC15"),
                ("FALTAS COMETIDAS", f"{m_faltas_c:.1f}", "Infrações cometidas", "#EF4444"),
                ("PRECISÃO PASSE", f"{pct_passes:.1f}%", f"{soma_p_certos} certos", "#0EA5E9")
            ]

            for i, (titulo, val, sub, cor) in enumerate(detalhes_kpis):
                box = tk.Frame(tech_inner, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", padx=10, pady=5)
                box.grid(row=i//2, column=i%2, sticky="nsew", padx=5, pady=5)
                tk.Label(box, text=titulo, font=("Segoe UI", 7, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")
                tk.Label(box, text=val, font=("Segoe UI", 14, "bold"), fg=cor, bg="#252F3D").pack(anchor="w")
                tk.Label(box, text=sub, font=("Segoe UI", 7), fg="#94A3B8", bg="#252F3D").pack(anchor="w")

            # ======================================================================
            # ANDAR 3: GRÁFICO DE LINHA (EVOLUÇÃO DA FORMA)
            # ======================================================================
            f_grafico_notas = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_grafico_notas.pack(fill="x", padx=40, pady=(10, 20))
            
            tk.Label(f_grafico_notas, text="EVOLUÇÃO DA FORMA (Últimos Jogos)", font=("Segoe UI", 14, "bold"), bg=BG_CARD, fg="white").pack(anchor="w", pady=(0, 5))
            tk.Label(f_grafico_notas, text="Flutuação das suas notas ao longo do tempo selecionado.", font=("Segoe UI", 10), bg=BG_CARD, fg=TEXT_SUB).pack(anchor="w", pady=(0, 20))

            if not jogos_grafico_linha:
                tk.Label(f_grafico_notas, text="Nenhum dado de nota disponível para gerar o gráfico.", fg=TEXT_SUB, bg=BG_CARD).pack(pady=30)
            else:
                limite_jogos = jogos_grafico_linha[-15:] if len(jogos_grafico_linha) > 15 else jogos_grafico_linha
                
                notas_plot = []; labels_plot = []; cores_pontos = []
                for j in limite_jogos:
                    try: n = float(j.get("Nota", 6.0))
                    except: n = 6.0
                    notas_plot.append(n)
                    
                    adv_limpo = str(j.get("Adversário", "Adv")).strip()[:3].upper()
                    labels_plot.append(adv_limpo)
                    
                    if n >= 8.0: cores_pontos.append("#4ADE80") 
                    elif n >= 6.5: cores_pontos.append("#FACC15") 
                    else: cores_pontos.append("#EF4444") 

                fig_line, ax_line = plt.subplots(figsize=(10, 3.5), facecolor=BG_CARD)
                self._aplicar_gradiente_fundo(ax_line, cor_topo="#1E3A8A", cor_fundo=BG_CARD) 
                
                x_pos = np.arange(len(notas_plot))
                ax_line.plot(x_pos, notas_plot, color="#38BDF8", linewidth=3, alpha=0.8, zorder=2)
                ax_line.fill_between(x_pos, notas_plot, y2=4.0, color="#38BDF8", alpha=0.15, zorder=1)
                
                for xp, yp, cp in zip(x_pos, notas_plot, cores_pontos):
                    ax_line.scatter(xp, yp, color=cp, s=80, edgecolor="white", linewidth=1.5, zorder=3)
                    ax_line.text(xp, yp + 0.3, f"{yp:.1f}", color="white", fontsize=9, fontweight="bold", ha="center", va="bottom", zorder=4)

                ax_line.set_xticks(x_pos)
                ax_line.set_xticklabels(labels_plot, color="#94A3B8", fontsize=9, fontweight="bold")
                ax_line.set_ylim(min(4.0, min(notas_plot) - 1.0), 10.5) 
                ax_line.spines['top'].set_visible(False); ax_line.spines['right'].set_visible(False)
                ax_line.spines['left'].set_visible(False); ax_line.spines['bottom'].set_color("#475569")
                ax_line.tick_params(axis='y', colors='#94A3B8', labelsize=10)
                ax_line.tick_params(axis='x', colors='#94A3B8', bottom=False)
                ax_line.grid(axis='y', linestyle='--', alpha=0.2, color="white", zorder=0)
                
                ax_line.axhline(y=m_nota, color="#F59E0B", linestyle=":", linewidth=1.5, alpha=0.7, zorder=1)
                ax_line.text(len(notas_plot) - 0.5, m_nota, f"Média ({m_nota:.1f})", color="#F59E0B", fontsize=9, ha="left", va="center")

                plt.tight_layout()
                canvas_line = FigureCanvasTkAgg(fig_line, master=f_grafico_notas)
                canvas_line.draw()
                canvas_line.get_tk_widget().pack(fill="both", expand=True)
                self.fig_tatica.append(fig_line)
                self.matplotlib_canvases.append(canvas_line)

            tk.Frame(dynamic_container, bg=BG_BASE, height=50).pack()

        combo.bind("<<ComboboxSelected>>", atualizar_view)
        atualizar_view()

    def aba_premios_individuais(self, parent_frame):
        from tkinter import Toplevel, messagebox, filedialog
        import datetime
        import shutil
        import os
        from PIL import Image, ImageTk, ImageDraw

        # --- ESTILOS & CORES ---
        BG_BASE = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        ACCENT = "#F59E0B"

        if not hasattr(self, 'premios_individuais'):
            self.premios_individuais = []

        # --- ESTRUTURA PRINCIPAL COM SCROLL ---
        aba_premios = ttk.Frame(parent_frame, style="Custom.TFrame")
        aba_premios.pack(fill="both", expand=True)

        canvas_premios = tk.Canvas(aba_premios, bg=BG_BASE, highlightthickness=0)
        scrollbar_premios = ttk.Scrollbar(aba_premios, orient="vertical", command=canvas_premios.yview)
        
        inner_frame = tk.Frame(canvas_premios, bg=BG_BASE)
        win_id = canvas_premios.create_window((0, 0), window=inner_frame, anchor="nw")
        
        canvas_premios.configure(yscrollcommand=scrollbar_premios.set)
        canvas_premios.pack(side="left", fill="both", expand=True)
        scrollbar_premios.pack(side="right", fill="y")
        
        def _on_resize(event): canvas_premios.itemconfig(win_id, width=event.width)
        canvas_premios.bind("<Configure>", _on_resize)
        def _on_mousewheel(event): canvas_premios.yview_scroll(int(-1*(event.delta/120)), "units")
        canvas_premios.bind_all("<MouseWheel>", _on_mousewheel)
        inner_frame.bind("<Configure>", lambda e: canvas_premios.configure(scrollregion=canvas_premios.bbox("all")))

        # --- CÁLCULO DE KPIs ---
        t_premios = sum(p.get("quantidade", 1) for p in self.premios_individuais)
        t_artilharias = sum(p.get("quantidade", 1) for p in self.premios_individuais if any(x in p.get("tipo", "") for x in ["Artilheiro", "Chuteira", "Líder"]))
        t_mvp = sum(p.get("quantidade", 1) for p in self.premios_individuais if any(x in p.get("tipo", "") for x in ["MVP", "Melhor Jogador", "Ballon", "POTM", "MOTM"]))
        t_tots = sum(p.get("quantidade", 1) for p in self.premios_individuais if any(x in p.get("tipo", "") for x in ["TOTS", "TOTY", "Seleção"]))

        # --- HEADER HERO ---
        hero_frame = tk.Frame(inner_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
        hero_frame.pack(fill="x", padx=40, pady=(30, 20))
        tk.Frame(hero_frame, bg=ACCENT, height=4).pack(side="top", fill="x")

        hero_inner = tk.Frame(hero_frame, bg=BG_CARD)
        hero_inner.pack(fill="both", expand=True, padx=30, pady=20)

        f_title = tk.Frame(hero_inner, bg=BG_CARD)
        f_title.pack(side="left", padx=(0, 40))
        tk.Label(f_title, text="GALERIA DE HONRARIAS", font=("Impact", 36), fg="white", bg=BG_CARD).pack(anchor="w")
        tk.Label(f_title, text="Prêmios individuais, artilharias e reconhecimentos.", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")

        def call_abrir_modal():
            abrir_modal_premio()

        btn_add = tk.Button(f_title, text="➕ CADASTRAR PRÊMIO", bg="#00E676", fg="#064E3B", font=("Segoe UI", 9, "bold"), relief="flat", cursor="hand2", padx=15, pady=8, command=call_abrir_modal)
        btn_add.pack(anchor="w", pady=(15, 0))

        f_kpis = tk.Frame(hero_inner, bg=BG_CARD)
        f_kpis.pack(side="right", expand=True, fill="x")
        for i in range(4): f_kpis.columnconfigure(i, weight=1)

        kpis_lista = [
            ("TOTAL PRÊMIOS", t_premios, "white", "🏆"),
            ("ARTILHARIAS", t_artilharias, "#F59E0B", "⚽"),
            ("MVP / MELHOR", t_mvp, "#A855F7", "⭐"),
            ("SELEÇÃO DO ANO", t_tots, "#38BDF8", "🌟")
        ]

        for i, (lbl, val, cor, icone) in enumerate(kpis_lista):
            box = tk.Frame(f_kpis, bg="#252F3D", highlightthickness=1, highlightbackground="#334155", padx=15, pady=10)
            box.grid(row=0, column=i, sticky="nsew", padx=10)
            tk.Label(box, text=f"{icone} {lbl}", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg="#252F3D").pack(anchor="w")
            tk.Label(box, text=str(val), font=("Segoe UI", 24, "bold"), fg=cor, bg="#252F3D").pack(anchor="w", pady=(5,0))

        # --- FILTROS ---
        ctrl_frame = tk.Frame(inner_frame, bg=BG_BASE)
        ctrl_frame.pack(fill="x", padx=40, pady=(0, 10))
        tk.Label(ctrl_frame, text="FILTRAR POR TIPO:", font=("Segoe UI", 9, "bold"), fg=ACCENT, bg=BG_BASE).pack(anchor="w")
        
        opcoes_filtro = ["Todos", "Artilharias & Gols", "MVP & POTM", "Seleções (TOTS/TOTY)", "Especiais"]
        var_filtro = tk.StringVar(value="Todos")
        combo = ttk.Combobox(ctrl_frame, textvariable=var_filtro, values=opcoes_filtro, state="readonly", width=30, font=("Segoe UI", 10))
        combo.pack(anchor="w", pady=5)

        # --- CONTAINER DA GALERIA ---
        container_galeria = tk.Frame(inner_frame, bg=BG_BASE)
        container_galeria.pack(fill="both", expand=True, padx=40, pady=10)

        if not hasattr(self, 'img_cache_premios'):
            self.img_cache_premios = []

        def atualizar_galeria(event=None):
            for widget in container_galeria.winfo_children(): widget.destroy()
            self.img_cache_premios.clear()

            if not self.premios_individuais:
                tk.Label(container_galeria, text="Nenhum prêmio individual registrado ainda.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_BASE).pack(pady=50)
                return

            # Filtragem
            filtro = var_filtro.get()
            premios_filtrados = []
            for p in self.premios_individuais:
                t = p.get("tipo", "")
                if filtro == "Artilharias & Gols" and not any(x in t for x in ["Artilheiro", "Chuteira", "Líder"]): continue
                if filtro == "MVP & POTM" and not any(x in t for x in ["MVP", "Melhor Jogador", "Ballon", "POTM", "MOTM"]): continue
                if filtro == "Seleções (TOTS/TOTY)" and not any(x in t for x in ["TOTS", "TOTY", "Seleção"]): continue
                if filtro == "Especiais" and not any(x in t for x in ["Puskás", "Golden Boy"]): continue
                premios_filtrados.append(p)

            if not premios_filtrados:
                tk.Label(container_galeria, text="Nenhum prêmio encontrado para este filtro.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_BASE).pack(pady=50)
                return

            cols = max(1, canvas_premios.winfo_width() // 280) if canvas_premios.winfo_width() > 100 else 4
            
            premios_ordenados = sorted(premios_filtrados, key=lambda x: str(x.get('ano', '0')), reverse=True)

            for i, premio in enumerate(premios_ordenados):
                r = i // cols
                c = i % cols
                
                tipo = premio.get("tipo", "Prêmio")
                comp = premio.get("comp", "")
                detalhe = premio.get("detalhe", "")
                ano = premio.get("ano", "")
                img_path = premio.get("imagem", "")
                qtd = premio.get("quantidade", 1)

                cor_borda = "#334155"
                icone = "🏅"
                cor_icone = "white"
                
                if any(x in tipo for x in ["POTM", "MOTM", "Mês"]): cor_borda = "#A855F7"; icone = "📆"; cor_icone = "#A855F7"
                elif any(x in tipo for x in ["TOTS", "TOTY", "Seleção"]): cor_borda = "#38BDF8"; icone = "🌟"; cor_icone = "#38BDF8"
                elif any(x in tipo for x in ["Chuteira", "Artilheiro", "Líder"]): cor_borda = "#F59E0B"; icone = "👟"; cor_icone = "#F59E0B"
                elif "Puskás" in tipo: cor_borda = "#EF4444"; icone = "🔥"; cor_icone = "#EF4444"
                elif "Golden Boy" in tipo: cor_borda = "#10B981"; icone = "👦"; cor_icone = "#10B981"
                elif any(x in tipo for x in ["MVP", "Melhor Jogador", "Ballon"]): cor_borda = "#FACC15"; icone = "👑"; cor_icone = "#FACC15"

                # Card Wrapper (Premium)
                card = tk.Frame(container_galeria, bg="#060B14", highlightthickness=1, highlightbackground=cor_borda, width=250, height=360)
                card.grid(row=r, column=c, padx=15, pady=15, sticky="nsew")
                card.pack_propagate(False)
                
                tk.Frame(card, bg=cor_borda, height=4).pack(side="top", fill="x")

                # Badge Ano e Quantidade
                f_top_card = tk.Frame(card, bg="#060B14")
                f_top_card.pack(fill="x", padx=10, pady=(10, 0))
                tk.Label(f_top_card, text=ano, font=("Impact", 16), fg="white", bg="#060B14").pack(side="left")
                
                if qtd > 1:
                    tk.Label(f_top_card, text=f"x{qtd}", font=("Segoe UI", 10, "bold"), fg="#0F172A", bg=cor_borda, padx=6, pady=2).pack(side="right")

                # Imagem / Emoji Central
                f_img = tk.Frame(card, bg="#060B14", width=120, height=120)
                f_img.pack(pady=15)
                f_img.pack_propagate(False)

                mostrou_imagem = False
                if img_path:
                    path_final = None
                    if os.path.exists(img_path): path_final = img_path
                    elif os.path.exists(os.path.abspath(img_path)): path_final = os.path.abspath(img_path)
                    elif hasattr(self, 'resource_path') and os.path.exists(self.resource_path(img_path)): path_final = self.resource_path(img_path)

                    if path_final:
                        try:
                            pil_img = Image.open(path_final).resize((110, 110), Image.Resampling.LANCZOS)
                            tk_img = ImageTk.PhotoImage(pil_img)
                            self.img_cache_premios.append(tk_img)
                            
                            lbl_imagem_trofeu = tk.Label(f_img, image=tk_img, bg="#060B14")
                            lbl_imagem_trofeu.image = tk_img 
                            lbl_imagem_trofeu.place(relx=0.5, rely=0.5, anchor="center")
                            mostrou_imagem = True
                        except: pass

                if not mostrou_imagem:
                    tk.Canvas(f_img, width=110, height=110, bg="#060B14", highlightthickness=0).place(relx=0.5, rely=0.5, anchor="center")
                    tk.Label(f_img, text=icone, font=("Segoe UI Emoji", 50), bg="#060B14", fg=cor_icone).place(relx=0.5, rely=0.5, anchor="center")

                # Textos Iniciais
                tk.Label(card, text=tipo.upper(), font=("Impact", 16), fg=cor_icone, bg="#060B14", wraplength=210, justify="center").pack(pady=(0, 5))
                
                f_comp = tk.Frame(card, bg="#060B14")
                f_comp.pack(fill="x", pady=(5, 0))
                
                if comp:
                    path_logo = self.club_logo_paths.get(comp, f"Logos/{comp.strip()}.png")
                    if hasattr(self, 'resource_path') and os.path.exists(self.resource_path(path_logo)):
                        try:
                            pil_l = Image.open(self.resource_path(path_logo)).resize((20, 20), Image.Resampling.LANCZOS)
                            tk_l = ImageTk.PhotoImage(pil_l)
                            self.img_cache_premios.append(tk_l)
                            
                            lbl_logo_comp = tk.Label(f_comp, image=tk_l, bg="#060B14")
                            lbl_logo_comp.image = tk_l
                            lbl_logo_comp.pack(side="left", padx=(10, 5))
                        except: pass
                    tk.Label(f_comp, text=comp.upper(), font=("Segoe UI", 9, "bold"), fg="white", bg="#060B14", wraplength=180, justify="left").pack(side="left")

                if detalhe:
                    tk.Label(card, text=detalhe, font=("Segoe UI", 9, "italic"), fg=TEXT_SUB, bg="#060B14", wraplength=210, justify="center").pack(pady=(10, 0))

                # Botões Invisíveis
                f_actions = tk.Frame(card, bg="#060B14")
                f_actions.pack(side="bottom", fill="x", pady=10, padx=15)
                
                def _excluir(idx=i, n=tipo):
                    premio_real = premios_ordenados[idx]
                    qtd_atual = premio_real.get("quantidade", 1)
                    msg = f"Remover 1 unidade de '{n}'?" if qtd_atual > 1 else f"Excluir '{n}' da galeria?"
                    if messagebox.askyesno("Excluir", msg):
                        if premio_real in self.premios_individuais:
                            if qtd_atual > 1: premio_real["quantidade"] = qtd_atual - 1
                            else: self.premios_individuais.remove(premio_real)
                            self.salvar_dados()
                            self.aba_premios_individuais(parent_frame) 

                def _editar(idx=i):
                    premio_real = premios_ordenados[idx]
                    abrir_modal_premio(is_edit=True, premio_edit=premio_real)

                btn_del = tk.Label(f_actions, text="🗑️", font=("Segoe UI", 12), bg="#060B14", fg="#EF4444", cursor="hand2")
                btn_del.pack(side="right", padx=5)
                btn_del.bind("<Button-1>", lambda e, ix=i, n=tipo: _excluir(ix, n))
                
                btn_ed = tk.Label(f_actions, text="✏️", font=("Segoe UI", 12), bg="#060B14", fg="#F59E0B", cursor="hand2")
                btn_ed.pack(side="right", padx=5)
                btn_ed.bind("<Button-1>", lambda e, ix=i: _editar(ix))
                
                tk.Label(f_actions, text="Opções:", font=("Segoe UI", 8), fg="#334155", bg="#060B14").pack(side="left")

                def on_ent(e, c=card, fc=f_top_card, fi=f_img, fco=f_comp, fa=f_actions, q=qtd):
                    try:
                        bg_h = "#1E293B"
                        c.config(bg=bg_h); fc.config(bg=bg_h); fi.config(bg=bg_h); fco.config(bg=bg_h); fa.config(bg=bg_h)
                        for w_parent in [c, fc, fi, fco, fa]:
                            for child in w_parent.winfo_children(): 
                                if isinstance(child, tk.Label):
                                    try: 
                                        if child.cget("text") != f"x{q}": child.config(bg=bg_h)
                                    except: pass
                    except: pass
                
                def on_lea(e, c=card, fc=f_top_card, fi=f_img, fco=f_comp, fa=f_actions, q=qtd):
                    try:
                        bg_n = "#060B14"
                        c.config(bg=bg_n); fc.config(bg=bg_n); fi.config(bg=bg_n); fco.config(bg=bg_n); fa.config(bg=bg_n)
                        for w_parent in [c, fc, fi, fco, fa]:
                            for child in w_parent.winfo_children(): 
                                if isinstance(child, tk.Label):
                                    try: 
                                        if child.cget("text") != f"x{q}": child.config(bg=bg_n)
                                    except: pass
                    except: pass
                
                card.bind("<Enter>", on_ent)
                card.bind("<Leave>", on_lea)

            for col_idx in range(cols): container_galeria.columnconfigure(col_idx, weight=1)

            tk.Frame(container_galeria, bg=BG_BASE, height=50).grid(row=len(premios_ordenados)//cols + 1, column=0)

        combo.bind("<<ComboboxSelected>>", atualizar_galeria)
        atualizar_galeria()

        # --- MODAL ADICIONAR / EDITAR PRÊMIO ---
        def abrir_modal_premio(is_edit=False, premio_edit=None):
            BG_MODAL = "#1F2937"; BG_INPUT = "#111827"; ACCENT_MODAL = "#F59E0B"; BORDER = "#374151"
            
            md = Toplevel(self)
            md.title("Editar Prêmio" if is_edit else "Novo Prêmio")
            md.geometry("450x700") 
            md.configure(bg=BG_MODAL)
            x = (md.winfo_screenwidth() // 2) - 225; y = (md.winfo_screenheight() // 2) - 350
            md.geometry(f"+{x}+{y}"); md.grab_set()

            mf = tk.Frame(md, bg=BG_MODAL)
            mf.pack(fill="both", expand=True, padx=30, pady=20)
            
            tk.Label(mf, text="✏️" if is_edit else "🏆", font=("Segoe UI Emoji", 40), bg=BG_MODAL).pack(pady=(0, 5))
            tk.Label(mf, text="EDITAR PRÊMIO" if is_edit else "NOVO PRÊMIO", font=("Segoe UI", 16, "bold"), fg="white", bg=BG_MODAL).pack()
            tk.Label(mf, text="Atualize os dados da honraria" if is_edit else "Registre um reconhecimento individual", font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_MODAL).pack(pady=(5, 15))

            v_tipo = tk.StringVar(value=premio_edit.get("tipo", "Jogador do Mês (POTM)") if is_edit else "Jogador do Mês (POTM)")
            v_comp = tk.StringVar(value=premio_edit.get("comp", self.informacoes.get("Clube Atual", "")) if is_edit else self.informacoes.get("Clube Atual", "")) 
            v_detalhe = tk.StringVar(value=premio_edit.get("detalhe", "") if is_edit else "")
            
            # --- AQUI ESTÁ A CORREÇÃO: ANO E QUANTIDADE NA MESMA LINHA ---
            v_ano = tk.StringVar(value=str(premio_edit.get("ano", datetime.datetime.now().year)) if is_edit else str(datetime.datetime.now().year))
            v_qtd = tk.StringVar(value=str(premio_edit.get("quantidade", 1)) if is_edit else "1")
            
            v_img = tk.StringVar() 

            def criar_campo(label, var, combo=None):
                tk.Label(mf, text=label.upper(), font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_MODAL).pack(anchor="w", pady=(5, 2))
                if combo: ttk.Combobox(mf, textvariable=var, values=combo, font=("Segoe UI", 11)).pack(fill="x")
                else: tk.Entry(mf, textvariable=var, font=("Segoe UI", 11), bg=BG_INPUT, fg="white", relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

            opcoes_tipo = [
                "Jogador do Mês (POTM)", "Man of the Match (MOTM)", "Chuteira de Ouro (Artilheiro)", "Líder em Assistências",
                "Seleção da Temporada (TOTS)", "Seleção do Ano (TOTY)", 
                "Melhor Jogador do Torneio", "Prêmio Puskás", "Golden Boy", "MVP", "Ballon D'or"
            ]
            
            criar_campo("Tipo de Prêmio", v_tipo, opcoes_tipo)
            criar_campo("Competição (Ex: Premier League)", v_comp, ["Brasileirão Seria A", "Champions League", "Premier League", "Copa do Mundo"])
            criar_campo("Detalhe (Ex: Novembro, 35 Gols)", v_detalhe)
            
            # DIVISÃO DA LINHA PARA ANO E QUANTIDADE
            f_row = tk.Frame(mf, bg=BG_MODAL)
            f_row.pack(fill="x", pady=5)
            f_row.columnconfigure(0, weight=1)
            f_row.columnconfigure(1, weight=1)
            
            f_ano = tk.Frame(f_row, bg=BG_MODAL)
            f_ano.grid(row=0, column=0, sticky="ew", padx=(0, 5))
            tk.Label(f_ano, text="ANO / TEMPORADA", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_MODAL).pack(anchor="w", pady=(0, 2))
            tk.Entry(f_ano, textvariable=v_ano, font=("Segoe UI", 11), bg=BG_INPUT, fg="white", relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)
            
            f_qtd = tk.Frame(f_row, bg=BG_MODAL)
            f_qtd.grid(row=0, column=1, sticky="ew", padx=(5, 0))
            tk.Label(f_qtd, text="QUANTIDADE", font=("Segoe UI", 8, "bold"), fg=TEXT_SUB, bg=BG_MODAL).pack(anchor="w", pady=(0, 2))
            tk.Spinbox(f_qtd, from_=1, to=999, textvariable=v_qtd, font=("Segoe UI", 11), bg=BG_INPUT, fg="white", buttonbackground=BORDER, relief="flat", highlightthickness=1, highlightbackground=BORDER).pack(fill="x", ipady=5)

            # CAMPO DE UPLOAD DE IMAGEM
            tk.Label(mf, text="IMAGEM DO TROFÉU", bg=BG_MODAL, fg=TEXT_SUB, font=("Segoe UI", 8, "bold")).pack(anchor="w", pady=(10,2))
            uf = tk.Frame(mf, bg=BG_INPUT, highlightthickness=1, highlightbackground=BORDER)
            uf.pack(fill="x", ipady=3)
            
            nome_img_antiga = os.path.basename(premio_edit.get("imagem", "")) if is_edit and premio_edit.get("imagem") else "Nenhum arquivo selecionado"
            lb_f = tk.Label(uf, text=nome_img_antiga[:25]+"...", bg=BG_INPUT, fg=TEXT_SUB, font=("Segoe UI", 9, "italic"))
            lb_f.pack(side="left", padx=15)
            
            def escolher_foto():
                p = filedialog.askopenfilename(parent=md, filetypes=[("Images", "*.png *.jpg *.webp")])
                if p: 
                    v_img.set(p)
                    lb_f.config(text=os.path.basename(p)[:25]+"...", fg=ACCENT_MODAL)
            
            tk.Button(uf, text="ESCOLHER", command=escolher_foto, bg="#374151", fg="white", font=("Segoe UI", 8, "bold"), relief="flat", padx=15, pady=5).pack(side="right", padx=5, pady=5)

            def salvar():
                if not v_tipo.get() or not v_ano.get():
                    messagebox.showwarning("Aviso", "Preencha o Tipo e o Ano!", parent=md)
                    return
                
                tipo_val = v_tipo.get()
                comp_val = v_comp.get()
                ano_val = v_ano.get()
                detalhe_val = v_detalhe.get()
                try: qtd_val = int(v_qtd.get())
                except: qtd_val = 1
                
                path_img_salva = premio_edit.get("imagem", "") if is_edit else ""
                imagem_selecionada = v_img.get()
                
                if imagem_selecionada:
                    if not os.path.exists("Premios"): 
                        try: os.makedirs("Premios")
                        except: pass
                    
                    ext = os.path.splitext(imagem_selecionada)[1]
                    safe_name = f"{tipo_val}_{ano_val}_{datetime.datetime.now().strftime('%H%M%S')}".replace(" ", "_").replace("/", "-").replace("\\", "")
                    dest = f"Premios/{safe_name}{ext}"
                    
                    try: 
                        shutil.copy(imagem_selecionada, dest)
                        path_img_salva = dest
                    except Exception as e:
                        print(f"Erro ao copiar imagem do prêmio: {e}")
                        path_img_salva = imagem_selecionada 

                if is_edit:
                    premio_edit["tipo"] = tipo_val
                    premio_edit["comp"] = comp_val
                    premio_edit["ano"] = ano_val
                    premio_edit["detalhe"] = detalhe_val
                    premio_edit["quantidade"] = qtd_val # <--- ATUALIZA A QUANTIDADE AQUI
                    if imagem_selecionada: premio_edit["imagem"] = path_img_salva
                else:
                    existente = False
                    for premio in self.premios_individuais:
                        if premio.get("tipo") == tipo_val and premio.get("comp") == comp_val and str(premio.get("ano")) == str(ano_val):
                            if messagebox.askyesno("Prêmio Duplicado", f"Você já registrou um '{tipo_val}' em {ano_val}.\nDeseja somar +{qtd_val} à quantidade?", parent=md):
                                premio["quantidade"] = premio.get("quantidade", 1) + qtd_val
                                if path_img_salva: premio["imagem"] = path_img_salva
                                if detalhe_val and detalhe_val not in premio.get("detalhe", ""):
                                    if premio.get("detalhe"): premio["detalhe"] += f", {detalhe_val}"
                                    else: premio["detalhe"] = detalhe_val
                                existente = True
                                break
                            else: return 

                    if not existente:
                        novo_premio = {
                            "tipo": tipo_val, "comp": comp_val, "detalhe": detalhe_val, 
                            "ano": ano_val, "imagem": path_img_salva, "quantidade": qtd_val # <--- SALVA A QUANTIDADE INICIAL
                        }
                        self.premios_individuais.append(novo_premio)
                
                self.salvar_dados()
                self.show_toast("Prêmio salvo com sucesso!", "sucesso")
                self.aba_premios_individuais(parent_frame) 
                md.destroy()

            tk.Button(mf, text="SALVAR ALTERAÇÕES" if is_edit else "SALVAR PRÊMIO", command=salvar, bg=ACCENT_MODAL, fg="#0F172A", font=("Segoe UI", 10, "bold"), relief="flat", pady=8, cursor="hand2").pack(fill="x", side="bottom", pady=20)

    def aba_entrosamento(self, parent_frame):
        import tkinter as tk
        from tkinter import ttk
        from PIL import Image, ImageTk, ImageDraw, ImageFont
        import os
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np

        # --- ESTILOS & CORES ---
        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        COLOR_REC = "#10B981"  # Verde (Recebidas / Garçons)
        COLOR_DAD = "#38BDF8"  # Azul Ciano (Dadas / Vítimas)
        ACCENT_PURPLE = "#A855F7"
        COLOR_GOLD = "#F59E0B"

        self.style.configure("EntMain.TFrame", background=BG_DARK)
        self.style.configure("EntCard.TFrame", background=BG_CARD, relief="solid", borderwidth=1, bordercolor="#334155")

        aba_ent = ttk.Frame(parent_frame, style="EntMain.TFrame")
        aba_ent.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_ent, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_ent, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="EntMain.TFrame")
        
        win_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        def _resize(e): canvas.itemconfig(win_id, width=e.width)
        canvas.bind("<Configure>", _resize)
        def _scroll(e): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))

        if not hasattr(self, 'cache_entrosamento'): self.cache_entrosamento = []

        def obter_avatar(nome_jogador, tamanho=50, cor_borda="#38BDF8"):
            nome_safe = nome_jogador.strip().replace(".", "").replace(" ", "_")
            caminho = resource_path(f"Faces/Face Players/{nome_safe}.png")
            try:
                if os.path.exists(caminho):
                    pil_img = Image.open(caminho).convert("RGBA").resize((tamanho, tamanho), Image.Resampling.LANCZOS)
                else:
                    pil_img = self._ps_avatar_pil(nome_jogador, tamanho)
                
                mask = Image.new("L", (tamanho, tamanho), 0)
                ImageDraw.Draw(mask).ellipse((2, 2, tamanho-2, tamanho-2), fill=255)
                comp = Image.new("RGBA", (tamanho, tamanho), (0,0,0,0))
                comp.paste(pil_img, (0,0), mask)
                ImageDraw.Draw(comp).ellipse((1, 1, tamanho-1, tamanho-1), outline=cor_borda, width=2)
                tk_img = ImageTk.PhotoImage(comp)
                self.cache_entrosamento.append(tk_img)
                return tk_img
            except: return None

        # --- HEADER ---
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="CONEXÕES EM CAMPO", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="Mapeamento de entrosamento: a química do elenco, quem te serve e quem consagra seus passes.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # Filtro
        ctrl_frame = tk.Frame(inner, bg=BG_DARK)
        ctrl_frame.pack(fill="x", padx=40, pady=(10, 10))
        opcoes_ano = ["Todas as Temporadas"] + sorted(list(getattr(self, 'dados_jogador', {}).keys()), reverse=True)
        selected_season = tk.StringVar(value=opcoes_ano[0])
        
        tk.Label(ctrl_frame, text="FILTRAR POR TEMPORADA:", font=("Segoe UI", 9, "bold"), fg=COLOR_GOLD, bg=BG_DARK).pack(side="left", padx=(0, 10))
        ttk.Combobox(ctrl_frame, textvariable=selected_season, values=opcoes_ano, state="readonly", width=30).pack(side="left")

        dynamic_container = tk.Frame(inner, bg=BG_DARK)
        dynamic_container.pack(fill="both", expand=True)

        if not hasattr(self, 'fig_entrosamento'): self.fig_entrosamento = []

        def atualizar_view(event=None):
            for f in self.fig_entrosamento: plt.close(f)
            self.fig_entrosamento.clear()
            for widget in dynamic_container.winfo_children(): widget.destroy()
            self.cache_entrosamento.clear()
            
            filtro = selected_season.get()

            # --- PROCESSAMENTO AGREGADO (Dadas vs Recebidas) ---
            parceiros = {} # Dicionário mestre: {Nome: {'rec': 0, 'dad': 0, 'tot': 0}}
            
            for jogo in self.ultimas_performances:
                if filtro != "Todas as Temporadas" and self._inferir_temporada(jogo.get("Data", "")) != filtro: 
                    continue
                
                det = jogo.get("Detalhes", {})
                rec_str = det.get("AssistRecebidaDe", "").strip()
                dad_str = det.get("AssistDadaPara", "").strip()
                
                if rec_str:
                    for n in [x.strip().title() for x in rec_str.split(",") if x.strip()]:
                        if n not in parceiros: parceiros[n] = {'rec': 0, 'dad': 0, 'tot': 0}
                        parceiros[n]['rec'] += 1
                        parceiros[n]['tot'] += 1
                        
                if dad_str:
                    for n in [x.strip().title() for x in dad_str.split(",") if x.strip()]:
                        if n not in parceiros: parceiros[n] = {'rec': 0, 'dad': 0, 'tot': 0}
                        parceiros[n]['dad'] += 1
                        parceiros[n]['tot'] += 1

            if not parceiros:
                tk.Label(dynamic_container, text="Nenhum dado de entrosamento (passes/assistências) registrado neste período.", font=("Segoe UI", 12), fg=TEXT_SUB, bg=BG_DARK).pack(pady=50)
                return

            # Ordenações Específicas
            top_recebidas = sorted([(n, d['rec']) for n, d in parceiros.items() if d['rec'] > 0], key=lambda x: x[1], reverse=True)[:5]
            top_dadas = sorted([(n, d['dad']) for n, d in parceiros.items() if d['dad'] > 0], key=lambda x: x[1], reverse=True)[:5]
            top_absoluto = sorted([(n, d) for n, d in parceiros.items()], key=lambda x: x[1]['tot'], reverse=True)

            meu_n = self.informacoes.get("Nome Completo", "Você").split()[0].upper()

            # ==================================================================
            # 1. HERO CARD: O TRIO DE OURO (MSN/BBC FACTOR)
            # ==================================================================
            hero_frame = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground=COLOR_GOLD)
            hero_frame.pack(fill="x", padx=40, pady=20, ipady=15)
            
            tk.Label(hero_frame, text="👑 O TRIO DE OURO DO ELENCO", font=("Segoe UI", 10, "bold"), fg=COLOR_GOLD, bg=BG_CARD).pack(pady=(15, 10))
            
            f_faces = tk.Frame(hero_frame, bg=BG_CARD)
            f_faces.pack(expand=True)
            
            # Pega o Top 1 e Top 2 para formar o trio com você
            parceiro_1 = top_absoluto[0][0] if len(top_absoluto) > 0 else "Ninguém"
            val_p1 = top_absoluto[0][1]['tot'] if len(top_absoluto) > 0 else 0
            
            parceiro_2 = top_absoluto[1][0] if len(top_absoluto) > 1 else "Ninguém"
            val_p2 = top_absoluto[1][1]['tot'] if len(top_absoluto) > 1 else 0
            
            # Desenha as faces (Você no meio)
            if parceiro_2 != "Ninguém":
                tk.Label(f_faces, image=obter_avatar(parceiro_2, 70, "#94A3B8"), bg=BG_CARD).pack(side="left", padx=15)
            
            tk.Label(f_faces, image=obter_avatar(meu_n, 100, COLOR_GOLD), bg=BG_CARD).pack(side="left", padx=25)
            
            if parceiro_1 != "Ninguém":
                tk.Label(f_faces, image=obter_avatar(parceiro_1, 70, "#94A3B8"), bg=BG_CARD).pack(side="left", padx=15)
            
            txt_trio = f"{parceiro_2.upper()}  •  {meu_n}  •  {parceiro_1.upper()}" if parceiro_2 != "Ninguém" else f"{meu_n}  •  {parceiro_1.upper()}"
            tk.Label(hero_frame, text=txt_trio, font=("Impact", 28), fg="white", bg=BG_CARD).pack(pady=(15, 0))
            tk.Label(hero_frame, text=f"Total combinado de {val_p1 + val_p2} conexões diretas para o gol.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_CARD).pack(pady=(0, 10))

            # ==================================================================
            # 2. GRÁFICO: A TEIA DE CONEXÕES (Dadas vs Recebidas)
            # ==================================================================
            f_grafico = tk.Frame(dynamic_container, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=20)
            f_grafico.pack(fill="both", expand=True, padx=40, pady=(0, 20))
            
            tk.Label(f_grafico, text="📊 BALANÇO DE ENTROSAMENTO (TOP 5 PARCEIROS)", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 15))

            if len(top_absoluto) > 0:
                fig_bar, ax_bar = plt.subplots(figsize=(10, 3.5), facecolor=BG_CARD)
                self._aplicar_gradiente_fundo(ax_bar, cor_topo="#1E3A8A", cor_fundo=BG_CARD)

                top_5 = top_absoluto[:5]
                labels_bar = [n[:12] + "." if len(n) > 12 else n for n, d in top_5]
                val_rec = [d['rec'] for n, d in top_5]
                val_dad = [d['dad'] for n, d in top_5]

                x = np.arange(len(labels_bar))
                width = 0.35

                # Barras lado a lado
                rects1 = ax_bar.bar(x - width/2, val_rec, width, label='Você Recebeu (Gols Seus)', color=COLOR_REC, edgecolor="white", linewidth=1, zorder=3)
                rects2 = ax_bar.bar(x + width/2, val_dad, width, label='Você Tocou (Gols Deles)', color=COLOR_DAD, edgecolor="white", linewidth=1, zorder=3)

                ax_bar.set_xticks(x)
                ax_bar.set_xticklabels(labels_bar, color="white", fontsize=10, fontweight="bold")
                
                # Valores em cima das barras
                def autolabel(rects, color_text):
                    for rect in rects:
                        height = rect.get_height()
                        if height > 0:
                            ax_bar.annotate(f'{height}', xy=(rect.get_x() + rect.get_width() / 2, height),
                                        xytext=(0, 3), textcoords="offset points", ha='center', va='bottom',
                                        fontsize=9, fontweight='bold', color=color_text, zorder=4)
                
                autolabel(rects1, COLOR_REC)
                autolabel(rects2, COLOR_DAD)

                ax_bar.spines['top'].set_visible(False); ax_bar.spines['right'].set_visible(False)
                ax_bar.spines['left'].set_visible(False); ax_bar.spines['bottom'].set_color("#475569")
                ax_bar.tick_params(axis='y', colors=TEXT_SUB, labelsize=9)
                ax_bar.grid(axis='y', linestyle='--', alpha=0.2, color="white", zorder=0)

                legend = ax_bar.legend(loc='upper right', frameon=False, ncol=2)
                for text in legend.get_texts(): text.set_color("white")

                plt.tight_layout()
                canvas_bar = FigureCanvasTkAgg(fig_bar, master=f_grafico)
                canvas_bar.draw()
                canvas_bar.get_tk_widget().pack(fill="both", expand=True)
                self.fig_entrosamento.append(fig_bar)
                self.matplotlib_canvases.append(canvas_bar)

            # ==================================================================
            # 3. TABELAS DE ANÁLISE (3 COLUNAS)
            # ==================================================================
            tables_grid = tk.Frame(dynamic_container, bg=BG_DARK)
            tables_grid.pack(fill="both", expand=True, padx=40)
            tables_grid.columnconfigure(0, weight=1); tables_grid.columnconfigure(1, weight=1); tables_grid.columnconfigure(2, weight=1)

            # Tabela Genérica Reutilizável
            def criar_tabela(parent, titulo, dados, cor, icone, col_idx, is_balanca=False):
                frame = tk.Frame(parent, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
                frame.grid(row=0, column=col_idx, sticky="nsew", padx=10, pady=10)
                
                header_t = tk.Frame(frame, bg="#252F3D", height=45)
                header_t.pack(fill="x")
                header_t.pack_propagate(False)
                tk.Frame(header_t, bg=cor, width=4).pack(side="left", fill="y")
                tk.Label(header_t, text=f"{icone} {titulo}", font=("Segoe UI", 10, "bold"), fg="white", bg="#252F3D").pack(side="left", padx=15)

                if not dados:
                    tk.Label(frame, text="Sem registros suficientes.", fg=TEXT_SUB, bg=BG_CARD, pady=40).pack()
                    return

                for i, dado in enumerate(dados[:5]):
                    row = tk.Frame(frame, bg=BG_CARD, height=50)
                    row.pack(fill="x", padx=15)
                    row.pack_propagate(False)
                    
                    if is_balanca:
                        nome, stats = dado
                        diff = stats['dad'] - stats['rec']
                        
                        f_n = tk.Frame(row, bg=BG_CARD); f_n.place(relx=0.0, rely=0.5, anchor="w")
                        tk.Label(f_n, image=obter_avatar(nome, 30, cor), bg=BG_CARD).pack(side="left", padx=(0, 5))
                        tk.Label(f_n, text=nome[:12].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg=BG_CARD).pack(side="left")
                        
                        # Análise de Balança
                        if diff > 0: txt_s = "Servidor"; cor_s = COLOR_DAD; val_s = f"+{diff} passes"
                        elif diff < 0: txt_s = "Finalizador"; cor_s = COLOR_REC; val_s = f"+{abs(diff)} rec."
                        else: txt_s = "Equilíbrio"; cor_s = "#F59E0B"; val_s = "Perfeito"
                        
                        f_s = tk.Frame(row, bg=BG_CARD); f_s.place(relx=0.95, rely=0.5, anchor="e")
                        tk.Label(f_s, text=txt_s, font=("Segoe UI", 8), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="e")
                        tk.Label(f_s, text=val_s, font=("Segoe UI", 10, "bold"), fg=cor_s, bg=BG_CARD).pack(anchor="e")
                        
                    else:
                        nome, val = dado
                        f_n = tk.Frame(row, bg=BG_CARD); f_n.place(relx=0.0, rely=0.5, anchor="w")
                        tk.Label(f_n, text=f"#{i+1}", font=("Segoe UI", 8, "bold"), fg=cor, bg=BG_CARD, width=3).pack(side="left")
                        tk.Label(f_n, image=obter_avatar(nome, 30, cor), bg=BG_CARD).pack(side="left", padx=5)
                        tk.Label(f_n, text=nome[:12].upper(), font=("Segoe UI", 9, "bold"), fg="white", bg=BG_CARD).pack(side="left")
                        
                        tk.Label(row, text=str(val), font=("Impact", 14), fg=cor, bg=BG_CARD).place(relx=0.95, rely=0.5, anchor="e")
                    
                    if i < len(dados)-1 and i < 4: tk.Frame(frame, bg="#334155", height=1).pack(fill="x", padx=15)

            criar_tabela(tables_grid, "SEUS GARÇONS", top_recebidas, COLOR_REC, "🎁", 0)
            criar_tabela(tables_grid, "SUAS VÍTIMAS", top_dadas, COLOR_DAD, "🎯", 1)
            
            # A Balança: Ordena pela diferença de tratamento (maior saldo de passes dadas)
            balanca_dados = sorted([(n, d) for n, d in parceiros.items()], key=lambda x: (x[1]['dad'] - x[1]['rec']), reverse=True)
            criar_tabela(tables_grid, "A BALANÇA (PERFIL)", balanca_dados, ACCENT_PURPLE, "⚖️", 2, is_balanca=True)

            tk.Frame(dynamic_container, bg=BG_DARK, height=50).pack()

        selected_season.trace_add("write", lambda *args: atualizar_view())
        atualizar_view()

    def aba_marcos_metas(self, parent_frame):
        import tkinter as tk
        from tkinter import ttk
        import re

        # --- ESTILOS & CORES ---
        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"

        self.style.configure("MilestoneMain.TFrame", background=BG_DARK)

        aba_metas = ttk.Frame(parent_frame, style="MilestoneMain.TFrame")
        aba_metas.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_metas, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_metas, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="MilestoneMain.TFrame")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        canvas.create_window((0, 0), window=inner, anchor="nw")
        
        def _resize(e): canvas.itemconfig(canvas.find_all()[0], width=e.width)
        canvas.bind("<Configure>", _resize)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind_all("<MouseWheel>", lambda e: canvas.yview_scroll(int(-1*(e.delta/120)), "units"))

        # ======================================================================
        # 1. MOTOR DE CÁLCULO DE DADOS (Extração Profunda)
        # ======================================================================
        t_jogos = sum(row[1] for row in self.dados_desempenho)
        t_gols = sum(row[2] for row in self.dados_desempenho)
        t_assis = sum(row[3] for row in self.dados_desempenho)
        t_ga = t_gols + t_assis
        
        # Variáveis Complexas
        hat_tricks = 0
        gols_apos_85 = 0
        gols_virada = 0
        gols_finais = 0
        gols_cabeca = 0
        gols_falta = 0
        dribles = 0
        passes_dec = 0
        dia_perfeito = 0
        seq_demonio = 0; max_seq_demonio = 0
        gols_por_adv = {}
        gols_ex_clube = 0
        
        # Mapear Ex-Clubes para a "Lei do Ex"
        ex_clubes = set()
        if hasattr(self, 'historico_transferencias'):
            for t in self.historico_transferencias:
                if t["De"].upper() not in ["BASE/FREE AGENT", "BASE / FREE AGENT", "DESCONHECIDO"]:
                    ex_clubes.add(t["De"].upper())
                ex_clubes.add(t["Para"].upper())
        clube_atual = self.informacoes.get("Clube Atual", "").upper()
        if clube_atual in ex_clubes: ex_clubes.remove(clube_atual)

        # Analisar Partidas Históricas
        performances_cronologicas = list(reversed(getattr(self, 'ultimas_performances', [])))
        status_ausente = ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]
        
        for jogo in performances_cronologicas:
            try:
                g = int(jogo.get("Gols", 0))
                a = int(jogo.get("Assistências", 0))
                n = float(jogo.get("Nota", 6.0))
                mins = int(jogo.get("Minutos", 90))
                adv = jogo.get("Adversário", "Desconhecido").upper()
                rodada = str(jogo.get("Rodada", "")).upper()
                det = jogo.get("Detalhes", {})
                pos = jogo.get("Posição", "MEI")
                
                if mins > 0 and pos not in status_ausente:
                    if g >= 3: hat_tricks += 1
                    if det.get("GolVirada"): gols_virada += 1
                    
                    min_jog_str = str(det.get("MinutosGolsJogador", ""))
                    mins_g = [int(m) for m in re.findall(r'\d+', min_jog_str)]
                    gols_apos_85 += sum(1 for m in mins_g if m >= 85)
                    
                    if "FINAL" in rodada and g > 0: gols_finais += g
                    gols_cabeca += int(det.get("Cabeca", 0))
                    gols_falta += int(det.get("FaltasGol", 0))
                    dribles += int(det.get("DriblesCertos", 0))
                    passes_dec += int(det.get("PassesDecisivos", 0)) + int(det.get("ChancesCriadas", 0))
                    
                    # Dia Perfeito: Gol + Assist + Nota >= 9.0
                    if g >= 1 and a >= 1 and n >= 9.0: dia_perfeito += 1
                    
                    # Modo Demônio: 3 jogos seguidos com Gol E Assistência
                    if g > 0 and a > 0: seq_demonio += 1
                    else: seq_demonio = 0
                    max_seq_demonio = max(max_seq_demonio, seq_demonio)
                    
                    gols_por_adv[adv] = gols_por_adv.get(adv, 0) + g
                    if adv in ex_clubes and g > 0: gols_ex_clube += g
            except: pass

        carrascos = sum(1 for v in gols_por_adv.values() if v >= 10)
        
        # Picos por Temporada
        max_gols_temp = 0; max_ass_temp = 0; max_ga_temp = 0; media_max_temp = 0.0
        for temp, dados in getattr(self, 'dados_jogador', {}).items():
             gt = dados.get("gols", 0); at = dados.get("assistencias", 0); jt = dados.get("jogos", 0)
             max_gols_temp = max(max_gols_temp, gt)
             max_ass_temp = max(max_ass_temp, at)
             max_ga_temp = max(max_ga_temp, gt + at)
             if jt > 0:
                 # Simula a média da temporada puxando do G/A
                 md = (gt * 0.15) + (at * 0.1) + 6.5 # Ponderação simulada para bater metas
                 if md > media_max_temp: media_max_temp = md

        # Títulos e Prêmios
        t_titulos = sum(int(item[4]) for item in getattr(self, 'conquistas', []))
        tem_titulo = t_titulos > 0
        tem_champions = any(any(x in t[1].upper() for x in ["CHAMPIONS", "LIBERTADORES", "MUNDIAL"]) for t in getattr(self, 'conquistas', []))
        
        meu_nome = self.informacoes.get("Nome Completo", "").lower()
        tem_bdo = sum(1 for b in getattr(self, 'ballondor_custom', []) if meu_nome in b['nome'].lower() or b['nome'].lower() in meu_nome) > 0
        
        tem_artilheiro = any(any(x in p.get("tipo", "").upper() for x in ["ARTILHEIRO", "CHUTEIRA"]) for p in getattr(self, 'premios_individuais', []))
        tem_garcom = any("ASSIST" in p.get("tipo", "").upper() for p in getattr(self, 'premios_individuais', []))
        
        # Lógica de Doblete/Triplete (Agrupamento por Ano)
        anos_titulos = {}
        for t in getattr(self, 'conquistas', []):
            anos = [x.strip() for x in str(t[2]).replace("Temp", "").split(",")]
            for ano in anos:
                if ano: anos_titulos[ano] = anos_titulos.get(ano, 0) + int(t[4])
                
        tem_doblete = any(v >= 2 for v in anos_titulos.values())
        tem_triplete = any(v >= 3 for v in anos_titulos.values())

        # ======================================================================
        # RENDERIZAÇÃO DA TELA
        # ======================================================================
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="METAS & PROGRESSÃO", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="O sistema de conquistas da sua carreira. Desbloqueie marcos e alcance o status de Lenda.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # --- SEÇÃO 1: PROGRESSÃO DE CARREIRA (Tiers RPG) ---
        def calcular_tier(valor_atual, patamares, titulos_tier):
            nivel = 1; alvo = patamares[-1] + 100; titulo = titulos_tier[-1]
            for i, p in enumerate(patamares):
                if valor_atual < p:
                    alvo = p; nivel = i + 1; titulo = titulos_tier[i]
                    break
            else:
                alvo = ((valor_atual // 100) + 1) * 100; nivel = len(patamares) + 1; titulo = "Lenda Suprema (Max)"
            pct = min(1.0, valor_atual / alvo)
            return alvo, nivel, titulo, pct

        esc_gols = [10, 50, 100, 200, 500]; tit_gols = ["Rookie Promissor", "Artilheiro Nato", "Predador de Área", "Ícone Mundial", "GOAT 🐐"]
        esc_ass = [10, 50, 100, 200, 300]; tit_ass = ["Visão de Jogo", "Garçom do Time", "Maestro", "Rei da Assistência", "Deus da Criação"]
        esc_jog = [50, 100, 250, 500, 800]; tit_jog = ["Ganhando Espaço", "Titular Absoluto", "Veterano Respeitado", "Lenda do Clube", "Mito Intocável"]
        esc_ga = [25, 100, 250, 500, 1000]; tit_ga = ["Fazendo Barulho", "Decisivo", "Estrela do Time", "Craque Geracional", "Dono do Jogo"]

        rpg_metas = [
            ("GOLS NA CARREIRA", t_gols, esc_gols, tit_gols, "#4ADE80", "⚽"),
            ("ASSISTÊNCIAS", t_assis, esc_ass, tit_ass, "#38BDF8", "🤝"),
            ("PARTIDAS JOGADAS", t_jogos, esc_jog, tit_jog, "#FACC15", "👕"),
            ("PARTICIPAÇÕES (G+A)", t_ga, esc_ga, tit_ga, "#A855F7", "🔥")
        ]

        tk.Label(inner, text="🌟 A JORNADA DO HERÓI", font=("Impact", 20), fg="#F59E0B", bg=BG_DARK).pack(anchor="w", padx=40, pady=(10, 5))
        
        grid_rpg = tk.Frame(inner, bg=BG_DARK)
        grid_rpg.pack(fill="x", padx=30, pady=(0, 20))
        for i in range(2): grid_rpg.columnconfigure(i, weight=1)

        for i, (categoria, atual, esc, tits, cor, icone) in enumerate(rpg_metas):
            alvo, nivel, nome_meta, pct = calcular_tier(atual, esc, tits)
            
            card = tk.Frame(grid_rpg, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155", padx=20, pady=15)
            card.grid(row=i//2, column=i%2, sticky="nsew", padx=10, pady=10)
            
            f_top = tk.Frame(card, bg=BG_CARD)
            f_top.pack(fill="x", pady=(0, 10))
            tk.Label(f_top, text=icone, font=("Segoe UI Emoji", 24), bg=BG_CARD).pack(side="left", padx=(0, 10))
            
            f_txt = tk.Frame(f_top, bg=BG_CARD)
            f_txt.pack(side="left", fill="x", expand=True)
            tk.Label(f_txt, text=f"NÍVEL {nivel}: {nome_meta.upper()}", font=("Segoe UI", 8, "bold"), fg="#1E293B", bg=cor, padx=5, pady=2).pack(anchor="w", pady=(0, 2))
            tk.Label(f_txt, text=categoria, font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w")
            
            f_bar = tk.Frame(card, bg="#0F172A", height=12)
            f_bar.pack(fill="x", pady=(5, 5)); f_bar.pack_propagate(False)
            tk.Frame(f_bar, bg=cor).place(relx=0, rely=0, relwidth=pct if pct > 0 else 0.02, relheight=1)
            
            f_bot = tk.Frame(card, bg=BG_CARD)
            f_bot.pack(fill="x")
            tk.Label(f_bot, text=f"{int(pct*100)}%", font=("Segoe UI", 10, "bold"), fg=cor, bg=BG_CARD).pack(side="left")
            tk.Label(f_bot, text=f"{atual} / {alvo}", font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(side="right")

        # --- MOTOR DE BADGES (TROFÉUS) ---
        def criar_grid_badges(titulo, subtitulo, icone_sec, cor_sec, lista_desafios):
            sec = tk.Frame(inner, bg=BG_DARK)
            sec.pack(fill="x", padx=40, pady=(20, 0))
            tk.Label(sec, text=f"{icone_sec} {titulo}", font=("Impact", 20), fg=cor_sec, bg=BG_DARK).pack(anchor="w")
            tk.Label(sec, text=subtitulo, font=("Segoe UI", 10, "italic"), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w", pady=(0, 10))
            
            grid = tk.Frame(inner, bg=BG_DARK)
            grid.pack(fill="x", padx=30)
            for i in range(3): grid.columnconfigure(i, weight=1)
            
            for i, d in enumerate(lista_desafios):
                titulo_d, desc_d, atingido, atual, alvo, icone_d, cor_d = d
                
                # Se não atingiu, fica "apagado"
                bg_card = BG_CARD if atingido else "#111827"
                borda_card = cor_d if atingido else "#334155"
                cor_txt_tit = cor_d if atingido else "#64748B"
                cor_txt_desc = "white" if atingido else "#475569"
                
                f = tk.Frame(grid, bg=bg_card, highlightthickness=1, highlightbackground=borda_card, padx=15, pady=15)
                f.grid(row=i//3, column=i%3, sticky="nsew", padx=10, pady=10)
                
                f_head = tk.Frame(f, bg=bg_card)
                f_head.pack(fill="x", pady=(0, 5))
                tk.Label(f_head, text=icone_d, font=("Segoe UI Emoji", 16), bg=bg_card, fg=cor_txt_tit).pack(side="left", padx=(0, 8))
                tk.Label(f_head, text=titulo_d.upper(), font=("Segoe UI", 10, "bold"), fg=cor_txt_tit, bg=bg_card).pack(side="left")
                
                tk.Label(f, text=desc_d, font=("Segoe UI", 9), fg=cor_txt_desc, bg=bg_card, wraplength=200, justify="left").pack(anchor="w", pady=(0, 10))
                
                if not atingido and alvo > 1:
                    # Barra de progresso do desafio
                    f_bar = tk.Frame(f, bg="#0F172A", height=6)
                    f_bar.pack(fill="x", pady=(5, 5)); f_bar.pack_propagate(False)
                    pct = min(1.0, atual / alvo)
                    tk.Frame(f_bar, bg="#475569").place(relx=0, rely=0, relwidth=pct if pct>0 else 0.05, relheight=1)
                    tk.Label(f, text=f"Progresso: {atual}/{alvo}", font=("Segoe UI", 8, "bold"), fg="#64748B", bg=bg_card).pack(anchor="e")
                elif atingido:
                    tk.Label(f, text="DESBLOQUEADO", font=("Segoe UI", 8, "bold"), fg="#1E293B", bg=cor_d, padx=5).pack(anchor="e")
                else:
                    tk.Label(f, text="BLOQUEADO", font=("Segoe UI", 8, "bold"), fg="#334155", bg=bg_card).pack(anchor="e")

                # Hover 
                def on_ent(e, c=f, a=atingido, cd=cor_d, bc=bg_card): 
                    if a: c.config(bg="#252F3D")
                    else: c.config(highlightbackground=cd)
                def on_lea(e, c=f, a=atingido, cd=cor_d, bc=bg_card): 
                    if a: c.config(bg=bc)
                    else: c.config(highlightbackground="#334155")
                f.bind("<Enter>", on_ent); f.bind("<Leave>", on_lea)

        # --- LISTAS DE DESAFIOS ---
        # (Titulo, Desc, Unlocked?, Atual, Alvo, Icone, Cor)
        
        metas_temporada = [
            ("A Máquina de Gols", "Marque 30+ gols em uma única temporada.", max_gols_temp >= 30, max_gols_temp, 30, "⚽", "#4ADE80"),
            ("O Rei das Assistências", "Dê 20+ assistências em uma única temporada.", max_ass_temp >= 20, max_ass_temp, 20, "🤝", "#38BDF8"),
            ("Ameaça Dupla", "Alcançe 50+ participações em gol na temporada.", max_ga_temp >= 50, max_ga_temp, 50, "🔥", "#F59E0B"),
            ("Chuteira Dourada", "Ganhe o prêmio de Artilheiro de uma competição.", tem_artilheiro, 1 if tem_artilheiro else 0, 1, "👟", "#FACC15"),
            ("Mãozinha Amiga", "Ganhe o prêmio de Líder em Assistências.", tem_garcom, 1 if tem_garcom else 0, 1, "🎁", "#60A5FA"),
            ("Alta Classe", "Termine uma temporada com nota média superior a 8.0.", media_max_temp >= 8.0, media_max_temp, 8.0, "⭐", "#A855F7")
        ]
        criar_grid_badges("METAS DE TEMPORADA", "Os grandes objetivos para provar que você domina um ano de futebol.", "📅", "#38BDF8", metas_temporada)

        conquistas_grandes = [
            ("O Primeiro Troféu", "Erga a sua primeira taça como profissional.", tem_titulo, 1 if tem_titulo else 0, 1, "🏆", "#FFD700"),
            ("Doblete Nacional", "Vença a Liga e a Copa no mesmo ano.", tem_doblete, 1 if tem_doblete else 0, 1, "🏅", "#F59E0B"),
            ("Triplete Histórico", "Conquiste 3 grandes títulos na mesma temporada.", tem_triplete, 1 if tem_triplete else 0, 1, "👑", "#A855F7"),
            ("Rei da Europa/América", "Vença a Champions, Libertadores ou Mundial.", tem_champions, 1 if tem_champions else 0, 1, "🌎", "#10B981"),
            ("Decisivo", "Marque pelo menos um gol em uma Final.", gols_finais > 0, gols_finais, 1, "🎯", "#EF4444"),
            ("Ballon d'Or", "Seja eleito o Melhor Jogador do Mundo.", tem_bdo, 1 if tem_bdo else 0, 1, "✨", "#FFD700")
        ]
        criar_grid_badges("CONQUISTAS GRANDES", "As marcas que separam os bons jogadores das lendas eternas.", "🏛️", "#F59E0B", conquistas_grandes)

        metas_clutch = [
            ("Ice Cold 🥶", "Marque 5 gols cruciais após os 85 minutos.", gols_apos_85 >= 5, gols_apos_85, 5, "❄️", "#38BDF8"),
            ("Herói Improvável", "Faça 10 gols que sacramentaram a virada do time.", gols_virada >= 10, gols_virada, 10, "🦸", "#EF4444"),
            ("A Bola Me Procura", "Faça 10+ Hat-tricks na carreira.", hat_tricks >= 10, hat_tricks, 10, "🎩", "#4ADE80"),
            ("Franco-Atirador", "Marque 15 gols de falta direta.", gols_falta >= 15, gols_falta, 15, "🏹", "#F59E0B"),
            ("Subindo no 3º Andar", "Marque 25 gols de cabeça.", gols_cabeca >= 25, gols_cabeca, 25, "🦅", "#A855F7"),
            ("Liso Demais", "Chegue a 100 dribles desconcertantes.", dribles >= 100, dribles, 100, "🌪️", "#10B981")
        ]
        criar_grid_badges("MOMENTOS CLUTCH & ESTILO", "Características que definem a sua personalidade em campo.", "⚡", "#EF4444", metas_clutch)

        metas_diferentonas = [
            ("Lei do Ex", "Marque um gol contra um clube que você já jogou.", gols_ex_clube > 0, gols_ex_clube, 1, "💔", "#EF4444"),
            ("O Carrasco", "Marque 10 ou mais gols contra um mesmo time.", carrascos > 0, carrascos, 1, "☠️", "#10B981"),
            ("Dia Perfeito", "Faça Gol + Assistência + Nota 9.0+ no mesmo jogo.", dia_perfeito > 0, dia_perfeito, 1, "💎", "#F59E0B"),
            ("Modo Demônio", "Faça Gol e Assistência em 3 jogos SEGUIDOS.", max_seq_demonio >= 3, max_seq_demonio, 3, "😈", "#A855F7"),
            ("Quebrando a Banca", "Transfira-se por mais de 50 Milhões.", max(t.get("Valor", "0").count("M") and float(t.get("Valor", "0").replace("€", "").replace("M", "").replace(",", ".")) or 0 for t in getattr(self, 'historico_transferencias', [])) >= 50, 1, 1, "💰", "#4ADE80"),
            ("Lealdade", "Jogue 250 partidas pelo mesmo clube.", any(v.get('jogos', 0) >= 250 for v in getattr(self, 'dados_desempenho_por_clubes', {}).values()), 1, 1, "🛡️", "#38BDF8")
        ]
        criar_grid_badges("METAS DIFERENTONAS", "Objetivos secretos, curiosos e difíceis de bater.", "👽", "#A855F7", metas_diferentonas)

        tk.Frame(inner, bg=BG_DARK, height=60).pack()

    def gerar_imagem_card(self):
        """Gera um Card estilo Ultimate Team em PNG para compartilhar."""
        from tkinter import filedialog, messagebox
        import os

        try:
            # Tamanho do card
            w, h = 400, 600
            
            # Cria a imagem base (Fundo Preto com borda Ouro)
            img = Image.new("RGB", (w, h), (15, 23, 42))
            draw = ImageDraw.Draw(img)
            
            # Bordas e Gradientes manuais
            draw.rectangle([0, 0, w-1, h-1], outline=(245, 158, 11), width=4) # Borda ouro
            draw.rectangle([10, 10, w-11, h-11], outline=(255, 255, 255), width=1) # Borda interna fina
            
            # Pega os dados
            nome = self.informacoes.get("Nome Completo", "Lenda").split()[-1].upper() # Sobrenome
            pos = self.informacoes.get("Posição", "MEI")
            nacionalidade = self.informacoes.get("Nacionalidade", "Brasil")
            clube = self.informacoes.get("Clube Atual", "Clube")
            
            # Overall Calculado via Radar
            overall = int(sum(self.atributos_jogador.values()) / len(self.atributos_jogador))
            
            # Fontes
            try:
                font_ovr = ImageFont.truetype("arialbd.ttf", 80)
                font_pos = ImageFont.truetype("arialbd.ttf", 30)
                font_name = ImageFont.truetype("arialbd.ttf", 40)
                font_stats = ImageFont.truetype("arialbd.ttf", 24)
                font_labels = ImageFont.truetype("arial.ttf", 20)
            except:
                font_ovr = font_pos = font_name = font_stats = font_labels = ImageFont.load_default()

            # Desenha OVR e POS
            draw.text((40, 50), str(overall), fill=(245, 158, 11), font=font_ovr)
            draw.text((50, 130), pos, fill=(255, 255, 255), font=font_pos)
            
            # Foto do Jogador
            path_face = f"Faces/{self.informacoes.get('Nome Completo', '').replace(' ', '_')}.png"
            if os.path.exists(path_face):
                face = Image.open(path_face).convert("RGBA").resize((220, 220), Image.Resampling.LANCZOS)
                img.paste(face, (150, 50), face)

            # Linha separadora
            draw.line([(40, 290), (w-40, 290)], fill=(245, 158, 11), width=2)
            
            # Nome
            bbox_name = draw.textbbox((0, 0), nome, font=font_name)
            w_name = bbox_name[2] - bbox_name[0]
            draw.text(((w - w_name) // 2, 300), nome, fill=(255, 255, 255), font=font_name)

            # --- ESTATÍSTICAS DO RADAR ---
            stats_keys = list(self.atributos_jogador.keys())
            stats_vals = list(self.atributos_jogador.values())
            
            # Grid 3x2 de Stats
            start_y = 380
            for i in range(6):
                if i >= len(stats_keys): break
                col = i % 2
                row = i // 2
                x_pos = 60 if col == 0 else 230
                y_pos = start_y + (row * 50)
                
                # Abreviação da Stat (Ex: Attack -> ATT)
                lbl = stats_keys[i][:3].upper()
                val = str(stats_vals[i])
                
                draw.text((x_pos, y_pos), val, fill=(245, 158, 11), font=font_stats) # Valor Ouro
                draw.text((x_pos + 45, y_pos + 3), lbl, fill=(255, 255, 255), font=font_labels) # Label Branco

            # Bandeira e Logo na parte inferior
            logo_path = self.club_logo_paths.get(clube)
            if logo_path and os.path.exists(logo_path):
                logo_clube = Image.open(logo_path).convert("RGBA").resize((50, 50), Image.Resampling.LANCZOS)
                img.paste(logo_clube, ((w//2)-25, 520), logo_clube)

            # Salvar
            file_path = filedialog.asksaveasfilename(
                defaultextension=".png", 
                initialfile=f"Card_{nome}_{overall}.png",
                title="Salvar Card do Jogador",
                filetypes=[("PNG Image", "*.png")]
            )
            
            if file_path:
                img.save(file_path)
                messagebox.showinfo("Sucesso", "Card exportado com sucesso!\nCompartilhe com a galera.")
        
        except Exception as e:
            messagebox.showerror("Erro", f"Erro ao gerar card: {str(e)}")

    def aba_financas_estilo(self, parent_frame):
        import datetime
        from tkinter import messagebox
        
        # --- ESTILOS & CORES ---
        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"
        COLOR_MONEY = "#10B981" # Verde Dinheiro

        self.style.configure("FinStyle.TFrame", background=BG_DARK)
        self.style.configure("AssetCard.TFrame", background=BG_CARD, relief="solid", borderwidth=1, bordercolor="#334155")

        aba_fin = ttk.Frame(parent_frame, style="FinStyle.TFrame")
        aba_fin.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_fin, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_fin, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="FinStyle.TFrame")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        canvas.create_window((0, 0), window=inner, anchor="nw")
        
        def _resize(e): canvas.itemconfig(canvas.find_all()[0], width=e.width)
        canvas.bind("<Configure>", _resize)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind_all("<MouseWheel>", lambda e: canvas.yview_scroll(int(-1*(e.delta/120)), "units"))

        # ======================================================================
        # MOTOR FINANCEIRO (Cálculo Retroativo)
        # ======================================================================
        if "Patrimonio" not in self.informacoes: self.informacoes["Patrimonio"] = []
        
        total_salario_recebido = 0.0
        total_semanas_carreira = 0.0 # Novo contador para o patrocinador
        
        # Pega a data do jogo mais recente como "Data Atual" do save
        ultima_data_jogo = datetime.datetime.now()
        if hasattr(self, 'ultimas_performances') and self.ultimas_performances:
            try:
                datas = [datetime.datetime.strptime(j["Data"], "%d/%m/%Y") for j in self.ultimas_performances]
                ultima_data_jogo = max(datas)
            except: pass

        # Calcula o salário por período de clube
        if hasattr(self, 'historico_transferencias'):
            def safe_date_parse_fin(d_str):
                try:
                    return datetime.datetime.strptime(d_str, "%d/%m/%Y")
                except:
                    return datetime.datetime.min
                    
            transf_ord = sorted(self.historico_transferencias, key=lambda x: safe_date_parse_fin(x.get("Data", "01/01/2000")))
            
            for i, t in enumerate(transf_ord):
                try:
                    d_ini = datetime.datetime.strptime(t.get("Data", "01/01/2000"), "%d/%m/%Y")
                    d_fim = ultima_data_jogo
                    if i < len(transf_ord) - 1:
                        d_fim = datetime.datetime.strptime(transf_ord[i+1].get("Data", "01/01/2000"), "%d/%m/%Y")
                    
                    if d_fim > d_ini:
                        semanas = (d_fim - d_ini).days / 7.0
                        total_semanas_carreira += semanas
                        
                        salario_str = str(t.get("Salario", self.informacoes.get("Salario Semanal", "1500")))
                        val_sal = float(salario_str.replace("€", "").replace("K", "000").replace("M", "000000").replace(".", "").strip())
                        total_salario_recebido += semanas * val_sal
                except: pass

        # Bônus por Performance
        t_gols = sum(row[2] for row in getattr(self, 'dados_desempenho', []))
        t_assis = sum(row[3] for row in getattr(self, 'dados_desempenho', []))
        t_titulos = sum(int(item[4]) for item in getattr(self, 'conquistas', []))
        t_motm = sum(1 for j in getattr(self, 'ultimas_performances', []) if j.get("Detalhes", {}).get("MOTM"))
        t_bdo = sum(1 for b in getattr(self, 'ballondor_custom', []) if self.informacoes.get("Nome Completo", "").lower() in b['nome'].lower())

        ganhos_bonus = (t_gols * 10000) + (t_assis * 5000) + (t_motm * 25000) + (t_titulos * 1000000) + (t_bdo * 3000000)
        
        # --- CÁLCULO DO PATROCINADOR MASTER ---
        patrocinador = self.informacoes.get("Fornecedor", "Sem Patrocínio")
        
        # Agora o valor não é mais engessado. Ele lê o que foi fechado no contrato.
        # Caso o jogador seja de um save antigo, colocamos 5000 como fallback.
        valor_base_patrocinio = self.informacoes.get("Valor_Patrocinio", 5000)
        
        # O dinheiro ganho de patrocínio é o valor do contrato atual multiplicado pelas semanas jogadas
        ganhos_patrocinio = total_semanas_carreira * valor_base_patrocinio
        # --------------------------------------

        dinheiro_total = total_salario_recebido + ganhos_bonus + ganhos_patrocinio
        
        # Gastos
        dinheiro_gasto = sum(item['valor'] for item in self.informacoes["Patrimonio"])
        saldo_atual = dinheiro_total - dinheiro_gasto

        # --- HEADER ---
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        tk.Label(header, text="FINANÇAS & LIFESTYLE", font=("Impact", 32), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="Gerencie seus salários, patrocínios e invista no seu império pessoal.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # --- GRID BANCÁRIO (3 COLUNAS) ---
        banco_grid = tk.Frame(inner, bg=BG_DARK)
        banco_grid.pack(fill="x", padx=40, pady=10)
        banco_grid.columnconfigure(0, weight=1); banco_grid.columnconfigure(1, weight=1); banco_grid.columnconfigure(2, weight=1)
        
        # 1. COLUNA: SALDO
        f_saldo = tk.Frame(banco_grid, bg=BG_CARD, highlightthickness=2, highlightbackground=COLOR_MONEY, padx=20, pady=20)
        f_saldo.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        tk.Label(f_saldo, text="SALDO DISPONÍVEL", font=("Segoe UI", 10, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")
        tk.Label(f_saldo, text=f"€ {saldo_atual:,.0f}".replace(",", "X").replace(".", ",").replace("X", "."), font=("Impact", 40), fg=COLOR_MONEY, bg=BG_CARD).pack(anchor="w", pady=(10, 0))

        def linha_extrato(parent, label, valor, cor, is_text=False):
            f = tk.Frame(parent, bg=BG_CARD)
            f.pack(fill="x", pady=4)
            tk.Label(f, text=label, font=("Segoe UI", 10), fg=TEXT_SUB, bg=BG_CARD).pack(side="left")
            if is_text:
                tk.Label(f, text=str(valor), font=("Segoe UI", 10, "bold"), fg=cor, bg=BG_CARD).pack(side="right")
            else:
                tk.Label(f, text=f"€ {valor:,.0f}".replace(",", "X").replace(".", ",").replace("X", "."), font=("Segoe UI", 10, "bold"), fg=cor, bg=BG_CARD).pack(side="right")

        # 2. COLUNA: ORIGEM DOS GANHOS (Agora inclui o patrocínio!)
        f_breakdown = tk.Frame(banco_grid, bg=BG_CARD, padx=20, pady=20, highlightthickness=1, highlightbackground="#334155")
        f_breakdown.grid(row=0, column=1, sticky="nsew", padx=10)
        tk.Label(f_breakdown, text="ORIGEM DOS GANHOS", font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 10))
        
        linha_extrato(f_breakdown, "Salários de Contrato:", total_salario_recebido, "#38BDF8")
        linha_extrato(f_breakdown, f"Patrocínio ({patrocinador}):", ganhos_patrocinio, "#4ADE80") # LINHA NOVA
        linha_extrato(f_breakdown, "Bônus por Metas (G+A+MOTM):", ganhos_bonus - (t_titulos*1000000) - (t_bdo*3000000), "#F59E0B")
        linha_extrato(f_breakdown, "Títulos & Melhor do Mundo:", (t_titulos*1000000)+(t_bdo*3000000), "#A855F7")
        tk.Frame(f_breakdown, bg="#334155", height=1).pack(fill="x", pady=5)
        linha_extrato(f_breakdown, "Total Gasto em Bens:", -dinheiro_gasto, "#EF4444")

        # 3. COLUNA: CONTRATO E STATUS
        f_status = tk.Frame(banco_grid, bg=BG_CARD, padx=20, pady=20, highlightthickness=1, highlightbackground="#334155")
        f_status.grid(row=0, column=2, sticky="nsew", padx=(10, 0))
        tk.Label(f_status, text="CONTRATO & STATUS", font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(anchor="w", pady=(0, 10))

        nivel = "Atleta Profissional"
        cor_nivel = "#94A3B8"
        if saldo_atual >= 100000000:
            nivel = "Magnata do Futebol 👑"
            cor_nivel = "#F59E0B"
        elif saldo_atual >= 50000000:
            nivel = "Ícone Global 🌍"
            cor_nivel = "#A855F7"
        elif saldo_atual >= 10000000:
            nivel = "Estrela Milionária 💎"
            cor_nivel = "#38BDF8"
        elif saldo_atual >= 1000000:
            nivel = "Atleta de Elite ⭐"
            cor_nivel = "#4ADE80"

        salario_str = self.informacoes.get("Salario Semanal", "1500")
        try: salario_num = float(salario_str.replace("€", "").replace("K", "000").replace("M", "000000").replace(".", "").strip())
        except: salario_num = 1500

        linha_extrato(f_status, "Salário Semanal:", salario_num, "#38BDF8")
        
        # Mostra o valor que o patrocinador está pagando por semana
        txt_patrocinio_semana = f"€ {valor_base_patrocinio:,.0f}/sem".replace(",", "X").replace(".", ",").replace("X", ".") if valor_base_patrocinio > 0 else "Nenhum"
        linha_extrato(f_status, "Contrato de Chuteira:", txt_patrocinio_semana, "#4ADE80", is_text=True)
        
        tk.Frame(f_status, bg="#334155", height=1).pack(fill="x", pady=5)
        linha_extrato(f_status, "Nível de Riqueza:", nivel, cor_nivel, is_text=True)

        # --- LOJA (CATÁLOGO EXPANDIDO) ---
        catalogo = [
            ("Veículos de Luxo", [
                ("Relógio de Grife", 75000, "⌚", "Puro estilo fora de campo."),
                ("Carro Esportivo", 350000, "🏎️", "Chegue no CT em alto nível."),
                ("Iate Particular", 8000000, "🛥️", "Férias no Mediterrâneo com privacidade."),
                ("Jato Particular VIP", 25000000, "🛩️", "Viagens internacionais sem estresse.")
            ]),
            ("Imóveis", [
                ("Apartamento de Luxo", 1200000, "🏢", "Localizado no centro da cidade."),
                ("Mansão com Campo", 5000000, "🏡", "Espaço para treinar em casa."),
                ("Cobertura em Dubai", 10000000, "🏙️", "O refúgio perfeito nas férias."),
                ("Ilha Particular", 15000000, "🏝️", "Seu próprio paraíso isolado.")
            ]),
            ("Negócios & Investimentos", [
                ("Marca Própria de Roupas", 2000000, "👕", "Expanda sua marca fora de campo."),
                ("Equipe de eSports", 3500000, "🎮", "Invista no mundo dos games."),
                ("Restaurante Fino", 5000000, "🍽️", "A culinária dos campeões."),
                ("Comprar Clube de Futebol", 150000000, "🏟️", "Compre seu próprio time para a aposentadoria.")
            ])
        ]

        def comprar_item(nome, valor, icone):
            if saldo_atual >= valor:
                if messagebox.askyesno("Confirmar Compra", f"Confirmar a compra de '{nome}' por € {valor:,}?"):
                    self.informacoes["Patrimonio"].append({"nome": nome, "valor": valor, "icone": icone, "data": datetime.datetime.now().strftime("%d/%m/%Y")})
                    self.salvar_dados()
                    self.show_toast(f"{nome} adquirido com sucesso!", "sucesso")
                    self.open_tab("Finanças & Estilo", "MERCADO & MÉDICO", 28) 
            else:
                messagebox.showerror("Saldo Insuficiente", f"Você precisa de mais € {valor - saldo_atual:,.0f} para comprar isso. Continue jogando e fazendo gols!")

        for categoria, itens in catalogo:
            tk.Label(inner, text=categoria.upper(), font=("Segoe UI", 12, "bold"), fg="white", bg=BG_DARK).pack(anchor="w", padx=40, pady=(20, 5))
            cat_grid = tk.Frame(inner, bg=BG_DARK)
            cat_grid.pack(fill="x", padx=30)
            
            for i, (nome, valor, icone, desc) in enumerate(itens):
                r, c = i // 4, i % 4
                card = ttk.Frame(cat_grid, style="AssetCard.TFrame", padding=15)
                card.grid(row=r, column=c, padx=10, pady=10, sticky="nsew")
                
                tk.Label(card, text=icone, font=("Segoe UI Emoji", 26), bg=BG_CARD).pack()
                tk.Label(card, text=nome.upper(), font=("Segoe UI", 10, "bold"), fg="white", bg=BG_CARD).pack(pady=(5, 0))
                tk.Label(card, text=desc, font=("Segoe UI", 8), fg=TEXT_SUB, bg=BG_CARD, wraplength=180).pack(pady=(0, 10))
                
                btn_buy = tk.Button(card, text=f"COMPRAR (€ {valor/1000000:.1f}M)" if valor>=1000000 else f"COMPRAR (€ {valor/1000:.0f}K)", 
                                    bg=COLOR_MONEY if saldo_atual >= valor else "#475569", 
                                    fg="#0F172A" if saldo_atual >= valor else "#94A3B8", 
                                    font=("Segoe UI", 9, "bold"), relief="flat", cursor="hand2" if saldo_atual >= valor else "X_cursor")
                btn_buy.config(command=lambda n=nome, v=valor, ic=icone: comprar_item(n, v, ic))
                btn_buy.pack(fill="x", side="bottom")

            for col_idx in range(4): cat_grid.columnconfigure(col_idx, weight=1)

        # --- SEU PATRIMÔNIO (INVENTÁRIO) ---
        tk.Label(inner, text="SEU IMPÉRIO (INVENTÁRIO)", font=("Segoe UI", 14, "bold"), fg="white", bg=BG_DARK).pack(anchor="w", padx=40, pady=(30, 10))
        bens_frame = tk.Frame(inner, bg=BG_DARK)
        bens_frame.pack(fill="x", padx=40)

        if not self.informacoes["Patrimonio"]:
            tk.Label(bens_frame, text="Você ainda não adquiriu nenhum bem de luxo. Invista seu salário!", font=("Segoe UI", 10, "italic"), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w", pady=10)
        else:
            for item in reversed(self.informacoes["Patrimonio"]):
                row_f = tk.Frame(bens_frame, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
                row_f.pack(fill="x", pady=5, ipady=10)
                tk.Label(row_f, text=item["icone"], font=("Segoe UI Emoji", 20), bg=BG_CARD).pack(side="left", padx=15)
                
                txt_box = tk.Frame(row_f, bg=BG_CARD)
                txt_box.pack(side="left")
                tk.Label(txt_box, text=item["nome"].upper(), font=("Segoe UI", 12, "bold"), fg="white", bg=BG_CARD).pack(anchor="w")
                tk.Label(txt_box, text=f"Adquirido em: {item.get('data', 'Desconhecido')}", font=("Segoe UI", 8), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w")
                tk.Label(row_f, text=f"Valor: € {item['valor']:,.0f}".replace(",", "X").replace(".", ",").replace("X", "."), font=("Segoe UI", 11, "bold"), fg=COLOR_MONEY, bg=BG_CARD).pack(side="right", padx=20)

        tk.Frame(inner, bg=BG_DARK, height=50).pack()

    def aba_recordes_pessoais(self, parent_frame):
        import tkinter as tk
        from tkinter import ttk
        import re

        # --- ESTILOS & CORES ---
        BG_DARK = "#0F172A"
        BG_CARD = "#1E293B"
        TEXT_MAIN = "#F8FAFC"
        TEXT_SUB = "#94A3B8"

        self.style.configure("RecMain.TFrame", background=BG_DARK)
        aba_rec = ttk.Frame(parent_frame, style="RecMain.TFrame")
        aba_rec.pack(fill="both", expand=True)

        canvas = tk.Canvas(aba_rec, bg=BG_DARK, highlightthickness=0)
        scrollbar = ttk.Scrollbar(aba_rec, orient="vertical", command=canvas.yview)
        inner = ttk.Frame(canvas, style="RecMain.TFrame")
        
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        canvas.create_window((0, 0), window=inner, anchor="nw")
        
        def _resize(e): canvas.itemconfig(canvas.find_all()[0], width=e.width)
        canvas.bind("<Configure>", _resize)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        
        def _scroll(e):
            if canvas.winfo_exists(): canvas.yview_scroll(int(-1*(e.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _scroll)

        # ======================================================================
        # 1. MOTOR DE ANÁLISE PROFUNDA DE RECORDES (Storytelling)
        # ======================================================================
        max_gols_jogo = 0; jogo_max_gols = None
        max_assists_jogo = 0; jogo_max_assists = None
        
        gols_finais = 0; viradas = 0; gols_clutch = 0; vitimas = {}
        maior_nota = 0.0; jogo_maior_nota = None
        max_seq_gols = 0; seq_gols = 0
        max_seq_part = 0; seq_part = 0
        hat_tricks = 0; pokers = 0
        gols_falta = 0; gols_cabeca = 0
        max_dribles = 0; jogo_max_dribles = None
        max_chances = 0; jogo_max_chances = None
        total_motm = 0; gols_cont_ano = {}
        jogos_perfeitos = 0; modo_lendario = 0
        pior_nota = 10.0; jogo_pior_nota = None
        minuto_mais_rapido = 999; jogo_gol_rapido = None
        minuto_mais_tardio = -1; jogo_gol_tardio = None

        performances_cronologicas = list(reversed(getattr(self, 'ultimas_performances', [])))
        status_ausente = ["Banco", "Suspenso", "Lesionado", "Não Relacionado", "Convocado"]

        for jogo in performances_cronologicas:
            try:
                g = int(jogo.get("Gols", 0))
                a = int(jogo.get("Assistências", 0))
                n = float(jogo.get("Nota", 6.0))
                mins = int(jogo.get("Minutos", 90))
                adv = jogo.get("Adversário", "Desconhecido")
                rodada = str(jogo.get("Rodada", "")).upper()
                tipo = jogo.get("Tipo", "Liga Nacional")
                pos = jogo.get("Posição", "MEI")
                det = jogo.get("Detalhes", {})
                
                if mins > 0 and pos not in status_ausente:
                    if g > max_gols_jogo: max_gols_jogo = g; jogo_max_gols = jogo
                    if a > max_assists_jogo: max_assists_jogo = a; jogo_max_assists = jogo
                    
                    if "FINAL" in rodada and g > 0: gols_finais += g
                    if det.get("GolVirada"): viradas += 1
                    
                    min_jog_str = str(det.get("MinutosGolsJogador", ""))
                    minutos_g = [int(m) for m in re.findall(r'\d+', min_jog_str)]
                    gols_clutch += sum(1 for m in minutos_g if m >= 85)
                    
                    vitimas[adv] = vitimas.get(adv, 0) + g
                    
                    if n > maior_nota: maior_nota = n; jogo_maior_nota = jogo
                    if g >= 4: pokers += 1
                    elif g == 3: hat_tricks += 1
                    
                    if g > 0: seq_gols += 1
                    else: seq_gols = 0
                    if seq_gols > max_seq_gols: max_seq_gols = seq_gols
                    
                    if (g + a) > 0: seq_part += 1
                    else: seq_part = 0
                    if seq_part > max_seq_part: max_seq_part = seq_part
                    
                    gols_falta += int(det.get("FaltasGol", 0))
                    gols_cabeca += int(det.get("Cabeca", 0))
                    
                    dribles = int(det.get("DriblesCertos", 0))
                    if dribles > max_dribles: max_dribles = dribles; jogo_max_dribles = jogo
                    
                    chances = int(det.get("ChancesCriadas", 0)) + int(det.get("PassesDecisivos", 0))
                    if chances > max_chances: max_chances = chances; jogo_max_chances = jogo
                    
                    if tipo == "Continental":
                        ano = self._inferir_temporada(jogo.get("Data", ""))
                        gols_cont_ano[ano] = gols_cont_ano.get(ano, 0) + g
                        
                    if det.get("MOTM"): total_motm += 1
                    
                    if g >= 3 and a >= 1 and n >= 9.8: jogos_perfeitos += 1
                    
                    is_jogo_grande = any(x in rodada for x in ["FINAL", "SEMI", "QUARTAS"]) or tipo in ["Continental", "Mundial de Clubes", "Seleção"]
                    if is_jogo_grande and (g + a) >= 2: modo_lendario += 1
                    
                    if mins >= 45 and n < pior_nota:
                        pior_nota = n; jogo_pior_nota = jogo

                    if minutos_g:
                        menor_m = min(minutos_g); maior_m = max(minutos_g)
                        if menor_m < minuto_mais_rapido: minuto_mais_rapido = menor_m; jogo_gol_rapido = jogo
                        if maior_m > minuto_mais_tardio: minuto_mais_tardio = maior_m; jogo_gol_tardio = jogo

            except: pass

        maior_vitima = max(vitimas, key=vitimas.get) if vitimas else "Nenhum"
        gols_maior_vitima = vitimas.get(maior_vitima, 0)
        
        melhor_cont = max(gols_cont_ano, key=gols_cont_ano.get) if gols_cont_ano else "Nenhuma"
        gols_melhor_cont = gols_cont_ano.get(melhor_cont, 0)
        
        melhor_temp_nome = "Nenhuma"; melhor_temp_val = 0
        for k, v in getattr(self, 'dados_jogador', {}).items():
            ga = v.get("gols", 0) + v.get("assistencias", 0)
            if ga > melhor_temp_val: melhor_temp_val = ga; melhor_temp_nome = k
                
        melhor_clube_nome = "Nenhum"; melhor_clube_gols = 0
        for k, v in getattr(self, 'dados_desempenho_por_clubes', {}).items():
            gc = v.get("gols", 0)
            if gc > melhor_clube_gols: melhor_clube_gols = gc; melhor_clube_nome = k

        # ======================================================================
        # RENDERIZAÇÃO DA TELA (DESIGN PREMIUM)
        # ======================================================================
        header = tk.Frame(inner, bg=BG_DARK, pady=20, padx=40)
        header.pack(fill="x")
        
        tk.Label(header, text="HALL DOS RECORDES", font=("Impact", 36), fg="white", bg=BG_DARK).pack(anchor="w")
        tk.Label(header, text="As marcas eternas, as glórias absolutas e os dias para esquecer da sua carreira.", font=("Segoe UI", 11), fg=TEXT_SUB, bg=BG_DARK).pack(anchor="w")

        # --- FUNÇÃO GERADORA DE CARDS MODERNOS ---
        def criar_card_achievement(parent, row, col, titulo, valor_destaque, subtitulo, contexto, icone, cor_neon):
            # Wrapper com padding para respirar na grade
            wrap = tk.Frame(parent, bg=BG_DARK)
            wrap.grid(row=row, column=col, sticky="nsew", padx=10, pady=10)
            
            # Card principal
            f = tk.Frame(wrap, bg=BG_CARD, highlightthickness=1, highlightbackground="#334155")
            f.pack(fill="both", expand=True)
            f.pack_propagate(False)
            f.config(height=200) 
            
            # Barra Lateral Neon
            tk.Frame(f, bg=cor_neon, width=4).pack(side="left", fill="y")
            
            # Conteúdo Interno
            content = tk.Frame(f, bg=BG_CARD, padx=20, pady=20)
            content.pack(fill="both", expand=True)
            
            # Topo (Icone e Título)
            top_f = tk.Frame(content, bg=BG_CARD)
            top_f.pack(fill="x", pady=(0, 10))
            tk.Label(top_f, text=icone, font=("Segoe UI Emoji", 16), fg=cor_neon, bg=BG_CARD).pack(side="left", padx=(0, 10))
            tk.Label(top_f, text=titulo.upper(), font=("Segoe UI", 9, "bold"), fg=cor_neon, bg=BG_CARD).pack(side="left")
            
            # Valor Gigante
            tk.Label(content, text=str(valor_destaque), font=("Impact", 32), fg="white", bg=BG_CARD).pack(anchor="w")
            
            # Subtítulo 
            tk.Label(content, text=subtitulo, font=("Segoe UI", 10, "bold"), fg=TEXT_SUB, bg=BG_CARD).pack(anchor="w", pady=(0, 5))
            
            # Contexto / Descrição
            tk.Label(content, text=contexto, font=("Segoe UI", 9, "italic"), fg="#64748B", bg=BG_CARD, wraplength=280, justify="left").pack(anchor="w")
            
            # Efeitos de Hover
            def on_ent(e, c=f, ic=content, tf=top_f): 
                c.config(highlightbackground=cor_neon, bg="#252F3D")
                ic.config(bg="#252F3D"); tf.config(bg="#252F3D")
                for w in ic.winfo_children() + tf.winfo_children(): 
                    if isinstance(w, tk.Label): w.config(bg="#252F3D")
                    
            def on_lea(e, c=f, ic=content, tf=top_f): 
                c.config(highlightbackground="#334155", bg=BG_CARD)
                ic.config(bg=BG_CARD); tf.config(bg=BG_CARD)
                for w in ic.winfo_children() + tf.winfo_children(): 
                    if isinstance(w, tk.Label): w.config(bg=BG_CARD)
                    
            wrap.bind("<Enter>", on_ent); wrap.bind("<Leave>", on_lea)
            f.bind("<Enter>", on_ent); f.bind("<Leave>", on_lea)
            for w in content.winfo_children() + top_f.winfo_children() + [content, top_f]:
                w.bind("<Enter>", on_ent); w.bind("<Leave>", on_lea)

        # Helper para criar os títulos das seções
        def criar_secao(titulo, icone_sec, cor_sec):
            sec = tk.Frame(inner, bg=BG_DARK, highlightthickness=0)
            sec.pack(fill="x", padx=40, pady=(30, 0))
            
            f_tit = tk.Frame(sec, bg=BG_DARK)
            f_tit.pack(anchor="w", pady=(0, 10))
            tk.Label(f_tit, text=icone_sec, font=("Segoe UI Emoji", 16), bg=BG_DARK).pack(side="left", padx=(0, 10))
            tk.Label(f_tit, text=titulo, font=("Segoe UI", 16, "bold"), fg=cor_sec, bg=BG_DARK).pack(side="left")
            
            tk.Frame(sec, bg="#1E293B", height=2).pack(fill="x")
            
            grid = tk.Frame(inner, bg=BG_DARK)
            grid.pack(fill="x", padx=30, pady=10)
            for i in range(3): grid.columnconfigure(i, weight=1) 
            return grid

        # ======================================================================
