            ttk.Combobox(f_pos, textvariable=v_pos, values=["GOL", "ZAG", "LDE", "LDD", "VOL", "MC", "MEI", "ME", "MD", "PE", "PD", "SA", "ATA"], state="readonly", width=12, font=("Segoe UI", 10)).pack(side="left")

            campo_txt("Jogos Disputados:", v_jg)
