                btn_excluir.pack(pady=(5, 10), fill="x", ipady=5)
                btn_excluir.bind("<Enter>", lambda e: btn_excluir.config(bg="#F87171"))
                btn_excluir.bind("<Leave>", lambda e: btn_excluir.config(bg="#EF4444"))


