            text_lote = tk.Text(f_lote, height=13, bg="#020617", fg="#10B981", font=("Consolas", 11), insertbackground="white", relief="flat", highlightthickness=1, highlightbackground="#334155", padx=10, pady=10)
            text_lote.pack(fill="both", expand=True, pady=(0, 15))
            text_lote.bind("<MouseWheel>", lambda e: text_lote.yview_scroll(int(-1*(e.delta/120)), "units"))

            def processar_lote_inteligente():
                texto = text_lote.get("1.0", "end-1c").strip()
                if not texto: return
                linhas = texto.split("\n")
                sucesso = 0
                erros = 0
                duplicados = 0
                temp_atual = var_ano_modal.get().strip()
                meses_pt = {"janeiro": "01", "fevereiro": "02", "março": "03", "marco": "03", "abril": "04", "maio": "05", "junho": "06", "julho": "07", "agosto": "08", "setembro": "09", "outubro": "10", "novembro": "11", "dezembro": "12"}
                ano_str = re.search(r'\d{4}', str(temp_atual))
                ano_base = int(ano_str.group(0)) if ano_str else 2026
                data_base = f"01/01/{ano_base}"
                for linha in linhas:
                    linha = linha.strip()
                    if not linha: continue
                    match_data = re.search(r'(\d+)\s+de\s+([A-Za-zç]+)', linha, re.IGNORECASE)
                    match_jogo = re.search(r'^-?\s*(.+?)\s+(\d+)\s*[-xX]\s*(\d+)\s+(.+?)$', linha)
                    if match_data and not match_jogo:
                        dia = match_data.group(1).zfill(2)
                        mes_num_str = meses_pt.get(match_data.group(2).lower(), '01')
                        ano_jogo = ano_base if int(mes_num_str) >= 7 else (ano_base + 1)
                        data_base = f"{dia}/{mes_num_str}/{ano_jogo}"
                        continue
                    if match_jogo:
                        try:
                            c = obter_nome_oficial(match_jogo.group(1).strip(), temp_atual)
                            f = obter_nome_oficial(match_jogo.group(4).strip(), temp_atual)
                            gc = int(match_jogo.group(2))
                            gf = int(match_jogo.group(3))
                            if any(j.get("temporada") == temp_atual and j.get("casa") == c and j.get("fora") == f for j in self.jogos_liga):
                                duplicados += 1; continue
                            self.jogos_liga.append({"data": data_base, "temporada": temp_atual, "casa": c, "fora": f, "gols_casa": gc, "gols_fora": gf})
                            if c not in self.club_logo_paths: self.baixar_logo_automaticamente(c)
                            if f not in self.club_logo_paths: self.baixar_logo_automaticamente(f)
                            sucesso += 1
                        except: erros += 1
                    else: erros += 1
                self.salvar_dados(); recarregar_filtro_temporadas(); var_ano.set(temp_atual); atualizar_view()
                msg_final = f"✅ {sucesso} novos jogos importados!\n"
                if duplicados > 0: msg_final += f"🔁 {duplicados} ignorados (já registrados).\n"
                if erros > 0: msg_final += f"⚠️ {erros} linhas inválidas ignoradas."
                messagebox.showinfo("Concluído", msg_final, parent=md)
                fechar_modal_add()

