        tk.Button(f_btns, text="⚙️ REGISTRAR JOGOS", bg="#10B981", fg="#0F172A", font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", padx=20, pady=10, command=abrir_modal_jogos).pack(side="left")

        # ======================================================================
