        container_linhas = tk.Frame(f_conteudo, bg=BG_CARD, pady=10); container_linhas.pack(fill="both", expand=True)

        def obter_rodada_maxima(ano_alvo):
            def parse_date(d_str):
                try: return datetime.datetime.strptime(d_str, "%d/%m/%Y")
                except: return datetime.datetime.min
            j_filtrados = sorted([j for j in self.jogos_liga if j.get("temporada", self._inferir_temporada(j.get("data", ""))) == ano_alvo], key=lambda x: parse_date(x.get("data", "")))
            contagem = {}
            for j in j_filtrados:
                rodada = max(contagem.get(j["casa"], 0), contagem.get(j["fora"], 0)) + 1
                contagem[j["casa"]] = rodada; contagem[j["fora"]] = rodada
            return max(contagem.values()) if contagem else 1

        def gerar_classificacao(ano_alvo, rodada_alvo):
            tabela_calc = {}; contagem_jogos = {}
            def parse_date(d_str):
                try: return datetime.datetime.strptime(d_str, "%d/%m/%Y")
                except: return datetime.datetime.min
            jogos_temporada = sorted([j for j in self.jogos_liga if j.get("temporada", self._inferir_temporada(j.get("data", ""))) == ano_alvo], key=lambda x: parse_date(x.get("data", "")))

            for jogo in jogos_temporada:
                c = jogo["casa"]; f = jogo["fora"]; gc = int(jogo["gols_casa"]); gf = int(jogo["gols_fora"])
                r_jogo = max(contagem_jogos.get(c, 0), contagem_jogos.get(f, 0)) + 1
                contagem_jogos[c] = r_jogo; contagem_jogos[f] = r_jogo
                if c not in tabela_calc: tabela_calc[c] = {"pts": 0, "j": 0, "v": 0, "e": 0, "d": 0, "gp": 0, "gc": 0, "sg": 0}
                if f not in tabela_calc: tabela_calc[f] = {"pts": 0, "j": 0, "v": 0, "e": 0, "d": 0, "gp": 0, "gc": 0, "sg": 0}

                if r_jogo <= rodada_alvo:
                    tabela_calc[c]["j"] += 1; tabela_calc[c]["gp"] += gc; tabela_calc[c]["gc"] += gf; tabela_calc[c]["sg"] += (gc - gf)
                    tabela_calc[f]["j"] += 1; tabela_calc[f]["gp"] += gf; tabela_calc[f]["gc"] += gc; tabela_calc[f]["sg"] += (gf - gc)
                    if gc > gf: 
                        tabela_calc[c]["pts"] += 3; tabela_calc[c]["v"] += 1; tabela_calc[f]["d"] += 1
                    elif gf > gc: 
                        tabela_calc[f]["pts"] += 3; tabela_calc[f]["v"] += 1; tabela_calc[c]["d"] += 1
                    else: 
                        tabela_calc[c]["pts"] += 1; tabela_calc[f]["pts"] += 1; tabela_calc[c]["e"] += 1; tabela_calc[f]["e"] += 1

            return sorted(tabela_calc.items(), key=lambda x: (x[1]["pts"], x[1]["sg"], x[1]["gp"]), reverse=True)

        def detectar_liga(times_nomes):
            times_upper = [t.upper() for t in times_nomes]
            marcadores_ale = ["BAYERN MÜNCHEN", "BORUSSIA DORTMUND", "RB LEIPZIG", "LEVERKUSEN", "FRANKFURT"]
            marcadores_aut = ["RED BULL SALZBURG", "STURM GRAZ", "LASK", "RAPID WIEN", "AUSTRIA WIEN", "RB SALZBURG"]
            marcadores_bra = ["FLAMENGO", "PALMEIRAS", "CORINTHIANS", "SÃO PAULO", "SANTOS", "BOTAFOGO"]
            marcadores_ing = ["MANCHESTER CITY", "ARSENAL", "LIVERPOOL", "CHELSEA", "MANCHESTER UNITED"]
            marcadores_esp = ["REAL MADRID", "BARCELONA", "ATLÉTICO DE MADRID", "SEVILLA"]
            marcadores_ita = ["JUVENTUS", "AC MILAN", "INTER DE MILÃO", "NAPOLI", "ROMA"]
            for t in times_upper:
                if t in marcadores_aut: return "AUT"
                if t in marcadores_ale: return "ALE"
                if t in marcadores_bra: return "BRA"
                if t in marcadores_ing: return "ING"
                if t in marcadores_esp: return "ESP"
                if t in marcadores_ita: return "ITA"
            return "DEFAULT"

        # ======================================================================
        # 4. HISTÓRICO DE CLASSIFICAÇÕES (GRÁFICO PREMIUM)
        # ======================================================================
        f_grafico = tk.Frame(inner, bg=BG_DARK, highlightthickness=1, highlightbackground="#1E293B")
        f_grafico.pack(fill="both", expand=True, padx=40, pady=(0, 40))

        header_g = tk.Frame(f_grafico, bg=BG_DARK, pady=15)
        header_g.pack(fill="x")
        tk.Label(header_g, text="📈 HISTÓRICO DAS CLASSIFICAÇÕES", font=("Segoe UI", 12, "bold"), fg="white", bg=BG_DARK).pack()

        cv_grafico = tk.Canvas(f_grafico, bg=BG_DARK, highlightthickness=0, height=320)
        cv_grafico.pack(fill="both", expand=True, padx=20, pady=10)
        cv_grafico.dots_data = {} 

        f_controles_g = tk.Frame(f_grafico, bg=BG_DARK, pady=15)
