        cb_time1.pack(side="left", padx=(5, 25))

        tk.Label(f_controles_g, text="Comparar com:", font=("Segoe UI", 9, "bold"), fg="#38BDF8", bg=BG_DARK).pack(side="left")
        var_time2 = tk.StringVar()
        cb_time2 = tk.OptionMenu(f_controles_g, var_time2, "")
