def _ps_parse_dmy(s):
    try:
        d, m, y = map(int, str(s).strip().split("/"))
        return datetime.date(y, m, d)
    except Exception: return None


class _PSHist:
    """Port do módulo de campeões do app de celular, ligado aos dados do App (self.app)."""
    def __init__(self, app):
        self.app = app; self.comps = []; self.by_key = {}; self.by_name = {}; self.drawn = {}; self.eq = {}; self.nl = set(); self.lin = {}
        self.ready = False; self.tcache = {}; self.memo = None
        if not PS.load() or not PS.hist: return
        j = PS.hist
        for c in j.get("c", []):
            e = PS.comps.resolve(c["n"])
            comp = {"n": c["n"], "g": c.get("g", ""), "r": c.get("r", []), "b": c.get("b", {}) or {}, "em": c.get("em", 0), "e": e,
                    "key": e.f if e else "h:" + _ps_lkey(c["n"]), "nat": c["n"] in _PS_NAT_COMPS}
            self.comps.append(comp)
        for c in self.comps:
            self.by_key.setdefault(c["key"], c); self.by_name[_ps_lkey(c["n"])] = c
        self.nl = {_ps_lkey(n) for n in j.get("nl", [])}
        self.lin = j.get("lin", {}) or {}
        seen = {}
        for e in PS.clubs.list:
            k0 = _ps_lkey(e.n)
            if k0 in seen: self.eq[e.f] = seen[k0]
            else: seen[k0] = e
        for g in j.get("eq", []) or []:
            es = [x for x in (PS.clubs.strict(n) for n in g) if x]
            for e in es[1:]:
                if e.f != es[0].f: self.eq[e.f] = self.canon(es[0])
        for n, k in _PS_DRAWN_STARS.items():
            e = PS.nats.strict(n) or PS.clubs.strict(n)
            if e: self.drawn[e.f] = k
        self.ready = True

    # ---------- dados do save ----------
    @property
    def perfs(self): return getattr(self.app, "ultimas_performances", []) or []
    @property
    def conquistas(self): return getattr(self.app, "conquistas", []) or []
    def manuais(self):
        if not hasattr(self.app, "campeoes_manuais") or not isinstance(self.app.campeoes_manuais, dict): self.app.campeoes_manuais = {}
        return self.app.campeoes_manuais
    def reset(self): self.memo = None

    def canon(self, e): return self.eq.get(e.f, e) if e else e

    def hist_team(self, name, nat=False):
        ck = ("n|" if nat else "c|") + str(name)
        if ck in self.tcache: return self.tcache[ck]
        raw = str(name or "").strip(); base = re.sub(r"\s*\([^)]*\)\s*$", "", raw) or raw
        a = _PS_HIST_ALIAS.get(_ps_lkey(base)); e = None
        blocked = _ps_lkey(raw) in self.nl or _ps_lkey(base) in self.nl
        if blocked:
            e = self.canon(PS.clubs.exact.get(_ps_lkey(raw)) or (PS.nats.exact.get(_ps_lkey(raw)) if nat else None))
        elif a != "":
            if nat: e = PS.nats.strict(raw) or PS.nats.strict(a or base) or PS.clubs.strict(raw) or PS.clubs.strict(a or base)
            else: e = PS.clubs.strict(raw) or PS.clubs.strict(a or base)
            e = self.canon(e)
        r = {"k": e.f if e else "h:" + _ps_lkey(a or base), "e": e, "label": e.label if e else base}
        succ = self.lin.get(raw) or self.lin.get(base)
        if succ: r["k"] = self.hist_team(succ, nat)["k"]
        self.tcache[ck] = r; return r

    def user_team(self, name):
        ck = "u|" + str(name)
        if ck in self.tcache: return self.tcache[ck]
        e = None
        try: e = PS.logos.resolve(name)
        except Exception: e = None
        if e and e.t not in ("c", "n"): e = None
        e = self.canon(e)
        r = {"k": e.f if e else "h:" + _ps_lkey(name), "e": e, "label": str(name)}
        self.tcache[ck] = r; return r

    def comp_of(self, name):
        if not self.ready or not name: return None
        c = self.by_name.get(_ps_lkey(name))
        if c: return c
        e = PS.comps.resolve(name)
        return self.by_key.get(e.f) if e else None

    @staticmethod
    def split(comp):
        return bool(comp["r"]) and "/" in str(comp["r"][-1][0]) if comp["r"] else True
    def season_lbl(self, comp, y):
        return f"{y-1}/{str(y)[-2:]}" if self.split(comp) else str(y)
    def end_year(self, comp):
        if self.split(comp) or comp["n"] in ("Copa do Mundo", "UEFA Euro"): return True
        return comp["g"] in _PS_EURO_G and not re.search(r"(^| )super(?! ?(lig|league|liga))|community shield|campeones|(^| )champions( |$)|cruijff|durand", _ps_lnorm(comp["n"]))
    def bulk_y(self, comp, s):
        m = re.match(r"^(\d{4})\s*[\/-]\s*(\d{2,4})$", str(s or "").strip())
        if m: return int(m.group(1)) + 1 if self.end_year(comp) else int(m.group(1))
        try: return int(str(s)[:4])
        except Exception: return datetime.date.today().year

    def career_cut(self):
        m = None
        for j in self.perfs:
            d = _ps_parse_dmy(j.get("Data"))
            if d and (m is None or d < m): m = d
        return m
    @staticmethod
    def row_end(s, y, nat, em):
        if nat: return datetime.date(y, 6, 1)
        if re.search(r"\d{4}/\d{2}", str(s)): return datetime.date(y, 6, 30)
        return datetime.date(y, max(1, min(12, int(em or 12))), 28)

    @staticmethod
    def trophy_seasons(c):
        out = []
        for m in re.finditer(r"(\d{4})(?:\s*[\/-]\s*(\d{2,4}))?", str(c[2] if len(c) > 2 else "")):
            y = int(m.group(1))
            out.append({"s": f"{y}/{str(m.group(2))[-2:]}", "y": y + 1} if m.group(2) else {"s": str(y), "y": y})
        try: q = max(1, int(c[4]))
        except Exception: q = 1
        while len(out) < q: out.append({"s": "?", "y": 9999})
        return out

    def find_specific(self, j):
        """Rodada do jogo (fica nos dicionários por torneio, igual ao formulário de partida)."""
        app = self.app; time_ = j.get("Time") or app.informacoes.get("Clube Atual")
        d = _ps_parse_dmy(j.get("Data")); cands = []
        if j.get("Temporada"): cands.append(str(j["Temporada"]))
        if d:
            eu = f"{d.year}/{str(d.year+1)[-2:]}" if d.month >= 7 else f"{d.year-1}/{str(d.year)[-2:]}"
            cands += [eu, str(d.year)]
        sel = j.get("Tipo") in ("Seleção", "National Team") or (j.get("Time") or "") == app.informacoes.get("Nacionalidade")
        if not sel:
            for key in ("dados_temporadas_Liga", "dados_temporadas_Copas_Nacional", "dados_temporadas_Copas_Regional", "dados_temporadas_Copas_Continental", "desmepenho_mundila_de_clubes"):
                dd = getattr(app, key, {}) or {}
                for ano in cands:
                    for it in dd.get(ano, []) or []:
                        if len(it) > 5 and it[0] == j.get("Competição") and it[2] == j.get("Data") and it[5] == j.get("Adversário"): return {"rodada": it[1], "ano": ano}
            for ano in cands:
                for it in ((getattr(app, "dados_temporadas_SuperCopa", {}) or {}).get(ano, {}) or {}).get(j.get("Competição"), []) or []:
                    if it.get("Data") == j.get("Data") and it.get("Adversário") == j.get("Adversário"): return {"rodada": it.get("Rodada"), "ano": ano}
        for it in (getattr(app, "dados_competicoes_por_seleção", {}) or {}).get(j.get("Competição"), []) or []:
            if len(it) > 4 and it[1] == j.get("Data") and it[4] == j.get("Adversário"): return {"rodada": it[0], "ano": None}
        return None

    @staticmethod
    def is_final(r):
        s = _ps_lnorm(r)
        return bool(re.search(r"(^| )(grand |grande )?finale?( |$)", s)) and not re.search(r"semi|quart|oitav|octav|quarter|eighth|1 (4|8|16)|pre|elimin|grup|group|play ?off|repesc", s)

    @staticmethod
    def score(j):
        try:
            a, b = [int(x) for x in str(j.get("Resultado", "")).split(" ")[0].split("-")]
        except Exception: return None
        casa = str(j.get("Local", "C")).upper() in ("C", "H", "CASA", "HOME")
        return (a, b) if casa else (b, a)
    @staticmethod
    def pens(j):
        m = re.search(r"(\d+)\s*[-x×:]\s*(\d+)", str((j.get("Detalhes") or {}).get("Penaltis", "")))
        if not m: return None
        a, b = int(m.group(1)), int(m.group(2))
        casa = str(j.get("Local", "C")).upper() in ("C", "H", "CASA", "HOME")
        return (a, b) if casa else (b, a)

    def finals(self):
        memo = self._memo()
        if memo["fin"] is not None: return memo["fin"]
        by = {}
        for j in self.perfs:
            comp = self.comp_of(j.get("Competição"))
            if not comp: continue
            sp = self.find_specific(j)
            if not sp or not self.is_final(sp.get("rodada")): continue
            d = _ps_parse_dmy(j.get("Data"))
            if not d: continue
            y = (d.year + 1 if d.month >= 7 else d.year) if self.split(comp) else d.year
            by.setdefault(id(comp), (comp, {}))[1].setdefault(y, []).append(j)
        out = {}
        for cid, (comp, m) in by.items():
            rows = []
            for y, js in m.items():
                js.sort(key=lambda x: _ps_parse_dmy(x.get("Data")) or datetime.date(1900, 1, 1))
                mine = theirs = 0; ok = True
                for j in js:
                    s = self.score(j)
                    if not s: ok = False; break
                    mine += s[0]; theirs += s[1]
                if not ok: continue
                last = js[-1]; win = True if mine > theirs else False if mine < theirs else None; pen = None
                if win is None:
                    pen = self.pens(last)
                    if pen and pen[0] != pen[1]: win = pen[0] > pen[1]
                if win is None: continue
                my = last.get("Time") or self.app.informacoes.get("Clube Atual"); opp = last.get("Adversário")
                cw, cl = (my, opp) if win else (opp, my)
                sc = (f"{mine}-{theirs}" if win else f"{theirs}-{mine}")
                if pen: sc += f" ({pen[0] if win else pen[1]}-{pen[1] if win else pen[0]} pên.)"
                if len(js) > 1: sc += " agr."
                u = self.user_team(cw)
                rows.append({"s": self.season_lbl(comp, y), "y": y, "champ": cw, "ru": cl, "ruT": self.user_team(cl), "sc": sc,
                             "me": win, "lost": not win, "fin": True, "k": u["k"], "e": u["e"], "label": u["label"]})
            out[cid] = rows
        memo["fin"] = out; return out

    def manual_rows(self, comp):
        M = self.manuais().get(_ps_lkey(comp["n"]), {}) or {}
        rows = []
        for y, v in M.items():
            if not v or not v.get("c"): continue
            u = self.user_team(v["c"])
            rows.append({"s": v.get("s") or self.season_lbl(comp, int(y)), "y": int(y), "champ": v["c"], "ru": v.get("v", ""),
                         "ruT": self.user_team(v["v"]) if v.get("v") else None, "sc": "", "k": u["k"], "e": u["e"], "label": u["label"], "man": True})
        return rows

    def career_rows(self, comp):
        rows = []
        for c in self.conquistas:
            if len(c) < 4 or self.comp_of(c[1]) is not comp: continue
            u = self.user_team(c[3])
            for ss in self.trophy_seasons(c):
                rows.append({"s": ss["s"], "y": ss["y"], "champ": c[3], "ru": "", "sc": "", "me": True, "k": u["k"], "e": u["e"], "label": c[3]})
        return rows

    def _memo(self):
        if self.memo is None: self.memo = {"cut": self.career_cut(), "tl": {}, "rank": {}, "stars": None, "fin": None}
        return self.memo

    def timeline(self, comp):
        memo = self._memo(); cid = id(comp)
        if cid in memo["tl"]: return memo["tl"][cid]
        cut = memo["cut"]; mine = self.career_rows(comp); by_y = {}
        for r in mine:
            if r["y"] < 9999 and r["y"] not in by_y: by_y[r["y"]] = r
        extra = []
        for f in self.finals().get(cid, []):
            m = by_y.get(f["y"])
            if m:
                if f["me"] and not m.get("ru"): m.update({"ru": f["ru"], "ruT": f["ruT"], "sc": f["sc"], "fin": True})
                continue
            r = dict(f); extra.append(r); by_y[f["y"]] = r
        for r in self.manual_rows(comp):
            if r["y"] in by_y: continue
            extra.append(r); by_y[r["y"]] = r
        rows = []
        for r in comp["r"]:
            if cut and self.row_end(r[0], r[1], comp["nat"], comp["em"]) > cut: continue
            if r[1] in by_y: continue
            t0 = self.hist_team(r[2], comp["nat"])
            rows.append({"s": r[0], "y": r[1], "champ": r[2], "ru": r[3] if len(r) > 3 else "", "sc": r[4] if len(r) > 4 else "", "k": t0["k"], "e": t0["e"], "label": t0["label"]})
        tl = sorted(rows + mine + extra, key=lambda x: (x["y"], str(x["s"])))
        memo["tl"][cid] = tl; return tl

    def ru_team(self, r, comp): return r.get("ruT") or self.hist_team(r["ru"], comp["nat"])

    def ranking(self, comp):
        memo = self._memo(); cid = id(comp)
        if cid in memo["rank"]: return memo["rank"][cid]
        T = {}
        def get(k, e, label):
            if k not in T: T[k] = {"k": k, "e": e, "label": label, "t": 0, "v": 0, "last": 0, "first": 0, "me": 0}
            return T[k]
        for n, q in comp["b"].items():
            t0 = self.hist_team(n, comp["nat"]); get(t0["k"], t0["e"], t0["label"])["t"] += q
        for r in self.timeline(comp):
            x = get(r["k"], r["e"], r["label"]); x["t"] += 1
            if r["y"] < 9999 and r["y"] >= x["last"] and r["e"]: x["e"] = r["e"]; x["label"] = r["label"]
            if r["y"] < 9999:
                x["last"] = max(x["last"], r["y"])
                if not x["first"]: x["first"] = r["y"]
            if r.get("me"): x["me"] += 1
            if r.get("ru"):
                t1 = self.ru_team(r, comp); get(t1["k"], t1["e"], t1["label"])["v"] += 1
        lst = sorted([x for x in T.values() if x["t"] or x["v"]], key=lambda x: (-x["t"], -x["v"], x["first"] or 9999))
        memo["rank"][cid] = lst; return lst

    def titles(self, comp, key):
        n = sum(1 for r in self.timeline(comp) if r["k"] == key)
        for nm, q in comp["b"].items():
            if self.hist_team(nm, comp["nat"])["k"] == key: n += q
        return n

    def star_map(self):
        memo = self._memo()
        if memo["stars"] is not None: return memo["stars"]
        M = {}
        def add(k, n):
            if n > 0: M[k] = M.get(k, 0) + n
        rules = [("Serie A", 0, lambda n: n // 10), ("Eredivisie", 0, lambda n: n // 10),
                 ("Bundesliga", 1964, lambda n: len([x for x in (3, 5, 10, 20, 30) if n >= x])), ("Copa do Mundo", 0, lambda n: n)]
        for name, frm, fn in rules:
            c = self.by_name.get(_ps_lkey(name))
            if not c: continue
            cnt = {}
            for r in self.timeline(c):
                if r["y"] >= frm: cnt[r["k"]] = cnt.get(r["k"], 0) + 1
            if not frm:
                for nm, q in c["b"].items():
                    k = self.hist_team(nm, c["nat"])["k"]; cnt[k] = cnt.get(k, 0) + q
            for k, n in cnt.items(): add(k, fn(n))
        uy = PS.nats.strict("Uruguay")
        if uy: add(uy.f, 2)
        fr = set()
        for nm in ("Ligue 1", "Ligue 2 BKT", "Coupe de France", "Trophée des Champions"):
            c = self.by_name.get(_ps_lkey(nm))
            if c:
                for r in c["r"]:
                    fr.add(self.hist_team(r[2])["k"])
                    if len(r) > 3 and r[3]: fr.add(self.hist_team(r[3])["k"])
        ucl = self.by_name.get(_ps_lkey("UEFA Champions League"))
        if ucl:
            cnt = {}
            for r in self.timeline(ucl):
                if r["k"] in fr: cnt[r["k"]] = cnt.get(r["k"], 0) + 1
            for k, n in cnt.items(): add(k, n)
        l1 = self.by_name.get(_ps_lkey("Ligue 1")); asse = PS.clubs.strict("AS Saint-Étienne")
        if l1 and asse: add(asse.f, self.titles(l1, asse.f) // 10)
        memo["stars"] = M; return M

    def stars_of(self, k): return max(0, self.star_map().get(k, 0) - self.drawn.get(k, 0)) if self.ready else 0
    def crest_stars(self, club): return self.stars_of(self.user_team(club)["k"]) if self.ready and club else 0

    def used(self):
        s = []
        for c in self.conquistas:
            x = self.comp_of(c[1]) if len(c) > 1 else None
            if x and x not in s: s.append(x)
        for j in self.perfs:
            x = self.comp_of(j.get("Competição"))
            if x and x not in s: s.append(x)
        return s

    def groups(self):
        g = {}
        for c in self.comps: g.setdefault(c["g"] or "", []).append(c)
        order = sorted(g.keys(), key=lambda a: (0 if a == "" else 1 if a == "Brasil" else 2, a))
        return g, order

    def search_key(self, c):
        return _ps_lnorm(" ".join([c["n"], _PS_COMP_EN.get(c["n"], ""), c["g"], _PS_GROUP_EN.get(c["g"], ""), "" if c["g"] else "internacional international"]))

    # ---------- notícia de título com contexto histórico ----------
    def noticia_titulo(self, comp_name, club, season_txt, stars_before):
        self.reset()
        comp = self.comp_of(comp_name); me = self.app.informacoes.get("Nome Completo", "Jogador"); F = str(me).split(" ")[0] or me
        stars_after = self.crest_stars(club)
        if comp:
            u = self.user_team(club); tl = self.timeline(comp); mine = [r for r in tl if r["k"] == u["k"]]
            n = self.titles(comp, u["k"]); cur = mine[-1] if mine else None; prev = mine[-2] if len(mine) > 1 else None
            streak = 1
            if cur and cur["y"] < 9999:
                y = cur["y"]
                while True:
                    p = [r for r in tl if r["y"] == y - 1]
                    if p and any(r["k"] == u["k"] for r in p): streak += 1; y -= 1
                    else: break
            rank = self.ranking(comp); lead = rank[0] if rank else None; second = next((x for x in rank if x["k"] != u["k"]), None)
            gap = cur["y"] - prev["y"] if prev and cur and prev["y"] < 9999 and cur["y"] < 9999 else 0
            cn = comp["n"]
            if n == 1:
                head = f"{club} conquista {cn} pela primeira vez na história"
                txt = f"Feito inédito: com {F} em campo, o {club} finalmente levanta a taça."
            elif streak >= 2:
                w = (_PS_ORD[streak - 1] if streak - 1 < len(_PS_ORD) else f"{streak}x ") + "campeão"
                head = f"{w}! {club} conquista {cn} mais uma vez"
                txt = f"{club} chega a {n} títulos de {cn}, com {F} como peça-chave da sequência."
            elif gap >= 10:
                head = f"Fim do jejum: {club} volta a vencer {cn} após {gap} anos"
                txt = f"A espera desde {prev['s']} acabou. É o {n}º título do clube na competição."
            elif lead and lead["k"] == u["k"] and (not second or n > second["t"]):
                head = f"{club} se isola como maior campeão de {cn}"
                txt = f"São {n} títulos, {n - (second['t'] if second else 0)} a mais que {second['label'] if second else 'o segundo colocado'}."
            else:
                head = f"{club} conquista {cn} e chega ao {n}º título"
                txt = f"{F} soma mais uma taça; " + (f"{lead['label']} segue como maior campeão, com {lead['t']}." if lead and lead["k"] != u["k"] else "o clube segue subindo no ranking histórico.")
        else:
            head = f"{club} conquista {comp_name}"; txt = f"{F} levanta mais uma taça ({season_txt})."
        if stars_after > stars_before:
            txt += f" O escudo do {club} ganha sua primeira estrela." if stars_after == 1 else f" O escudo do {club} ganha mais uma estrela — agora são {stars_after}."
        last = None; ld = ""
        for j in self.perfs:
            d = _ps_parse_dmy(j.get("Data"))
            if d and (last is None or d > last): last = d; ld = j.get("Data")
        return {"tipo": "titulo", "data": ld or datetime.date.today().strftime("%d/%m/%Y"), "titulo": head, "texto_curto": txt,
                "tag": "TÍTULO", "comp": comp_name, "clube": club, "temp": season_txt, "lida": False}

    def paragrafos_titulo(self, n):
        comp_name = n.get("comp", ""); club = n.get("clube", ""); hc = self.comp_of(comp_name)
        F = str(self.app.informacoes.get("Nome Completo", "Jogador")).split(" ")[0]
        def same(j):
            return str(j.get("Competição", "")).lower() == str(comp_name).lower() or (hc is not None and self.comp_of(j.get("Competição")) is hc)
        js = [j for j in self.perfs if same(j) and (not club or (j.get("Time") or self.app.informacoes.get("Clube Atual")) == club)]
        m = re.search(r"(\d{4})(?:\s*[\/-]\s*(\d{2,4}))?", str(n.get("temp", "")))
        season = (f"{m.group(1)}/{str(m.group(2))[-2:]}" if m.group(2) else m.group(1)) if m else ""
        if not season and js:
            last = max(js, key=lambda j: _ps_parse_dmy(j.get("Data")) or datetime.date(1900, 1, 1))
            season = self.app._inferir_temporada(last.get("Data", ""))
        if season:
            ins = [j for j in js if self.app._inferir_temporada(j.get("Data", "")) == season]
            if ins: js = ins
        jogou = [j for j in js if j.get("Posição") not in ("Banco", "Lesionado", "Suspenso", "Não Relacionado", "Convocado")]
        g = sum(int(j.get("Gols", 0) or 0) for j in js); a = sum(int(j.get("Assistências", 0) or 0) for j in js)
        notas = [float(j.get("Nota", 0) or 0) for j in jogou if float(j.get("Nota", 0) or 0) > 0]
        avg = sum(notas) / len(notas) if notas else 0
        def res(j):
            s = self.score(j)
            return None if not s else "W" if s[0] > s[1] else "L" if s[0] < s[1] else "D"
        W = sum(1 for j in js if res(j) == "W"); D = sum(1 for j in js if res(j) == "D"); L = sum(1 for j in js if res(j) == "L")
        paras = [n.get("texto_curto", "")]
        if js:
            paras.append(f"{F} disputou {len(js)} jogo{'s' if len(js) > 1 else ''} da campanha ({W} vitórias, {D} empates e {L} derrotas), com {g} gol{'s' if g != 1 else ''} e {a} assistência{'s' if a != 1 else ''}" + (f" e nota média de {avg:.2f}." if avg else "."))
        fin = None
        for j in sorted(js, key=lambda x: _ps_parse_dmy(x.get("Data")) or datetime.date(1900, 1, 1), reverse=True):
            sp = self.find_specific(j)
            if sp and self.is_final(sp.get("rodada")): fin = j; break
        if fin:
            s = self.score(fin); p = self.pens(fin); gf = int(fin.get("Gols", 0) or 0)
            paras.append(f"Na decisão, o {club} superou o {fin.get('Adversário')}" + (f" por {s[0]} a {s[1]}" if s else "") + (f" ({p[0]} a {p[1]} nos pênaltis)" if p else "") + (f", com {gf} gols de {F}" if gf > 1 else f", com gol de {F}" if gf == 1 else "") + ".")
        if hc:
            u = self.user_team(club); tot = self.titles(hc, u["k"]); rank = self.ranking(hc)
            pos = next((i + 1 for i, x in enumerate(rank) if x["k"] == u["k"]), 0); lead = rank[0] if rank else None
            if tot:
                paras.append(f"É o {tot}º título do {club} na história da {hc['n']}" + (", o maior campeão da competição." if pos == 1 else f"; o {lead['label']} lidera o ranking histórico com {lead['t']}." if lead else "."))
        return [p for p in paras if p], hc


def _ps_hist(app):
    h = getattr(app, "_ps_hist_obj", None)
    if h is None or not h.ready:
        h = _PSHist(app); app._ps_hist_obj = h
    h.reset(); h.tcache = {}
    return h


