def _ps_clubes_hint(self):
    out = []
    for c in [self.informacoes.get("Clube Atual")] + [j.get("Time") for j in (getattr(self, "ultimas_performances", []) or [])[:80]] + list((getattr(self, "dados_desempenho_por_clubes", {}) or {}).keys()):
        if c and c not in out: out.append(c)
    return out

def _ps_avatar_pil(self, nome, tam, clubes=None):
    """Rosto do banco offline (ou silhueta) — usado quando não há face própria em Faces/Face Players."""
    img = _ps_face_pil(nome, clubes if clubes is not None else self._ps_clubes_hint(), tam)
    return img if img is not None else _ps_silhueta(tam)

def _ps_preparar_logos(self):
    """Em segundo plano: copia do banco offline os escudos de tudo que existe no save."""
    nomes = set()
    try:
        nomes.update([self.informacoes.get("Clube Atual"), self.informacoes.get("Nacionalidade")])
        for j in getattr(self, "ultimas_performances", []) or []: nomes.update([j.get("Time"), j.get("Adversário"), j.get("Competição")])
        for c in getattr(self, "conquistas", []) or []:
            if len(c) > 3: nomes.update([c[1], c[3]])
        nomes.update((getattr(self, "dados_desempenho_por_clubes", {}) or {}).keys())
        for t in getattr(self, "historico_transferencias", []) or []: nomes.update([t.get("De"), t.get("Para")])
    except Exception: pass
    def tarefa():
        for n in list(nomes):
            if n: _ps_logo_offline(n)
    threading.Thread(target=tarefa, daemon=True).start()


# ------------------------------- campo de jogador com autocompletar -------------------------------
def _ps_campo_jogador(self, parent, row, col, label, var):
    f = ttk.Frame(parent, style="FormCard.TFrame")
    f.grid(row=row, column=col, sticky="ew", padx=8, pady=5)
    ttk.Label(f, text=label, style="FormLabel.TLabel").pack(anchor="w")
    ent = tk.Entry(f, textvariable=var, font=("Segoe UI", 10), bg="#334155", fg="white", insertbackground="white", highlightthickness=0, relief="flat")
    ent.pack(fill="x", ipady=3)
    tk.Label(f, text="Digite e escolha (vírgula separa nomes)", font=("Segoe UI", 8), fg="#64748B", bg="#1E293B").pack(anchor="w")
    st = {"pop": None, "imgs": [], "after": None}

    def opcoes():
        PS.load()
        full = var.get(); q = full.split(",")[-1].strip()
        ja = {_ps_lkey(x) for x in full.split(",")[:-1] if x.strip()}
        club = self.vars_add_match["Clube"].get() if hasattr(self, "vars_add_match") else self.informacoes.get("Clube Atual")
        mine = {}
        for j in getattr(self, "ultimas_performances", []) or []:
            d = j.get("Detalhes") or {}
            for k in ("AssistRecebidaDe", "AssistDadaPara"):
                for n in str(d.get(k, "")).split(","):
                    n = n.strip()
                    if n and _ps_lkey(n) not in mine: mine[_ps_lkey(n)] = (n, j.get("Time"))
        for L in (getattr(self, "dados_elenco", {}) or {}).values():
            for p in L or []:
                n = str(p.get("nome", "")).strip()
                if n and _ps_lkey(n) not in mine: mine[_ps_lkey(n)] = (n, "")
        qk = _ps_lnorm(q); out = []; vistos = set()
        def push(n, pid, c, usado):
            k = _ps_lkey(n)
            if k in vistos or k in ja: return
            vistos.add(k); out.append((n, pid, c, usado))
        for n, c in mine.values():
            ln = _ps_lnorm(n)
            if qk and not (qk in ln or any(w.startswith(qk.split(" ")[0]) for w in ln.split(" "))): continue
            p = PS.faces.find(n, [c or club, club])
            push(n, p["id"] if p else None, p["c"] if p else "", True)
        for p in PS.faces.search(q, club, 30): push(p["n"], p["id"], p["c"], False)
        return out[:10]

    def fechar(_=None):
        if st["pop"] is not None:
            try: st["pop"].destroy()
            except Exception: pass
        st["pop"] = None; st["imgs"].clear()

    def escolher(nome):
        partes = var.get().split(",")
        partes[-1] = (" " if len(partes) > 1 else "") + nome
        var.set(",".join(partes)); ent.icursor("end"); fechar(); ent.focus_set()

    def abrir(_=None):
        ops = opcoes(); fechar()
        if not ops: return
        pop = tk.Toplevel(ent); pop.wm_overrideredirect(True); pop.configure(bg="#334155")
        try: pop.attributes("-topmost", True)
        except Exception: pass
        x = ent.winfo_rootx(); y = ent.winfo_rooty() + ent.winfo_height() + 2; w = max(ent.winfo_width(), 300)
        pop.geometry(f"{w}x{min(len(ops), 8) * 44 + 4}+{x}+{y}")
        inner = tk.Frame(pop, bg="#0F172A"); inner.pack(fill="both", expand=True, padx=1, pady=1)
        for n, pid, c, usado in ops[:8]:
            row_f = tk.Frame(inner, bg="#0F172A", cursor="hand2", height=44); row_f.pack(fill="x"); row_f.pack_propagate(False)
            img = None
            if pid and PS.base:
                try:
                    im = Image.open(PS.path(f"p/{pid}.webp")).convert("RGBA"); ww, hh = im.size; s = min(ww, hh)
                    im = im.crop(((ww - s) // 2, 0, (ww - s) // 2 + s, s)); bg = Image.new("RGBA", im.size, (27, 37, 55, 255)); bg.alpha_composite(im); img = bg.resize((34, 34), Image.Resampling.LANCZOS)
                except Exception: img = None
            if img is None: img = _ps_silhueta(34)
            mask = Image.new("L", (34, 34), 0); ImageDraw.Draw(mask).ellipse((0, 0, 33, 33), fill=255)
            comp_img = Image.new("RGBA", (34, 34), (0, 0, 0, 0)); comp_img.paste(img, (0, 0), mask)
            tki = ImageTk.PhotoImage(comp_img); st["imgs"].append(tki)
            lab_i = tk.Label(row_f, image=tki, bg="#0F172A"); lab_i.pack(side="left", padx=8)
            tf = tk.Frame(row_f, bg="#0F172A"); tf.pack(side="left", fill="x", expand=True)
            l1 = tk.Label(tf, text=n, font=("Segoe UI", 10, "bold"), fg="white", bg="#0F172A", anchor="w"); l1.pack(anchor="w")
            l2 = tk.Label(tf, text=(c or "") + ("   • já usado" if usado else ""), font=("Segoe UI", 8), fg="#38BDF8", bg="#0F172A", anchor="w"); l2.pack(anchor="w")
            for wdg in (row_f, lab_i, tf, l1, l2):
                wdg.bind("<Button-1>", lambda e, nn=n: escolher(nn))
                wdg.bind("<Enter>", lambda e, rr=row_f: [w2.config(bg="#1E293B") for w2 in [rr] + list(rr.winfo_children()) + [x for ch in rr.winfo_children() for x in ch.winfo_children()]])
                wdg.bind("<Leave>", lambda e, rr=row_f: [w2.config(bg="#0F172A") for w2 in [rr] + list(rr.winfo_children()) + [x for ch in rr.winfo_children() for x in ch.winfo_children()]])
        st["pop"] = pop; st["first"] = ops[0][0]

    def on_key(e):
        if e.keysym == "Escape": fechar(); return
        if e.keysym == "Return":
            if st["pop"] is not None and st.get("first"): escolher(st["first"])
            return
        if st["after"]: ent.after_cancel(st["after"])
        st["after"] = ent.after(180, abrir)

    def on_out(_):
        ent.after(200, lambda: fechar() if self.focus_get() is not ent else None)

    ent.bind("<KeyRelease>", on_key)
    ent.bind("<FocusIn>", lambda e: ent.after(50, abrir))
    ent.bind("<FocusOut>", on_out)
    ent.bind("<Destroy>", fechar)
    return ent


# ------------------------------- aba Campeões -------------------------------
def _ps_img_cache(self, key, maker):
    if not hasattr(self, "_ps_imgs"): self._ps_imgs = {}
    if key not in self._ps_imgs:
        pil = maker()
        self._ps_imgs[key] = ImageTk.PhotoImage(pil) if pil is not None else None
    return self._ps_imgs[key]

def _ps_crest(self, parent, e, label, size, bg, stars=0):
    """Escudo (ou iniciais) com as estrelas por cima, como no celular."""
    def make():
        base = _ps_entry_img(e, size) if e else None
        if base is None:
            base = Image.new("RGBA", (size, size), (0, 0, 0, 0)); d = ImageDraw.Draw(base)
            h = sum(ord(ch) * 31 for ch in str(label)) % 360
            import colorsys
            r, g, b = [int(x * 255) for x in colorsys.hls_to_rgb(h / 360, 0.38, 0.55)]
            d.rounded_rectangle((1, 1, size - 2, size - 2), radius=size // 4, fill=(r, g, b, 255))
            ini = "".join(w[0] for w in re.sub(r"[^\w -]", "", str(label)).split()[:3]).upper() or "?"
            try: fnt = ImageFont.truetype("arialbd.ttf", max(8, int(size * 0.32)))
            except Exception: fnt = ImageFont.load_default()
            bb = d.textbbox((0, 0), ini, font=fnt); d.text(((size - (bb[2] - bb[0])) / 2, (size - (bb[3] - bb[1])) / 2 - 1), ini, fill="white", font=fnt)
        if stars and size >= 22:
            band = max(7, size // 5); out = Image.new("RGBA", (size, size + band), (0, 0, 0, 0)); out.paste(base, (0, band), base)
            d = ImageDraw.Draw(out); n = min(stars, 5); sw = band
            x0 = (size - n * sw) / 2
            for i in range(n):
                cx = x0 + i * sw + sw / 2; cy = band / 2; R = sw * 0.48; r2 = R * 0.45; pts = []
                import math
                for k in range(10):
                    ang = -math.pi / 2 + k * math.pi / 5; rr = R if k % 2 == 0 else r2
                    pts.append((cx + rr * math.cos(ang), cy + rr * math.sin(ang)))
                d.polygon(pts, fill=(251, 191, 36, 255), outline=(107, 78, 0, 255))
            if stars > 5:
                try: fnt = ImageFont.truetype("arialbd.ttf", band)
                except Exception: fnt = ImageFont.load_default()
            return out
        return base
    img = self._ps_img_cache(("crest", e.f if e else label, size, stars), make)
    lbl = tk.Label(parent, image=img, bg=bg)
    if stars > 5: lbl.config(text=f"{stars}★", compound="top", fg="#FBBF24", font=("Segoe UI", 7, "bold"))
    return lbl


def _ps_aba_campeoes(self, parent_frame, comp_key=None):
    BG = "#0F172A"; CARD = "#1E293B"; SUB = "#94A3B8"; GOLD = "#FBBF24"; ACC = "#38BDF8"
    for w in parent_frame.winfo_children(): w.destroy()
    H = _ps_hist(self)
    root = tk.Frame(parent_frame, bg=BG); root.pack(fill="both", expand=True)
    if not H.ready:
        tk.Label(root, text="🏛 CAMPEÕES", font=("Impact", 32), fg="white", bg=BG).pack(anchor="w", padx=40, pady=(30, 5))
        tk.Label(root, text="Não encontrei a pasta \"Dados\" ao lado do ProStats.\nCopie a pasta Dados (escudos, rostos e história dos campeões) para a mesma pasta do programa e abra esta aba de novo.",
                 font=("Segoe UI", 12), fg=SUB, bg=BG, justify="left").pack(anchor="w", padx=40)
        return

    canvas = tk.Canvas(root, bg=BG, highlightthickness=0); sb = ttk.Scrollbar(root, orient="vertical", command=canvas.yview)
    inner = tk.Frame(canvas, bg=BG); win = canvas.create_window((0, 0), window=inner, anchor="nw")
    canvas.configure(yscrollcommand=sb.set); canvas.pack(side="left", fill="both", expand=True); sb.pack(side="right", fill="y")
    canvas.bind("<Configure>", lambda e: canvas.itemconfig(win, width=e.width))
    inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
    canvas.bind_all("<MouseWheel>", lambda e: canvas.yview_scroll(int(-1 * (e.delta / 120)), "units"))

    comp = None
    if comp_key:
        comp = next((c for c in H.comps if c["key"] == comp_key), None) or H.by_name.get(comp_key)

    # ======================= PÁGINA DA COMPETIÇÃO =======================
    if comp:
        tl = H.timeline(comp); rank = H.ranking(comp); last = tl[-1] if tl else None; top = rank[0] if rank else None
        mine_keys = {H.user_team(n)["k"] for n in list((getattr(self, "dados_desempenho_por_clubes", {}) or {}).keys()) + [self.informacoes.get("Clube Atual"), self.informacoes.get("Nacionalidade")] + [c[3] for c in H.conquistas if len(c) > 3] if n}
        my_titles = sum(1 for r in tl if r.get("me"))
        bar = tk.Frame(inner, bg=BG); bar.pack(fill="x", padx=40, pady=(20, 0))
        tk.Button(bar, text="🡨  CAMPEÕES", bg=CARD, fg=ACC, font=("Segoe UI", 9, "bold"), relief="flat", cursor="hand2", padx=12, pady=4,
                  command=lambda: self._ps_aba_campeoes(parent_frame)).pack(side="left")
        tk.Button(bar, text="＋ ADICIONAR CAMPEÕES", bg=ACC, fg="#0F172A", font=("Segoe UI", 9, "bold"), relief="flat", cursor="hand2", padx=12, pady=4,
                  command=lambda: self._ps_campeoes_em_massa(parent_frame, comp["g"], comp["key"])).pack(side="right")
        hero = tk.Frame(inner, bg=BG); hero.pack(fill="x", padx=40, pady=(15, 10))
        self._ps_crest(hero, comp["e"], comp["n"], 72, BG).pack(side="left", padx=(0, 18))
        ht = tk.Frame(hero, bg=BG); ht.pack(side="left")
        tk.Label(ht, text=comp["n"].upper(), font=("Impact", 30), fg="white", bg=BG).pack(anchor="w")
        tk.Label(ht, text=(f"{comp['g']} · " if comp["g"] else "Internacional · ") + f"{len(tl)} edições" + (f" · desde {tl[0]['s']}" if tl else ""), font=("Segoe UI", 11), fg=SUB, bg=BG).pack(anchor="w")
        kp = tk.Frame(inner, bg=BG); kp.pack(fill="x", padx=40, pady=10)
        for i in range(3): kp.columnconfigure(i, weight=1)
        def kpi(col, crest_row, valor, rotulo, cor="white"):
            f = tk.Frame(kp, bg=CARD, padx=15, pady=12, highlightthickness=1, highlightbackground="#334155"); f.grid(row=0, column=col, sticky="nsew", padx=6)
            if crest_row: self._ps_crest(f, crest_row["e"], crest_row["label"], 40, CARD, H.stars_of(crest_row["k"])).pack()
            tk.Label(f, text=valor, font=("Impact", 22), fg=cor, bg=CARD).pack()
            tk.Label(f, text=rotulo, font=("Segoe UI", 9, "bold"), fg=SUB, bg=CARD).pack()
        kpi(0, top, str(top["t"]) if top else "–", "MAIOR CAMPEÃO" + (f": {top['label']}" if top else ""))
        kpi(1, last, last["s"] if last else "–", "ÚLTIMO CAMPEÃO" + (f": {last['label']}" if last else ""))
        kpi(2, None, str(my_titles), "SEUS TÍTULOS", GOLD)
        tabs = tk.Frame(inner, bg=BG); tabs.pack(fill="x", padx=40, pady=(10, 5))
        aba = getattr(self, "_ps_hist_tab", "rank")
        def set_tab(v): self._ps_hist_tab = v; self._ps_aba_campeoes(parent_frame, comp["key"])
        for v, t in (("rank", "🏆 RANKING"), ("seasons", "📅 TEMPORADAS")):
            tk.Button(tabs, text=t, bg=ACC if aba == v else CARD, fg="#0F172A" if aba == v else "white", font=("Segoe UI", 9, "bold"), relief="flat", cursor="hand2", padx=14, pady=5,
                      command=lambda vv=v: set_tab(vv)).pack(side="left", padx=(0, 6))
        lista = tk.Frame(inner, bg=BG); lista.pack(fill="x", padx=40, pady=(5, 40))
        if aba == "rank":
            for i, x in enumerate(rank[:80]):
                eh = x["k"] in mine_keys; bgc = "#2A2410" if eh else CARD
                r = tk.Frame(lista, bg=bgc, padx=12, pady=6); r.pack(fill="x", pady=1)
                tk.Label(r, text=f"{i+1}", width=3, font=("Segoe UI", 11, "bold"), fg=SUB, bg=bgc).pack(side="left")
                self._ps_crest(r, x["e"], x["label"], 34, bgc, H.stars_of(x["k"])).pack(side="left", padx=8)
                t = tk.Frame(r, bg=bgc); t.pack(side="left", fill="x", expand=True)
                tk.Label(t, text=x["label"] + (f"   ★ {x['me']} com você" if x["me"] else ""), font=("Segoe UI", 11, "bold"), fg=GOLD if x["me"] else "white", bg=bgc, anchor="w").pack(anchor="w")
                sub = []
                if x["v"]: sub.append(f"{x['v']} vice" + ("s" if x["v"] > 1 else ""))
                if x["last"]: sub.append(f"último em {x['last']}")
                tk.Label(t, text=" · ".join(sub), font=("Segoe UI", 9), fg=SUB, bg=bgc, anchor="w").pack(anchor="w")
                tk.Label(r, text=str(x["t"]), font=("Impact", 22), fg="white", bg=bgc).pack(side="right", padx=10)
            if comp["b"]:
                tk.Label(lista, text="* Inclui títulos anteriores ao início da lista de temporadas.", font=("Segoe UI", 9, "italic"), fg=SUB, bg=BG).pack(anchor="w", pady=6)
        else:
            for rr in list(reversed(tl))[:220]:
                eh = rr.get("me") or rr.get("lost"); bgc = "#2A2410" if eh else CARD
                r = tk.Frame(lista, bg=bgc, padx=12, pady=6); r.pack(fill="x", pady=1)
                tk.Label(r, text="–" if rr["s"] == "?" else rr["s"], width=9, font=("Segoe UI", 10, "bold"), fg=SUB, bg=bgc, anchor="w").pack(side="left")
                self._ps_crest(r, rr["e"], rr["label"], 32, bgc, H.stars_of(rr["k"])).pack(side="left", padx=8)
                t = tk.Frame(r, bg=bgc); t.pack(side="left", fill="x", expand=True)
                chip = "   SUA CARREIRA" if rr.get("me") else "   🥈 VICE (VOCÊ)" if rr.get("lost") else ""
                tk.Label(t, text=rr["label"] + chip, font=("Segoe UI", 11, "bold"), fg=GOLD if rr.get("me") else "white", bg=bgc, anchor="w").pack(anchor="w")
                if rr.get("ru"):
                    tk.Label(t, text=(f"{rr['sc']}  " if rr.get("sc") else "") + "x " + H.ru_team(rr, comp)["label"], font=("Segoe UI", 9), fg=SUB, bg=bgc, anchor="w").pack(anchor="w")
        return

    # ======================= LISTA DE COMPETIÇÕES =======================
    head = tk.Frame(inner, bg=BG); head.pack(fill="x", padx=40, pady=(25, 5))
    tk.Label(head, text="🏛 CAMPEÕES", font=("Impact", 32), fg="white", bg=BG).pack(side="left")
    tk.Button(head, text="＋ ADICIONAR CAMPEÕES", bg=ACC, fg="#0F172A", font=("Segoe UI", 10, "bold"), relief="flat", cursor="hand2", padx=16, pady=6,
              command=lambda: self._ps_campeoes_em_massa(parent_frame)).pack(side="right")
    tk.Label(inner, text="Todos os campeões da história. Seus títulos entram na lista, finais que você disputou (Rodada = \"Final\") contam sozinhas e o escudo ganha estrelas.",
             font=("Segoe UI", 10), fg=SUB, bg=BG, wraplength=900, justify="left").pack(anchor="w", padx=40)
    sf = tk.Frame(inner, bg=BG); sf.pack(fill="x", padx=40, pady=12)
    tk.Label(sf, text="🔎", font=("Segoe UI", 12), fg=SUB, bg=BG).pack(side="left")
    vq = tk.StringVar(value=getattr(self, "_ps_hist_q", ""))
    eq = tk.Entry(sf, textvariable=vq, font=("Segoe UI", 11), bg=CARD, fg="white", insertbackground="white", relief="flat", highlightthickness=1, highlightbackground="#334155")
    eq.pack(side="left", fill="x", expand=True, ipady=5, padx=8)
    tk.Label(sf, text="Buscar competição ou país (português ou inglês)", font=("Segoe UI", 9), fg="#64748B", bg=BG).pack(side="left")
    corpo = tk.Frame(inner, bg=BG); corpo.pack(fill="x", padx=40, pady=(0, 40))
    g, order = H.groups(); used = H.used()

    def item(parent, c):
        tl = H.timeline(c); last = tl[-1] if tl else None
        r = tk.Frame(parent, bg=CARD, padx=12, pady=6, cursor="hand2"); r.pack(fill="x", pady=1)
        w1 = self._ps_crest(r, c["e"], c["n"], 32, CARD); w1.pack(side="left", padx=(0, 10))
        t = tk.Frame(r, bg=CARD); t.pack(side="left", fill="x", expand=True)
        l1 = tk.Label(t, text=c["n"], font=("Segoe UI", 11, "bold"), fg="white", bg=CARD, anchor="w"); l1.pack(anchor="w")
        l2 = tk.Label(t, text=f"{len(tl)} edições" + (f" · desde {tl[0]['s']}" if tl else ""), font=("Segoe UI", 9), fg=SUB, bg=CARD, anchor="w"); l2.pack(anchor="w")
        ws = [r, w1, t, l1, l2]
        if last:
            lf = tk.Frame(r, bg=CARD); lf.pack(side="right")
            w3 = self._ps_crest(lf, last["e"], last["label"], 26, CARD, H.stars_of(last["k"])); w3.pack(side="left", padx=6)
            w4 = tk.Label(lf, text=str(last["s"])[-7:], font=("Segoe UI", 9, "bold"), fg=SUB, bg=CARD); w4.pack(side="left")
            ws += [lf, w3, w4]
        for w in ws: w.bind("<Button-1>", lambda e, k=c["key"]: [setattr(self, "_ps_hist_q", vq.get()), setattr(self, "_ps_hist_tab", "rank"), self._ps_aba_campeoes(parent_frame, k)])

    def montar(*_):
        for w in corpo.winfo_children(): w.destroy()
        q = _ps_lnorm(vq.get())
        blocos = ([("SUAS COMPETIÇÕES", used)] if used and not q else []) + [((gg or "INTERNACIONAIS").upper(), g[gg]) for gg in order]
        for titulo, comps in blocos:
            vis = [c for c in comps if not q or q in H.search_key(c)]
            if not vis: continue
            tk.Label(corpo, text=titulo, font=("Segoe UI", 9, "bold"), fg="#64748B", bg=BG).pack(anchor="w", pady=(14, 4))
            box = tk.Frame(corpo, bg=BG); box.pack(fill="x")
            for c in vis: item(box, c)
    st = {"job": None}
    def agenda(*_):
        if st["job"]: self.after_cancel(st["job"])
        st["job"] = self.after(250, montar)
    vq.trace_add("write", agenda)
    montar()


def _ps_campeoes_em_massa(self, parent_frame, grupo=None, comp_key=None):
    """Adiciona os campeões de várias competições de uma vez (temporada + país)."""
    BG = "#0F172A"; CARD = "#1E293B"; SUB = "#94A3B8"; ACC = "#38BDF8"
    H = _ps_hist(self)
    if not H.ready: return
    md = tk.Toplevel(self); md.title("Adicionar campeões"); md.configure(bg=BG); md.geometry("820x760"); md.grab_set()
    tk.Label(md, text="＋ ADICIONAR CAMPEÕES", font=("Impact", 24), fg="white", bg=BG).pack(anchor="w", padx=25, pady=(18, 0))
    tk.Label(md, text="Escolha a temporada e o país e preencha os campeões de todas as competições de uma vez. Deixe em branco o que não quiser mudar; apagar um nome remove o campeão que você digitou.",
             font=("Segoe UI", 10), fg=SUB, bg=BG, wraplength=760, justify="left").pack(anchor="w", padx=25, pady=(4, 10))
    top = tk.Frame(md, bg=BG); top.pack(fill="x", padx=25)
    temporadas = sorted(set(list((getattr(self, "dados_jogador", {}) or {}).keys()) + [self._inferir_temporada(j.get("Data", "")) for j in H.perfs]), key=lambda s: (int(str(s)[:4]) if str(s)[:4].isdigit() else 0, s), reverse=True)
    if not temporadas: temporadas = [str(datetime.date.today().year)]
    g, order = H.groups(); used = H.used()
    grupos = ([("*", "Suas competições")] if used else []) + [(x, x or "Internacionais") for x in order]
    v_s = tk.StringVar(value=temporadas[0])
    ini = grupo if grupo is not None else ("*" if used else order[0])
    v_g = tk.StringVar(value=next((l for k, l in grupos if k == ini), grupos[0][1]))
    tk.Label(top, text="TEMPORADA", font=("Segoe UI", 8, "bold"), fg=SUB, bg=BG).grid(row=0, column=0, sticky="w")
    tk.Label(top, text="PAÍS", font=("Segoe UI", 8, "bold"), fg=SUB, bg=BG).grid(row=0, column=1, sticky="w", padx=(15, 0))
    cb_s = ttk.Combobox(top, textvariable=v_s, values=temporadas, state="readonly", width=14); cb_s.grid(row=1, column=0, sticky="w")
    cb_g = ttk.Combobox(top, textvariable=v_g, values=[l for _, l in grupos], state="readonly", width=30); cb_g.grid(row=1, column=1, sticky="w", padx=(15, 0))

    wrap = tk.Frame(md, bg=BG); wrap.pack(fill="both", expand=True, padx=25, pady=12)
    cv = tk.Canvas(wrap, bg=BG, highlightthickness=0); sb = ttk.Scrollbar(wrap, orient="vertical", command=cv.yview)
    body = tk.Frame(cv, bg=BG); wid = cv.create_window((0, 0), window=body, anchor="nw")
    cv.configure(yscrollcommand=sb.set); cv.pack(side="left", fill="both", expand=True); sb.pack(side="right", fill="y")
    cv.bind("<Configure>", lambda e: cv.itemconfig(wid, width=e.width)); body.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))
    md.bind("<MouseWheel>", lambda e: cv.yview_scroll(int(-1 * (e.delta / 120)), "units"))
    pend = {}; linhas = []
    meus_clubes = list((getattr(self, "dados_desempenho_por_clubes", {}) or {}).keys())

    def guardar():
        for ck, y, s, vc, vv in linhas: pend[(ck, y)] = (vc.get().strip(), vv.get().strip(), s)

    def montar(*_):
        guardar(); linhas.clear()
        for w in body.winfo_children(): w.destroy()
        gk = next((k for k, l in grupos if l == v_g.get()), "")
        comps = used if gk == "*" else g.get(gk, [])
        if comp_key: comps = sorted(comps, key=lambda c: c["key"] != comp_key)
        for c in comps:
            y = H.bulk_y(c, v_s.get()); lbl = H.season_lbl(c, y); ck = _ps_lkey(c["n"])
            cur = next((r for r in H.timeline(c) if r["y"] == y), None)
            man = (H.manuais().get(ck, {}) or {}).get(str(y)) or {}
            card = tk.Frame(body, bg=CARD, padx=12, pady=8); card.pack(fill="x", pady=3)
            hd = tk.Frame(card, bg=CARD); hd.pack(fill="x")
            self._ps_crest(hd, c["e"], c["n"], 24, CARD).pack(side="left", padx=(0, 8))
            tk.Label(hd, text=c["n"], font=("Segoe UI", 10, "bold"), fg="white", bg=CARD).pack(side="left")
            tk.Label(hd, text=lbl, font=("Segoe UI", 9, "bold"), fg=ACC, bg=CARD).pack(side="right")
            if cur and (cur.get("me") or cur.get("fin")):
                tk.Label(card, text=f"🏆 {cur['label']}" + (f"  ·  vice: {H.ru_team(cur, c)['label']}" if cur.get("ru") else "") + "   — definido pela sua carreira",
                         font=("Segoe UI", 9), fg=SUB, bg=CARD).pack(anchor="w", pady=(4, 0))
                continue
            p = pend.get((ck, y))
            vc = tk.StringVar(value=p[0] if p else man.get("c", "")); vv = tk.StringVar(value=p[1] if p else man.get("v", ""))
            sugest = [x["label"] for x in H.ranking(c)[:60]] + meus_clubes
            fr = tk.Frame(card, bg=CARD); fr.pack(fill="x", pady=(4, 0)); fr.columnconfigure(1, weight=1); fr.columnconfigure(3, weight=1)
            tk.Label(fr, text="Campeão", font=("Segoe UI", 8, "bold"), fg=SUB, bg=CARD).grid(row=0, column=0, sticky="w")
            ttk.Combobox(fr, textvariable=vc, values=sugest).grid(row=0, column=1, sticky="ew", padx=(6, 14))
            tk.Label(fr, text="Vice", font=("Segoe UI", 8, "bold"), fg=SUB, bg=CARD).grid(row=0, column=2, sticky="w")
            ttk.Combobox(fr, textvariable=vv, values=sugest).grid(row=0, column=3, sticky="ew", padx=(6, 0))
            if cur and not cur.get("man"):
                tk.Label(card, text=f"Atual: {cur['label']}" + (f" (vice {H.ru_team(cur, c)['label']})" if cur.get("ru") else ""), font=("Segoe UI", 8, "italic"), fg="#64748B", bg=CARD).pack(anchor="w")
            linhas.append((ck, y, lbl, vc, vv))
        cv.yview_moveto(0)

    def salvar():
        guardar(); M = H.manuais(); n = 0
        for (ck, y), (c, v, s) in pend.items():
            box = M.setdefault(ck, {}); y = str(y)
            if c:
                if box.get(y, {}).get("c") != c or box.get(y, {}).get("v", "") != v: box[y] = {"c": c, "v": v, "s": s}; n += 1
            elif y in box: del box[y]; n += 1
            if not box: M.pop(ck, None)
        self.salvar_dados(); md.destroy()
        try: self.show_toast(f"Campeões salvos ({n})")
        except Exception: pass
        self._ps_aba_campeoes(parent_frame, comp_key)

    cb_s.bind("<<ComboboxSelected>>", montar); cb_g.bind("<<ComboboxSelected>>", montar)
    tk.Label(md, text="Finais que você disputou entram sozinhas: basta o jogo ter \"Final\" no campo Rodada. Se perder, o adversário vira campeão e seu time aparece como vice.",
             font=("Segoe UI", 9), fg="#64748B", bg=BG, wraplength=760, justify="left").pack(anchor="w", padx=25)
    tk.Button(md, text="SALVAR CAMPEÕES", bg="#00E676", fg="#064E3B", font=("Segoe UI", 11, "bold"), relief="flat", cursor="hand2", command=salvar).pack(fill="x", padx=25, pady=12, ipady=6)
    montar()


def _ps_abrir_campeoes(self, comp_key=None):
    self._ps_hist_alvo = comp_key; self._ps_hist_tab = "rank"
    self.open_tab("Campeões", "VISÃO GERAL", 40)


def _ps_noticia_titulo(self, nome, clube, temporada, stars_antes):
    try:
        H = _ps_hist(self)
        if not H.ready: return
        nw = H.noticia_titulo(nome, clube, temporada, stars_antes)
        if not hasattr(self, "feed_noticias") or self.feed_noticias is None: self.feed_noticias = []
        self.feed_noticias.insert(0, nw)
        self.noticias_nao_lidas = int(getattr(self, "noticias_nao_lidas", 0) or 0) + 1
        try: self.atualizar_badge_notificacao()
        except Exception: pass
    except Exception as e: print("Notícia de título:", e)


def _ps_remover_noticia_titulo(self, nome, clube, todas=True):
    fd = getattr(self, "feed_noticias", []) or []
    alvo = [i for i, n in enumerate(fd) if n.get("tipo") == "titulo" and str(n.get("comp", "")).lower() == str(nome).lower() and n.get("clube") == clube]
    if not todas: alvo = alvo[:1]
    for i in sorted(alvo, reverse=True):
        if not fd[i].get("lida"): self.noticias_nao_lidas = max(0, int(getattr(self, "noticias_nao_lidas", 0) or 0) - 1)
        del fd[i]


def _ps_stars_antes(self, clube):
    try:
        H = _ps_hist(self)
        return H.crest_stars(clube) if H.ready else 0
    except Exception: return 0


for _n, _f in list(globals().items()):
    if _n.startswith("_ps_") and callable(_f) and _n not in ("_ps_lnorm", "_ps_lkey", "_ps_strip_years", "_ps_sig", "_ps_lev", "_ps_tok_eq", "_ps_tok_strict",
                                                              "_ps_logo_offline", "_ps_entry_img", "_ps_silhueta", "_ps_face_pil", "_ps_parse_dmy", "_ps_hist"):
        setattr(App, _n, _f)


if __name__ == "__main__":
    # Ensure necessary directories exist, create if not
    for dir_name in ["Faces", "Logos", "Titulos", "Faces/Ballon d'Or"]: # Added Faces/Ballon d'Or
        if not os.path.exists(dir_name):
            try:
                os.makedirs(dir_name)
                print(f"Diretório '{dir_name}' criado. Por favor, adicione as imagens necessárias.")
            except OSError as e:
                print(f"Erro ao criar o diretório {dir_name}: {e}")

    # Define placeholder images to be created if they don't exist
    # This ensures the app can run even without actual image files
    placeholder_images_info = {
    }
    
    ballondor_player_placeholders_list = list(App.ballondor_winners.keys())

    for player_name in ballondor_player_placeholders_list:
        sanitized_player_name = (player_name.replace(' ', '_')
                                 .replace('.', '')
                                 .replace('ç', 'c')
                                 .replace('é', 'e')
                                 .replace('ã', 'a')
                                 .replace('á', 'a')
                                 .replace('í', 'i')
                                 .replace('ó', 'o')
                                 .replace('ú', 'u')
                                 .replace('Í', 'I')) # Added for Í
        path = f"Faces/Ballon d'Or/{sanitized_player_name}.png"
        if not os.path.exists(path):
            try:
                # Generate a simple gray placeholder image with initials or name
                initials = "".join([n[0] for n in player_name.split() if n]).upper()[:3]
                if not initials: initials = player_name[:3].upper() # Fallback if name is single word
                
                img = Image.new('RGB', (100, 100), color=(100, 100, 100)) # Placeholder image size
                d = ImageDraw.Draw(img)
                try:
                    font = ImageFont.truetype("arialbd.ttf", 24) # Use a bold font for initials
                except IOError:
                    font = ImageFont.load_default()
                
                text_bbox = d.textbbox((0,0), initials, font=font)
                text_w = text_bbox[2] - text_bbox[0]
                text_h = text_bbox[3] - text_bbox[1]
                
                position = ((100 - text_w) / 2, (100 - text_h) / 2)
                d.text(position, initials, fill="white", font=font, align="center")
                img.save(path)
                print(f"Imagem placeholder para Ballon d'Or '{path}' criada.")
            except Exception as e:
                print(f"Não foi possível criar a imagem placeholder para Ballon d'Or '{path}': {e}")


    for path, info in placeholder_images_info.items():
        if not os.path.exists(path):
            try:
                img = Image.new('RGB', info["size"], color=info["color"])
                d = ImageDraw.Draw(img)
                font_size = info.get("font_size", 12)
                try:
                    font = ImageFont.truetype("arial.ttf", font_size)
                except IOError:
                    font = ImageFont.load_default()
                
                text_color = info.get("text_color", (255,255,255) if sum(info["color"]) < 384 else (0,0,0)) # Determine text color based on background luminance

                # Calculate text position for centering
                text_bbox = d.textbbox((0,0), info["text"], font=font)
                text_w = text_bbox[2] - text_bbox[0]
                text_h = text_bbox[3] - text_bbox[1]
                position = ((info["size"][0]-text_w)/2, (info["size"][1]-text_h)/2 - (font_size/4 if "\n" in info["text"] else 0)) 
                
                d.text(position, info["text"], fill=text_color, font=font, align="center")
                img.save(path)
                print(f"Imagem placeholder '{path}' criada.")
            except Exception as e:
                print(f"Não foi possível criar a imagem placeholder '{path}': {e}")

    app = App()
    app.mainloop()
